window.QUIZ_ORALE = {"versione":"1.4 · 20/11/2026","materie":["DL","INPS","INAIL","PPP","TRIB","RAG","DEO"],"rami":{"DEO-1":"Ordinamento e deontologia","DEO-2":"Ordinamento e deontologia","DEO-3":"Ordinamento e deontologia","DEO-4":"Ordinamento e deontologia","DEO-5":"Ordinamento e deontologia","DEO-6":"Ordinamento e deontologia","DEO-22":"Ordinamento e deontologia","DEO-23":"Ordinamento e deontologia","DEO-7":"Ordinamento e deontologia","DEO-8":"Ordinamento e deontologia","DEO-9":"Ordinamento e deontologia","DEO-10":"Ordinamento e deontologia","DEO-11":"Ordinamento e deontologia","DEO-12":"Ordinamento e deontologia","DEO-13":"Ordinamento e deontologia","DEO-14":"Ordinamento e deontologia","DEO-15":"Ordinamento e deontologia","DEO-16":"Ordinamento e deontologia","DEO-17":"Ordinamento e deontologia","DEO-18":"Ordinamento e deontologia","DEO-19":"Ordinamento e deontologia","DEO-20":"Ordinamento e deontologia","DEO-21":"Ordinamento e deontologia","PPP-X1":"Pubblico e costituzionale","DEO-X1":"Ordinamento e deontologia","DEO-X2":"Ordinamento e deontologia","DEO-X3":"Ordinamento e deontologia","DEO-X4":"Ordinamento e deontologia","DEO-X5":"Ordinamento e deontologia","DEO-X6":"Ordinamento e deontologia","S22-DEO-1":"Ordinamento e deontologia","S22-DEO-12":"Ordinamento e deontologia","S22-DEO-14":"Ordinamento e deontologia","S22-DEO-15":"Ordinamento e deontologia"},"domande":[{"id":"DL-1a~0","s":"DL-1a","q":"Qual è il cuore di «Il codice civile e la nozione di lavoro subordinato»? Rispondi in due o tre frasi.","a":"Per l'art. 2094 c.c. è prestatore di lavoro subordinato chi si obbliga, mediante retribuzione, a collaborare nell'impresa prestando il proprio lavoro intellettuale o manuale alle dipendenze e sotto la direzione dell'imprenditore. Gli elementi sono tre: collaborazione, onerosità ed eterodirezione.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-1a~1","s":"DL-1a","q":"Quali sono i tre elementi della subordinazione nell'art. 2094 c.c.?","a":"Collaborazione, onerosità ed eterodirezione.","v":{"p":null,"e":[["Collaborazione","k",["collabor"]],["onerosità","k",["oneros"]],["eterodirezione","k",["eterodir"]]],"r":[]}},{"id":"DL-1a~2","s":"DL-1a","q":"Quali poteri del datore esprimono il vincolo di subordinazione?","a":"Direttivo, di controllo e disciplinare (artt. 2104 e 2106 c.c.).","v":{"p":null,"e":[["Direttivo","k",["dirett"]],["controllo","k",["contro"]],["disciplinare","k",["discipli"]]],"r":[["art. 2104 c.c.",["2104"]]]}},{"id":"DL-1a~3","s":"DL-1a","q":"Il nome dato dalle parti al contratto (nomen iuris) è decisivo per la qualificazione?","a":"No: prevale il concreto svolgimento del rapporto; il nome conta solo in via sussidiaria nei casi incerti.","v":{"p":"n","e":[["prevale","k",["preva"]],["concreto","k",["concr"]],["svolgimento","k",["svolgime"]],["rapporto","k",["rappo","contratt"]],["conta","k",["conta"]],["sussidiaria","k",["sussidia"]],["incerti","k",["incer"]]],"r":[]}},{"id":"DL-2a~0","s":"DL-2a","q":"Qual è il cuore di «I requisiti essenziali del contratto di lavoro»? Rispondi in due o tre frasi.","a":"Il contratto di lavoro è un contratto di scambio tra prestazione di lavoro e retribuzione; i suoi requisiti sono quelli dell'art. 1325 c.c.: accordo delle parti, causa, oggetto e forma quando è prescritta.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-2a~1","s":"DL-2a","q":"Quali sono i requisiti del contratto di lavoro secondo l'art. 1325 c.c.?","a":"Accordo delle parti, causa, oggetto e forma quando è prescritta.","v":{"p":null,"e":[["Accordo","k",["accor"]],["parti","k",["parti"]],["causa","k",["causa"]],["oggetto","k",["ogget"]],["forma","k",["forma"]],["prescritta","k",["prescri"]]],"r":[]}},{"id":"DL-2a~2","s":"DL-2a","q":"A quale età si può lavorare?","a":"16 anni, con l'obbligo di istruzione assolto, salvo eccezioni di legge.","v":{"p":null,"e":[["16","n",["16"]],["anni","k",["ann"]],["obbligo","k",["obbli","obblig"]],["istruzione","k",["istruzi"]],["assolto","k",["assol"]],["eccezioni","k",["eccezi","salvo","tranne","esclus","eccett"]],["legge","k",["legge"]]],"r":[]}},{"id":"DL-2a~3","s":"DL-2a","q":"Il termine apposto al contratto senza atto scritto che effetto ha?","a":"È privo di effetto: il rapporto è a tempo indeterminato; eccezione per i rapporti fino a 12 giorni (art. 19, c. 4, D.Lgs. 81/2015).","v":{"p":null,"e":[["12","m",["12"]],["privo","k",["privo","nessun","inefficac","null","non ha effett","non produce","non vale"]],["rapporto","k",["rappo","contratt"]],["tempo","k",["tempo"]],["indeterminato","k",["indeterm"]],["eccezione","k",["eccezi","salvo","tranne","esclus","eccett"]],["giorni","k",["giorn","gg"]]],"r":[["81/2015",["81","2015"]],["art. 19",["19"]]]}},{"id":"DL-4a~0","s":"DL-4a","q":"Qual è il cuore di «La prestazione di fatto e la tutela del lavoratore»? Rispondi in due o tre frasi.","a":"La prestazione di fatto è il lavoro eseguito in base a un contratto nullo o annullato: per l'art. 2126 c.c. la nullità o l'annullamento non producono effetto per il periodo in cui il rapporto ha avuto esecuzione, salvo che la nullità derivi dall'illiceità dell'oggetto o della causa.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-4a~1","s":"DL-4a","q":"Che effetto ha la nullità del contratto di lavoro per il periodo già eseguito?","a":"Nessuno: restano dovuti retribuzione e trattamenti (art. 2126 c.c.).","v":{"p":"n","e":[["restano","k",["resta"]],["dovuti","k",["dovut"]],["retribuzione","k",["retribuz","stipend","paga","salari"]],["trattamenti","k",["trattame"]]],"r":[["art. 2126 c.c.",["2126"]]]}},{"id":"DL-4a~2","s":"DL-4a","q":"Quando la tutela dell'art. 2126 c.c. non opera?","a":"Se la nullità deriva dall'illiceità dell'oggetto o della causa: resta solo l'arricchimento senza causa (art. 2041 c.c.).","v":{"p":null,"e":[["nullità","k",["nulli","invalid","inefficac","privo","priva","nessun effett","non ha effett","non produce effett"]],["deriva","k",["deriv"]],["illiceità","k",["illice"]],["oggetto","k",["ogget"]],["causa","k",["causa"]],["resta","k",["resta"]],["arricchimento","k",["arricchi"]]],"r":[["art. 2041 c.c.",["2041"]]]}},{"id":"DL-4a~3","s":"DL-4a","q":"Il minore sotto l'età minima che ha lavorato ha diritto alla retribuzione?","a":"Sì: il lavoro è prestato violando norme a tutela del lavoratore (art. 2126, c. 2).","v":{"p":"s","e":[["prestato","k",["prest"]],["violando","k",["viola"]],["norme","k",["norme"]],["tutela","k",["tutel"]]],"r":[["art. 2126",["2126"]]]}},{"id":"DL-4b~0","s":"DL-4b","q":"Qual è il cuore di «Le collaborazioni coordinate e continuative»? Rispondi in due o tre frasi.","a":"Le collaborazioni coordinate e continuative sono rapporti di lavoro autonomo che si concretano in una prestazione d'opera continuativa e prevalentemente personale, coordinata con il committente (art. 409, n. 3, c.p.c.): il collaboratore organizza da sé l'attività, nel rispetto delle modalità di coordinamento stabilite di comune accordo.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-4b~1","s":"DL-4b","q":"Quale norma definisce le collaborazioni coordinate e continuative?","a":"L'art. 409, n. 3, c.p.c.","v":{"p":null,"e":[["art. 409","n",["409"]]],"r":[]},"t":"e"},{"id":"DL-4b~2","s":"DL-4b","q":"Che disciplina si applica alle collaborazioni etero-organizzate dal committente?","a":"Quella del lavoro subordinato (art. 2, c. 1, D.Lgs. 81/2015).","v":{"p":null,"e":[["lavoro","k",["lavor","dipendent","prestator"]],["subordinato","k",["subordin"]]],"r":[["81/2015",["81","2015"]],["art. 2",["2"]]]}},{"id":"DL-4b~3","s":"DL-4b","q":"Come sono qualificati fiscalmente i compensi dei co.co.co.?","a":"Redditi assimilati a quelli di lavoro dipendente (art. 50, c. 1, lett. c-bis, TUIR).","v":{"p":null,"e":[["Redditi","k",["reddi"]],["assimilati","k",["assimil"]],["lavoro","k",["lavor","dipendent","prestator"]],["dipendente","k",["dipende","lavorat"]]],"r":[["art. 50",["50"]]]}},{"id":"DL-5a~0","s":"DL-5a","q":"Qual è il cuore di «Gli effetti della certificazione dei contratti e la sua valenza giuridica»? Rispondi in due o tre frasi.","a":"La certificazione (artt. 75-81 D.Lgs. 276/2003) è una procedura volontaria con cui le parti fanno attestare da una commissione che il contratto con cui si scambia una prestazione di lavoro ha i requisiti di forma e contenuto richiesti dalla legge. Lo scopo è dare certezza alla qualificazione e ridurre il contenzioso.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-5a~1","s":"DL-5a","q":"In quali articoli del D.Lgs. 276/2003 è regolata la certificazione dei contratti?","a":"Artt. 75-81.","v":{"p":null,"e":[["art. 75-81","n",["75","81"]]],"r":[]},"t":"e"},{"id":"DL-5a~2","s":"DL-5a","q":"Entro quanto si conclude il procedimento di certificazione?","a":"Entro 30 giorni (art. 78).","v":{"p":null,"e":[["30","n",["30"]],["giorni","k",["giorn","gg"]]],"r":[["art. 78",["78"]]]},"t":"d"},{"id":"DL-5a~3","s":"DL-5a","q":"Per quali motivi si impugna davanti al giudice del lavoro la certificazione?","a":"Erronea qualificazione, vizio del consenso, difformità tra programma certificato e attuazione (art. 80).","v":{"p":null,"e":[["Erronea","k",["erron"]],["vizio","k",["vizio"]],["consenso","k",["conse"]],["difformità","k",["difform"]],["programma","k",["progra"]],["attuazione","k",["attuazi"]]],"r":[["art. 80",["80"]]]}},{"id":"DL-6a~0","s":"DL-6a","q":"Qual è il cuore di «Gli elementi essenziali del lavoro autonomo»? Rispondi in due o tre frasi.","a":"Il lavoro autonomo ha il suo modello nel contratto d'opera: chi si obbliga a compiere, verso un corrispettivo, un'opera o un servizio, con lavoro prevalentemente proprio e senza vincolo di subordinazione verso il committente (art. 2222 c.c.).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-6a~1","s":"DL-6a","q":"Quale articolo del codice civile definisce il contratto d'opera?","a":"L'art. 2222 c.c.","v":{"p":null,"e":[["art. 2222","n",["2222"]]],"r":[]},"t":"p"},{"id":"DL-6a~2","s":"DL-6a","q":"Oltre quanti giorni i termini di pagamento al lavoratore autonomo sono abusivi (L. 81/2017)?","a":"Oltre 60 giorni.","v":{"p":null,"e":[["60","n",["60"]]],"r":[]}},{"id":"DL-6a~3","s":"DL-6a","q":"Che reddito produce il lavoro autonomo occasionale?","a":"Reddito diverso (art. 67, c. 1, lett. l, TUIR).","v":{"p":null,"e":[["diverso","k",["diver"]]],"r":[["art. 67",["67"]]]}},{"id":"DL-7a~0","s":"DL-7a","q":"Qual è il cuore di «Il lavoro autonomo occasionale: obblighi, limiti, tutele»? Rispondi in due o tre frasi.","a":"Il lavoratore autonomo occasionale svolge un'opera o un servizio ex art. 2222 c.c. con lavoro prevalentemente proprio, senza subordinazione, senza coordinamento con il committente e in modo non abituale. Non va confuso con le prestazioni occasionali dell'art. 54-bis D.L. 50/2017, gestite sulla piattaforma INPS.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-7a~1","s":"DL-7a","q":"A chi e quando va comunicato l'avvio di un lavoro autonomo occasionale?","a":"All'ITL, prima dell'inizio, in via telematica (art. 14, c. 1, D.Lgs. 81/2008).","v":{"p":null,"e":[["ITL","k",["itl","ispettorato"]],["inizio","k",["inizi"]],["telematica","k",["telemat","online","on line","via web","digital"]]],"r":[["81/2008",["81","2008"]],["art. 14",["14"]]]}},{"id":"DL-7a~2","s":"DL-7a","q":"Sanzione per la mancata comunicazione dell'autonomo occasionale?","a":"Da 500 a 2.500 euro per lavoratore, senza diffida.","v":{"p":null,"e":[["500","n",["500"]],["2.500","n",["2500"]],["euro","k",["eur"]],["lavoratore","k",["lavorat","dipendent","prestator"]],["diffida","k",["diffi"]]],"r":[]},"t":"d"},{"id":"DL-7a~3","s":"DL-7a","q":"Oltre quale reddito annuo l'autonomo occasionale entra nella gestione separata INPS?","a":"Oltre 5.000 euro.","v":{"p":null,"e":[["5.000","n",["5000"]],["euro","k",["eur"]]],"r":[]}},{"id":"DL-19a~0","s":"DL-19a","q":"Qual è il cuore di «Le differenze tra lavoro autonomo e lavoro subordinato»? Rispondi in due o tre frasi.","a":"La distinzione passa per il vincolo di subordinazione: il lavoratore subordinato mette a disposizione le proprie energie sotto la direzione del datore (art. 2094 c.c.); l'autonomo si obbliga a un'opera o a un servizio, con lavoro prevalentemente proprio e organizzando da sé tempi e modi (art. 2222 c.c.).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-19a~1","s":"DL-19a","q":"Che tipo di obbligazione assume il lavoratore autonomo?","a":"Un obbligo di risultato, con autonomia organizzativa e rischio a suo carico.","v":{"p":null,"e":[["risultato","k",["risult"]],["organizzativa","k",["organizz"]],["rischio","k",["risch"]],["carico","k",["caric"]]],"r":[]}},{"id":"DL-19a~2","s":"DL-19a","q":"Che reddito producono il lavoro subordinato e il lavoro autonomo abituale?","a":"Lavoro dipendente (art. 49 TUIR) e lavoro autonomo (art. 53 TUIR).","v":{"p":null,"e":[["dipendente","k",["dipende","lavorat"]]],"r":[["art. 49",["49"]],["art. 53",["53"]]]}},{"id":"DL-19a~3","s":"DL-19a","q":"Quali indici usa la giurisprudenza nei casi dubbi di subordinazione?","a":"Orario, continuità, retribuzione fissa, inserimento nell'organizzazione, assenza di struttura imprenditoriale.","v":{"p":null,"e":[["Orario","k",["orari"]],["continuità","k",["continu"]],["retribuzione","k",["retribuz","stipend","paga","salari"]],["fissa","k",["fissa"]],["inserimento","k",["inserime"]],["organizzazione","k",["organizz"]],["assenza","k",["assen"]],["struttura","k",["strutt"]],["imprenditoriale","k",["imprendi"]]],"r":[]}},{"id":"DL-X13~0","s":"DL-X13","q":"Qual è il cuore di «Il lavoro tramite piattaforme digitali: rider e tutele»? Rispondi in due o tre frasi.","a":"Per chi lavora tramite piattaforme digitali la qualificazione dipende dalle concrete modalità della prestazione, non dal nome del contratto: se emergono poteri di direzione e controllo, anche esercitati tramite algoritmi, il rapporto si presume subordinato salvo prova contraria (art. 12 D.L. 62/2026); i rider davvero autonomi hanno le tutele minime del capo V-bis del D.Lgs. 81/2015.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-X13~1","s":"DL-X13","q":"Quale norma del 2026 introduce la presunzione di subordinazione per i rider?","a":"L'art. 12 D.L. 62/2026.","v":{"p":null,"e":[["62/2026","n",["62","2026"]],["art. 12","n",["12"]]],"r":[]},"t":"p"},{"id":"DL-X13~2","s":"DL-X13","q":"Indennità minima del rider autonomo per notte, festivi e maltempo?","a":"Almeno il 10% (art. 47-quater D.Lgs. 81/2015).","v":{"p":null,"e":[["10%","n",["10"]]],"r":[["81/2015",["81","2015"]],["art. 47",["47"]]]},"t":"d"},{"id":"DL-X13~3","s":"DL-X13","q":"Per quanti anni la piattaforma conserva i dati su accessi, rifiuti e compensi?","a":"5 anni (art. 13 D.L. 62/2026).","v":{"p":null,"e":[["5","n",["5"]]],"r":[["62/2026",["62","2026"]],["art. 13",["13"]]]},"t":"d"},{"id":"DL-1b~0","s":"DL-1b","q":"Qual è il cuore di «Il contratto a tempo determinato»? Rispondi in due o tre frasi.","a":"Il contratto a tempo determinato è un contratto di lavoro subordinato con un termine finale, alla cui scadenza il rapporto si estingue automaticamente. È disciplinato dagli artt. 19-29 D.Lgs. 81/2015; la forma comune resta il tempo indeterminato.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-1b~1","s":"DL-1b","q":"Fino a quanti mesi il contratto a termine non richiede condizioni?","a":"12 mesi.","v":{"p":null,"e":[["12","n",["12"]]],"r":[]}},{"id":"DL-1b~2","s":"DL-1b","q":"Quante proroghe sono ammesse nel contratto a termine?","a":"Massimo 4 in 24 mesi.","v":{"p":null,"e":[["4","n",["4"]],["24","n",["24"]],["mesi","k",["mes"]]],"r":[]}},{"id":"DL-1b~3","s":"DL-1b","q":"Limite quantitativo dei contratti a termine e conseguenza della violazione?","a":"20% dei lavoratori a tempo indeterminato al 1° gennaio; la violazione dà una sanzione amministrativa, non la trasformazione.","v":{"p":null,"e":[["20%","n",["20"]],["1","n",["1"]],["lavoratori","k",["lavorat","dipendent","prestator"]],["tempo","k",["tempo"]],["indeterminato","k",["indeterm"]],["gennaio","k",["genna"]],["sanzione","k",["sanzi","multa","ammend"]],["amministrativa","k",["amminist"]],["trasformazione","k",["trasform"]]],"r":[]}},{"id":"DL-1b~4","s":"DL-1b","q":"Termine di impugnazione del contratto a termine e indennità in caso di conversione?","a":"180 giorni dalla cessazione; indennità da 2,5 a 12 mensilità (art. 28).","v":{"p":null,"e":[["180","n",["180"]],["2,5","m",["2.5"]],["12","m",["12"]],["giorni","k",["giorn","gg"]],["cessazione","k",["cessazi"]],["mensilità","k",["mensil"]]],"r":[["art. 28",["28"]]]}},{"id":"DL-2b~0","s":"DL-2b","q":"Qual è il cuore di «Il contratto a tempo parziale»? Rispondi in due o tre frasi.","a":"Il part-time è un rapporto di lavoro subordinato, a tempo indeterminato o determinato, con orario inferiore al tempo pieno (40 ore settimanali o il minore orario del CCNL). È disciplinato dagli artt. 4-12 D.Lgs. 81/2015.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-2b~1","s":"DL-2b","q":"Limite e maggiorazione del lavoro supplementare se il CCNL non dispone?","a":"Fino al 25% delle ore settimanali, maggiorazione del 15%.","v":{"p":null,"e":[["25%","n",["25"]],["15%","n",["15"]],["ore","k",["ore"]],["settimanali","k",["settiman"]]],"r":[]},"t":"d"},{"id":"DL-2b~2","s":"DL-2b","q":"Preavviso minimo per attivare le clausole elastiche nel part-time?","a":"Almeno 2 giorni.","v":{"p":null,"e":[["2","n",["2"]],["giorni","k",["giorn","gg"]]],"r":[]},"t":"d"},{"id":"DL-2b~3","s":"DL-2b","q":"Il rifiuto di passare al part-time è giustificato motivo di licenziamento?","a":"No (art. 8, c. 1, D.Lgs. 81/2015).","v":{"p":"n","e":[],"r":[["81/2015",["81","2015"]],["art. 8",["8"]]]}},{"id":"DL-3a~0","s":"DL-3a","q":"Qual è il cuore di «Il patto di prova: funzione, forma, durata»? Rispondi in due o tre frasi.","a":"Il patto di prova subordina l'assunzione definitiva all'esito positivo di un esperimento, nel reciproco interesse delle parti (art. 2096 c.c.): il datore verifica capacità e idoneità del lavoratore, il lavoratore la convenienza del posto.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-3a~1","s":"DL-3a","q":"Che forma richiede il patto di prova e quando va stipulato?","a":"Scritta, firmata da entrambi, prima o al massimo contestualmente all'inizio del rapporto.","v":{"p":null,"e":[["Scritta","k",["scrit"]],["firmata","k",["firma"]],["entrambi","k",["entra"]],["contestualmente","k",["contestu"]],["inizio","k",["inizi"]],["rapporto","k",["rappo","contratt"]]],"r":[]}},{"id":"DL-3a~2","s":"DL-3a","q":"Durata massima del patto di prova?","a":"6 mesi, salvo durata inferiore del CCNL (art. 7 D.Lgs. 104/2022).","v":{"p":null,"e":[["6","n",["6"]],["mesi","k",["mes"]],["inferiore","k",["inferi"]],["CCNL","k",["ccnl","contratto collettivo","contratti collettivi"]]],"r":[["104/2022",["104","2022"]],["art. 7",["7"]]]}},{"id":"DL-3a~3","s":"DL-3a","q":"Prova nei contratti a termine: quale proporzione si applica?","a":"Un giorno di prova ogni 15 di calendario (art. 13 L. 203/2024).","v":{"p":null,"e":[["15","n",["15"]],["giorno","k",["giorn","gg"]],["calendario","k",["calenda"]]],"r":[["203/2024",["203","2024"]],["art. 13",["13"]]]},"t":"d"},{"id":"DL-3b~0","s":"DL-3b","q":"Qual è il cuore di «Il lavoro intermittente (a chiamata)»? Rispondi in due o tre frasi.","a":"Il lavoro intermittente, o a chiamata, è un contratto di lavoro subordinato, a tempo determinato o indeterminato, con cui il lavoratore si mette a disposizione del datore, che lo chiama quando ne ha bisogno (artt. 13-18 D.Lgs. 81/2015).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-3b~1","s":"DL-3b","q":"Quali sono le causali soggettive del lavoro intermittente?","a":"Lavoratori con meno di 24 anni o più di 55.","v":{"p":null,"e":[["24","n",["24"]],["55","n",["55"]],["anni","k",["ann"]]],"r":[]}},{"id":"DL-3b~2","s":"DL-3b","q":"Limite di giornate del lavoro intermittente tra le stesse parti?","a":"400 giornate in 3 anni solari, salvo turismo, pubblici esercizi e spettacolo.","v":{"p":null,"e":[["400","n",["400"]],["3","n",["3"]],["anni","k",["ann"]],["solari","k",["solar"]],["turismo","k",["turis"]],["pubblici","k",["pubbl"]],["esercizi","k",["eserc"]],["spettacolo","k",["spettac"]]],"r":[]}},{"id":"DL-3b~3","s":"DL-3b","q":"Sanzione per la mancata comunicazione preventiva della chiamata?","a":"Da 400 a 2.400 euro per lavoratore, senza diffida.","v":{"p":null,"e":[["400","n",["400"]],["2.400","n",["2400"]],["euro","k",["eur"]],["lavoratore","k",["lavorat","dipendent","prestator"]],["diffida","k",["diffi"]]],"r":[]},"t":"d"},{"id":"DL-9a~0","s":"DL-9a","q":"Qual è il cuore di «Il distacco: requisiti di legittimità»? Rispondi in due o tre frasi.","a":"Il distacco si ha quando un datore di lavoro, per soddisfare un proprio interesse, mette temporaneamente uno o più lavoratori a disposizione di un altro soggetto per l'esecuzione di una determinata attività (art. 30 D.Lgs. 276/2003).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-9a~1","s":"DL-9a","q":"Quale norma disciplina il distacco nel settore privato?","a":"L'art. 30 D.Lgs. 276/2003.","v":{"p":null,"e":[["276/2003","n",["276","2003"]],["art. 30","n",["30"]]],"r":[]},"t":"e"},{"id":"DL-9a~2","s":"DL-9a","q":"Distacco in un'unità a più di 50 km: a quale condizione è ammesso?","a":"Solo per comprovate ragioni tecniche, organizzative, produttive o sostitutive.","v":{"p":null,"e":[["comprovate","k",["comprov"]],["ragioni","k",["ragio"]],["tecniche","k",["tecni"]],["organizzative","k",["organizz"]],["produttive","k",["produtt"]],["sostitutive","k",["sostitut"]]],"r":[]}},{"id":"DL-9a~3","s":"DL-9a","q":"Fino a quando vale il distacco sperimentale senza interesse del distaccante del D.L. 62/2026?","a":"Fino al 31/12/2029, previo accordo sindacale (art. 16-quater).","v":{"p":null,"e":[["31","n",["31"]],["2029","n",["2029"]],["dicembre","k",["dicem"]],["previo","k",["previ"]],["accordo","k",["accor"]],["sindacale","k",["sindac"]]],"r":[["art. 16",["16"]]]},"t":"d"},{"id":"DL-10a~0","s":"DL-10a","q":"Qual è il cuore di «La somministrazione di lavoro: condizioni e limiti»? Rispondi in due o tre frasi.","a":"La somministrazione è la forma lecita di fornitura di manodopera: un'agenzia autorizzata mette a disposizione di un utilizzatore lavoratori propri dipendenti, che per tutta la missione lavorano nell'interesse e sotto la direzione e il controllo dell'utilizzatore (art. 30 D.Lgs. 81/2015).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-10a~1","s":"DL-10a","q":"Limite dei somministrati a tempo indeterminato, salvo CCNL?","a":"20% dei lavoratori a tempo indeterminato dell'utilizzatore al 1° gennaio.","v":{"p":null,"e":[["20%","n",["20"]],["1","n",["1"]],["lavoratori","k",["lavorat","dipendent","prestator"]],["utilizzatore","k",["utilizza"]],["gennaio","k",["genna"]]],"r":[]}},{"id":"DL-10a~2","s":"DL-10a","q":"Limite complessivo di contratti a termine e somministrati a termine?","a":"30%, con le esenzioni previste.","v":{"p":null,"e":[["30%","n",["30"]],["esenzioni","k",["esenzi"]],["previste","k",["previ"]]],"r":[]}},{"id":"DL-10a~3","s":"DL-10a","q":"Nella somministrazione, a chi spetta il potere disciplinare?","a":"All'agenzia; il potere direttivo spetta all'utilizzatore.","v":{"p":null,"e":[["agenzia","k",["agenz"]],["direttivo","k",["dirett"]],["utilizzatore","k",["utilizza"]]],"r":[]}},{"id":"DL-21a~0","s":"DL-21a","q":"Qual è il cuore di «L'apprendistato professionalizzante»? Rispondi in due o tre frasi.","a":"L'apprendistato è un contratto di lavoro a tempo indeterminato finalizzato alla formazione e all'occupazione dei giovani, con causa mista: lavoro in cambio di retribuzione e formazione. Il professionalizzante (secondo livello) serve a conseguire una qualificazione professionale ai fini contrattuali (artt. 41-47 D.Lgs. 81/2015).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-21a~1","s":"DL-21a","q":"Età per l'apprendistato professionalizzante?","a":"Da 18 a 29 anni (da 17 con qualifica professionale).","v":{"p":null,"e":[["18","n",["18"]],["29","n",["29"]],["anni","k",["ann"]]],"r":[]}},{"id":"DL-21a~2","s":"DL-21a","q":"Durata minima dell'apprendistato?","a":"6 mesi (art. 42, c. 2).","v":{"p":null,"e":[["6","n",["6"]],["mesi","k",["mes"]]],"r":[["art. 42",["42"]]]},"t":"d"},{"id":"DL-21a~3","s":"DL-21a","q":"Rapporto massimo tra apprendisti e qualificati?","a":"3 apprendisti ogni 2 qualificati; sotto 10 dipendenti il 100%.","v":{"p":null,"e":[["3","n",["3"]],["2","n",["2"]],["10","m",["10"]],["100%","m",["100"]],["sotto","k",["sotto"]],["dipendenti","k",["dipende","lavorat"]]],"r":[]},"t":"d"},{"id":"DL-X12~0","s":"DL-X12","q":"Qual è il cuore di «Il lavoro agile (smart working)»? Rispondi in due o tre frasi.","a":"Il lavoro agile è una modalità di esecuzione del rapporto di lavoro subordinato, decisa con accordo tra le parti: la prestazione si svolge in parte nei locali aziendali e in parte all'esterno, senza postazione fissa e senza precisi vincoli di orario o di luogo, entro i soli limiti di durata massima dell'orario di lavoro (art. 18 L. 81/2017).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-X12~1","s":"DL-X12","q":"Preavviso per il recesso dall'accordo di lavoro agile?","a":"Almeno 30 giorni; 90 per il datore se il lavoratore è disabile.","v":{"p":null,"e":[["30","n",["30"]],["90","m",["90"]],["giorni","k",["giorn","gg"]],["datore","k",["dator","aziend","impres"]],["disabile","k",["disab"]]],"r":[]},"t":"d"},{"id":"DL-X12~2","s":"DL-X12","q":"Entro quanto va comunicato il lavoro agile al Ministero?","a":"Entro 5 giorni dall'avvio, dalla modifica o dalla cessazione.","v":{"p":null,"e":[["5","n",["5"]],["giorni","k",["giorn","gg"]],["avvio","k",["avvio"]],["modifica","k",["modif"]],["cessazione","k",["cessazi"]]],"r":[]}},{"id":"DL-X12~3","s":"DL-X12","q":"Chi ha priorità nelle richieste di lavoro agile?","a":"Genitori di figli fino a 12 anni (senza limiti se disabili gravi), lavoratori con disabilità grave, caregiver.","v":{"p":null,"e":[["12","n",["12"]],["Genitori","k",["genit"]],["figli","k",["figli"]],["anni","k",["ann"]],["disabilità","k",["disabil"]],["grave","k",["grave"]],["caregiver","k",["caregi"]]],"r":[]}},{"id":"S22-DL-10~0","s":"S22-DL-10","q":"Qual è il cuore di «Il lavoro occasionale: PrestO e Libretto famiglia»? Rispondi in due o tre frasi.","a":"Le prestazioni occasionali (art. 54-bis D.L. 50/2017, conv. L. 96/2017) sono attività di ridotta entità entro limiti annui di compenso e di durata, gestite con la piattaforma INPS. Hanno due canali: il Libretto famiglia per le persone fisiche fuori dall'attività d'impresa o professionale, il contratto di prestazione occasionale (PrestO) per gli altri utilizzatori.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-DL-10~1","s":"S22-DL-10","q":"Limite annuo di compenso per prestatore nelle prestazioni occasionali?","a":"5.000 euro da tutti gli utilizzatori.","v":{"p":null,"e":[["5.000","n",["5000"]],["euro","k",["eur"]],["utilizzatori","k",["utilizza"]]],"r":[]}},{"id":"S22-DL-10~2","s":"S22-DL-10","q":"Compenso minimo orario nel PrestO?","a":"9 euro l'ora.","v":{"p":null,"e":[["9","n",["9"]],["euro","k",["eur"]]],"r":[]},"t":"d"},{"id":"S22-DL-10~3","s":"S22-DL-10","q":"Valore del titolo del Libretto famiglia?","a":"10 euro per prestazioni fino a un'ora.","v":{"p":null,"e":[["10","n",["10"]],["euro","k",["eur"]],["prestazioni","k",["prestazi"]]],"r":[]},"t":"d"},{"id":"S22-DL-2~0","s":"S22-DL-2","q":"Qual è il cuore di «I diritti di precedenza e la loro incidenza sugli incentivi alle assunzioni»? Rispondi in due o tre frasi.","a":"Il diritto di precedenza è il diritto di un lavoratore a essere preferito ad altri nelle nuove assunzioni del datore. Nasce soprattutto dal contratto a termine (art. 24 D.Lgs. 81/2015) e dal part-time. Ha un effetto diretto sugli incentivi: l'assunzione che viola il diritto di precedenza di un altro lavoratore non dà diritto ai benefici (art. 31 D.Lgs. 150/2015).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-DL-2~1","s":"S22-DL-2","q":"Chi ha diritto di precedenza dopo un contratto a termine?","a":"Chi ha lavorato più di 6 mesi, per le assunzioni a tempo indeterminato entro 12 mesi (art. 24 D.Lgs. 81/2015).","v":{"p":null,"e":[["6","n",["6"]],["12","n",["12"]],["lavorato","k",["lavor","dipendent","prestator"]],["mesi","k",["mes"]],["assunzioni","k",["assunzi"]],["tempo","k",["tempo"]],["indeterminato","k",["indeterm"]]],"r":[["81/2015",["81","2015"]],["art. 24",["24"]]]}},{"id":"S22-DL-2~2","s":"S22-DL-2","q":"Entro quanto il lavoratore deve esercitare per iscritto la precedenza?","a":"Entro 6 mesi dalla cessazione (3 mesi per gli stagionali).","v":{"p":null,"e":[["6","n",["6"]],["mesi","k",["mes"]],["cessazione","k",["cessazi"]]],"r":[]},"t":"d"},{"id":"S22-DL-2~3","s":"S22-DL-2","q":"Che effetto ha sugli incentivi un'assunzione che viola il diritto di precedenza?","a":"Gli incentivi non spettano (art. 31 D.Lgs. 150/2015).","v":{"p":null,"e":[["spettano","k",["spett"]]],"r":[["150/2015",["150","2015"]],["art. 31",["31"]]]}},{"id":"S22-DL-8~0","s":"S22-DL-8","q":"Qual è il cuore di «Il tirocinio formativo»? Rispondi in due o tre frasi.","a":"Il tirocinio è un percorso formativo di alternanza tra studio e lavoro, per l'orientamento e la formazione professionale; non è un rapporto di lavoro (art. 1, c. 720-726, L. 234/2021). È curriculare se serve a conseguire un titolo di studio; extracurriculare negli altri casi, con disciplina regionale sulla base di linee guida concordate tra Stato e Regioni.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-DL-8~1","s":"S22-DL-8","q":"Il tirocinio è un rapporto di lavoro?","a":"No: è un percorso formativo di alternanza studio-lavoro (art. 1, c. 720 ss., L. 234/2021).","v":{"p":"n","e":[["percorso","k",["perco"]],["formativo","k",["format"]],["alternanza","k",["alterna"]],["studio","k",["studi"]]],"r":[["234/2021",["234","2021"]],["art. 1",["1"]]]}},{"id":"S22-DL-8~2","s":"S22-DL-8","q":"Sanzione per la mancata corresponsione dell'indennità di tirocinio?","a":"Da 1.000 a 6.000 euro (c. 722).","v":{"p":null,"e":[["1.000","n",["1000"]],["6.000","n",["6000"]],["euro","k",["eur"]]],"r":[]},"t":"d"},{"id":"S22-DL-8~3","s":"S22-DL-8","q":"Sanzione per il tirocinio fraudolento?","a":"Ammenda di 50 euro per tirocinante e per giorno (c. 723).","v":{"p":null,"e":[["50","n",["50"]],["Ammenda","k",["ammen"]],["euro","k",["eur"]],["giorno","k",["giorn","gg"]]],"r":[]},"t":"d"},{"id":"DL-8a~0","s":"DL-8a","q":"Qual è il cuore di «Il patto di non concorrenza»? Rispondi in due o tre frasi.","a":"Il patto di non concorrenza è l'accordo con cui il lavoratore si obbliga a non svolgere attività in concorrenza con il datore per un periodo successivo alla fine del rapporto (art. 2125 c.c.). È diverso dal divieto di concorrenza dell'art. 2105, che vale solo durante il rapporto.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-8a~1","s":"DL-8a","q":"Requisiti del patto di non concorrenza a pena di nullità?","a":"Forma scritta, corrispettivo, limiti di oggetto, tempo e luogo (art. 2125 c.c.).","v":{"p":null,"e":[["Forma","k",["forma"]],["scritta","k",["scrit"]],["corrispettivo","k",["corrispe"]],["limiti","k",["limit"]],["oggetto","k",["ogget"]],["tempo","k",["tempo"]],["luogo","k",["luogo"]]],"r":[["art. 2125 c.c.",["2125"]]]}},{"id":"DL-8a~2","s":"DL-8a","q":"Durata massima del patto di non concorrenza?","a":"5 anni per i dirigenti, 3 anni per gli altri.","v":{"p":null,"e":[["5","n",["5"]],["3","n",["3"]],["anni","k",["ann"]],["dirigenti","k",["dirige"]]],"r":[]}},{"id":"DL-8a~3","s":"DL-8a","q":"Quale norma regola l'obbligo di fedeltà durante il rapporto?","a":"L'art. 2105 c.c.","v":{"p":null,"e":[["art. 2105","n",["2105"]]],"r":[]},"t":"e"},{"id":"DL-13a~0","s":"DL-13a","q":"Qual è il cuore di «Le mansioni e lo ius variandi»? Rispondi in due o tre frasi.","a":"Le mansioni sono i compiti concreti che il lavoratore deve svolgere e che il datore può pretendere. Per l'art. 2103 c.c. il lavoratore va adibito alle mansioni per cui è stato assunto, a quelle del superiore inquadramento acquisito o a mansioni dello stesso livello e categoria legale delle ultime svolte: entro questi limiti il datore esercita lo ius variandi.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-13a~1","s":"DL-13a","q":"Dopo quanto l'assegnazione a mansioni superiori diventa definitiva, in mancanza di CCNL?","a":"Dopo 6 mesi continuativi, salvo sostituzione di un assente.","v":{"p":null,"e":[["6","n",["6"]],["mesi","k",["mes"]],["continuativi","k",["continua"]],["sostituzione","k",["sostituz"]],["assente","k",["assen"]]],"r":[]}},{"id":"DL-13a~2","s":"DL-13a","q":"Demansionamento unilaterale: di quanto e con quale forma?","a":"Un solo livello sotto, stessa categoria legale, comunicazione scritta a pena di nullità.","v":{"p":null,"e":[["livello","k",["livel"]],["sotto","k",["sotto"]],["categoria","k",["catego"]],["legale","k",["legal"]],["comunicazione","k",["comunica"]],["scritta","k",["scrit"]],["pena","k",["pen"]],["nullità","k",["nulli","invalid","inefficac","privo","priva","nessun effett","non ha effett","non produce effett"]]],"r":[]}},{"id":"DL-13a~3","s":"DL-13a","q":"Dove si stipula il patto di demansionamento?","a":"In sede protetta (art. 2113 c.c.: giudice, ITL, commissioni di certificazione).","v":{"p":null,"e":[["protetta","k",["prote"]]],"r":[["art. 2113 c.c.",["2113"]]]}},{"id":"DL-15a~0","s":"DL-15a","q":"Qual è il cuore di «Gli impianti audiovisivi e i controlli a distanza»? Rispondi in due o tre frasi.","a":"L'art. 4 St. lav. vieta che il controllo a distanza dei lavoratori sia l'unica finalità di impianti e strumenti. Impianti audiovisivi e altri strumenti da cui deriva anche un controllo a distanza sono ammessi solo per esigenze organizzative e produttive, per la sicurezza del lavoro o per la tutela del patrimonio, previo accordo sindacale o autorizzazione dell'ITL.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-15a~1","s":"DL-15a","q":"Senza accordo sindacale, chi autorizza gli impianti di controllo a distanza?","a":"L'Ispettorato territoriale del lavoro.","v":{"p":null,"e":[["Ispettorato","k",["ispettor"]],["territoriale","k",["territor"]],["lavoro","k",["lavor","dipendent","prestator"]]],"r":[]}},{"id":"DL-15a~2","s":"DL-15a","q":"Per quali strumenti non servono accordo né autorizzazione?","a":"Strumenti usati per la prestazione (pc, telefono) e di rilevazione accessi e presenze.","v":{"p":null,"e":[["usati","k",["usati"]],["prestazione","k",["prestazi"]],["rilevazione","k",["rilevazi"]],["accessi","k",["acces"]],["presenze","k",["prese"]]],"r":[]}},{"id":"DL-15a~3","s":"DL-15a","q":"A quale condizione i dati raccolti sono utilizzabili anche a fini disciplinari?","a":"Adeguata informazione al lavoratore e rispetto della normativa privacy.","v":{"p":null,"e":[["Adeguata","k",["adegu"]],["informazione","k",["informaz"]],["lavoratore","k",["lavorat","dipendent","prestator"]],["normativa","k",["normat"]],["privacy","k",["priva","nessun","inefficac","null","non ha effett","non produce","non vale"]]],"r":[]}},{"id":"DL-X19~0","s":"DL-X19","q":"Qual è il cuore di «La protezione dei dati personali del lavoratore»? Rispondi in due o tre frasi.","a":"Il datore di lavoro tratta i dati dei dipendenti come titolare del trattamento secondo il Regolamento UE 2016/679 (GDPR) e il Codice privacy (D.Lgs. 196/2003), che per il rapporto di lavoro rinvia ai divieti di indagine dell'art. 8 e alle regole sui controlli a distanza dell'art. 4 dello Statuto dei lavoratori.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-X19~1","s":"DL-X19","q":"Quale articolo del GDPR consente regole specifiche per il trattamento dei dati nel lavoro?","a":"L'art. 88 GDPR.","v":{"p":null,"e":[["art. 88","n",["88"]]],"r":[]},"t":"e"},{"id":"DL-X19~2","s":"DL-X19","q":"Quale articolo del Codice privacy rinvia al divieto di indagini sulle opinioni (art. 8 St. lav.)?","a":"L'art. 113.","v":{"p":null,"e":[["art. 113","n",["113"]]],"r":[]},"t":"e"},{"id":"DL-X19~3","s":"DL-X19","q":"Con quali sanzioni è punita la violazione degli artt. 4, c. 1, e 8 St. lav.?","a":"Sanzioni penali dell'art. 38 St. lav. (art. 171 Codice privacy).","v":{"p":null,"e":[["art. 38","n",["38"]],["penali","k",["penal"]]],"r":[["art. 171",["171"]]]},"t":"e"},{"id":"DL-14a~0","s":"DL-14a","q":"Qual è il cuore di «Le informazioni da fornire al lavoratore all'assunzione»? Rispondi in due o tre frasi.","a":"All'assunzione il datore deve informare il lavoratore per iscritto sulle condizioni applicabili al contratto e al rapporto (art. 1 D.Lgs. 152/1997, riscritto dal Decreto trasparenza, D.Lgs. 104/2022).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-14a~1","s":"DL-14a","q":"Quale decreto ha riscritto l'informativa all'assunzione?","a":"Il Decreto trasparenza, D.Lgs. 104/2022 (art. 1 D.Lgs. 152/1997).","v":{"p":null,"e":[["104/2022","n",["104","2022"]],["trasparenza","k",["traspare"]]],"r":[["152/1997",["152","1997"]],["art. 1",["1"]]]},"t":"e"},{"id":"DL-14a~2","s":"DL-14a","q":"Entro quanto vanno date le informazioni mancanti per iscritto?","a":"Entro 7 giorni; ferie, congedi e CCNL entro un mese.","v":{"p":null,"e":[["7","n",["7"]],["giorni","k",["giorn","gg"]],["ferie","k",["ferie"]],["congedi","k",["conge"]],["CCNL","k",["ccnl","contratto collettivo","contratti collettivi"]],["mese","k",["mes"]]],"r":[]}},{"id":"DL-14a~3","s":"DL-14a","q":"Quale dato ha aggiunto il D.L. 62/2026 all'informativa?","a":"Il codice del CCNL applicato (lett. q-bis).","v":{"p":null,"e":[["codice","k",["codic"]],["CCNL","k",["ccnl","contratto collettivo","contratti collettivi"]],["applicato","k",["applic"]]],"r":[]}},{"id":"DL-19b~0","s":"DL-19b","q":"Qual è il cuore di «Il prospetto paga e il libro unico del lavoro»? Rispondi in due o tre frasi.","a":"Il prospetto paga è il documento analitico che il datore consegna a ogni pagamento, con le voci della retribuzione e tutte le ritenute (art. 1 L. 4/1953); il libro unico del lavoro (LUL) registra per ogni lavoratore dati del rapporto, presenze e trattamento economico (artt. 39-40 D.L. 112/2008).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-19b~1","s":"DL-19b","q":"Quale legge disciplina il prospetto paga?","a":"L'art. 1 L. 4/1953.","v":{"p":null,"e":[["4/1953","n",["4","1953"]],["art. 1","n",["1"]]],"r":[]},"t":"e"},{"id":"DL-19b~2","s":"DL-19b","q":"Entro quando si registrano i dati nel LUL e per quanto si conserva?","a":"Entro la fine del mese successivo; conservazione 5 anni dall'ultima registrazione.","v":{"p":null,"e":[["5","m",["5"]],["fine","k",["fin"]],["mese","k",["mes"]],["successivo","k",["success"]],["anni","k",["ann"]],["ultima","k",["ultim"]]],"r":[]}},{"id":"DL-19b~3","s":"DL-19b","q":"La firma del lavoratore sulla busta paga prova il pagamento?","a":"No (art. 1, c. 912, L. 205/2017).","v":{"p":"n","e":[],"r":[["205/2017",["205","2017"]],["art. 1",["1"]]]}},{"id":"DL-20a~0","s":"DL-20a","q":"Qual è il cuore di «La tracciabilità della retribuzione»? Rispondi in due o tre frasi.","a":"Dalla legge di bilancio 2018 è vietato pagare la retribuzione in contanti direttamente al lavoratore: i datori e i committenti devono usare strumenti tracciabili tramite banca o ufficio postale (art. 1, c. 910 ss., L. 205/2017).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-20a~1","s":"DL-20a","q":"Da quando è vietato pagare la retribuzione in contanti?","a":"Dalla legge di bilancio 2018 (art. 1, c. 910 ss., L. 205/2017).","v":{"p":null,"e":[["2018","n",["2018"]],["legge","k",["legge"]],["bilancio","k",["bilan"]]],"r":[["205/2017",["205","2017"]],["art. 1",["1"]]]},"t":"d"},{"id":"DL-20a~2","s":"DL-20a","q":"Sanzione per il pagamento non tracciato della retribuzione?","a":"Da 1.000 a 5.000 euro (c. 913).","v":{"p":null,"e":[["1.000","n",["1000"]],["5.000","n",["5000"]],["euro","k",["eur"]]],"r":[]},"t":"d"},{"id":"DL-20a~3","s":"DL-20a","q":"Vitto e alloggio possono essere pagati in contanti?","a":"Sì: il divieto riguarda solo la retribuzione (nota INL 7369/2018).","v":{"p":"s","e":[["divieto","k",["divie","vietat","vieta"]],["riguarda","k",["rigua"]],["retribuzione","k",["retribuz","stipend","paga","salari"]]],"r":[["7369/2018",["7369","2018"]]]}},{"id":"DL-14b~0","s":"DL-14b","q":"Qual è il cuore di «Le ferie»? Rispondi in due o tre frasi.","a":"Le ferie annuali retribuite sono un diritto irrinunciabile del lavoratore (art. 36, c. 3, Cost.; art. 2109 c.c.): servono a recuperare le energie psicofisiche e a partecipare alla vita familiare e sociale. Il D.Lgs. 66/2003 (art. 10) ne fissa il minimo in 4 settimane.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-14b~1","s":"DL-14b","q":"Minimo legale di ferie annuali?","a":"4 settimane (art. 10 D.Lgs. 66/2003).","v":{"p":null,"e":[["4","n",["4"]],["settimane","k",["settim"]]],"r":[["66/2003",["66","2003"]],["art. 10",["10"]]]}},{"id":"DL-14b~2","s":"DL-14b","q":"Come si godono le 4 settimane di ferie?","a":"Almeno 2 nell'anno di maturazione; le altre 2 entro i 18 mesi successivi.","v":{"p":null,"e":[["2","n",["2"]],["18","m",["18"]],["anno","k",["ann"]],["maturazione","k",["maturazi"]],["mesi","k",["mes"]],["successivi","k",["success"]]],"r":[]}},{"id":"DL-14b~3","s":"DL-14b","q":"Si possono monetizzare le ferie legali?","a":"No: l'indennità sostitutiva è ammessa solo alla cessazione o nei contratti a termine brevi.","v":{"p":"n","e":[["indennità","k",["indenn"]],["sostitutiva","k",["sostitut"]],["ammessa","k",["ammes"]],["cessazione","k",["cessazi"]],["contratti","k",["contra","rapport"]],["termine","k",["termi","scadenz"]],["brevi","k",["brevi"]]],"r":[]}},{"id":"DL-16a~0","s":"DL-16a","q":"Qual è il cuore di «L'orario di lavoro nel D.Lgs. 66/2003»? Rispondi in due o tre frasi.","a":"Il D.Lgs. 66/2003 definisce orario di lavoro qualsiasi periodo in cui il lavoratore è al lavoro, a disposizione del datore e nell'esercizio delle sue funzioni (art. 1, c. 2, lett. a). Fissa l'orario normale, il limite massimo medio, i riposi e le pause; ai CCNL lascia ampi spazi.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-16a~1","s":"DL-16a","q":"Orario normale di lavoro?","a":"40 ore settimanali (art. 3 D.Lgs. 66/2003).","v":{"p":null,"e":[["40","n",["40"]],["ore","k",["ore"]],["settimanali","k",["settiman"]]],"r":[["66/2003",["66","2003"]],["art. 3",["3"]]]}},{"id":"DL-16a~2","s":"DL-16a","q":"Durata massima media della settimana lavorativa?","a":"48 ore ogni 7 giorni, straordinario compreso, come media su 4 mesi (art. 4).","v":{"p":null,"e":[["48","n",["48"]],["7","n",["7"]],["4","n",["4"]],["ore","k",["ore"]],["giorni","k",["giorn","gg"]],["straordinario","k",["straordi"]],["compreso","k",["compr"]],["mesi","k",["mes"]]],"r":[["art. 4",["4"]]]}},{"id":"DL-16a~3","s":"DL-16a","q":"Riposo giornaliero e settimanale minimi?","a":"11 ore consecutive ogni 24; 24 ore consecutive ogni 7 giorni, come media su 14.","v":{"p":null,"e":[["11","n",["11"]],["24","n",["24"]],["7","m",["7"]],["14","m",["14"]],["ore","k",["ore"]],["consecutive","k",["consecut"]],["media","k",["media"]]],"r":[]}},{"id":"DL-17a~0","s":"DL-17a","q":"Qual è il cuore di «Il lavoro straordinario e il lavoro supplementare»? Rispondi in due o tre frasi.","a":"Lo straordinario è il lavoro prestato oltre l'orario normale di 40 ore settimanali (art. 1, c. 2, lett. c, D.Lgs. 66/2003); il supplementare è il lavoro del part-time oltre l'orario concordato ma entro l'orario normale (art. 6 D.Lgs. 81/2015).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-17a~1","s":"DL-17a","q":"Senza CCNL, limite annuo di straordinario?","a":"250 ore l'anno, con accordo tra le parti.","v":{"p":null,"e":[["250","n",["250"]],["ore","k",["ore"]],["accordo","k",["accor"]],["parti","k",["parti"]]],"r":[]}},{"id":"DL-17a~2","s":"DL-17a","q":"Differenza tra straordinario e supplementare?","a":"Straordinario oltre l'orario normale di 40 ore; supplementare nel part-time oltre l'orario concordato ma entro il normale.","v":{"p":null,"e":[["40","n",["40"]],["orario","k",["orari"]],["normale","k",["norma"]],["ore","k",["ore"]],["part","k",["part"]],["time","k",["tim"]],["concordato","k",["concord"]]],"r":[]}},{"id":"DL-17a~3","s":"DL-17a","q":"Imposta sostitutiva 2026 su notturno, festivo e turni?","a":"15%, per redditi di lavoro dipendente 2025 fino a 40.000 euro (L. 199/2025).","v":{"p":null,"e":[["15%","n",["15"]],["2025","n",["2025"]],["40.000","n",["40000"]],["redditi","k",["reddi"]],["lavoro","k",["lavor","dipendent","prestator"]],["dipendente","k",["dipende","lavorat"]],["euro","k",["eur"]]],"r":[["199/2025",["199","2025"]]]},"t":"d"},{"id":"DL-11a~0","s":"DL-11a","q":"Qual è il cuore di «Il welfare aziendale»? Rispondi in due o tre frasi.","a":"Il welfare aziendale è l'insieme di beni, servizi e somme che il datore eroga ai dipendenti con finalità sociali (educazione, assistenza, salute, conciliazione vita-lavoro), in tutto o in parte esclusi dal reddito di lavoro dipendente e dai contributi (art. 51 TUIR).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-11a~1","s":"DL-11a","q":"Quale articolo del TUIR regola il welfare aziendale esente?","a":"L'art. 51 TUIR.","v":{"p":null,"e":[["art. 51","n",["51"]]],"r":[]},"t":"p"},{"id":"DL-11a~2","s":"DL-11a","q":"Soglia di esenzione dei fringe benefit per il 2025-2027?","a":"1.000 euro, 2.000 con figli a carico (L. 207/2024, c. 390).","v":{"p":null,"e":[["1.000","n",["1000"]],["2.000","n",["2000"]],["euro","k",["eur"]],["figli","k",["figli"]],["carico","k",["caric"]]],"r":[["207/2024",["207","2024"]]]}},{"id":"DL-11a~3","s":"DL-11a","q":"Limite di reddito per convertire il premio di risultato in welfare?","a":"Reddito di lavoro dipendente dell'anno prima fino a 80.000 euro.","v":{"p":null,"e":[["80.000","n",["80000"]],["lavoro","k",["lavor","dipendent","prestator"]],["dipendente","k",["dipende","lavorat"]],["anno","k",["ann"]],["euro","k",["eur"]]],"r":[]},"t":"d"},{"id":"DL-18a~0","s":"DL-18a","q":"Qual è il cuore di «La retribuzione ai sensi dell'art. 36 della Costituzione»? Rispondi in due o tre frasi.","a":"Per l'art. 36 Cost. il lavoratore ha diritto a una retribuzione proporzionata alla quantità e qualità del suo lavoro e in ogni caso sufficiente ad assicurare a sé e alla famiglia un'esistenza libera e dignitosa. Proporzionalità e sufficienza sono requisiti inderogabili.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-18a~1","s":"DL-18a","q":"Quali sono i due requisiti della retribuzione per l'art. 36 Cost.?","a":"Proporzionalità e sufficienza.","v":{"p":null,"e":[["Proporzionalità","k",["proporzi"]],["sufficienza","k",["sufficie"]]],"r":[]}},{"id":"DL-18a~2","s":"DL-18a","q":"Quale norma consente al giudice di determinare la retribuzione?","a":"L'art. 2099, c. 2, c.c.","v":{"p":null,"e":[["art. 2099","n",["2099"]]],"r":[]},"t":"e"},{"id":"DL-18a~3","s":"DL-18a","q":"A quale parametro rinvia il salario giusto dell'art. 7 D.L. 62/2026?","a":"Al trattamento economico complessivo (TEC) del CCNL leader.","v":{"p":null,"e":[["trattamento","k",["trattame"]],["economico","k",["econom"]],["complessivo","k",["compless"]],["CCNL","k",["ccnl","contratto collettivo","contratti collettivi"]],["leader","k",["leade"]]],"r":[]}},{"id":"DL-18b~0","s":"DL-18b","q":"Qual è il cuore di «Il superminimo e gli altri elementi aggiuntivi della retribuzione»? Rispondi in due o tre frasi.","a":"La retribuzione si compone di elementi fissi stabiliti dal CCNL e di elementi accessori; il superminimo è la parte di retribuzione che supera i minimi tariffari, concessa individualmente (ad personam) o collettivamente.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-18b~1","s":"DL-18b","q":"Importo dell'EDR?","a":"10,33 euro per 13 mensilità.","v":{"p":null,"e":[["10,33","n",["10.33"]],["13","n",["13"]],["euro","k",["eur"]],["mensilità","k",["mensil"]]],"r":[]}},{"id":"DL-18b~2","s":"DL-18b","q":"Il contratto individuale può peggiorare il CCNL?","a":"No, può solo migliorarlo (art. 2077 c.c.).","v":{"p":"n","e":[["migliorarlo","k",["migliora"]]],"r":[["art. 2077 c.c.",["2077"]]]}},{"id":"DL-18b~3","s":"DL-18b","q":"Quale articolo dello Statuto vieta i trattamenti economici collettivi discriminatori?","a":"L'art. 16 St. lav.","v":{"p":null,"e":[["art. 16","n",["16"]]],"r":[]},"t":"e"},{"id":"S22-DL-20~0","s":"S22-DL-20","q":"Qual è il cuore di «La retribuzione, il prospetto paga e la prescrizione dei diritti del lavoratore»? Rispondi in due o tre frasi.","a":"La retribuzione è la prestazione fondamentale del datore: deve essere proporzionata e sufficiente (art. 36 Cost.), va documentata con il prospetto paga e pagata con strumenti tracciabili. I crediti retributivi si prescrivono in cinque anni, che oggi decorrono dalla cessazione del rapporto.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-DL-20~1","s":"S22-DL-20","q":"Prescrizione dei crediti retributivi e da quando decorre?","a":"5 anni, dalla cessazione del rapporto.","v":{"p":null,"e":[["5","n",["5"]],["anni","k",["ann"]],["cessazione","k",["cessazi"]],["rapporto","k",["rappo","contratt"]]],"r":[]}},{"id":"S22-DL-20~2","s":"S22-DL-20","q":"Prescrizione dei diritti non retributivi, come la qualifica superiore?","a":"10 anni (art. 2946 c.c.).","v":{"p":null,"e":[["10","n",["10"]],["anni","k",["ann"]]],"r":[["art. 2946 c.c.",["2946"]]]}},{"id":"S22-DL-20~3","s":"S22-DL-20","q":"Prescrizione presuntiva delle retribuzioni mensili?","a":"1 anno (art. 2955, n. 2, c.c.).","v":{"p":null,"e":[["1","n",["1"]],["anno","k",["ann"]]],"r":[["art. 2955",["2955"]]]},"t":"d"},{"id":"S22-DL-21~0","s":"S22-DL-21","q":"Qual è il cuore di «La sospensione del rapporto per impossibilità temporanea del lavoratore»? Rispondi in due o tre frasi.","a":"Quando il lavoratore non può lavorare per una causa che non gli è imputabile, il rapporto non si estingue ma resta sospeso. Le regole civilistiche dell'impossibilità sopravvenuta (artt. 1256 e 1463 c.c.) sono corrette dall'art. 2110 c.c.: conservazione del posto, anzianità e tutela economica per malattia, infortunio, gravidanza e puerperio.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-DL-21~1","s":"S22-DL-21","q":"Quale articolo del codice civile tutela il posto in caso di malattia e infortunio?","a":"L'art. 2110 c.c.","v":{"p":null,"e":[["art. 2110","n",["2110"]]],"r":[]},"t":"p"},{"id":"S22-DL-21~2","s":"S22-DL-21","q":"Le ferie chieste in malattia che effetto hanno sul comporto?","a":"Lo interrompono (Cass. ord. 582/2024).","v":{"p":null,"e":[["interrompono","k",["interrom"]]],"r":[["582/2024",["582","2024"]]]}},{"id":"S22-DL-21~3","s":"S22-DL-21","q":"Se l'inidoneità diventa permanente il rapporto si risolve da solo?","a":"No: serve il licenziamento per giustificato motivo oggettivo, previo repêchage.","v":{"p":"n","e":[["serve","k",["serve"]],["licenziamento","k",["licenzia","recess"]],["giustificato","k",["giustifi"]],["motivo","k",["motiv"]],["oggettivo","k",["oggett"]],["previo","k",["previ"]],["repêchage","k",["repech"]]],"r":[]}},{"id":"S22-DL-22~0","s":"S22-DL-22","q":"Qual è il cuore di «La sospensione del rapporto per impossibilità temporanea del datore di lavoro»? Rispondi in due o tre frasi.","a":"Quando è il datore a non poter ricevere la prestazione, la regola di fondo è che il rischio dell'impresa resta a suo carico: se rifiuta la prestazione offerta senza un motivo legittimo è in mora (art. 1206 c.c.) e deve la retribuzione. Il rapporto può essere sospeso senza retribuzione solo per cause non imputabili, e il sostegno al reddito passa per la cassa integrazione o i fondi di solidarietà.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-DL-22~1","s":"S22-DL-22","q":"Il datore che rifiuta senza motivo la prestazione offerta deve la retribuzione?","a":"Sì: è in mora del creditore (art. 1206 c.c.).","v":{"p":"s","e":[["mora","k",["mor"]],["creditore","k",["credit"]]],"r":[["art. 1206 c.c.",["1206"]]]}},{"id":"S22-DL-22~2","s":"S22-DL-22","q":"Nella sospensione ispettiva dell'attività, retribuzione e contributi sono dovuti?","a":"Sì (art. 14 D.Lgs. 81/2008).","v":{"p":"s","e":[],"r":[["81/2008",["81","2008"]],["art. 14",["14"]]]}},{"id":"S22-DL-22~3","s":"S22-DL-22","q":"Liquidazione giudiziale: dopo quanto, senza subentro del curatore, i rapporti cessano?","a":"Dopo 4 mesi, con effetto dalla data di apertura (art. 189 CCII).","v":{"p":null,"e":[["4","n",["4"]],["mesi","k",["mes"]],["effetto","k",["effet"]],["data","k",["dat"]],["apertura","k",["apert"]]],"r":[["art. 189",["189"]]]}},{"id":"DL-15b~0","s":"DL-15b","q":"Qual è il cuore di «Il mobbing»? Rispondi in due o tre frasi.","a":"Il mobbing è una nozione di dottrina e giurisprudenza, senza una norma specifica: una serie di condotte persecutorie, sistematiche e prolungate, del datore, dei superiori o dei colleghi, che lede la salute, la personalità o la dignità del lavoratore, spesso per estrometterlo dall'azienda.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-15b~1","s":"DL-15b","q":"Su quale norma si fonda la responsabilità del datore per mobbing?","a":"L'art. 2087 c.c. (responsabilità contrattuale), più l'art. 2043 c.c.","v":{"p":null,"e":[["art. 2087","n",["2087"]],["art. 2043","n",["2043"]]],"r":[]},"t":"p"},{"id":"DL-15b~2","s":"DL-15b","q":"Quali sono gli elementi del mobbing per la Cassazione?","a":"Pluralità di condotte persecutorie ripetute, evento lesivo, nesso causale, intento persecutorio.","v":{"p":null,"e":[["Pluralità","k",["plural"]],["condotte","k",["condo"]],["persecutorie","k",["persecut"]],["ripetute","k",["ripet"]],["evento","k",["event"]],["lesivo","k",["lesiv"]],["nesso","k",["nesso"]],["causale","k",["causa"]],["intento","k",["inten"]]],"r":[]}},{"id":"DL-15b~3","s":"DL-15b","q":"Che cos'è lo straining?","a":"Forma attenuata di mobbing: anche una sola azione con effetti duraturi o un ambiente stressogeno.","v":{"p":null,"e":[["Forma","k",["forma"]],["attenuata","k",["attenu"]],["mobbing","k",["mobbi"]],["sola","k",["sol"]],["azione","k",["azion"]],["effetti","k",["effet"]],["duraturi","k",["durat"]],["ambiente","k",["ambie"]],["stressogeno","k",["stressog"]]],"r":[]}},{"id":"DL-17b~0","s":"DL-17b","q":"Qual è il cuore di «Le misure generali di tutela nel D.Lgs. 81/2008»? Rispondi in due o tre frasi.","a":"L'art. 15 D.Lgs. 81/2008 elenca le misure generali di tutela della salute e della sicurezza: è il programma della prevenzione, che parte dalla valutazione dei rischi e dà priorità all'eliminazione del rischio alla fonte. Si collega all'obbligo generale di sicurezza dell'art. 2087 c.c.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-17b~1","s":"DL-17b","q":"Quale articolo del D.Lgs. 81/2008 elenca le misure generali di tutela?","a":"L'art. 15.","v":{"p":null,"e":[["art. 15","n",["15"]]],"r":[]},"t":"e"},{"id":"DL-17b~2","s":"DL-17b","q":"Protezione collettiva o individuale: quale ha priorità?","a":"Quella collettiva.","v":{"p":null,"e":[["collettiva","k",["collett"]]],"r":[]}},{"id":"DL-17b~3","s":"DL-17b","q":"A quale norma del codice civile si collega l'obbligo generale di sicurezza?","a":"L'art. 2087 c.c.","v":{"p":null,"e":[["art. 2087","n",["2087"]]],"r":[]},"t":"p"},{"id":"DL-23b~0","s":"DL-23b","q":"Qual è il cuore di «La valutazione dei rischi»? Rispondi in due o tre frasi.","a":"La valutazione dei rischi è l'adempimento centrale della sicurezza: il datore deve valutare tutti i rischi per la salute e la sicurezza dei lavoratori e riportarne l'esito nel documento di valutazione dei rischi, il DVR (artt. 17 e 28 D.Lgs. 81/2008). È un obbligo che il datore non può delegare.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-23b~1","s":"DL-23b","q":"Quali articoli del D.Lgs. 81/2008 regolano valutazione dei rischi e DVR?","a":"Artt. 17 e 28 (e 29 per le modalità).","v":{"p":null,"e":[["art. 17","n",["17"]],["art. 28","n",["28"]]],"r":[]},"t":"p"},{"id":"DL-23b~2","s":"DL-23b","q":"Entro quanto va aggiornato il DVR dopo una modifica rilevante?","a":"Entro 30 giorni.","v":{"p":null,"e":[["30","n",["30"]],["giorni","k",["giorn","gg"]]],"r":[]},"t":"d"},{"id":"DL-23b~3","s":"DL-23b","q":"Quali contratti sono vietati senza DVR?","a":"Contratti a termine, somministrazione e lavoro intermittente.","v":{"p":null,"e":[["termine","k",["termi","scadenz"]],["somministrazione","k",["somminis"]],["lavoro","k",["lavor","dipendent","prestator"]],["intermittente","k",["intermit"]]],"r":[]}},{"id":"DL-X17~0","s":"DL-X17","q":"Qual è il cuore di «I soggetti della sicurezza aziendale e la delega di funzioni»? Rispondi in due o tre frasi.","a":"Il sistema di prevenzione del D.Lgs. 81/2008 ruota attorno al datore di lavoro, che può delegare molte funzioni ma non la valutazione dei rischi con il DVR né la nomina del RSPP (art. 17); accanto a lui operano dirigenti e preposti (artt. 18-19), il servizio di prevenzione e protezione, il medico competente e il rappresentante dei lavoratori per la sicurezza.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-X17~1","s":"DL-X17","q":"Quali obblighi del datore non sono delegabili?","a":"Valutazione dei rischi con il DVR e nomina del RSPP (art. 17).","v":{"p":null,"e":[["DVR","k",["dvr","documento di valutazione","valutazione dei rischi"]],["nomina","k",["nomin"]],["RSPP","k",["rspp","responsabile del servizio"]]],"r":[["art. 17",["17"]]]}},{"id":"DL-X17~2","s":"DL-X17","q":"Requisiti formali della delega di funzioni?","a":"Atto scritto con data certa, poteri e autonomia di spesa, accettazione scritta, pubblicità (art. 16).","v":{"p":null,"e":[["Atto","k",["att"]],["scritto","k",["scrit"]],["data","k",["dat"]],["certa","k",["certa"]],["poteri","k",["poter"]],["autonomia","k",["autono"]],["spesa","k",["spesa"]],["accettazione","k",["accettaz"]],["pubblicità","k",["pubblic"]]],"r":[["art. 16",["16"]]]}},{"id":"DL-X17~3","s":"DL-X17","q":"Fino a quanti lavoratori l'RLS è di norma eletto direttamente o territoriale?","a":"Fino a 15 lavoratori.","v":{"p":null,"e":[["15","n",["15"]]],"r":[]},"t":"d"},{"id":"DL-5b~0","s":"DL-5b","q":"Qual è il cuore di «Il congedo di maternità obbligatorio»? Rispondi in due o tre frasi.","a":"Il congedo di maternità è l'astensione obbligatoria della lavoratrice nei due mesi prima della data presunta del parto e nei tre mesi dopo (art. 16 D.Lgs. 151/2001), con un'indennità INPS dell'80% della retribuzione. Attua la protezione della madre e del bambino voluta dagli artt. 31 e 37 Cost.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-5b~1","s":"DL-5b","q":"Durata del congedo di maternità obbligatorio?","a":"2 mesi prima della data presunta del parto e 3 mesi dopo (art. 16 D.Lgs. 151/2001).","v":{"p":null,"e":[["2","n",["2"]],["3","n",["3"]],["mesi","k",["mes"]],["data","k",["dat"]],["presunta","k",["presu"]],["parto","k",["parto"]]],"r":[["151/2001",["151","2001"]],["art. 16",["16"]]]}},{"id":"DL-5b~2","s":"DL-5b","q":"Misura dell'indennità di maternità INPS?","a":"80% della retribuzione.","v":{"p":null,"e":[["80%","n",["80"]],["retribuzione","k",["retribuz","stipend","paga","salari"]]],"r":[]}},{"id":"DL-5b~3","s":"DL-5b","q":"Fino a quando vige il divieto di licenziamento della lavoratrice madre?","a":"Dall'inizio della gravidanza fino a un anno del bambino (art. 54).","v":{"p":null,"e":[["inizio","k",["inizi"]],["gravidanza","k",["gravida"]],["anno","k",["ann"]],["bambino","k",["bambi"]]],"r":[["art. 54",["54"]]]}},{"id":"DL-6b~0","s":"DL-6b","q":"Qual è il cuore di «L'interdizione anticipata dal lavoro»? Rispondi in due o tre frasi.","a":"L'interdizione anticipata dal lavoro è il provvedimento che estende l'astensione obbligatoria della lavoratrice prima dei due mesi antecedenti il parto, o la prolunga dopo, quando la gravidanza o il lavoro mettono a rischio la salute della madre o del bambino (art. 17 D.Lgs. 151/2001).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-6b~1","s":"DL-6b","q":"Chi dispone l'interdizione anticipata dal lavoro?","a":"L'ASL per le gravi complicanze della gravidanza; l'Ispettorato territoriale del lavoro per lavoro pregiudizievole o se lo spostamento ad altre mansioni è impossibile (art. 17 D.Lgs. 151/2001).","v":{"p":null,"e":[["ASL","k",["asl"]],["gravi","k",["gravi"]],["complicanze","k",["complica"]],["gravidanza","k",["gravida"]],["Ispettorato","k",["ispettor"]],["territoriale","k",["territor"]],["pregiudizievole","k",["pregiudi"]],["spostamento","k",["spostame"]],["mansioni","k",["mansi"]],["impossibile","k",["impossib"]]],"r":[["151/2001",["151","2001"]],["art. 17",["17"]]]}},{"id":"DL-6b~2","s":"DL-6b","q":"Fino a quando vale il divieto di lavori pericolosi per la lavoratrice?","a":"Durante la gravidanza e fino a 7 mesi dopo il parto (art. 7).","v":{"p":null,"e":[["7","n",["7"]],["Durante","k",["duran"]],["gravidanza","k",["gravida"]],["mesi","k",["mes"]],["parto","k",["parto"]]],"r":[["art. 7",["7"]]]},"t":"d"},{"id":"DL-6b~3","s":"DL-6b","q":"Pena per chi adibisce la lavoratrice a lavori vietati?","a":"Arresto fino a 6 mesi; non si applica la prescrizione del D.Lgs. 758/1994.","v":{"p":null,"e":[["6","n",["6"]],["758/1994","m",["758","1994"]],["Arresto","k",["arres"]],["mesi","k",["mes"]],["applica","k",["appli"]],["prescrizione","k",["prescriz"]]],"r":[]},"t":"d"},{"id":"DL-7b~0","s":"DL-7b","q":"Qual è il cuore di «Il congedo di paternità obbligatorio»? Rispondi in due o tre frasi.","a":"Il congedo di paternità obbligatorio spetta al padre lavoratore dipendente per 10 giorni lavorativi (20 in caso di parto plurimo), fruibili anche in modo non continuativo dai due mesi prima ai cinque mesi dopo il parto, con un'indennità INPS del 100% (art. 27-bis D.Lgs. 151/2001, introdotto dal D.Lgs. 105/2022).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-7b~1","s":"DL-7b","q":"Durata del congedo di paternità obbligatorio?","a":"10 giorni lavorativi (20 se parto plurimo).","v":{"p":null,"e":[["10","n",["10"]],["giorni","k",["giorn","gg"]],["lavorativi","k",["lavorat","dipendent","prestator"]]],"r":[]}},{"id":"DL-7b~2","s":"DL-7b","q":"Indennità del congedo di paternità obbligatorio?","a":"100%, a carico INPS (art. 27-bis D.Lgs. 151/2001).","v":{"p":null,"e":[["100%","n",["100"]],["carico","k",["caric"]],["INPS","k",["inps"]]],"r":[["151/2001",["151","2001"]],["art. 27",["27"]]]}},{"id":"DL-7b~3","s":"DL-7b","q":"Preavviso al datore per il congedo di paternità?","a":"Almeno 5 giorni, per iscritto.","v":{"p":null,"e":[["5","n",["5"]],["giorni","k",["giorn","gg"]],["iscritto","k",["iscri"]]],"r":[]},"t":"d"},{"id":"DL-10b~0","s":"DL-10b","q":"Qual è il cuore di «Il collocamento obbligatorio dei disabili»? Rispondi in due o tre frasi.","a":"La L. 68/1999 ha sostituito il vecchio collocamento obbligatorio con il collocamento mirato: valorizzare le capacità residue delle persone con disabilità e inserirle nel posto più adatto, con un obbligo di assunzione per i datori da 15 dipendenti in su.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-10b~1","s":"DL-10b","q":"Da quanti dipendenti scatta l'obbligo di assunzione dei disabili?","a":"Da 15 dipendenti in su (L. 68/1999).","v":{"p":null,"e":[["15","n",["15"]]],"r":[["68/1999",["68","1999"]]]}},{"id":"DL-10b~2","s":"DL-10b","q":"Quota di riserva per i datori con più di 50 dipendenti?","a":"Il 7%.","v":{"p":null,"e":[["7%","n",["7"]]],"r":[]}},{"id":"DL-10b~3","s":"DL-10b","q":"Termine per inviare il prospetto informativo disabili?","a":"Entro il 31 gennaio, se nell'anno è cambiata la situazione occupazionale.","v":{"p":null,"e":[["31","n",["31"]],["gennaio","k",["genna"]],["anno","k",["ann"]],["cambiata","k",["cambi"]],["situazione","k",["situazi"]],["occupazionale","k",["occupazi"]]],"r":[]}},{"id":"DL-12a~0","s":"DL-12a","q":"Qual è il cuore di «L'età minima e il lavoro dei minori»? Rispondi in due o tre frasi.","a":"L'art. 37 Cost. affida alla legge il limite minimo di età per il lavoro salariato e garantisce ai minori, a parità di lavoro, la parità di retribuzione. La disciplina è la L. 977/1967, adeguata alla dir. 94/33/CE dal D.Lgs. 345/1999: l'età minima coincide con la fine dell'obbligo di istruzione.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-12a~1","s":"DL-12a","q":"Età minima di accesso al lavoro?","a":"16 anni, con almeno 10 anni di istruzione obbligatoria.","v":{"p":null,"e":[["16","n",["16"]],["10","n",["10"]],["anni","k",["ann"]],["istruzione","k",["istruzi"]],["obbligatoria","k",["obbligat","obblig"]]],"r":[]}},{"id":"DL-12a~2","s":"DL-12a","q":"Orario massimo degli adolescenti?","a":"8 ore al giorno e 40 a settimana; vietato il notturno.","v":{"p":null,"e":[["8","n",["8"]],["40","n",["40"]],["ore","k",["ore"]],["giorno","k",["giorn","gg"]],["settimana","k",["settim"]],["vietato","k",["vieta","divieto","divieti"]],["notturno","k",["nottu"]]],"r":[]},"t":"d"},{"id":"DL-12a~3","s":"DL-12a","q":"Quale legge disciplina il lavoro dei minori?","a":"La L. 977/1967 (adeguata dal D.Lgs. 345/1999).","v":{"p":null,"e":[["977/1967","n",["977","1967"]]],"r":[["345/1999",["345","1999"]]]},"t":"e"},{"id":"DL-X15~0","s":"DL-X15","q":"Qual è il cuore di «Il trasferimento d'azienda e la tutela dei lavoratori»? Rispondi in due o tre frasi.","a":"Nel trasferimento d'azienda, cioè ogni operazione che cambia il titolare di un'attività economica organizzata che conserva la propria identità (compresi affitto e usufrutto, anche di un ramo), il rapporto di lavoro continua con il cessionario e il lavoratore conserva tutti i diritti maturati (art. 2112 c.c.); nelle aziende con più di 15 dipendenti cedente e cessionario devono prima informare e consultare i sindacati (art. 47 L. 428/1990).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-X15~1","s":"DL-X15","q":"Nel trasferimento d'azienda serve il consenso del lavoratore?","a":"No: il rapporto prosegue con il cessionario (art. 2112 c.c.).","v":{"p":"n","e":[["rapporto","k",["rappo","contratt"]],["prosegue","k",["prose"]],["cessionario","k",["cessiona"]]],"r":[["art. 2112 c.c.",["2112"]]]}},{"id":"DL-X15~2","s":"DL-X15","q":"Con quanto anticipo va fatta la comunicazione sindacale dell'art. 47 L. 428/1990?","a":"Almeno 25 giorni prima, se gli occupati sono più di 15.","v":{"p":null,"e":[["25","n",["25"]],["15","n",["15"]],["giorni","k",["giorn","gg"]],["occupati","k",["occup"]]],"r":[]}},{"id":"DL-X15~3","s":"DL-X15","q":"Entro quanto il lavoratore può dimettersi per giusta causa dopo il trasferimento?","a":"Se le condizioni cambiano sostanzialmente nei 3 mesi successivi.","v":{"p":null,"e":[["3","n",["3"]],["condizioni","k",["condizi"]],["cambiano","k",["cambi"]],["sostanzialmente","k",["sostanzi"]],["mesi","k",["mes"]],["successivi","k",["success"]]],"r":[]},"t":"d"},{"id":"DL-X18~0","s":"DL-X18","q":"Qual è il cuore di «Il whistleblowing nel settore privato»? Rispondi in due o tre frasi.","a":"Il D.Lgs. 24/2023, che recepisce la direttiva (UE) 2019/1937, protegge chi segnala violazioni di norme nazionali o europee apprese nel contesto di lavoro: le imprese obbligate devono attivare canali interni riservati, il segnalante può in certi casi rivolgersi all'ANAC e ogni ritorsione nei suoi confronti è nulla.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-X18~1","s":"DL-X18","q":"Da quanti dipendenti medi un'impresa privata deve attivare il canale di whistleblowing?","a":"Almeno 50 (o settori sensibili, o modello 231).","v":{"p":null,"e":[["50","n",["50"]]],"r":[]}},{"id":"DL-X18~2","s":"DL-X18","q":"Tempi di avviso e riscontro nel canale interno?","a":"Avviso entro 7 giorni, riscontro entro 3 mesi.","v":{"p":null,"e":[["7","n",["7"]],["3","n",["3"]],["giorni","k",["giorn","gg"]],["mesi","k",["mes"]]],"r":[]},"t":"d"},{"id":"DL-X18~3","s":"DL-X18","q":"Sanzioni ANAC per ritorsioni o mancata istituzione dei canali?","a":"Da 10.000 a 50.000 euro (art. 21 D.Lgs. 24/2023).","v":{"p":null,"e":[["10.000","n",["10000"]],["50.000","n",["50000"]],["euro","k",["eur"]]],"r":[["24/2023",["24","2023"]],["art. 21",["21"]]]},"t":"d"},{"id":"S22-DL-6~0","s":"S22-DL-6","q":"Qual è il cuore di «L'assunzione di lavoratori stranieri, comunitari e non comunitari»? Rispondi in due o tre frasi.","a":"L'assunzione di uno straniero segue regole diverse secondo la cittadinanza. Il cittadino UE gode della libera circolazione e si assume come un italiano. Il cittadino extra UE residente all'estero entra di regola nelle quote del decreto flussi, con nulla osta dello Sportello unico per l'immigrazione e contratto di soggiorno (D.Lgs. 286/1998, artt. 21-27).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-DL-6~1","s":"S22-DL-6","q":"Quale testo unico regola l'ingresso dei lavoratori extra UE?","a":"Il D.Lgs. 286/1998, artt. 21-27.","v":{"p":null,"e":[["286/1998","n",["286","1998"]],["art. 21-27","n",["21","27"]]],"r":[]},"t":"e"},{"id":"S22-DL-6~2","s":"S22-DL-6","q":"Validità del nulla osta al lavoro?","a":"6 mesi; rilascio entro 60 giorni.","v":{"p":null,"e":[["6","n",["6"]],["60","m",["60"]],["mesi","k",["mes"]],["rilascio","k",["rilas"]],["giorni","k",["giorn","gg"]]],"r":[]},"t":"d"},{"id":"S22-DL-6~3","s":"S22-DL-6","q":"Pena per l'occupazione di stranieri senza permesso di soggiorno?","a":"Reclusione da 6 mesi a 3 anni e multa di 5.000 euro per lavoratore.","v":{"p":null,"e":[["6","n",["6"]],["3","n",["3"]],["5.000","n",["5000"]],["Reclusione","k",["reclusi"]],["mesi","k",["mes"]],["anni","k",["ann"]],["multa","k",["multa"]],["euro","k",["eur"]],["lavoratore","k",["lavorat","dipendent","prestator"]]],"r":[]},"t":"d"},{"id":"DL-X14~0","s":"DL-X14","q":"Qual è il cuore di «Il licenziamento collettivo: presupposti, procedura e sanzioni»? Rispondi in due o tre frasi.","a":"Si ha licenziamento collettivo quando un datore con più di 15 dipendenti, per riduzione o trasformazione dell'attività o cessazione, intende effettuare almeno 5 licenziamenti nell'arco di 120 giorni nella stessa unità produttiva o in più unità della stessa provincia (art. 24 L. 223/1991): prima di licenziare deve svolgere la procedura sindacale e amministrativa dell'art. 4 e scegliere i lavoratori con i criteri dell'art. 5.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-X14~1","s":"DL-X14","q":"Presupposti del licenziamento collettivo?","a":"Più di 15 dipendenti, almeno 5 licenziamenti in 120 giorni (art. 24 L. 223/1991).","v":{"p":null,"e":[["15","n",["15"]],["5","n",["5"]],["120","n",["120"]],["dipendenti","k",["dipende","lavorat"]],["giorni","k",["giorn","gg"]]],"r":[["223/1991",["223","1991"]],["art. 24",["24"]]]}},{"id":"DL-X14~2","s":"DL-X14","q":"Durata delle fasi della procedura di licenziamento collettivo?","a":"Fase sindacale fino a 45 giorni, fase amministrativa fino a 30; dimezzate sotto 10 esuberi.","v":{"p":null,"e":[["45","n",["45"]],["30","n",["30"]],["10","m",["10"]],["sindacale","k",["sindac"]],["giorni","k",["giorn","gg"]],["amministrativa","k",["amminist"]],["dimezzate","k",["dimezz"]],["sotto","k",["sotto"]],["esuberi","k",["esube"]]],"r":[]},"t":"d"},{"id":"DL-X14~3","s":"DL-X14","q":"Criteri legali di scelta dei lavoratori da licenziare?","a":"Carichi di famiglia, anzianità, esigenze tecnico-produttive e organizzative (art. 5).","v":{"p":null,"e":[["Carichi","k",["caric"]],["famiglia","k",["famig"]],["anzianità","k",["anzian"]],["esigenze","k",["esige"]],["tecnico","k",["tecni"]],["produttive","k",["produtt"]],["organizzative","k",["organizz"]]],"r":[["art. 5",["5"]]]}},{"id":"DL-X20~0","s":"DL-X20","q":"Qual è il cuore di «La liquidazione giudiziale e i rapporti di lavoro subordinato»? Rispondi in due o tre frasi.","a":"L'apertura della liquidazione giudiziale non scioglie i rapporti di lavoro ma li sospende: entro 4 mesi (con possibile proroga fino a 8 mesi decisa dal giudice delegato) il curatore, autorizzato, decide se subentrare o recedere; senza decisione i rapporti cessano dalla data di apertura e la cessazione dà diritto alla NASpI (artt. 189-190 CCII).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-X20~1","s":"DL-X20","q":"Che effetto ha la liquidazione giudiziale sui rapporti di lavoro?","a":"Li sospende finché il curatore subentra o recede (art. 189 CCII).","v":{"p":null,"e":[["sospende","k",["sospe"]],["finché","k",["finch"]],["curatore","k",["curat"]],["subentra","k",["suben"]],["recede","k",["reced"]]],"r":[["art. 189",["189"]]]}},{"id":"DL-X20~2","s":"DL-X20","q":"Le dimissioni durante la sospensione che natura hanno?","a":"Si considerano per giusta causa, con effetto dalla data di apertura.","v":{"p":"s","e":[["considerano","k",["consider"]],["giusta","k",["giust"]],["causa","k",["causa"]],["effetto","k",["effet"]],["data","k",["dat"]],["apertura","k",["apert"]]],"r":[]}},{"id":"DL-X20~3","s":"DL-X20","q":"Chi garantisce TFR e ultime 3 mensilità in caso di insolvenza?","a":"Il Fondo di garanzia INPS (L. 297/1982; D.Lgs. 80/1992).","v":{"p":null,"e":[["Fondo","k",["fondo"]],["INPS","k",["inps"]]],"r":[["297/1982",["297","1982"]],["80/1992",["80","1992"]]]}},{"id":"S22-DL-23~0","s":"S22-DL-23","q":"Qual è il cuore di «Le dimissioni e la risoluzione consensuale»? Rispondi in due o tre frasi.","a":"Le dimissioni sono il recesso del lavoratore; la risoluzione consensuale è l'accordo tra le parti per chiudere il rapporto. Per entrambe vale, a pena di inefficacia, la procedura telematica dell'art. 26 D.Lgs. 151/2015, con 7 giorni per revocare. Le dimissioni richiedono il preavviso (art. 2118 c.c.), salvo la giusta causa (art. 2119 c.c.).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-DL-23~1","s":"S22-DL-23","q":"Quanti giorni ha il lavoratore per revocare le dimissioni telematiche?","a":"7 giorni (art. 26 D.Lgs. 151/2015).","v":{"p":null,"e":[["7","n",["7"]]],"r":[["151/2015",["151","2015"]],["art. 26",["26"]]]}},{"id":"S22-DL-23~2","s":"S22-DL-23","q":"Dopo quanti giorni di assenza ingiustificata si hanno dimissioni per fatti concludenti, senza CCNL?","a":"Oltre 15 giorni (art. 26, c. 7-bis).","v":{"p":null,"e":[["15","n",["15"]]],"r":[["art. 26",["26"]]]}},{"id":"S22-DL-23~3","s":"S22-DL-23","q":"Chi convalida le dimissioni della lavoratrice nei primi 3 anni del bambino?","a":"L'ITL (art. 55, c. 4, D.Lgs. 151/2001).","v":{"p":null,"e":[["ITL","k",["itl","ispettorato"]]],"r":[["151/2001",["151","2001"]],["art. 55",["55"]]]}},{"id":"S22-DL-25~0","s":"S22-DL-25","q":"Qual è il cuore di «Il licenziamento per giustificato motivo oggettivo e la procedura dell'art. 7 L. 604/1966»? Rispondi in due o tre frasi.","a":"Il giustificato motivo oggettivo comprende le ragioni inerenti all'attività produttiva, all'organizzazione del lavoro e al suo regolare funzionamento (art. 3 L. 604/1966). Il datore deve provare la ragione organizzativa effettiva, il nesso con il posto soppresso e l'impossibilità di ricollocare il lavoratore (repêchage). Nelle imprese con più di 15 dipendenti, per gli assunti prima del 7 marzo 2015, va prima esperita la procedura dell'art. 7 L. 604/1966 presso l'ITL.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-DL-25~1","s":"S22-DL-25","q":"Quale norma definisce il giustificato motivo oggettivo?","a":"L'art. 3 L. 604/1966.","v":{"p":null,"e":[["604/1966","n",["604","1966"]],["art. 3","n",["3"]]],"r":[]},"t":"p"},{"id":"S22-DL-25~2","s":"S22-DL-25","q":"Tempi della procedura dell'art. 7 L. 604/1966 davanti all'ITL?","a":"Convocazione entro 7 giorni, conclusione entro 20.","v":{"p":null,"e":[["7","n",["7"]],["20","n",["20"]],["Convocazione","k",["convocaz"]],["giorni","k",["giorn","gg"]],["conclusione","k",["conclusi"]]],"r":[]},"t":"d"},{"id":"S22-DL-25~3","s":"S22-DL-25","q":"Che cos'è il repêchage?","a":"L'obbligo di verificare un'altra utilizzazione del lavoratore prima di licenziarlo.","v":{"p":null,"e":[["obbligo","k",["obbli","obblig"]],["verificare","k",["verific"]],["utilizzazione","k",["utilizza"]],["lavoratore","k",["lavorat","dipendent","prestator"]],["licenziarlo","k",["licenzia","recess"]]],"r":[]}},{"id":"DL-13b~0","s":"DL-13b","q":"Qual è il cuore di «Le rinunce e le transazioni»? Rispondi in due o tre frasi.","a":"Le norme del lavoro sono inderogabili e i diritti che ne derivano indisponibili: per questo l'art. 2113 c.c. rende invalide le rinunzie e le transazioni del lavoratore su diritti nati da norme inderogabili di legge o di contratto collettivo, salvo che siano fatte in una sede protetta.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-13b~1","s":"DL-13b","q":"Entro quanto si impugnano rinunce e transazioni (art. 2113 c.c.)?","a":"Entro 6 mesi dalla cessazione o dall'atto, se successivo.","v":{"p":null,"e":[["6","n",["6"]],["mesi","k",["mes"]],["cessazione","k",["cessazi"]],["atto","k",["att"]],["successivo","k",["success"]]],"r":[]}},{"id":"DL-13b~2","s":"DL-13b","q":"Quali sono le sedi protette?","a":"Commissione ITL, sede sindacale, collegio di conciliazione e arbitrato, giudice, commissioni di certificazione.","v":{"p":null,"e":[["Commissione","k",["commissi"]],["ITL","k",["itl","ispettorato"]],["sindacale","k",["sindac"]],["collegio","k",["colle"]],["conciliazione","k",["concilia"]],["arbitrato","k",["arbitr"]],["giudice","k",["giudi","tribunal"]],["certificazione","k",["certific"]]],"r":[]}},{"id":"DL-13b~3","s":"DL-13b","q":"La quietanza a saldo generica vale come rinuncia?","a":"No: è una semplice dichiarazione di scienza.","v":{"p":"n","e":[["semplice","k",["sempl"]],["dichiarazione","k",["dichiara"]],["scienza","k",["scien"]]],"r":[]}},{"id":"DL-21b~0","s":"DL-21b","q":"Qual è il cuore di «Gli accordi conciliativi in sede protetta»? Rispondi in due o tre frasi.","a":"Gli accordi conciliativi in sede protetta sono le conciliazioni concluse davanti a soggetti terzi che garantiscono la genuinità della volontà del lavoratore: per questo le rinunzie e le transazioni che contengono non sono impugnabili (art. 2113, c. 4, c.c.).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-21b~1","s":"DL-21b","q":"Effetto della richiesta di conciliazione all'ITL su prescrizione e decadenze?","a":"Interrompe la prescrizione e sospende le decadenze fino a 20 giorni dopo la fine del tentativo.","v":{"p":null,"e":[["20","n",["20"]],["Interrompe","k",["interro"]],["sospende","k",["sospe"]],["giorni","k",["giorn","gg"]],["fine","k",["fin"]],["tentativo","k",["tentat"]]],"r":[]},"t":"d"},{"id":"DL-21b~2","s":"DL-21b","q":"Importo dell'offerta di conciliazione nelle tutele crescenti?","a":"Una mensilità per anno di servizio, da 3 a 27; dimezzato sotto soglia.","v":{"p":null,"e":[["3","n",["3"]],["27","n",["27"]],["mensilità","k",["mensil"]],["anno","k",["ann"]],["servizio","k",["servi"]],["dimezzato","k",["dimezz"]],["sotto","k",["sotto"]],["soglia","k",["sogli"]]],"r":[]}},{"id":"DL-21b~3","s":"DL-21b","q":"L'offerta di conciliazione è soggetta a IRPEF e contributi?","a":"No: è esente.","v":{"p":"n","e":[["esente","k",["esent"]]],"r":[]}},{"id":"DL-9b~0","s":"DL-9b","q":"Qual è il cuore di «L'efficacia dei contratti collettivi nazionali»? Rispondi in due o tre frasi.","a":"Il contratto collettivo nazionale è un contratto di diritto comune, perché l'art. 39 Cost., seconda parte, non è stato attuato: vincola solo gli iscritti alle associazioni firmatarie (art. 1372 c.c.). La sua efficacia si è allargata per altre vie.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-9b~1","s":"DL-9b","q":"Perché il CCNL vincola solo gli iscritti?","a":"Perché l'art. 39 Cost., seconda parte, non è attuato: è un contratto di diritto comune.","v":{"p":null,"e":[["art. 39","n",["39"]],["seconda","k",["secon"]],["attuato","k",["attua"]],["contratto","k",["contra","rapport"]],["diritto","k",["dirit"]],["comune","k",["comun"]]],"r":[]}},{"id":"DL-9b~2","s":"DL-9b","q":"Rappresentatività minima per negoziare secondo il Testo unico 2014?","a":"Il 5%.","v":{"p":null,"e":[["5%","n",["5"]]],"r":[]}},{"id":"DL-9b~3","s":"DL-9b","q":"Quale contratto collettivo ha efficacia generale per legge?","a":"Il contratto di prossimità (art. 8 D.L. 138/2011).","v":{"p":null,"e":[["prossimità","k",["prossim"]]],"r":[["138/2011",["138","2011"]],["art. 8",["8"]]]}},{"id":"DL-12b~0","s":"DL-12b","q":"Qual è il cuore di «I contratti di prossimità»? Rispondi in due o tre frasi.","a":"L'art. 8 D.L. 138/2011, convertito dalla L. 148/2011, consente a contratti aziendali o territoriali di derogare anche alla legge e ai CCNL, in materie tassative e per finalità tipiche, con efficacia verso tutti i lavoratori interessati. È una norma eccezionale (Corte cost. 221/2012).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-12b~1","s":"DL-12b","q":"Quale norma disciplina i contratti di prossimità?","a":"L'art. 8 D.L. 138/2011, conv. L. 148/2011.","v":{"p":null,"e":[["138/2011","n",["138","2011"]],["art. 8","n",["8"]]],"r":[["148/2011",["148","2011"]]]},"t":"p"},{"id":"DL-12b~2","s":"DL-12b","q":"La retribuzione è materia derogabile dai contratti di prossimità?","a":"No: il mero contenimento retributivo non vi rientra (Corte cost. 52/2023).","v":{"p":"n","e":[["mero","k",["mer"]],["contenimento","k",["contenim"]],["retributivo","k",["retribut"]],["rientra","k",["rient"]]],"r":[["52/2023",["52","2023"]]]}},{"id":"DL-12b~3","s":"DL-12b","q":"Nelle imprese fino a 15 dipendenti, dove si firmano le intese di prossimità peggiorative dopo il D.L. 62/2026?","a":"Presso l'ITL (art. 7-bis).","v":{"p":null,"e":[["Presso","k",["press"]],["ITL","k",["itl","ispettorato"]]],"r":[["art. 7",["7"]]]}},{"id":"DL-16b~0","s":"DL-16b","q":"Qual è il cuore di «Il diritto di sciopero»? Rispondi in due o tre frasi.","a":"Lo sciopero è l'astensione collettiva e concertata dal lavoro per la tutela di interessi collettivi; è un diritto costituzionale (art. 40 Cost.) di titolarità individuale e di esercizio collettivo, che si esercita nell'ambito delle leggi che lo regolano.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-16b~1","s":"DL-16b","q":"Quale legge regola lo sciopero nei servizi pubblici essenziali?","a":"La L. 146/1990.","v":{"p":null,"e":[["146/1990","n",["146","1990"]]],"r":[]},"t":"e"},{"id":"DL-16b~2","s":"DL-16b","q":"Lo sciopero politico è legittimo?","a":"Sì, se non mira a sovvertire l'ordinamento costituzionale (Corte cost. 290/1974).","v":{"p":"s","e":[["mira","k",["mir"]],["sovvertire","k",["sovvert"]],["ordinamento","k",["ordiname"]],["costituzionale","k",["costituz"]]],"r":[["290/1974",["290","1974"]]]}},{"id":"DL-16b~3","s":"DL-16b","q":"Esiste un diritto di serrata?","a":"No: la Costituzione non la prevede; la dottrina la ritiene lecita ex art. 41 Cost.","v":{"p":"n","e":[["art. 41","m",["41"]],["Costituzione","k",["costituz"]],["prevede","k",["preve"]],["dottrina","k",["dottr"]],["ritiene","k",["ritie"]],["lecita","k",["lecit"]]],"r":[]}},{"id":"DL-X16~0","s":"DL-X16","q":"Qual è il cuore di «Le rappresentanze sindacali in azienda (RSA e RSU) e la repressione della condotta antisindacale»? Rispondi in due o tre frasi.","a":"Le rappresentanze sindacali aziendali sono costituite su iniziativa dei lavoratori in ogni unità produttiva (con più di 15 dipendenti) nell'ambito dei sindacati che firmano i contratti collettivi applicati, che hanno partecipato alle trattative (C. cost. 231/2013) o che sono comparativamente più rappresentativi sul piano nazionale (C. cost. 156/2025); le RSU sono invece elette da tutti i lavoratori secondo gli accordi interconfederali; contro i comportamenti antisindacali il sindacato ha il ricorso d'urgenza dell'art. 28 dello Statuto dei lavoratori.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-X16~1","s":"DL-X16","q":"Quale sentenza del 2025 ha esteso l'art. 19 St. lav. ai sindacati comparativamente più rappresentativi?","a":"Corte cost. 30/10/2025 n. 156.","v":{"p":null,"e":[["30","n",["30"]],["2025","n",["2025"]],["Corte","k",["corte"]],["ottobre","k",["ottob"]]],"r":[]},"t":"e"},{"id":"DL-X16~2","s":"DL-X16","q":"Entro quanto decide il giudice sul ricorso per condotta antisindacale?","a":"Nei 2 giorni successivi, con decreto motivato immediatamente esecutivo; opposizione entro 15 giorni.","v":{"p":null,"e":[["2","n",["2"]],["15","m",["15"]],["giorni","k",["giorn","gg"]],["successivi","k",["success"]],["decreto","k",["decre"]],["motivato","k",["motiv"]],["immediatamente","k",["immediat"]],["esecutivo","k",["esecut"]],["opposizione","k",["opposizi"]]],"r":[]},"t":"d"},{"id":"DL-X16~3","s":"DL-X16","q":"Durata in carica delle RSU?","a":"3 anni.","v":{"p":null,"e":[["3","n",["3"]],["anni","k",["ann"]]],"r":[]},"t":"d"},{"id":"DL-8b~0","s":"DL-8b","q":"Qual è il cuore di «L'appalto illecito e fraudolento: sanzioni»? Rispondi in due o tre frasi.","a":"L'appalto è genuino se l'appaltatore organizza i mezzi necessari, anche solo esercitando il potere organizzativo e direttivo sui lavoratori, e assume il rischio d'impresa (art. 1655 c.c.; art. 29, c. 1, D.Lgs. 276/2003). Se questi requisiti mancano, l'appalto è illecito: è una somministrazione abusiva di manodopera.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-8b~1","s":"DL-8b","q":"Quando l'appalto è genuino?","a":"Se l'appaltatore organizza i mezzi (anche solo dirigendo i lavoratori) e assume il rischio d'impresa (art. 29 D.Lgs. 276/2003).","v":{"p":null,"e":[["organizza","k",["organi"]],["mezzi","k",["mezzi"]],["assume","k",["assum"]],["rischio","k",["risch"]],["impresa","k",["impre","non si prescrive","non si prescrivono"]]],"r":[["276/2003",["276","2003"]],["art. 29",["29"]]]}},{"id":"DL-8b~2","s":"DL-8b","q":"Sanzione per l'appalto illecito?","a":"Arresto fino a un mese o ammenda di 60 euro per lavoratore e giornata, tra 5.000 e 60.000 euro.","v":{"p":null,"e":[["60","n",["60"]],["5.000","n",["5000"]],["60.000","n",["60000"]],["Arresto","k",["arres"]],["mese","k",["mes"]],["ammenda","k",["ammen"]],["euro","k",["eur"]],["lavoratore","k",["lavorat","dipendent","prestator"]],["giornata","k",["giorn","gg"]]],"r":[]},"t":"d"},{"id":"DL-8b~3","s":"DL-8b","q":"Durata della solidarietà del committente nell'appalto genuino?","a":"2 anni dalla cessazione dell'appalto.","v":{"p":null,"e":[["2","n",["2"]],["anni","k",["ann"]],["cessazione","k",["cessazi"]]],"r":[]}},{"id":"DL-11b~0","s":"DL-11b","q":"Qual è il cuore di «Il caporalato e l'interposizione illecita»? Rispondi in due o tre frasi.","a":"Il caporalato è il reclutamento e l'impiego illecito di lavoratori sottoposti a sfruttamento, approfittando del loro stato di bisogno. Lo punisce l'art. 603-bis c.p. (intermediazione illecita e sfruttamento del lavoro), che colpisce sia il caporale sia il datore che utilizza la manodopera.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-11b~1","s":"DL-11b","q":"Quale articolo del codice penale punisce il caporalato?","a":"L'art. 603-bis c.p.","v":{"p":null,"e":[["art. 603-bis","n",["603"]]],"r":[]},"t":"e"},{"id":"DL-11b~2","s":"DL-11b","q":"Pena base per intermediazione illecita e sfruttamento?","a":"Reclusione da 1 a 6 anni e multa da 500 a 1.000 euro per lavoratore.","v":{"p":null,"e":[["1","n",["1"]],["6","n",["6"]],["500","n",["500"]],["1.000","n",["1000"]],["Reclusione","k",["reclusi"]],["anni","k",["ann"]],["multa","k",["multa"]],["euro","k",["eur"]],["lavoratore","k",["lavorat","dipendent","prestator"]]],"r":[]},"t":"d"},{"id":"DL-11b~3","s":"DL-11b","q":"Quali sono gli indici di sfruttamento?","a":"Retribuzioni difformi dai CCNL, violazioni reiterate di orario e riposi, violazioni di sicurezza, condizioni degradanti.","v":{"p":null,"e":[["Retribuzioni","k",["retribuz","stipend","paga","salari"]],["difformi","k",["diffo"]],["CCNL","k",["ccnl","contratto collettivo","contratti collettivi"]],["violazioni","k",["violazi"]],["reiterate","k",["reiter"]],["orario","k",["orari"]],["riposi","k",["ripos"]],["sicurezza","k",["sicure"]],["condizioni","k",["condizi"]],["degradanti","k",["degrada"]]],"r":[]}},{"id":"DL-20b~0","s":"DL-20b","q":"Qual è il cuore di «Il lavoro sommerso: definizione e sanzioni»? Rispondi in due o tre frasi.","a":"Il lavoro sommerso comprende il lavoro «nero», cioè il rapporto del tutto sconosciuto alle autorità perché manca la comunicazione preventiva di assunzione, e il lavoro «grigio», formalmente dichiarato ma irregolare nello svolgimento. Il lavoro nero è punito con la maxisanzione dell'art. 3 D.L. 12/2002.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-20b~1","s":"DL-20b","q":"Differenza tra lavoro nero e lavoro grigio?","a":"Nero: manca la comunicazione preventiva; grigio: dichiarato ma irregolare nello svolgimento.","v":{"p":null,"e":[["manca","k",["manca"]],["comunicazione","k",["comunica"]],["preventiva","k",["prevent"]],["dichiarato","k",["dichiar"]],["irregolare","k",["irregol"]],["svolgimento","k",["svolgime"]]],"r":[]}},{"id":"DL-20b~2","s":"DL-20b","q":"Maxisanzione per lavoratore in nero fino a 30 giorni?","a":"Da 1.950 a 11.700 euro.","v":{"p":null,"e":[["1.950","n",["1950"]],["11.700","n",["11700"]],["euro","k",["eur"]]],"r":[]}},{"id":"DL-20b~3","s":"DL-20b","q":"Per quanti giorni il lavoratore va mantenuto in servizio con la diffida da lavoro nero?","a":"Almeno 90 giorni.","v":{"p":null,"e":[["90","n",["90"]]],"r":[]}},{"id":"DL-22a~0","s":"DL-22a","q":"Qual è il cuore di «Il provvedimento di sospensione dell'attività d'impresa»? Rispondi in due o tre frasi.","a":"Il provvedimento di sospensione dell'attività d'impresa (art. 14 D.Lgs. 81/2008) è un potere vincolato dell'Ispettorato, esercitabile anche dalle ASL per la sicurezza: si adotta quando almeno il 10% dei lavoratori presenti all'accesso è irregolare o quando si riscontra una grave violazione di sicurezza dell'Allegato I.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-22a~1","s":"DL-22a","q":"Soglia di lavoratori irregolari per la sospensione dell'attività?","a":"Almeno il 10% dei presenti all'accesso (art. 14 D.Lgs. 81/2008).","v":{"p":null,"e":[["10%","n",["10"]],["presenti","k",["prese"]],["accesso","k",["acces"]]],"r":[["81/2008",["81","2008"]],["art. 14",["14"]]]}},{"id":"DL-22a~2","s":"DL-22a","q":"Somma aggiuntiva per la revoca della sospensione per lavoro irregolare?","a":"2.500 euro fino a cinque irregolari, 5.000 oltre.","v":{"p":null,"e":[["2.500","n",["2500"]],["5","n",["5"]],["5.000","n",["5000"]],["euro","k",["eur"]]],"r":[]},"t":"d"},{"id":"DL-22a~3","s":"DL-22a","q":"Ricorso contro la sospensione per lavoro irregolare?","a":"All'Ispettorato interregionale entro 30 giorni; se tace 30 giorni, la sospensione perde efficacia.","v":{"p":null,"e":[["30","n",["30"]],["Ispettorato","k",["ispettor"]],["interregionale","k",["interreg"]],["giorni","k",["giorn","gg"]],["tace","k",["tac"]],["perde","k",["perde"]],["efficacia","k",["effica"]]],"r":[]},"t":"d"},{"id":"DL-22b~0","s":"DL-22b","q":"Qual è il cuore di «La conciliazione monocratica»? Rispondi in due o tre frasi.","a":"La conciliazione monocratica (art. 11 D.Lgs. 124/2004) è un tentativo di accordo davanti a un solo funzionario dell'Ispettorato territoriale del lavoro, per le questioni di natura patrimoniale tra lavoratore e datore: serve a prevenire il contenzioso e a chiudere l'ispezione con il pagamento.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-22b~1","s":"DL-22b","q":"Quale norma disciplina la conciliazione monocratica?","a":"L'art. 11 D.Lgs. 124/2004.","v":{"p":null,"e":[["124/2004","n",["124","2004"]],["art. 11","n",["11"]]],"r":[]},"t":"e"},{"id":"DL-22b~2","s":"DL-22b","q":"Sono ammessi accordi solo transattivi in conciliazione monocratica?","a":"No: va riconosciuto un periodo di lavoro effettivo (circ. Min. Lav. 36/2009).","v":{"p":"n","e":[["riconosciuto","k",["riconosc"]],["periodo","k",["perio"]],["lavoro","k",["lavor","dipendent","prestator"]],["effettivo","k",["effett"]]],"r":[["36/2009",["36","2009"]]]}},{"id":"DL-22b~3","s":"DL-22b","q":"Che effetto ha il pagamento in conciliazione monocratica sull'ispezione?","a":"Estingue il procedimento ispettivo senza sanzioni.","v":{"p":null,"e":[["Estingue","k",["estin"]],["procedimento","k",["procedim"]],["ispettivo","k",["ispett"]],["sanzioni","k",["sanzi","multa","ammend"]]],"r":[]}},{"id":"DL-23a~0","s":"DL-23a","q":"Qual è il cuore di «La patente a crediti»? Rispondi in due o tre frasi.","a":"Dal 1° ottobre 2024 le imprese e i lavoratori autonomi che operano nei cantieri temporanei o mobili devono avere la patente a crediti, rilasciata in formato digitale dall'INL (art. 27 D.Lgs. 81/2008; D.M. 132/2024).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-23a~1","s":"DL-23a","q":"Da quando è obbligatoria la patente a crediti nei cantieri?","a":"Dal 1° ottobre 2024 (art. 27 D.Lgs. 81/2008).","v":{"p":null,"e":[["1","n",["1"]],["2024","n",["2024"]],["ottobre","k",["ottob"]]],"r":[["81/2008",["81","2008"]],["art. 27",["27"]]]},"t":"d"},{"id":"DL-23a~2","s":"DL-23a","q":"Crediti iniziali e soglia minima per lavorare?","a":"30 crediti iniziali; si lavora con almeno 15.","v":{"p":null,"e":[["30","n",["30"]],["15","m",["15"]]],"r":[]}},{"id":"DL-23a~3","s":"DL-23a","q":"Sanzione per chi lavora senza patente o con meno di 15 crediti?","a":"10% del valore dei lavori, non inferiore a 12.000 euro.","v":{"p":null,"e":[["10%","n",["10"]],["12.000","n",["12000"]],["valore","k",["valor"]],["inferiore","k",["inferi"]],["euro","k",["eur"]]],"r":[]},"t":"d"},{"id":"DL-X10~0","s":"DL-X10","q":"Qual è il cuore di «Diffide e prescrizione obbligatoria: la regolarizzazione degli illeciti amministrativi e penali»? Rispondi in due o tre frasi.","a":"Il sistema premia chi regolarizza. Per gli illeciti amministrativi sanabili c'è la diffida (art. 13 D.Lgs. 124/2004) e, prima ancora, la diffida amministrativa del D.Lgs. 103/2024; per le contravvenzioni c'è la prescrizione obbligatoria (art. 15 D.Lgs. 124/2004 e artt. 20-25 D.Lgs. 758/1994), che porta all'estinzione del reato. Chi non regolarizza riceve la contestazione e paga in misura ridotta.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-X10~1","s":"DL-X10","q":"Limiti della diffida amministrativa del D.Lgs. 103/2024?","a":"Sanzioni con massimo fino a 5.000 euro, prima violazione nel quinquennio, 20 giorni per sanare.","v":{"p":null,"e":[["5.000","n",["5000"]],["20","n",["20"]],["Sanzioni","k",["sanzi","multa","ammend"]],["euro","k",["eur"]],["violazione","k",["violazi"]],["quinquennio","k",["quinquen"]],["giorni","k",["giorn","gg"]],["sanare","k",["sanar"]]],"r":[]},"t":"d"},{"id":"DL-X10~2","s":"DL-X10","q":"Termini della diffida obbligatoria dell'art. 13 D.Lgs. 124/2004?","a":"30 giorni per regolarizzare e 15 per pagare il minimo.","v":{"p":null,"e":[["30","n",["30"]],["15","n",["15"]],["giorni","k",["giorn","gg"]],["regolarizzare","k",["regolari"]],["pagare","k",["pagar"]]],"r":[]}},{"id":"DL-X10~3","s":"DL-X10","q":"Quanto si paga per estinguere la contravvenzione con la prescrizione obbligatoria?","a":"Un quarto del massimo dell'ammenda, entro 30 giorni.","v":{"p":null,"e":[["30","n",["30"]],["quarto","k",["quart"]],["ammenda","k",["ammen"]],["giorni","k",["giorn","gg"]]],"r":[]}},{"id":"DL-X11~0","s":"DL-X11","q":"Qual è il cuore di «Il lavoro nero: maxisanzione, diffida e sospensione dell'attività»? Rispondi in due o tre frasi.","a":"Il lavoro nero è l'impiego di lavoratori subordinati senza la comunicazione preventiva di assunzione. Oltre al recupero di contributi e premi, comporta la maxisanzione per ciascun lavoratore (art. 3, c. 3-5, D.L. 12/2002) e, se riguarda almeno il 10% dei presenti, la sospensione dell'attività (art. 14 D.Lgs. 81/2008). Si distingue dal lavoro grigio, formalmente dichiarato ma irregolare nei fatti.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-X11~1","s":"DL-X11","q":"Di quanto sono aumentati gli importi della maxisanzione dal D.L. 19/2024?","a":"Del 30%.","v":{"p":null,"e":[["30%","n",["30"]]],"r":[]},"t":"d"},{"id":"DL-X11~2","s":"DL-X11","q":"Entro quanto va adempiuta la diffida speciale da lavoro nero?","a":"Entro 120 giorni dal verbale unico.","v":{"p":null,"e":[["120","n",["120"]],["giorni","k",["giorn","gg"]],["verbale","k",["verba"]],["unico","k",["unico"]]],"r":[]},"t":"d"},{"id":"DL-X11~3","s":"DL-X11","q":"Quale contratto non è ammesso per regolarizzare con la diffida da lavoro nero?","a":"Il lavoro intermittente (part-time almeno al 50%; termine pieno almeno 3 mesi).","v":{"p":null,"e":[["intermittente","k",["intermit"]]],"r":[]}},{"id":"DL-X7~0","s":"DL-X7","q":"Qual è il cuore di «La diffida accertativa per crediti patrimoniali (art. 12 D.Lgs. 124/2004)»? Rispondi in due o tre frasi.","a":"La diffida accertativa (art. 12 D.Lgs. 124/2004) è il provvedimento con cui l'ispettore, quando nella vigilanza emergono inosservanze della disciplina contrattuale da cui derivano crediti patrimoniali dei lavoratori, diffida il datore a pagare gli importi accertati. Se il datore non concilia e non ricorre, la diffida diventa titolo esecutivo a favore del lavoratore.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-X7~1","s":"DL-X7","q":"Quale norma disciplina la diffida accertativa?","a":"L'art. 12 D.Lgs. 124/2004.","v":{"p":null,"e":[["124/2004","n",["124","2004"]],["art. 12","n",["12"]]],"r":[]},"t":"p"},{"id":"DL-X7~2","s":"DL-X7","q":"Termine per conciliare o ricorrere contro la diffida accertativa?","a":"30 giorni dalla notifica; il ricorso al direttore sospende l'esecutività.","v":{"p":null,"e":[["30","n",["30"]],["giorni","k",["giorn","gg"]],["notifica","k",["notif"]],["direttore","k",["dirett"]],["sospende","k",["sospe"]],["esecutività","k",["esecutiv"]]],"r":[]}},{"id":"DL-X7~3","s":"DL-X7","q":"La diffida accertativa divenuta titolo esecutivo passa in giudicato?","a":"No: il datore può contestare il credito con l'opposizione all'esecuzione (Cass. 20826/2025).","v":{"p":"n","e":[["datore","k",["dator","aziend","impres"]],["contestare","k",["contest"]],["credito","k",["credi"]],["opposizione","k",["opposizi"]],["esecuzione","k",["esecuzi"]]],"r":[["20826/2025",["20826","2025"]]]}},{"id":"DL-X8~0","s":"DL-X8","q":"Qual è il cuore di «La disposizione del personale ispettivo (art. 14 D.Lgs. 124/2004)»? Rispondi in due o tre frasi.","a":"La disposizione (art. 14 D.Lgs. 124/2004, riscritto dall'art. 12-bis D.L. 76/2020) è il provvedimento immediatamente esecutivo con cui l'ispettore dell'INL ordina al datore di rimuovere irregolarità in materia di lavoro e legislazione sociale che non sono già punite con sanzioni penali o amministrative. È un potere discrezionale («può adottare») che rende effettive le norme prive di sanzione.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-X8~1","s":"DL-X8","q":"Quale norma disciplina la disposizione dell'ispettore?","a":"L'art. 14 D.Lgs. 124/2004, riscritto dall'art. 12-bis D.L. 76/2020.","v":{"p":null,"e":[["124/2004","n",["124","2004"]],["76/2020","n",["76","2020"]],["art. 14","n",["14"]],["art. 12-bis","n",["12"]],["riscritto","k",["riscri"]]],"r":[]},"t":"p"},{"id":"DL-X8~2","s":"DL-X8","q":"Ricorso contro la disposizione: termini ed effetti?","a":"Entro 15 giorni al direttore dell'ITL, che decide in 15; silenzio-rigetto; non sospende l'esecutività.","v":{"p":null,"e":[["15","n",["15"]],["giorni","k",["giorn","gg"]],["direttore","k",["dirett"]],["ITL","k",["itl","ispettorato"]],["decide","k",["decid"]],["silenzio","k",["silen"]],["rigetto","k",["riget"]],["sospende","k",["sospe"]],["esecutività","k",["esecutiv"]]],"r":[]}},{"id":"DL-X8~3","s":"DL-X8","q":"Sanzione per l'inottemperanza alla disposizione?","a":"Da 500 a 3.000 euro, senza diffida.","v":{"p":null,"e":[["500","n",["500"]],["3.000","n",["3000"]],["euro","k",["eur"]],["diffida","k",["diffi"]]],"r":[]},"t":"d"},{"id":"DL-X9~0","s":"DL-X9","q":"Qual è il cuore di «La vigilanza in materia di lavoro: organi, accesso ispettivo e verbali»? Rispondi in due o tre frasi.","a":"La vigilanza in materia di lavoro e legislazione sociale rende effettive le tutele degli artt. 35 e 36 Cost. ed è regolata dal D.Lgs. 124/2004. La esercita principalmente l'Ispettorato nazionale del lavoro (INL), con gli ITL e gli IAM; INPS e INAIL vigilano sul versante contributivo e assicurativo; ASL e INL, in modo paritario, sulla sicurezza. La logica del decreto è prima regolarizzare, poi sanzionare.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-X9~1","s":"DL-X9","q":"Quale decreto ha istituito l'INL?","a":"Il D.Lgs. 149/2015.","v":{"p":null,"e":[["149/2015","n",["149","2015"]]],"r":[]},"t":"e"},{"id":"DL-X9~2","s":"DL-X9","q":"Gli ispettori INPS e INAIL sono ufficiali di polizia giudiziaria?","a":"No: lo sono solo gli ispettori INL.","v":{"p":"n","e":[["INL","k",["inl","ispettorato"]]],"r":[]}},{"id":"DL-X9~3","s":"DL-X9","q":"Il verbale ispettivo fa piena prova anche del contenuto delle dichiarazioni raccolte?","a":"No: solo dei fatti avvenuti davanti all'ispettore e della provenienza delle dichiarazioni (Cass. 37764/2021).","v":{"p":"n","e":[["fatti","k",["fatti"]],["avvenuti","k",["avven"]],["davanti","k",["davan"]],["provenienza","k",["provenie"]]],"r":[["37764/2021",["37764","2021"]]]}},{"id":"S22-DL-1~0","s":"S22-DL-1","q":"Qual è il cuore di «La costituzione e la documentazione del rapporto di lavoro subordinato; la sanzione per il lavoro sommerso (art. 3 D.L. 12/2002)»? Rispondi in due o tre frasi.","a":"Il rapporto di lavoro subordinato nasce con un contratto a forma di regola libera, ma la legge lo accompagna con una serie di documenti obbligatori: la comunicazione preventiva di assunzione, l'informativa scritta sulle condizioni di lavoro, l'iscrizione nel libro unico e il prospetto paga. Se manca la comunicazione preventiva il rapporto è «in nero» e scatta la maxisanzione dell'art. 3 D.L. 12/2002.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-DL-1~1","s":"S22-DL-1","q":"Termine della comunicazione obbligatoria di assunzione?","a":"Entro le 24 del giorno precedente l'inizio del rapporto, anche se festivo.","v":{"p":null,"e":[["24","n",["24"]],["giorno","k",["giorn","gg"]],["precedente","k",["precede"]],["inizio","k",["inizi"]],["rapporto","k",["rappo","contratt"]],["festivo","k",["festi"]]],"r":[]}},{"id":"S22-DL-1~2","s":"S22-DL-1","q":"Termine per comunicare trasformazioni, proroghe e cessazioni?","a":"Entro 5 giorni.","v":{"p":null,"e":[["5","n",["5"]],["giorni","k",["giorn","gg"]]],"r":[]}},{"id":"S22-DL-1~3","s":"S22-DL-1","q":"Sanzione per l'omessa comunicazione obbligatoria?","a":"Da 100 a 500 euro per lavoratore, diffidabile (art. 19, c. 3, D.Lgs. 276/2003).","v":{"p":null,"e":[["100","n",["100"]],["500","n",["500"]],["euro","k",["eur"]],["lavoratore","k",["lavorat","dipendent","prestator"]],["diffidabile","k",["diffidab"]]],"r":[["276/2003",["276","2003"]],["art. 19",["19"]]]},"t":"d"},{"id":"S22-DL-30~0","s":"S22-DL-30","q":"Qual è il cuore di «Le ispezioni del lavoro, il ruolo del consulente e la diffida»? Rispondi in due o tre frasi.","a":"La vigilanza in materia di lavoro e legislazione sociale spetta principalmente all'INL, attraverso ITL e IAM (artt. 6-7 D.Lgs. 124/2004), con INPS e INAIL per i profili previdenziali e le ASL per la sicurezza. La logica del decreto è prima regolarizzare e poi sanzionare: la diffida è lo strumento centrale. Il consulente del lavoro è l'interlocutore qualificato degli ispettori.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-DL-30~1","s":"S22-DL-30","q":"Quali articoli del D.Lgs. 124/2004 regolano gli organi di vigilanza?","a":"Gli artt. 6-7.","v":{"p":null,"e":[["art. 6-7","n",["6","7"]]],"r":[]},"t":"e"},{"id":"S22-DL-30~2","s":"S22-DL-30","q":"Le dichiarazioni dei lavoratori si raccolgono alla presenza del datore?","a":"No, senza la presenza del datore.","v":{"p":"n","e":[],"r":[]}},{"id":"S22-DL-30~3","s":"S22-DL-30","q":"Dove può tenere il LUL il consulente del lavoro?","a":"Nel proprio studio, previa comunicazione all'ITL.","v":{"p":null,"e":[["studio","k",["studi"]],["previa","k",["previ"]],["comunicazione","k",["comunica"]],["ITL","k",["itl","ispettorato"]]],"r":[]}},{"id":"DL-X1~0","s":"DL-X1","q":"Qual è il cuore di «Il regime delle tutele contro il licenziamento illegittimo»? Rispondi in due o tre frasi.","a":"Le tutele contro il licenziamento illegittimo dipendono dalla data di assunzione (prima o dal 7/3/2015), dalle dimensioni del datore e dal vizio accertato: art. 18 St. lav. e L. 604/1966 per i vecchi assunti, D.Lgs. 23/2015 per i nuovi.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-X1~1","s":"DL-X1","q":"Soglia dimensionale per la tutela dell'art. 18 St. lav.?","a":"Oltre 15 dipendenti nell'unità o nel Comune (oltre 5 se agricolo), o oltre 60 in ogni caso.","v":{"p":null,"e":[["15","n",["15"]],["60","n",["60"]],["dipendenti","k",["dipende","lavorat"]],["unità","k",["unita"]],["Comune","k",["comun"]]],"r":[]}},{"id":"DL-X1~2","s":"DL-X1","q":"Indennità per i nuovi assunti (D.Lgs. 23/2015) quando non c'è reintegra?","a":"Tra 6 e 36 mensilità.","v":{"p":null,"e":[["6","n",["6"]],["36","n",["36"]],["mensilità","k",["mensil"]]],"r":[]}},{"id":"DL-X1~3","s":"DL-X1","q":"Quale sentenza ha eliminato il tetto di 6 mensilità per i piccoli datori?","a":"Corte cost. 21/7/2025 n. 118.","v":{"p":null,"e":[["21","n",["21"]],["2025","n",["2025"]],["Corte","k",["corte"]],["luglio","k",["lugli"]]],"r":[]},"t":"e"},{"id":"DL-X2~0","s":"DL-X2","q":"Qual è il cuore di «Il potere disciplinare: procedimento e garanzie dell'art. 7 dello Statuto dei lavoratori»? Rispondi in due o tre frasi.","a":"Il potere disciplinare è la facoltà del datore di sanzionare il lavoratore che viola gli obblighi di diligenza, obbedienza e fedeltà (artt. 2104-2105 c.c.), secondo la gravità dell'infrazione (art. 2106 c.c.). L'art. 7 St. lav. ne fissa le garanzie sostanziali e procedurali.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-X2~1","s":"DL-X2","q":"Dopo quanti giorni dalla contestazione si può irrogare una sanzione più grave del rimprovero verbale?","a":"Dopo 5 giorni (art. 7 St. lav.).","v":{"p":null,"e":[["5","n",["5"]]],"r":[["art. 7",["7"]]]}},{"id":"DL-X2~2","s":"DL-X2","q":"Limiti di multa e sospensione disciplinare?","a":"Multa fino a 4 ore di retribuzione base; sospensione fino a 10 giorni.","v":{"p":null,"e":[["4","n",["4"]],["10","m",["10"]],["ore","k",["ore"]],["retribuzione","k",["retribuz","stipend","paga","salari"]],["giorni","k",["giorn","gg"]]],"r":[]}},{"id":"DL-X2~3","s":"DL-X2","q":"Dopo quanto le sanzioni disciplinari non contano più?","a":"Dopo 2 anni dalla loro applicazione.","v":{"p":null,"e":[["2","n",["2"]],["anni","k",["ann"]],["applicazione","k",["applicaz"]]],"r":[]}},{"id":"DL-X3~0","s":"DL-X3","q":"Qual è il cuore di «Il «salario giusto» nel D.L. 62/2026»? Rispondi in due o tre frasi.","a":"Il D.L. 30/4/2026 n. 62, convertito dalla L. 25/6/2026 n. 112, non introduce un salario minimo legale: per il settore privato fa della contrattazione collettiva comparativamente più rappresentativa la misura della retribuzione giusta dell'art. 36 Cost., attraverso il trattamento economico complessivo (TEC) del CCNL leader (art. 7).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-X3~1","s":"DL-X3","q":"Il D.L. 62/2026 introduce un salario minimo legale?","a":"No: rinvia al TEC del CCNL leader (art. 7).","v":{"p":"n","e":[["rinvia","k",["rinvi"]],["TEC","k",["tec"]],["CCNL","k",["ccnl","contratto collettivo","contratti collettivi"]],["leader","k",["leade"]]],"r":[["art. 7",["7"]]]}},{"id":"DL-X3~2","s":"DL-X3","q":"Entro quanto dalla scadenza, senza rinnovo del CCNL, scatta l'anticipazione IPCA?","a":"9 mesi: anticipazione del 50% dell'IPCA-NEI (art. 10).","v":{"p":null,"e":[["9","n",["9"]],["50%","n",["50"]],["mesi","k",["mes"]]],"r":[["art. 10",["10"]]]}},{"id":"DL-X3~3","s":"DL-X3","q":"Da quando vale la regola dell'art. 10 per i CCNL già scaduti?","a":"Dal 1/1/2027.","v":{"p":null,"e":[["1","n",["1"]],["2027","n",["2027"]],["gennaio","k",["genna"]]],"r":[]}},{"id":"DL-X4~0","s":"DL-X4","q":"Qual è il cuore di «La trasparenza retributiva nel D.Lgs. 96/2026»? Rispondi in due o tre frasi.","a":"Il D.Lgs. 7/5/2026 n. 96, in vigore dal 7/6/2026, attua la dir. (UE) 2023/970 sulla trasparenza retributiva: rende verificabile il principio della parità di retribuzione tra uomini e donne per lo stesso lavoro o per un lavoro di pari valore (art. 37 Cost.; art. 157 TFUE). Si applica al lavoro pubblico e privato.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-X4~1","s":"DL-X4","q":"Quale direttiva attua il D.Lgs. 96/2026 e quando è entrato in vigore?","a":"Dir. (UE) 2023/970; in vigore dal 7/6/2026.","v":{"p":null,"e":[["2023","n",["2023"]],["970","n",["970"]],["7","m",["7"]],["2026","m",["2026"]],["giugno","k",["giugn"]]],"r":[]},"t":"p"},{"id":"DL-X4~2","s":"DL-X4","q":"Entro quanto il datore risponde alla richiesta di informazioni sui livelli retributivi?","a":"Entro 2 mesi, per iscritto.","v":{"p":null,"e":[["2","n",["2"]],["mesi","k",["mes"]],["iscritto","k",["iscri"]]],"r":[]}},{"id":"DL-X4~3","s":"DL-X4","q":"Oltre quale divario scatta la valutazione congiunta delle retribuzioni?","a":"Almeno il 5%, non giustificato e non corretto entro 6 mesi (art. 10).","v":{"p":null,"e":[["5%","n",["5"]],["6","n",["6"]],["giustificato","k",["giustifi"]],["corretto","k",["corre"]],["mesi","k",["mes"]]],"r":[["art. 10",["10"]]]}},{"id":"DL-X5~0","s":"DL-X5","q":"Qual è il cuore di «Le dimissioni per fatti concludenti»? Rispondi in due o tre frasi.","a":"Il Collegato lavoro (art. 19 L. 203/2024) ha aggiunto il c. 7-bis all'art. 26 D.Lgs. 151/2015: se l'assenza ingiustificata dura oltre il termine del CCNL o, in mancanza, oltre 15 giorni, il datore può comunicarla all'ITL e il rapporto si intende risolto per volontà del lavoratore, senza la procedura telematica delle dimissioni.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-X5~1","s":"DL-X5","q":"Quale legge ha introdotto le dimissioni per fatti concludenti?","a":"Il Collegato lavoro, art. 19 L. 203/2024 (art. 26, c. 7-bis, D.Lgs. 151/2015).","v":{"p":null,"e":[["203/2024","n",["203","2024"]],["art. 19","n",["19"]],["Collegato","k",["colleg"]],["lavoro","k",["lavor","dipendent","prestator"]]],"r":[["151/2015",["151","2015"]],["art. 26",["26"]]]},"t":"e"},{"id":"DL-X5~2","s":"DL-X5","q":"La comunicazione all'ITL dell'assenza è un obbligo per il datore?","a":"No, è una facoltà (circ. Min. Lav. 6/2025).","v":{"p":"n","e":[["facoltà","k",["facol"]]],"r":[["6/2025",["6","2025"]]]}},{"id":"DL-X5~3","s":"DL-X5","q":"Con le dimissioni per fatti concludenti spetta la NASpI?","a":"No.","v":{"p":"n","e":[],"r":[]}},{"id":"DL-X6~0","s":"DL-X6","q":"Qual è il cuore di «Il ruolo del consulente del lavoro nella crisi d'impresa (D.Lgs. 14/2019)»? Rispondi in due o tre frasi.","a":"Il Codice della crisi chiede di riconoscere la crisi presto e di gestirla preservando la continuità: il CdL interviene prima (assetti adeguati e segnali di allarme), durante (consultazione sindacale e strumenti del lavoro nel piano) e dentro le procedure (esperto, curatore, rapporti di lavoro nella liquidazione giudiziale).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DL-X6~1","s":"DL-X6","q":"Quale norma del codice civile impone assetti adeguati a rilevare la crisi?","a":"L'art. 2086, c. 2, c.c. (con l'art. 3 CCII).","v":{"p":null,"e":[["art. 2086","n",["2086"]]],"r":[["art. 3",["3"]]]},"t":"e"},{"id":"DL-X6~2","s":"DL-X6","q":"Quando l'INPS segnala la crisi (art. 25-novies CCII)?","a":"Ritardo oltre 90 giorni nei contributi, oltre il 30% del dovuto dell'anno precedente e oltre 15.000 euro.","v":{"p":null,"e":[["90","n",["90"]],["30%","n",["30"]],["15.000","n",["15000"]],["Ritardo","k",["ritar"]],["giorni","k",["giorn","gg"]],["contributi","k",["contrib","contribuz","contribut"]],["dovuto","k",["dovut"]],["anno","k",["ann"]],["precedente","k",["precede"]],["euro","k",["eur"]]],"r":[]},"t":"d"},{"id":"DL-X6~3","s":"DL-X6","q":"Requisiti del CdL per fare l'esperto della composizione negoziata?","a":"5 anni di iscrizione e almeno 3 casi documentati (art. 13, c. 3).","v":{"p":null,"e":[["5","n",["5"]],["3","n",["3"]],["anni","k",["ann"]],["iscrizione","k",["iscrizi"]],["documentati","k",["document"]]],"r":[["art. 13",["13"]]]},"t":"d"},{"id":"INPS-3~0","s":"INPS-3","q":"Qual è il cuore di «La contribuzione obbligatoria e le assicurazioni sociali (IVS, minori, ex INPDAP, casse professionali)»? Rispondi in due o tre frasi.","a":"La contribuzione obbligatoria finanzia le assicurazioni sociali dei lavoratori: l'assicurazione generale obbligatoria per invalidità, vecchiaia e superstiti, le cosiddette assicurazioni minori e le forme sostitutive o esclusive.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INPS-3~1","s":"INPS-3","q":"Aliquota IVS del Fondo pensioni lavoratori dipendenti e ripartizione?","a":"33%: 23,81% a carico del datore, 9,19% del lavoratore.","v":{"p":null,"e":[["33%","n",["33"]],["23,81%","n",["23.81"]],["9,19%","n",["9.19"]],["carico","k",["caric"]],["datore","k",["dator","aziend","impres"]]],"r":[]}},{"id":"INPS-3~2","s":"INPS-3","q":"Quali sono le assicurazioni minori?","a":"Malattia, maternità, disoccupazione (NASpI), cassa integrazione, ANF (CUAF), Fondo di garanzia TFR.","v":{"p":null,"e":[["Malattia","k",["malat"]],["maternità","k",["matern"]],["disoccupazione","k",["disoccup"]],["cassa","k",["cassa","cig"]],["integrazione","k",["integraz"]],["ANF","k",["anf"]],["Fondo","k",["fondo"]],["garanzia","k",["garan"]],["TFR","k",["tfr","trattamento di fine rapporto","liquidazione"]]],"r":[]}},{"id":"INPS-3~3","s":"INPS-3","q":"Qual è la cassa di previdenza dei consulenti del lavoro?","a":"L'ENPACL.","v":{"p":null,"e":[["ENPACL","k",["enpacl"]]],"r":[]}},{"id":"INPS-8~0","s":"INPS-8","q":"Qual è il cuore di «Unità produttiva e unità operativa»? Rispondi in due o tre frasi.","a":"L'unità produttiva è la sede dotata di autonomia organizzativa capace di svolgere l'intero ciclo produttivo o una sua fase; l'unità operativa è il luogo dove si svolge stabilmente il lavoro dei dipendenti.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INPS-8~1","s":"INPS-8","q":"Quanti numeri di matricola INPS ha di regola un datore?","a":"Una sola posizione contributiva per tutti i lavoratori.","v":{"p":null,"e":[["sola","k",["sol"]],["posizione","k",["posizi"]],["contributiva","k",["contribu","contribuz","contribut"]],["lavoratori","k",["lavorat","dipendent","prestator"]]],"r":[]}},{"id":"INPS-8~2","s":"INPS-8","q":"Che cos'è l'unità produttiva per l'INPS?","a":"Sede con autonomia, idonea a svolgere l'intero ciclo produttivo o una sua fase completa, con maestranze continuative (msg. 1444/2017).","v":{"p":null,"e":[["autonomia","k",["autono"]],["idonea","k",["idone"]],["svolgere","k",["svolg"]],["intero","k",["inter"]],["ciclo","k",["ciclo"]],["fase","k",["fas"]],["completa","k",["compl"]],["maestranze","k",["maestra"]],["continuative","k",["continua"]]],"r":[["1444/2017",["1444","2017"]]]}},{"id":"INPS-8~3","s":"INPS-8","q":"Per quali istituti INPS rileva l'unità produttiva?","a":"Per gli ammortizzatori: anzianità di 30 giorni, durata massima, CIGO.","v":{"p":null,"e":[["30","n",["30"]],["ammortizzatori","k",["ammortiz"]],["anzianità","k",["anzian"]],["giorni","k",["giorn","gg"]],["durata","k",["durat"]],["massima","k",["massi"]],["CIGO","k",["cigo","cassa integrazione"]]],"r":[]},"t":"d"},{"id":"INPS-12~0","s":"INPS-12","q":"Qual è il cuore di «La prescrizione dei contributi»? Rispondi in due o tre frasi.","a":"I contributi previdenziali e assistenziali si prescrivono in cinque anni; una volta prescritti non possono più essere versati (art. 3, c. 9, L. 335/1995).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INPS-12~1","s":"INPS-12","q":"Termine di prescrizione dei contributi?","a":"5 anni (art. 3, c. 9, L. 335/1995).","v":{"p":null,"e":[["5","n",["5"]],["anni","k",["ann"]]],"r":[["335/1995",["335","1995"]],["art. 3",["3"]]]}},{"id":"INPS-12~2","s":"INPS-12","q":"Quando la prescrizione contributiva diventa decennale?","a":"Se il lavoratore o i superstiti presentano denuncia.","v":{"p":null,"e":[["lavoratore","k",["lavorat","dipendent","prestator"]],["superstiti","k",["superst"]],["presentano","k",["present"]],["denuncia","k",["denun"]]],"r":[]}},{"id":"INPS-12~3","s":"INPS-12","q":"Si possono versare contributi prescritti?","a":"No, nemmeno spontaneamente (irricevibilità); il lavoratore può chiedere la rendita vitalizia (art. 13 L. 1338/1962).","v":{"p":"n","e":[["nemmeno","k",["nemme"]],["spontaneamente","k",["spontane"]],["lavoratore","k",["lavorat","dipendent","prestator"]],["chiedere","k",["chied"]],["rendita","k",["rendi"]],["vitalizia","k",["vitali"]]],"r":[["1338/1962",["1338","1962"]],["art. 13",["13"]]]}},{"id":"INPS-13~0","s":"INPS-13","q":"Qual è il cuore di «Le dilazioni dei debiti contributivi»? Rispondi in due o tre frasi.","a":"I debiti contributivi verso l'INPS non ancora affidati all'agente della riscossione possono essere rateizzati: dal 2025 la legge consente fino a 60 rate mensili (art. 2, c. 11 e 11-bis, D.L. 338/1989).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INPS-13~1","s":"INPS-13","q":"Massimo di rate per i debiti contributivi INPS dal 2025?","a":"Fino a 60 rate mensili (art. 2, c. 11-bis, D.L. 338/1989).","v":{"p":null,"e":[["60","n",["60"]],["mensili","k",["mensi"]]],"r":[["338/1989",["338","1989"]],["art. 2",["2"]]]}},{"id":"INPS-13~2","s":"INPS-13","q":"Fino a quanti euro di debito si arriva a 36 rate?","a":"Fino a 500.000 euro; oltre, fino a 60 rate.","v":{"p":null,"e":[["500.000","n",["500000"]],["60","m",["60"]]],"r":[]},"t":"d"},{"id":"INPS-13~3","s":"INPS-13","q":"Quante rate non pagate causano la revoca della dilazione?","a":"Tre, anche non consecutive.","v":{"p":null,"e":[["3","n",["3"]],["consecutive","k",["consecut"]]],"r":[]},"t":"d"},{"id":"INPS-14~0","s":"INPS-14","q":"Qual è il cuore di «L'inquadramento aziendale e la posizione contributiva»? Rispondi in due o tre frasi.","a":"L'inquadramento è la classificazione del datore di lavoro in un settore previdenziale, fatta dall'INPS in via esclusiva in base all'attività svolta (art. 49 L. 88/1989); da esso dipendono aliquote e prestazioni.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INPS-14~1","s":"INPS-14","q":"Chi decide l'inquadramento previdenziale del datore e su quale norma?","a":"L'INPS, in via esclusiva (art. 49 L. 88/1989).","v":{"p":null,"e":[["INPS","k",["inps"]],["esclusiva","k",["esclus"]]],"r":[["88/1989",["88","1989"]],["art. 49",["49"]]]},"t":"e"},{"id":"INPS-14~2","s":"INPS-14","q":"Quali sono i settori dell'art. 49 L. 88/1989?","a":"Industria, artigianato, agricoltura, terziario, credito e assicurazioni.","v":{"p":null,"e":[["Industria","k",["indust"]],["artigianato","k",["artigian"]],["agricoltura","k",["agricolt"]],["terziario","k",["terzia"]],["credito","k",["credi"]],["assicurazioni","k",["assicura"]]],"r":[]}},{"id":"INPS-14~3","s":"INPS-14","q":"Da quando l'INPS usa la classificazione ATECO 2025?","a":"Dal 1/4/2025 (circ. INPS 71/2025).","v":{"p":null,"e":[["1","n",["1"]],["2025","n",["2025"]],["aprile","k",["april"]]],"r":[["71/2025",["71","2025"]]]},"t":"d"},{"id":"INPS-15~0","s":"INPS-15","q":"Qual è il cuore di «Il minimale contributivo e il CCNL comparativamente più rappresentativo»? Rispondi in due o tre frasi.","a":"I contributi si calcolano su una retribuzione non inferiore a quella dei contratti collettivi nazionali e, se ci sono più contratti, a quella dei contratti comparativamente più rappresentativi; in ogni caso non sotto il minimale giornaliero di legge.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INPS-15~1","s":"INPS-15","q":"Quale norma fissa il minimale contrattuale contributivo?","a":"L'art. 1, c. 1, D.L. 338/1989.","v":{"p":null,"e":[["338/1989","n",["338","1989"]],["art. 1","n",["1"]]],"r":[]},"t":"e"},{"id":"INPS-15~2","s":"INPS-15","q":"Minimale giornaliero contributivo 2026?","a":"58,13 euro (9,50% del trattamento minimo di pensione).","v":{"p":null,"e":[["58,13","n",["58.13"]],["euro","k",["eur"]]],"r":[]},"t":"d"},{"id":"INPS-15~3","s":"INPS-15","q":"Con più CCNL per la stessa categoria, quale vale per i contributi?","a":"Quello delle organizzazioni comparativamente più rappresentative (art. 2, c. 25, L. 549/1995).","v":{"p":null,"e":[["organizzazioni","k",["organizz"]],["comparativamente","k",["comparat"]],["rappresentative","k",["rapprese"]]],"r":[["549/1995",["549","1995"]],["art. 2",["2"]]]}},{"id":"INPS-18~0","s":"INPS-18","q":"Qual è il cuore di «Evasione e omissione contributiva»? Rispondi in due o tre frasi.","a":"Omissione ed evasione contributiva sono le due forme di mancato versamento sanzionate con sanzioni civili dall'art. 116, c. 8, L. 388/2000; l'omesso versamento delle ritenute ha anche una sanzione penale o amministrativa.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INPS-18~1","s":"INPS-18","q":"Sanzione civile per omissione contributiva?","a":"Tasso BCE più 5,5 punti annui, tetto 40% (solo BCE se si paga entro 120 giorni).","v":{"p":null,"e":[["5,5","n",["5.5"]],["40%","n",["40"]],["Tasso","k",["tasso"]],["BCE","k",["bce"]],["punti","k",["punti"]],["annui","k",["annui"]],["tetto","k",["tetto"]]],"r":[]}},{"id":"INPS-18~2","s":"INPS-18","q":"Sanzione civile per evasione contributiva?","a":"30% annuo, con tetto del 60%.","v":{"p":null,"e":[["30%","n",["30"]],["60%","n",["60"]],["annuo","k",["annuo"]],["tetto","k",["tetto"]]],"r":[]}},{"id":"INPS-18~3","s":"INPS-18","q":"Ritenute previdenziali non versate: soglia di rilevanza penale?","a":"Oltre 10.000 euro annui; non punibile chi paga entro 3 mesi dalla contestazione.","v":{"p":null,"e":[["10.000","n",["10000"]],["3","m",["3"]],["euro","k",["eur"]],["annui","k",["annui"]],["punibile","k",["punib"]],["paga","k",["pag"]],["mesi","k",["mes"]],["contestazione","k",["contesta"]]],"r":[]}},{"id":"INPS-20~0","s":"INPS-20","q":"Qual è il cuore di «Il DURC»? Rispondi in due o tre frasi.","a":"Il DURC attesta, con un'unica interrogazione telematica sul codice fiscale, la regolarità contributiva verso INPS, INAIL e, per l'edilizia, Casse edili (art. 4 D.L. 34/2014; D.M. 30/1/2015).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INPS-20~1","s":"INPS-20","q":"Durata di validità del DURC?","a":"120 giorni dalla richiesta.","v":{"p":null,"e":[["120","n",["120"]],["giorni","k",["giorn","gg"]],["richiesta","k",["richie"]]],"r":[]}},{"id":"INPS-20~2","s":"INPS-20","q":"Giorni per regolarizzare dopo l'invito dell'ente in caso di irregolarità?","a":"15 giorni.","v":{"p":null,"e":[["15","n",["15"]]],"r":[]},"t":"d"},{"id":"INPS-20~3","s":"INPS-20","q":"Quale norma ha introdotto il DURC on line?","a":"L'art. 4 D.L. 34/2014 (D.M. 30/1/2015).","v":{"p":null,"e":[["34/2014","n",["34","2014"]],["art. 4","n",["4"]]],"r":[]},"t":"e"},{"id":"INPS-22~0","s":"INPS-22","q":"Qual è il cuore di «I contributi obbligatori e il rapporto di lavoro»? Rispondi in due o tre frasi.","a":"Il rapporto di lavoro subordinato fa sorgere per legge il rapporto contributivo: il datore versa i contributi anche per la quota del lavoratore e ne risponde in via esclusiva (artt. 2114-2116 c.c.).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INPS-22~1","s":"INPS-22","q":"Quali articoli del codice civile regolano la previdenza obbligatoria?","a":"Artt. 2114-2116 c.c.","v":{"p":null,"e":[["art. 2114-2116","n",["2114","2116"]]],"r":[]},"t":"p"},{"id":"INPS-22~2","s":"INPS-22","q":"Chi risponde del versamento anche della quota del lavoratore?","a":"Il datore, con diritto di rivalsa tramite trattenuta (art. 2115 c.c.).","v":{"p":null,"e":[["datore","k",["dator","aziend","impres"]],["diritto","k",["dirit"]],["rivalsa","k",["rival"]],["tramite","k",["trami"]],["trattenuta","k",["tratten"]]],"r":[["art. 2115 c.c.",["2115"]]]}},{"id":"INPS-22~3","s":"INPS-22","q":"Quale norma allinea la base contributiva a quella fiscale?","a":"L'art. 12 L. 153/1969 (in armonia con l'art. 51 TUIR).","v":{"p":null,"e":[["153/1969","n",["153","1969"]],["art. 12","n",["12"]]],"r":[["art. 51",["51"]]]},"t":"p"},{"id":"INPS-23~0","s":"INPS-23","q":"Qual è il cuore di «Il principio di automaticità delle prestazioni»? Rispondi in due o tre frasi.","a":"Per il principio di automaticità le prestazioni previdenziali spettano al lavoratore subordinato anche se il datore non ha versato i contributi (art. 2116 c.c.), nei limiti della prescrizione.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INPS-23~1","s":"INPS-23","q":"Quale norma prevede l'automaticità delle prestazioni?","a":"L'art. 2116 c.c.","v":{"p":null,"e":[["art. 2116","n",["2116"]]],"r":[]},"t":"p"},{"id":"INPS-23~2","s":"INPS-23","q":"Limite dell'automaticità delle prestazioni?","a":"Solo per i contributi non prescritti; oltre i 5 anni risponde il datore.","v":{"p":null,"e":[["5","m",["5"]],["contributi","k",["contrib","contribuz","contribut"]],["prescritti","k",["prescri"]],["anni","k",["ann"]],["risponde","k",["rispo"]],["datore","k",["dator","aziend","impres"]]],"r":[]}},{"id":"INPS-23~3","s":"INPS-23","q":"L'automaticità vale per i collaboratori della gestione separata?","a":"No, salvo l'indennità di maternità (art. 64-ter D.Lgs. 151/2001).","v":{"p":"n","e":[["indennità","k",["indenn"]],["maternità","k",["matern"]]],"r":[["151/2001",["151","2001"]],["art. 64",["64"]]]}},{"id":"INPS-X2~0","s":"INPS-X2","q":"Qual è il cuore di «La gestione separata INPS: iscritti, aliquote e versamenti»? Rispondi in due o tre frasi.","a":"La gestione separata, istituita presso l'INPS dal 1996 (art. 2, c. 26, L. 335/1995), assicura per invalidità, vecchiaia e superstiti i lavoratori che non hanno un'altra gestione obbligatoria per quell'attività: collaboratori coordinati e continuativi e figure assimilate (amministratori, sindaci, dottorandi), professionisti senza cassa e autonomi occasionali oltre 5.000 euro annui.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INPS-X2~1","s":"INPS-X2","q":"Aliquota gestione separata 2026 per i collaboratori con DIS-COLL?","a":"35,03% (circ. INPS 8/2026).","v":{"p":null,"e":[["35,03%","n",["35.03"]]],"r":[["8/2026",["8","2026"]]]}},{"id":"INPS-X2~2","s":"INPS-X2","q":"Ripartizione dei contributi tra committente e collaboratore?","a":"2/3 committente, 1/3 collaboratore; versa tutto il committente.","v":{"p":null,"e":[["2","n",["2"]],["3","n",["3"]],["1","n",["1"]],["versa","k",["versa"]]],"r":[]}},{"id":"INPS-X2~3","s":"INPS-X2","q":"Aliquota 2026 dei professionisti senza cassa?","a":"26,07% (24% se pensionati o assicurati altrove).","v":{"p":null,"e":[["26,07%","n",["26.07"]]],"r":[]},"t":"d"},{"id":"INPS-X3~0","s":"INPS-X3","q":"Qual è il cuore di «Incentivi ed esoneri contributivi alle assunzioni: regole generali e misure 2026»? Rispondi in due o tre frasi.","a":"Gli incentivi all'occupazione riducono o azzerano i contributi a carico del datore che assume o stabilizza determinate categorie di lavoratori; spettano solo se il datore rispetta i principi generali dell'art. 31 D.Lgs. 150/2015, è in regola con il DURC e i contratti collettivi (art. 1, c. 1175, L. 296/2006) e, dal 2026, se il trattamento economico individuale non è inferiore a quello del CCNL di riferimento (art. 7, c. 5, D.L. 62/2026).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INPS-X3~1","s":"INPS-X3","q":"Quale norma fissa i principi generali sugli incentivi?","a":"L'art. 31 D.Lgs. 150/2015.","v":{"p":null,"e":[["150/2015","n",["150","2015"]],["art. 31","n",["31"]]],"r":[]},"t":"e"},{"id":"INPS-X3~2","s":"INPS-X3","q":"Bonus giovani 2026: tetto mensile nelle Marche?","a":"650 euro (500 nel resto d'Italia, fuori ZES).","v":{"p":null,"e":[["650","n",["650"]],["euro","k",["eur"]]],"r":[]}},{"id":"INPS-X3~3","s":"INPS-X3","q":"Esonero per la certificazione della parità di genere?","a":"Fino all'1% dei contributi datoriali e 50.000 euro annui (art. 5 L. 162/2021).","v":{"p":null,"e":[["1%","n",["1"]],["50.000","n",["50000"]],["contributi","k",["contrib","contribuz","contribut"]],["datoriali","k",["datori"]],["euro","k",["eur"]],["annui","k",["annui"]]],"r":[["162/2021",["162","2021"]],["art. 5",["5"]]]},"t":"d"},{"id":"S22-INPS-11~0","s":"S22-INPS-11","q":"Qual è il cuore di «Le modalità di pagamento dei contributi INPS per lavoratori subordinati e autonomi»? Rispondi in due o tre frasi.","a":"I contributi INPS si pagano con il modello F24, che consente anche la compensazione con crediti fiscali e previdenziali. Le scadenze cambiano secondo la categoria: per i dipendenti il giorno 16 del mese successivo al periodo di paga; per artigiani e commercianti rate fisse sul minimale e saldo e acconti con le imposte; per la gestione separata dipende da chi deve versare.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-INPS-11~1","s":"S22-INPS-11","q":"Scadenza del versamento dei contributi dei dipendenti?","a":"Il 16 del mese successivo al periodo di paga, con F24.","v":{"p":null,"e":[["16","n",["16"]],["24","n",["24"]],["mese","k",["mes"]],["successivo","k",["success"]],["periodo","k",["perio"]],["paga","k",["pag"]]],"r":[]}},{"id":"S22-INPS-11~2","s":"S22-INPS-11","q":"Aliquota IVS 2026 di artigiani e commercianti?","a":"24%.","v":{"p":null,"e":[["24%","n",["24"]]],"r":[]},"t":"d"},{"id":"S22-INPS-11~3","s":"S22-INPS-11","q":"Quale norma consente la compensazione in F24?","a":"L'art. 17 D.Lgs. 241/1997.","v":{"p":null,"e":[["241/1997","n",["241","1997"]],["art. 17","n",["17"]]],"r":[]},"t":"e"},{"id":"INPS-9~0","s":"INPS-9","q":"Qual è il cuore di «Il modello UniLav»? Rispondi in due o tre frasi.","a":"L'UniLav è il modello telematico unificato con cui tutti i datori di lavoro, pubblici e privati, comunicano assunzioni, proroghe, trasformazioni e cessazioni dei rapporti di lavoro.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INPS-9~1","s":"INPS-9","q":"Termine dell'UniLav di assunzione?","a":"Entro il giorno precedente l'inizio del rapporto.","v":{"p":null,"e":[["giorno","k",["giorn","gg"]],["precedente","k",["precede"]],["inizio","k",["inizi"]],["rapporto","k",["rappo","contratt"]]],"r":[]}},{"id":"INPS-9~2","s":"INPS-9","q":"Quale modello si usa in caso di urgenza?","a":"UniUrg, con UniLav entro il primo giorno utile e comunque entro 5 giorni.","v":{"p":null,"e":[["1","n",["1"]],["5","n",["5"]],["UniUrg","k",["uniurg"]],["UniLav","k",["unilav"]],["giorno","k",["giorn","gg"]],["utile","k",["utile"]]],"r":[]}},{"id":"INPS-9~3","s":"INPS-9","q":"Da quando l'assunzione si può comunicare tramite SIISL?","a":"Dal 1/1/2026 (art. 14, c. 2, D.L. 159/2025).","v":{"p":null,"e":[["1","n",["1"]],["2026","n",["2026"]],["gennaio","k",["genna"]]],"r":[["159/2025",["159","2025"]],["art. 14",["14"]]]},"t":"d"},{"id":"S22-INPS-10~0","s":"S22-INPS-10","q":"Qual è il cuore di «La Comunicazione Unica per la nascita dell'impresa»? Rispondi in due o tre frasi.","a":"La Comunicazione Unica (ComUnica) è la pratica telematica unica con cui chi avvia un'impresa assolve insieme gli adempimenti verso Registro delle imprese, Agenzia delle Entrate, INPS e INAIL (art. 9 D.L. 7/2007, conv. L. 40/2007). Si presenta all'ufficio del Registro delle imprese, che la smista agli enti.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-INPS-10~1","s":"S22-INPS-10","q":"Quale norma istituisce la Comunicazione Unica?","a":"L'art. 9 D.L. 7/2007, conv. L. 40/2007.","v":{"p":null,"e":[["7/2007","n",["7","2007"]],["art. 9","n",["9"]]],"r":[["40/2007",["40","2007"]]]},"t":"e"},{"id":"S22-INPS-10~2","s":"S22-INPS-10","q":"Cosa comunica l'INAIL dopo ComUnica?","a":"Codice ditta e PAT, ed emette il certificato di assicurazione.","v":{"p":null,"e":[["Codice","k",["codic"]],["ditta","k",["ditta"]],["PAT","k",["pat"]],["emette","k",["emett"]],["certificato","k",["certific"]],["assicurazione","k",["assicura"]]],"r":[]}},{"id":"S22-INPS-10~3","s":"S22-INPS-10","q":"La ricevuta del Registro delle imprese consente di avviare l'attività?","a":"Sì, subito, se ci sono i presupposti di legge.","v":{"p":"s","e":[["subito","k",["subit"]],["presupposti","k",["presuppo"]],["legge","k",["legge"]]],"r":[]}},{"id":"S22-INPS-4~0","s":"S22-INPS-4","q":"Qual è il cuore di «Il contenzioso amministrativo nei confronti dell'INPS»? Rispondi in due o tre frasi.","a":"Prima di andare dal giudice, contro i provvedimenti dell'INPS si propone ricorso amministrativo ai Comitati dell'Istituto. Per le prestazioni dei dipendenti privati il ricorso al Comitato provinciale è condizione di procedibilità della domanda giudiziale (artt. 46-47 L. 88/1989). Le regole operative sono nel Regolamento dei ricorsi del 18/1/2023, illustrato dalla circolare INPS 48/2023.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-INPS-4~1","s":"S22-INPS-4","q":"Termine ordinario per il ricorso ai Comitati INPS?","a":"90 giorni dal provvedimento.","v":{"p":null,"e":[["90","n",["90"]],["giorni","k",["giorn","gg"]],["provvedimento","k",["provvedi"]]],"r":[]}},{"id":"S22-INPS-4~2","s":"S22-INPS-4","q":"Dopo quanti giorni si forma il silenzio-rigetto sulla domanda all'INPS?","a":"120 giorni (art. 7 L. 533/1973).","v":{"p":null,"e":[["120","n",["120"]]],"r":[["533/1973",["533","1973"]],["art. 7",["7"]]]},"t":"d"},{"id":"S22-INPS-4~3","s":"S22-INPS-4","q":"Termine di opposizione all'avviso di addebito?","a":"40 giorni, davanti al giudice del lavoro (art. 24 D.Lgs. 46/1999).","v":{"p":null,"e":[["40","n",["40"]],["giorni","k",["giorn","gg"]],["davanti","k",["davan"]],["giudice","k",["giudi","tribunal"]],["lavoro","k",["lavor","dipendent","prestator"]]],"r":[["46/1999",["46","1999"]],["art. 24",["24"]]]}},{"id":"S22-INPS-5~0","s":"S22-INPS-5","q":"Qual è il cuore di «Il sistema UniEmens»? Rispondi in due o tre frasi.","a":"UniEmens è il flusso telematico mensile con cui il datore di lavoro, o il consulente delegato, trasmette all'INPS i dati retributivi e contributivi individuali di ogni lavoratore (art. 44 D.L. 269/2003, conv. L. 326/2003). È la base del conto assicurativo del lavoratore e del calcolo dei contributi.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-INPS-5~1","s":"S22-INPS-5","q":"Termine di invio del flusso UniEmens?","a":"Entro l'ultimo giorno del mese successivo a quello di competenza.","v":{"p":null,"e":[["ultimo","k",["ultim"]],["giorno","k",["giorn","gg"]],["mese","k",["mes"]],["successivo","k",["success"]],["competenza","k",["compete"]]],"r":[]}},{"id":"S22-INPS-5~2","s":"S22-INPS-5","q":"Quale norma ha istituito UniEmens?","a":"L'art. 44 D.L. 269/2003, conv. L. 326/2003.","v":{"p":null,"e":[["269/2003","n",["269","2003"]],["art. 44","n",["44"]]],"r":[["326/2003",["326","2003"]]]},"t":"e"},{"id":"S22-INPS-5~3","s":"S22-INPS-5","q":"Che cos'è il principio di nettizzazione?","a":"Contributi esposti e versati al netto di esoneri e sgravi spettanti.","v":{"p":null,"e":[["Contributi","k",["contrib","contribuz","contribut"]],["esposti","k",["espos"]],["versati","k",["versa"]],["netto","k",["netto"]],["esoneri","k",["esone","sgrav","agevol","riduz"]],["sgravi","k",["sgrav","esoner","agevol","riduz"]],["spettanti","k",["spetta"]]],"r":[]}},{"id":"INPS-7~0","s":"INPS-7","q":"Qual è il cuore di «Il Fondo di garanzia per il TFR e i crediti di lavoro»? Rispondi in due o tre frasi.","a":"Il Fondo di garanzia dell'INPS paga al lavoratore il TFR e le ultime retribuzioni non corrisposte quando il datore è insolvente (art. 2 L. 297/1982; D.Lgs. 80/1992).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INPS-7~1","s":"INPS-7","q":"Quali norme regolano il Fondo di garanzia INPS?","a":"Art. 2 L. 297/1982 (TFR) e D.Lgs. 80/1992 (ultime retribuzioni).","v":{"p":null,"e":[["297/1982","n",["297","1982"]],["80/1992","n",["80","1992"]],["art. 2","n",["2"]]],"r":[]},"t":"e"},{"id":"INPS-7~2","s":"INPS-7","q":"Quante mensilità di retribuzione copre il Fondo di garanzia?","a":"Le ultime 3, se rientrano nei 12 mesi precedenti la procedura.","v":{"p":null,"e":[["3","n",["3"]],["12","n",["12"]],["ultime","k",["ultim"]],["rientrano","k",["rientr"]],["mesi","k",["mes"]],["precedenti","k",["precede"]],["procedura","k",["proced"]]],"r":[]}},{"id":"INPS-7~3","s":"INPS-7","q":"Contributo che finanzia il Fondo di garanzia?","a":"0,20% delle retribuzioni (0,40% per i dirigenti industriali).","v":{"p":null,"e":[["0,20%","n",["0.20"]],["retribuzioni","k",["retribuz","stipend","paga","salari"]]],"r":[]},"t":"d"},{"id":"INPS-10~0","s":"INPS-10","q":"Qual è il cuore di «Il congedo parentale»? Rispondi in due o tre frasi.","a":"Il congedo parentale è il diritto di ciascun genitore di astenersi dal lavoro nei primi 14 anni del figlio, con un'indennità INPS in parte all'80% e in parte al 30% (artt. 32-35 D.Lgs. 151/2001).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INPS-10~1","s":"INPS-10","q":"Fino a quale età del figlio spetta il congedo parentale ai dipendenti dal 2026?","a":"14 anni (L. 199/2025, c. 219).","v":{"p":null,"e":[["14","n",["14"]],["anni","k",["ann"]]],"r":[["199/2025",["199","2025"]]]}},{"id":"INPS-10~2","s":"INPS-10","q":"Indennità del congedo parentale?","a":"30% per 9 mesi; 3 mesi all'80% entro i 6 anni del figlio.","v":{"p":null,"e":[["30%","n",["30"]],["9","n",["9"]],["3","m",["3"]],["80%","m",["80"]],["6","m",["6"]],["mesi","k",["mes"]],["anni","k",["ann"]],["figlio","k",["figli"]]],"r":[]}},{"id":"INPS-10~3","s":"INPS-10","q":"Preavviso per il congedo parentale?","a":"Almeno 5 giorni (2 per quello orario).","v":{"p":null,"e":[["5","n",["5"]],["giorni","k",["giorn","gg"]]],"r":[]},"t":"d"},{"id":"INPS-16~0","s":"INPS-16","q":"Qual è il cuore di «La previdenza complementare»? Rispondi in due o tre frasi.","a":"La previdenza complementare è il secondo pilastro volontario che integra la pensione pubblica attraverso fondi pensione finanziati soprattutto dal TFR (D.Lgs. 252/2005).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INPS-16~1","s":"INPS-16","q":"Quale decreto disciplina la previdenza complementare?","a":"Il D.Lgs. 252/2005.","v":{"p":null,"e":[["252/2005","n",["252","2005"]]],"r":[]},"t":"e"},{"id":"INPS-16~2","s":"INPS-16","q":"Dal 1/7/2026 come aderisce il neoassunto alla previdenza complementare?","a":"Automaticamente, se entro 60 giorni non rinuncia (L. 199/2025, c. 204-205).","v":{"p":null,"e":[["60","n",["60"]],["Automaticamente","k",["automati"]],["giorni","k",["giorn","gg"]],["rinuncia","k",["rinun"]]],"r":[["199/2025",["199","2025"]]]}},{"id":"INPS-16~3","s":"INPS-16","q":"Fondo residuale se manca il fondo contrattuale?","a":"COMETA.","v":{"p":null,"e":[["COMETA","k",["cometa"]]],"r":[]}},{"id":"INPS-17~0","s":"INPS-17","q":"Qual è il cuore di «La malattia: adempimenti e diritti»? Rispondi in due o tre frasi.","a":"La malattia sospende il rapporto con conservazione del posto per il periodo di comporto (art. 2110 c.c.); per molte categorie il reddito è garantito da un'indennità INPS integrata dal datore.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INPS-17~1","s":"INPS-17","q":"Da quale giorno l'INPS paga l'indennità di malattia e per quanti giorni l'anno?","a":"Dal 4° giorno, fino a 180 giorni l'anno.","v":{"p":null,"e":[["4","n",["4"]],["180","n",["180"]]],"r":[]}},{"id":"INPS-17~2","s":"INPS-17","q":"Misura dell'indennità INPS di malattia?","a":"50% dal 4° al 20° giorno, 66,66% dal 21° al 180°.","v":{"p":null,"e":[["50%","n",["50"]],["4","n",["4"]],["20","n",["20"]],["66,66%","n",["66.66"]],["21","n",["21"]],["180","n",["180"]],["giorno","k",["giorn","gg"]]],"r":[]}},{"id":"INPS-17~3","s":"INPS-17","q":"Fasce di reperibilità per la visita di controllo?","a":"Dalle 10 alle 12 e dalle 17 alle 19, anche festivi.","v":{"p":null,"e":[["10","n",["10"]],["12","n",["12"]],["17","n",["17"]],["19","n",["19"]],["festivi","k",["festi"]]],"r":[]}},{"id":"INPS-19~0","s":"INPS-19","q":"Qual è il cuore di «I permessi della L. 104/1992»? Rispondi in due o tre frasi.","a":"La L. 104/1992 riconosce permessi retribuiti al lavoratore con disabilità grave e a chi assiste un familiare con disabilità grave non ricoverato a tempo pieno (art. 33).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INPS-19~1","s":"INPS-19","q":"Permessi del lavoratore con disabilità grave (L. 104/1992)?","a":"2 ore al giorno o 3 giorni al mese (art. 33, c. 6).","v":{"p":null,"e":[["2","n",["2"]],["3","n",["3"]],["ore","k",["ore"]],["giorno","k",["giorn","gg"]],["mese","k",["mes"]]],"r":[["art. 33",["33"]]]}},{"id":"INPS-19~2","s":"INPS-19","q":"Permessi per assistere un familiare con disabilità grave?","a":"3 giorni al mese (art. 33, c. 3).","v":{"p":null,"e":[["3","n",["3"]],["giorni","k",["giorn","gg"]],["mese","k",["mes"]]],"r":[["art. 33",["33"]]]}},{"id":"INPS-19~3","s":"INPS-19","q":"Durata massima del congedo straordinario per assistenza?","a":"Fino a 2 anni (art. 42 D.Lgs. 151/2001).","v":{"p":null,"e":[["2","n",["2"]],["anni","k",["ann"]]],"r":[["151/2001",["151","2001"]],["art. 42",["42"]]]}},{"id":"INPS-X4~0","s":"INPS-X4","q":"Qual è il cuore di «Ricongiunzione, totalizzazione e cumulo dei periodi contributivi»? Rispondi in due o tre frasi.","a":"Chi ha versato contributi in più gestioni previdenziali può unirli per ottenere un'unica pensione con tre istituti: la ricongiunzione, che trasferisce materialmente i contributi in una sola gestione ed è onerosa; la totalizzazione e il cumulo, che sono gratuiti e sommano i periodi non coincidenti, con pensione calcolata pro quota da ciascuna gestione.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INPS-X4~1","s":"INPS-X4","q":"Quale istituto trasferisce i contributi in un'unica gestione ed è oneroso?","a":"La ricongiunzione (L. 29/1979; L. 45/1990 per le casse professionali).","v":{"p":null,"e":[["ricongiunzione","k",["ricongiu"]]],"r":[["29/1979",["29","1979"]],["45/1990",["45","1990"]]]}},{"id":"INPS-X4~2","s":"INPS-X4","q":"Quale norma regola la totalizzazione?","a":"Il D.Lgs. 42/2006.","v":{"p":null,"e":[["42/2006","n",["42","2006"]]],"r":[]},"t":"e"},{"id":"INPS-X4~3","s":"INPS-X4","q":"Quale legge ha introdotto il cumulo gratuito?","a":"La L. 228/2012 (art. 1, c. 239 ss.), ampliata dalla L. 232/2016.","v":{"p":null,"e":[["228/2012","n",["228","2012"]],["232/2016","n",["232","2016"]],["ampliata","k",["ampli"]]],"r":[["art. 1",["1"]]]},"t":"e"},{"id":"S22-INPS-1~0","s":"S22-INPS-1","q":"Qual è il cuore di «Il sistema previdenziale: le gestioni e le principali pensioni»? Rispondi in due o tre frasi.","a":"Il sistema previdenziale pubblico è a ripartizione: i contributi dei lavoratori attivi pagano le pensioni in corso. L'INPS gestisce l'assicurazione generale obbligatoria (AGO) per i dipendenti privati (FPLD), le gestioni speciali degli autonomi (artigiani, commercianti, coltivatori diretti), la gestione separata e le gestioni ex INPDAP dei pubblici; i liberi professionisti ordinistici hanno le proprie Casse. Le due pensioni strutturali sono la vecchiaia e l'anticipata (riforma Fornero, art. 24 D.L. 201/2011).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-INPS-1~1","s":"S22-INPS-1","q":"Requisiti della pensione di vecchiaia nel 2026?","a":"67 anni e almeno 20 anni di contributi.","v":{"p":null,"e":[["67","n",["67"]],["20","n",["20"]],["anni","k",["ann"]],["contributi","k",["contrib","contribuz","contribut"]]],"r":[]}},{"id":"S22-INPS-1~2","s":"S22-INPS-1","q":"Contributi per la pensione anticipata ordinaria nel 2026?","a":"42 anni e 10 mesi gli uomini, 41 anni e 10 mesi le donne.","v":{"p":null,"e":[["42","n",["42"]],["10","n",["10"]],["41","n",["41"]],["anni","k",["ann"]],["mesi","k",["mes"]],["uomini","k",["uomin"]],["donne","k",["donne"]]],"r":[]}},{"id":"S22-INPS-1~3","s":"S22-INPS-1","q":"Il diritto alla pensione si prescrive?","a":"No, è imprescrittibile; i ratei si prescrivono in 5 anni.","v":{"p":"n","e":[["5","m",["5"]],["imprescrittibile","k",["imprescr","non si prescrive","non si prescrivono"]],["ratei","k",["ratei"]],["anni","k",["ann"]]],"r":[]}},{"id":"S22-INPS-13~0","s":"S22-INPS-13","q":"Qual è il cuore di «L'assegno unico e universale»? Rispondi in due o tre frasi.","a":"L'assegno unico e universale (AUU, D.Lgs. 230/2021) è il sostegno economico mensile per i figli a carico, pagato direttamente dall'INPS su domanda. Ha sostituito assegni al nucleo familiare per chi ha figli, detrazioni per figli under 21 e altri bonus; l'importo dipende dall'ISEE.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-INPS-13~1","s":"S22-INPS-13","q":"Quale decreto istituisce l'assegno unico e universale?","a":"Il D.Lgs. 230/2021.","v":{"p":null,"e":[["230/2021","n",["230","2021"]]],"r":[]},"t":"e"},{"id":"S22-INPS-13~2","s":"S22-INPS-13","q":"Fino a quale età spetta l'AUU per i figli maggiorenni?","a":"Fino a 21 anni, se studiano, fanno tirocinio, lavorano con reddito sotto 8.000 euro o sono disoccupati iscritti.","v":{"p":null,"e":[["21","n",["21"]],["8.000","n",["8000"]],["anni","k",["ann"]],["studiano","k",["studi"]],["tirocinio","k",["tiroci"]],["lavorano","k",["lavor","dipendent","prestator"]],["reddito","k",["reddi"]],["sotto","k",["sotto"]],["euro","k",["eur"]],["disoccupati","k",["disoccup"]],["iscritti","k",["iscri"]]],"r":[]},"t":"d"},{"id":"S22-INPS-13~3","s":"S22-INPS-13","q":"L'assegno unico passa in busta paga?","a":"No: lo paga direttamente l'INPS.","v":{"p":"n","e":[["direttamente","k",["direttam"]],["INPS","k",["inps"]]],"r":[]}},{"id":"S22-INPS-2~0","s":"S22-INPS-2","q":"Qual è il cuore di «I requisiti pensionistici diversi da quelli ordinari»? Rispondi in due o tre frasi.","a":"Accanto a vecchiaia e anticipata ordinaria esistono canali d'uscita con requisiti diversi: strutturali (anticipata contributiva, precoci, usuranti) o sperimentali e ormai a esaurimento (quota 103, opzione donna), oltre all'APE sociale. Il principio di cristallizzazione consente di usare un requisito maturato entro la scadenza anche dopo.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-INPS-2~1","s":"S22-INPS-2","q":"Requisiti della pensione anticipata contributiva?","a":"64 anni, 20 anni di contributi, importo almeno 3 volte l'assegno sociale (contributivi puri).","v":{"p":null,"e":[["64","n",["64"]],["20","n",["20"]],["3","n",["3"]],["anni","k",["ann"]],["importo","k",["impor"]],["volte","k",["volte"]],["assegno","k",["asseg"]],["sociale","k",["socia"]]],"r":[]}},{"id":"S22-INPS-2~2","s":"S22-INPS-2","q":"Requisiti dei lavoratori precoci?","a":"12 mesi di lavoro prima dei 19 anni; pensione con 41 anni di contributi in casi di tutela.","v":{"p":null,"e":[["12","n",["12"]],["19","n",["19"]],["41","m",["41"]],["mesi","k",["mes"]],["anni","k",["ann"]],["pensione","k",["pensi"]],["contributi","k",["contrib","contribuz","contribut"]],["tutela","k",["tutel"]]],"r":[]},"t":"d"},{"id":"S22-INPS-2~3","s":"S22-INPS-2","q":"Quota 103 è stata prorogata per il 2026?","a":"No: vale solo per chi ha maturato i requisiti entro il 31/12/2025.","v":{"p":"n","e":[["31","n",["31"]],["2025","n",["2025"]],["vale","k",["val"]],["maturato","k",["matur"]],["requisiti","k",["requis"]],["dicembre","k",["dicem"]]],"r":[]}},{"id":"S22-INPS-3~0","s":"S22-INPS-3","q":"Qual è il cuore di «I sistemi di calcolo della pensione»? Rispondi in due o tre frasi.","a":"I sistemi di calcolo sono tre: retributivo (media delle ultime retribuzioni), contributivo (contributi versati in tutta la vita, introdotto dalla L. 335/1995) e misto. Quale si applica dipende dai contributi posseduti al 31/12/1995; dal 2012 tutti passano al contributivo per le anzianità successive (riforma Fornero).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-INPS-3~1","s":"S22-INPS-3","q":"Quale legge ha introdotto il sistema contributivo?","a":"La L. 335/1995.","v":{"p":null,"e":[["335/1995","n",["335","1995"]]],"r":[]},"t":"p"},{"id":"S22-INPS-3~2","s":"S22-INPS-3","q":"Quale aliquota si accantona ogni anno nel contributivo per i dipendenti?","a":"33% della retribuzione imponibile (24% per artigiani e commercianti).","v":{"p":null,"e":[["33%","n",["33"]],["retribuzione","k",["retribuz","stipend","paga","salari"]],["imponibile","k",["imponib"]]],"r":[]}},{"id":"S22-INPS-3~3","s":"S22-INPS-3","q":"Chi ha almeno 18 anni di contributi al 31/12/1995 che sistema ha?","a":"Retributivo fino al 2011, contributivo dal 2012.","v":{"p":null,"e":[["2011","n",["2011"]],["2012","n",["2012"]],["Retributivo","k",["retribut"]]],"r":[]}},{"id":"INPS-1~0","s":"INPS-1","q":"Qual è il cuore di «La cassa integrazione guadagni ordinaria»? Rispondi in due o tre frasi.","a":"La CIGO integra la retribuzione dei dipendenti delle imprese industriali (e assimilate) in caso di sospensione o riduzione dell'attività per eventi transitori non imputabili o per situazioni temporanee di mercato (artt. 10-18 D.Lgs. 148/2015).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INPS-1~1","s":"INPS-1","q":"Misura dell'integrazione salariale CIGO?","a":"80% della retribuzione globale per le ore non lavorate, entro il massimale (2026: 1.423,69 euro lordi).","v":{"p":null,"e":[["80%","n",["80"]],["retribuzione","k",["retribuz","stipend","paga","salari"]],["globale","k",["globa"]],["ore","k",["ore"]],["lavorate","k",["lavor","dipendent","prestator"]],["massimale","k",["massim"]]],"r":[]}},{"id":"INPS-1~2","s":"INPS-1","q":"Durata della CIGO?","a":"13 settimane continuative, prorogabili fino a 52; 52 settimane nel biennio mobile.","v":{"p":null,"e":[["13","n",["13"]],["52","n",["52"]],["settimane","k",["settim"]],["continuative","k",["continua"]],["prorogabili","k",["prorogab"]],["biennio","k",["bienn"]],["mobile","k",["mobil"]]],"r":[]}},{"id":"INPS-1~3","s":"INPS-1","q":"Entro quanto si presenta la domanda di CIGO?","a":"Entro 15 giorni dall'inizio della sospensione (art. 15).","v":{"p":null,"e":[["15","n",["15"]],["giorni","k",["giorn","gg"]],["inizio","k",["inizi"]],["sospensione","k",["sospensi"]]],"r":[["art. 15",["15"]]]}},{"id":"INPS-2~0","s":"INPS-2","q":"Qual è il cuore di «La cassa integrazione guadagni straordinaria»? Rispondi in due o tre frasi.","a":"La CIGS sostiene il reddito in caso di riorganizzazione, crisi aziendale o contratto di solidarietà, per i datori non coperti dai fondi di solidarietà che nel semestre precedente hanno occupato mediamente più di 15 dipendenti (artt. 19-25-ter D.Lgs. 148/2015).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INPS-2~1","s":"INPS-2","q":"Quali datori accedono alla CIGS?","a":"Con più di 15 dipendenti medi nel semestre, non coperti dai fondi di solidarietà.","v":{"p":null,"e":[["15","n",["15"]],["dipendenti","k",["dipende","lavorat"]],["medi","k",["med"]],["semestre","k",["semes"]],["coperti","k",["coper"]],["fondi","k",["fondi"]],["solidarietà","k",["solidari"]]],"r":[]}},{"id":"INPS-2~2","s":"INPS-2","q":"Durate massime per causale CIGS?","a":"Riorganizzazione 24 mesi, crisi 12 mesi, solidarietà 24 mesi nel quinquennio.","v":{"p":null,"e":[["24","n",["24"]],["12","n",["12"]],["Riorganizzazione","k",["riorgani"]],["mesi","k",["mes"]],["crisi","k",["crisi"]],["solidarietà","k",["solidari"]],["quinquennio","k",["quinquen"]]],"r":[]}},{"id":"INPS-2~3","s":"INPS-2","q":"Limite di ore sospendibili in CIGS per riorganizzazione o crisi?","a":"L'80% delle ore lavorabili nell'unità produttiva.","v":{"p":null,"e":[["80%","n",["80"]],["ore","k",["ore"]],["lavorabili","k",["lavorab"]],["unità","k",["unita"]],["produttiva","k",["produtt"]]],"r":[]},"t":"d"},{"id":"INPS-4~0","s":"INPS-4","q":"Qual è il cuore di «La classificazione degli ammortizzatori sociali»? Rispondi in due o tre frasi.","a":"Gli ammortizzatori sociali sono le misure di politica passiva che tutelano il reddito del lavoratore e si distinguono in strumenti in costanza di rapporto e strumenti per la disoccupazione.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INPS-4~1","s":"INPS-4","q":"Quali sono gli ammortizzatori in costanza di rapporto?","a":"CIGO, CIGS, fondi di solidarietà e FIS, contratti di solidarietà.","v":{"p":null,"e":[["CIGO","k",["cigo","cassa integrazione"]],["CIGS","k",["cigs","cassa integrazione"]],["fondi","k",["fondi"]],["solidarietà","k",["solidari"]],["FIS","k",["fis"]],["contratti","k",["contra","rapport"]]],"r":[]}},{"id":"INPS-4~2","s":"INPS-4","q":"Quale decreto disciplina NASpI e DIS-COLL?","a":"Il D.Lgs. 22/2015.","v":{"p":null,"e":[["22/2015","n",["22","2015"]]],"r":[]},"t":"p"},{"id":"INPS-4~3","s":"INPS-4","q":"Che cos'è l'ISCRO?","a":"Indennità straordinaria di continuità reddituale e operativa per gli autonomi in gestione separata.","v":{"p":null,"e":[["Indennità","k",["indenn"]],["straordinaria","k",["straordi"]],["continuità","k",["continu"]],["reddituale","k",["redditu"]],["operativa","k",["operat"]],["autonomi","k",["auton"]],["gestione","k",["gesti"]],["separata","k",["separ"]]],"r":[]}},{"id":"INPS-5~0","s":"INPS-5","q":"Qual è il cuore di «Presupposti e limiti degli ammortizzatori sociali»? Rispondi in due o tre frasi.","a":"Gli ammortizzatori in costanza di rapporto richiedono requisiti di lavoratore, di datore e di causale, e incontrano limiti di misura e di durata fissati dal D.Lgs. 148/2015.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INPS-5~1","s":"INPS-5","q":"Anzianità minima del lavoratore per gli ammortizzatori in costanza di rapporto?","a":"30 giorni di effettivo lavoro nell'unità produttiva (art. 1).","v":{"p":null,"e":[["30","n",["30"]],["giorni","k",["giorn","gg"]],["effettivo","k",["effett"]],["unità","k",["unita"]],["produttiva","k",["produtt"]]],"r":[["art. 1",["1"]]]}},{"id":"INPS-5~2","s":"INPS-5","q":"Durata massima complessiva degli ammortizzatori?","a":"24 mesi nel quinquennio mobile per unità produttiva (30 edilizia e lapidei; fino a 36 con solidarietà).","v":{"p":null,"e":[["24","n",["24"]],["mesi","k",["mes"]],["quinquennio","k",["quinquen"]],["mobile","k",["mobil"]],["unità","k",["unita"]],["produttiva","k",["produtt"]]],"r":[]}},{"id":"INPS-5~3","s":"INPS-5","q":"Effetto dell'omessa comunicazione all'INPS dell'altra attività lavorativa?","a":"Decadenza dal trattamento (art. 8).","v":{"p":null,"e":[["Decadenza","k",["decade"]],["trattamento","k",["trattame"]]],"r":[["art. 8",["8"]]]}},{"id":"INPS-6~0","s":"INPS-6","q":"Qual è il cuore di «La NASpI»? Rispondi in due o tre frasi.","a":"La NASpI è l'indennità mensile di disoccupazione per i lavoratori subordinati che hanno perso involontariamente il lavoro (D.Lgs. 22/2015).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INPS-6~1","s":"INPS-6","q":"Requisito contributivo della NASpI?","a":"13 settimane nei 4 anni precedenti.","v":{"p":null,"e":[["13","n",["13"]],["4","n",["4"]],["settimane","k",["settim"]],["anni","k",["ann"]],["precedenti","k",["precede"]]],"r":[]}},{"id":"INPS-6~2","s":"INPS-6","q":"Durata massima della NASpI?","a":"Metà delle settimane contributive degli ultimi 4 anni: massimo 2 anni.","v":{"p":null,"e":[["4","n",["4"]],["2","n",["2"]],["Metà","k",["met"]],["settimane","k",["settim"]],["contributive","k",["contribu","contribuz","contribut"]],["ultimi","k",["ultim"]],["anni","k",["ann"]]],"r":[]}},{"id":"INPS-6~3","s":"INPS-6","q":"Termine per la domanda di NASpI?","a":"68 giorni dalla cessazione.","v":{"p":null,"e":[["68","n",["68"]],["giorni","k",["giorn","gg"]],["cessazione","k",["cessazi"]]],"r":[]}},{"id":"INPS-11~0","s":"INPS-11","q":"Qual è il cuore di «Le misure a sostegno del reddito»? Rispondi in due o tre frasi.","a":"Le misure a sostegno del reddito dei lavoratori si dividono tra integrazioni durante il rapporto e indennità dopo la cessazione, con regole diverse per subordinati, collaboratori e autonomi.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INPS-11~1","s":"INPS-11","q":"Durata dell'assegno di integrazione salariale del FIS?","a":"13 settimane nel biennio mobile fino a 5 dipendenti, 26 oltre.","v":{"p":null,"e":[["13","n",["13"]],["5","n",["5"]],["26","n",["26"]],["settimane","k",["settim"]],["biennio","k",["bienn"]],["mobile","k",["mobil"]],["dipendenti","k",["dipende","lavorat"]]],"r":[]}},{"id":"INPS-11~2","s":"INPS-11","q":"Indennità di disoccupazione dei collaboratori?","a":"La DIS-COLL.","v":{"p":null,"e":[["DISCOLL","k",["discoll","dis coll"]]],"r":[]}},{"id":"INPS-11~3","s":"INPS-11","q":"Quale principio lega le prestazioni alle politiche attive?","a":"Il principio di condizionalità.","v":{"p":null,"e":[["condizionalità","k",["condizio"]]],"r":[]}},{"id":"INPS-21~0","s":"INPS-21","q":"Qual è il cuore di «La compatibilità della NASpI con l'attività lavorativa»? Rispondi in due o tre frasi.","a":"Durante la NASpI il lavoro non fa automaticamente perdere l'indennità: conta il tipo di attività, la sua durata e il reddito previsto (artt. 9-10 D.Lgs. 22/2015).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INPS-21~1","s":"INPS-21","q":"Lavoro subordinato in NASpI fino a 6 mesi con reddito sopra il limite esente: che succede?","a":"La NASpI è sospesa d'ufficio per la durata del rapporto.","v":{"p":null,"e":[["sospesa","k",["sospe"]],["ufficio","k",["uffic"]],["durata","k",["durat"]],["rapporto","k",["rappo","contratt"]]],"r":[]}},{"id":"INPS-21~2","s":"INPS-21","q":"Di quanto si riduce la NASpI con un reddito sotto il limite esente?","a":"Dell'80% del reddito previsto, comunicato entro 30 giorni.","v":{"p":null,"e":[["80%","n",["80"]],["30","n",["30"]],["previsto","k",["previ"]],["comunicato","k",["comunic"]],["giorni","k",["giorn","gg"]]],"r":[]},"t":"d"},{"id":"INPS-21~3","s":"INPS-21","q":"DIS-COLL e lavoro subordinato: quando si ha decadenza?","a":"Oltre 5 giorni di lavoro; fino a 5 giorni è sospesa.","v":{"p":null,"e":[["5","n",["5"]],["giorni","k",["giorn","gg"]],["sospesa","k",["sospe"]]],"r":[]},"t":"d"},{"id":"INPS-X5~0","s":"INPS-X5","q":"Qual è il cuore di «Il contributo di licenziamento («ticket NASpI»)»? Rispondi in due o tre frasi.","a":"Il ticket di licenziamento è una somma una tantum a carico del datore di lavoro, destinata a finanziare la NASpI, dovuta quando un rapporto a tempo indeterminato cessa per una causa che darebbe diritto alla NASpI, a prescindere dal fatto che il lavoratore abbia i requisiti contributivi o la chieda davvero (art. 2, c. 31, L. 92/2012).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INPS-X5~1","s":"INPS-X5","q":"Quale norma prevede il ticket di licenziamento?","a":"L'art. 2, c. 31, L. 92/2012.","v":{"p":null,"e":[["92/2012","n",["92","2012"]],["art. 2","n",["2"]]],"r":[]},"t":"e"},{"id":"INPS-X5~2","s":"INPS-X5","q":"Importo del ticket per ogni anno di anzianità?","a":"41% del massimale mensile NASpI (2026: circa 649,73 euro).","v":{"p":null,"e":[["41%","n",["41"]],["massimale","k",["massim"]],["mensile","k",["mensi"]],["NASpI","k",["naspi","disoccupazione"]]],"r":[]}},{"id":"INPS-X5~3","s":"INPS-X5","q":"Quando il ticket è triplicato?","a":"Nei licenziamenti collettivi senza accordo sindacale (c. 35).","v":{"p":null,"e":[["licenziamenti","k",["licenzia","recess"]],["collettivi","k",["collett"]],["accordo","k",["accor"]],["sindacale","k",["sindac"]]],"r":[]}},{"id":"S22-INPS-14~0","s":"S22-INPS-14","q":"Qual è il cuore di «I fondi di solidarietà bilaterali e il Fondo di integrazione salariale (FIS)»? Rispondi in due o tre frasi.","a":"Per i datori di lavoro che non rientrano nella cassa integrazione ordinaria, la tutela in caso di sospensione o riduzione dell'attività è affidata ai fondi di solidarietà (D.Lgs. 148/2015, artt. 26 ss.): fondi bilaterali di settore istituiti dalla contrattazione collettiva, fondi alternativi (artigianato e somministrazione) e, in via residuale, il Fondo di integrazione salariale (FIS) presso l'INPS. Dal 2022 l'obbligo riguarda i datori con almeno un dipendente.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-INPS-14~1","s":"S22-INPS-14","q":"Da quanti dipendenti è obbligatoria la copertura dei fondi di solidarietà o del FIS?","a":"Da almeno un dipendente (dal 2022).","v":{"p":null,"e":[["dipendente","k",["dipende","lavorat"]]],"r":[]}},{"id":"S22-INPS-14~2","s":"S22-INPS-14","q":"Ripartizione del contributo ai fondi di solidarietà?","a":"2/3 datore, 1/3 lavoratore (art. 33 D.Lgs. 148/2015).","v":{"p":null,"e":[["2","n",["2"]],["3","n",["3"]],["1","n",["1"]],["datore","k",["dator","aziend","impres"]],["lavoratore","k",["lavorat","dipendent","prestator"]]],"r":[["148/2015",["148","2015"]],["art. 33",["33"]]]},"t":"d"},{"id":"S22-INPS-14~3","s":"S22-INPS-14","q":"Su quale piattaforma si chiede l'assegno FIS?","a":"OMNIA IS.","v":{"p":null,"e":[["OMNIA","k",["omnia"]],["IS","k",["is"]]],"r":[]}},{"id":"INPS-X1~0","s":"INPS-X1","q":"Qual è il cuore di «Le novità 2026 sulla NASpI e sul congedo parentale»? Rispondi in due o tre frasi.","a":"Le novità 2025-2026 riguardano soprattutto l'accesso alla NASpI dopo dimissioni e la sua liquidazione anticipata, e l'estensione a 14 anni del congedo parentale dei dipendenti.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INPS-X1~1","s":"INPS-X1","q":"Liquidazione anticipata della NASpI dal 2026: come avviene?","a":"In due rate: 70% subito, 30% alla fine del periodo teorico.","v":{"p":null,"e":[["2","n",["2"]],["70%","n",["70"]],["30%","n",["30"]],["rate","k",["rat"]],["subito","k",["subit"]],["fine","k",["fin"]],["periodo","k",["perio"]],["teorico","k",["teori"]]],"r":[]}},{"id":"INPS-X1~2","s":"INPS-X1","q":"Soglia e massimale NASpI 2026?","a":"Soglia 1.456,72 euro, massimale 1.584,70 euro (circ. INPS 4/2026).","v":{"p":null,"e":[["1.456,72","n",["1456.72"]],["1.584,70","n",["1584.70"]],["euro","k",["eur"]]],"r":[["4/2026",["4","2026"]]]},"t":"d"},{"id":"INPS-X1~3","s":"INPS-X1","q":"NASpI dopo dimissioni nei 12 mesi precedenti: cosa serve dal 2025?","a":"Maturare le 13 settimane dopo quella cessazione (L. 207/2024, art. 1, c. 171).","v":{"p":null,"e":[["13","n",["13"]],["Maturare","k",["matur"]],["settimane","k",["settim"]],["cessazione","k",["cessazi"]]],"r":[["207/2024",["207","2024"]],["art. 1",["1"]]]}},{"id":"INAIL-1~0","s":"INAIL-1","q":"Qual è il cuore di «La regolarità contributiva INAIL»? Rispondi in due o tre frasi.","a":"La regolarità verso l'INAIL significa aver denunciato le attività e pagato correttamente i premi; si attesta con il DURC, che verifica insieme INPS, INAIL e Casse edili.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INAIL-1~1","s":"INAIL-1","q":"Entro quando si fa l'autoliquidazione INAIL?","a":"Entro il 16 febbraio, con la dichiarazione delle retribuzioni.","v":{"p":null,"e":[["16","n",["16"]],["febbraio","k",["febbr"]],["dichiarazione","k",["dichiara"]],["retribuzioni","k",["retribuz","stipend","paga","salari"]]],"r":[]}},{"id":"INAIL-1~2","s":"INAIL-1","q":"Prescrizione dei premi INAIL?","a":"5 anni.","v":{"p":null,"e":[["5","n",["5"]],["anni","k",["ann"]]],"r":[]}},{"id":"INAIL-1~3","s":"INAIL-1","q":"Quale norma fissa le sanzioni civili INPS e INAIL?","a":"L'art. 116, c. 8, L. 388/2000.","v":{"p":null,"e":[["388/2000","n",["388","2000"]],["art. 116","n",["116"]]],"r":[]},"t":"p"},{"id":"INAIL-2~0","s":"INAIL-2","q":"Qual è il cuore di «Gli adempimenti per una nuova attività o una nuova sede»? Rispondi in due o tre frasi.","a":"Chi avvia un'attività soggetta all'obbligo assicurativo, o apre una nuova sede, deve fare telematicamente la denuncia di esercizio all'INAIL, che costituisce il rapporto assicurativo e calcola il premio (art. 12 T.U. D.P.R. 1124/1965; D.I. 27/2/2019).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INAIL-2~1","s":"INAIL-2","q":"Quale norma prevede la denuncia di esercizio INAIL?","a":"L'art. 12 T.U. D.P.R. 1124/1965 (con il D.I. 27/2/2019).","v":{"p":null,"e":[["1124/1965","n",["1124","1965"]],["art. 12","n",["12"]],["TU","k",["tu"]]],"r":[]},"t":"e"},{"id":"INAIL-2~2","s":"INAIL-2","q":"Quando va presentata la denuncia di iscrizione?","a":"Contestualmente all'inizio dell'attività; per urgenza entro 5 giorni, motivando.","v":{"p":null,"e":[["5","m",["5"]],["Contestualmente","k",["contestu"]],["inizio","k",["inizi"]],["attività","k",["attiv"]],["urgenza","k",["urgen"]],["giorni","k",["giorn","gg"]],["motivando","k",["motiva"]]],"r":[]}},{"id":"INAIL-2~3","s":"INAIL-2","q":"Cosa attribuisce l'INAIL dopo la denuncia di esercizio?","a":"Codice ditta, una PAT per ogni sede, voce di tariffa e tasso.","v":{"p":null,"e":[["Codice","k",["codic"]],["ditta","k",["ditta"]],["PAT","k",["pat"]],["voce","k",["voc"]],["tariffa","k",["tarif"]],["tasso","k",["tasso"]]],"r":[]}},{"id":"INAIL-3~0","s":"INAIL-3","q":"Qual è il cuore di «L'autoliquidazione del premio»? Rispondi in due o tre frasi.","a":"Con l'autoliquidazione il datore di lavoro calcola e versa da sé il premio INAIL: entro il 16 febbraio paga la regolazione dell'anno precedente e la rata anticipata dell'anno in corso.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INAIL-3~1","s":"INAIL-3","q":"In quante rate si può pagare l'autoliquidazione e con quali scadenze?","a":"Quattro rate del 25%: 16/2, 16/5, 16/8, 16/11.","v":{"p":null,"e":[["4","n",["4"]],["25%","n",["25"]],["16","n",["16"]],["febbraio","k",["febbr"]],["maggio","k",["maggi"]],["agosto","k",["agost"]],["novembre","k",["novem"]]],"r":[]}},{"id":"INAIL-3~2","s":"INAIL-3","q":"Cosa si versa con l'autoliquidazione?","a":"Regolazione dell'anno precedente e rata anticipata dell'anno in corso (somma algebrica).","v":{"p":null,"e":[["Regolazione","k",["regolazi"]],["anno","k",["ann"]],["precedente","k",["precede"]],["rata","k",["rat"]],["anticipata","k",["anticip"]],["corso","k",["corso"]]],"r":[]}},{"id":"INAIL-3~3","s":"INAIL-3","q":"Come si calcola il premio INAIL?","a":"Retribuzioni × tasso della voce di tariffa, eventualmente ridotto per oscillazione.","v":{"p":null,"e":[["Retribuzioni","k",["retribuz","stipend","paga","salari"]],["tasso","k",["tasso"]],["voce","k",["voc"]],["tariffa","k",["tarif"]],["eventualmente","k",["eventual"]],["ridotto","k",["ridot"]],["oscillazione","k",["oscillaz"]]],"r":[]}},{"id":"INAIL-4~0","s":"INAIL-4","q":"Qual è il cuore di «La denuncia di variazione tardiva od omessa»? Rispondi in due o tre frasi.","a":"Ogni variazione dell'attività assicurata, del titolare, della sede o delle lavorazioni va denunciata telematicamente all'INAIL entro 30 giorni (art. 12, c. 3-4, T.U.; art. 14 D.I. 27/2/2019).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INAIL-4~1","s":"INAIL-4","q":"Termine per denunciare le variazioni all'INAIL?","a":"30 giorni, solo telematicamente.","v":{"p":null,"e":[["30","n",["30"]],["giorni","k",["giorn","gg"]],["telematicamente","k",["telemati","online","on line","via web","digital"]]],"r":[]},"t":"d"},{"id":"INAIL-4~2","s":"INAIL-4","q":"Se il rischio aumenta e la variazione non è denunciata, cosa accade?","a":"L'INAIL recupera la differenza di premio con le sanzioni civili.","v":{"p":null,"e":[["INAIL","k",["inail"]],["recupera","k",["recup"]],["differenza","k",["differe"]],["premio","k",["premi"]],["sanzioni","k",["sanzi","multa","ammend"]],["civili","k",["civil"]]],"r":[]}},{"id":"INAIL-4~3","s":"INAIL-4","q":"Una variazione tardiva che riduce il rischio ha effetto retroattivo?","a":"Di regola no.","v":{"p":null,"e":[["regola","k",["regol"]]],"r":[]}},{"id":"INAIL-5~0","s":"INAIL-5","q":"Qual è il cuore di «Le riduzioni del tasso di premio»? Rispondi in due o tre frasi.","a":"Il tasso medio della voce di tariffa può essere ridotto per andamento infortunistico favorevole e per interventi di prevenzione (oscillazione del tasso, artt. 19-23 D.I. 27/2/2019).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INAIL-5~1","s":"INAIL-5","q":"Termine della domanda di riduzione del tasso per prevenzione?","a":"Entro il 28 febbraio, in via telematica.","v":{"p":null,"e":[["28","n",["28"]],["febbraio","k",["febbr"]],["telematica","k",["telemat","online","on line","via web","digital"]]],"r":[]}},{"id":"INAIL-5~2","s":"INAIL-5","q":"Misura della riduzione per prevenzione nei primi due anni della PAT?","a":"8%.","v":{"p":null,"e":[["8%","n",["8"]]],"r":[]},"t":"d"},{"id":"INAIL-5~3","s":"INAIL-5","q":"Chi è escluso dal bonus per andamento infortunistico dal 2026?","a":"Chi negli ultimi due anni è stato condannato in via definitiva per gravi violazioni di sicurezza (D.L. 159/2025).","v":{"p":null,"e":[["2","n",["2"]],["ultimi","k",["ultim"]],["anni","k",["ann"]],["condannato","k",["condann"]],["definitiva","k",["definit"]],["gravi","k",["gravi"]],["violazioni","k",["violazi"]],["sicurezza","k",["sicure"]]],"r":[["159/2025",["159","2025"]]]}},{"id":"INAIL-6~0","s":"INAIL-6","q":"Qual è il cuore di «La rateazione dei debiti non iscritti a ruolo»? Rispondi in due o tre frasi.","a":"I premi INAIL non ancora iscritti a ruolo possono essere rateizzati con la stessa disciplina dei contributi INPS: dal 2025 la legge ammette fino a 60 rate mensili (art. 2, c. 11 e 11-bis, D.L. 338/1989).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INAIL-6~1","s":"INAIL-6","q":"Fino a quante rate si dilazionano i premi INAIL non a ruolo?","a":"Fino a 60 rate mensili (art. 2, c. 11-bis, D.L. 338/1989).","v":{"p":null,"e":[["60","n",["60"]],["mensili","k",["mensi"]]],"r":[["338/1989",["338","1989"]],["art. 2",["2"]]]},"t":"d"},{"id":"INAIL-6~2","s":"INAIL-6","q":"Soglia di debito per passare da 36 a 60 rate?","a":"500.000 euro.","v":{"p":null,"e":[["500.000","n",["500000"]],["euro","k",["eur"]]],"r":[]},"t":"d"},{"id":"INAIL-6~3","s":"INAIL-6","q":"La sanzione civile ridotta a cosa è subordinata?","a":"Al pagamento della prima rata.","v":{"p":null,"e":[["pagamento","k",["pagame"]],["rata","k",["rat"]]],"r":[]}},{"id":"INAIL-16~0","s":"INAIL-16","q":"Qual è il cuore di «L'obbligo assicurativo»? Rispondi in due o tre frasi.","a":"L'obbligo assicurativo INAIL nasce quando ricorrono insieme un requisito oggettivo, l'attività pericolosa, e uno soggettivo, il lavoratore protetto (artt. 1 e 4 T.U. D.P.R. 1124/1965).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INAIL-16~1","s":"INAIL-16","q":"Quali sono i requisiti dell'obbligo assicurativo INAIL?","a":"Oggettivo (attività pericolosa, art. 1) e soggettivo (lavoratore protetto, art. 4 T.U.).","v":{"p":null,"e":[["Oggettivo","k",["oggett"]],["soggettivo","k",["soggett"]]],"r":[["art. 1",["1"]],["art. 4",["4"]]]}},{"id":"INAIL-16~2","s":"INAIL-16","q":"Ripartizione del premio INAIL per i parasubordinati?","a":"1/3 lavoratore, 2/3 committente.","v":{"p":null,"e":[["1","n",["1"]],["3","n",["3"]],["2","n",["2"]],["lavoratore","k",["lavorat","dipendent","prestator"]],["committente","k",["committe"]]],"r":[]},"t":"d"},{"id":"INAIL-16~3","s":"INAIL-16","q":"In agricoltura quali attività sono assicurate?","a":"Tutte le attività.","v":{"p":null,"e":[["attività","k",["attiv"]]],"r":[]}},{"id":"INAIL-23~0","s":"INAIL-23","q":"Qual è il cuore di «La tariffa ordinaria (D.I. 27/2/2019)»? Rispondi in due o tre frasi.","a":"La tariffa ordinaria dei premi INAIL, approvata con decreto interministeriale del 27/2/2019 e in vigore dal 2019, fissa per ogni lavorazione una voce e un tasso medio, distinti per gestione tariffaria.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INAIL-23~1","s":"INAIL-23","q":"Quale decreto ha approvato la tariffa ordinaria dei premi?","a":"Il D.I. 27/2/2019.","v":{"p":null,"e":[["27","n",["27"]],["2019","n",["2019"]],["febbraio","k",["febbr"]]],"r":[]},"t":"e"},{"id":"INAIL-23~2","s":"INAIL-23","q":"Quante gestioni tariffarie ci sono nell'industria?","a":"Quattro: industria, artigianato, terziario, altre attività (D.Lgs. 38/2000).","v":{"p":null,"e":[["4","n",["4"]],["artigianato","k",["artigian"]],["terziario","k",["terzia"]],["attività","k",["attiv"]]],"r":[["38/2000",["38","2000"]]]}},{"id":"INAIL-23~3","s":"INAIL-23","q":"Come si calcola l'oscillazione per andamento infortunistico dal 2019?","a":"Sulla gravità degli eventi e sull'intera PAT, non sulla singola voce.","v":{"p":null,"e":[["gravità","k",["gravi"]],["eventi","k",["event"]],["intera","k",["inter"]],["PAT","k",["pat"]],["singola","k",["singo"]],["voce","k",["voc"]]],"r":[]}},{"id":"S22-INAIL-5~0","s":"S22-INAIL-5","q":"Qual è il cuore di «Il contenzioso amministrativo INAIL (artt. 27-28 delle Modalità di applicazione delle tariffe)»? Rispondi in due o tre frasi.","a":"Contro i provvedimenti dell'INAIL in materia di tariffa dei premi il datore può proporre ricorso amministrativo (artt. 27-28 delle Modalità di applicazione delle tariffe, D.M. 27/2/2019, e D.P.R. 314/2001). Dal 12 gennaio 2025, per effetto dell'art. 2 L. 203/2024 (Collegato lavoro), i ricorsi non vanno più al Presidente o al Consiglio di amministrazione ma alle Direzioni regionali (circ. INAIL 4/2025).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-INAIL-5~1","s":"S22-INAIL-5","q":"Dal 2025 a chi si ricorre contro i provvedimenti di classificazione INAIL?","a":"Alla Direzione regionale (art. 2 L. 203/2024).","v":{"p":null,"e":[["Direzione","k",["direzi"]],["regionale","k",["region"]]],"r":[["203/2024",["203","2024"]],["art. 2",["2"]]]}},{"id":"S22-INAIL-5~2","s":"S22-INAIL-5","q":"Termine del ricorso amministrativo INAIL in materia di tariffa?","a":"30 giorni dalla ricezione del provvedimento, solo telematico.","v":{"p":null,"e":[["30","n",["30"]],["giorni","k",["giorn","gg"]],["ricezione","k",["ricezi"]],["provvedimento","k",["provvedi"]],["telematico","k",["telemat","online","on line","via web","digital"]]],"r":[]},"t":"d"},{"id":"S22-INAIL-5~3","s":"S22-INAIL-5","q":"Il ricorso tempestivo sospende il provvedimento?","a":"Sì: si pagano i premi con il tasso precedente, salvo conguaglio.","v":{"p":"s","e":[["pagano","k",["pagan"]],["premi","k",["premi"]],["tasso","k",["tasso"]],["precedente","k",["precede"]],["conguaglio","k",["conguag"]]],"r":[]}},{"id":"INAIL-8~0","s":"INAIL-8","q":"Qual è il cuore di «L'infortunio sul lavoro»? Rispondi in due o tre frasi.","a":"L'infortunio sul lavoro è la lesione causata da una causa violenta in occasione di lavoro, da cui derivi la morte o un'inabilità permanente, oppure un'inabilità temporanea assoluta di oltre tre giorni (art. 2 T.U.).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INAIL-8~1","s":"INAIL-8","q":"Definizione di infortunio sul lavoro?","a":"Lesione da causa violenta in occasione di lavoro, con morte, inabilità permanente o temporanea assoluta oltre 3 giorni (art. 2 T.U.).","v":{"p":null,"e":[["3","n",["3"]],["Lesione","k",["lesio"]],["causa","k",["causa"]],["violenta","k",["viole"]],["occasione","k",["occasi"]],["morte","k",["morte"]],["inabilità","k",["inabil"]],["permanente","k",["permane"]],["temporanea","k",["tempora"]],["assoluta","k",["assol"]],["giorni","k",["giorn","gg"]]],"r":[["art. 2",["2"]]]}},{"id":"INAIL-8~2","s":"INAIL-8","q":"Il concorso di cause preesistenti esclude l'infortunio?","a":"No.","v":{"p":"n","e":[],"r":[]}},{"id":"INAIL-8~3","s":"INAIL-8","q":"Quale rischio esclude l'indennizzo?","a":"Il rischio elettivo.","v":{"p":null,"e":[["elettivo","k",["elett"]]],"r":[]}},{"id":"INAIL-9~0","s":"INAIL-9","q":"Qual è il cuore di «L'infortunio in itinere»? Rispondi in due o tre frasi.","a":"L'infortunio in itinere è quello che avviene nel normale percorso tra abitazione e lavoro, tra due luoghi di lavoro o verso il luogo abituale dei pasti se manca la mensa (art. 2 T.U., come modificato dall'art. 12 D.Lgs. 38/2000).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INAIL-9~1","s":"INAIL-9","q":"Quale norma ha introdotto l'infortunio in itinere?","a":"L'art. 12 D.Lgs. 38/2000 (modifica dell'art. 2 T.U.).","v":{"p":null,"e":[["38/2000","n",["38","2000"]],["art. 12","n",["12"]]],"r":[["art. 2",["2"]]]},"t":"e"},{"id":"INAIL-9~2","s":"INAIL-9","q":"Quali percorsi sono tutelati in itinere?","a":"Casa-lavoro, tra due luoghi di lavoro, lavoro-luogo dei pasti senza mensa.","v":{"p":null,"e":[["2","n",["2"]],["Casa","k",["cas"]],["lavoro","k",["lavor","dipendent","prestator"]],["luoghi","k",["luogh"]],["luogo","k",["luogo"]],["pasti","k",["pasti"]],["mensa","k",["mensa"]]],"r":[]}},{"id":"INAIL-9~3","s":"INAIL-9","q":"La bicicletta è un mezzo tutelato in itinere?","a":"Sì, è sempre considerata necessitata.","v":{"p":"s","e":[["considerata","k",["consider"]],["necessitata","k",["necessit"]]],"r":[]}},{"id":"INAIL-10~0","s":"INAIL-10","q":"Qual è il cuore di «Rischio generico, specifico ed elettivo»? Rispondi in due o tre frasi.","a":"La distinzione tra rischio specifico, generico ed elettivo serve a stabilire se c'è occasione di lavoro e quindi se l'infortunio è indennizzabile.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INAIL-10~1","s":"INAIL-10","q":"Il rischio generico è indennizzabile?","a":"No, salvo che sia aggravato dalle circostanze del lavoro.","v":{"p":"n","e":[["aggravato","k",["aggrav"]],["circostanze","k",["circosta"]],["lavoro","k",["lavor","dipendent","prestator"]]],"r":[]}},{"id":"INAIL-10~2","s":"INAIL-10","q":"Che cos'è il rischio improprio?","a":"Attività preparatorie o strumentali al lavoro, indennizzabili (Cass. 16417/2005).","v":{"p":null,"e":[["Attività","k",["attiv"]],["preparatorie","k",["preparat"]],["strumentali","k",["strument"]],["lavoro","k",["lavor","dipendent","prestator"]],["indennizzabili","k",["indenniz"]]],"r":[["16417/2005",["16417","2005"]]]}},{"id":"INAIL-10~3","s":"INAIL-10","q":"Requisiti del rischio elettivo?","a":"Atto volontario e abnorme, motivi personali, nessun nesso con il lavoro.","v":{"p":null,"e":[["Atto","k",["att"]],["volontario","k",["volonta"]],["abnorme","k",["abnor"]],["motivi","k",["motiv"]],["personali","k",["person"]],["nessun","k",["nessu"]],["nesso","k",["nesso"]],["lavoro","k",["lavor","dipendent","prestator"]]],"r":[]}},{"id":"INAIL-11~0","s":"INAIL-11","q":"Qual è il cuore di «La denuncia e la comunicazione d'infortunio»? Rispondi in due o tre frasi.","a":"Il datore di lavoro deve denunciare all'INAIL, in via telematica, ogni infortunio non guaribile entro tre giorni: entro 2 giorni dalla ricezione dei dati del certificato, entro 24 ore se mortale o con pericolo di morte (art. 53 T.U.).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INAIL-11~1","s":"INAIL-11","q":"Termine della denuncia di infortunio del datore?","a":"Entro 2 giorni dalla ricezione dei dati del certificato; 24 ore se mortale (art. 53 T.U.).","v":{"p":null,"e":[["2","n",["2"]],["24","m",["24"]],["giorni","k",["giorn","gg"]],["ricezione","k",["ricezi"]],["certificato","k",["certific"]],["ore","k",["ore"]],["mortale","k",["morta"]]],"r":[["art. 53",["53"]]]}},{"id":"INAIL-11~2","s":"INAIL-11","q":"Termine della comunicazione a fini statistici (SINP)?","a":"Entro 48 ore, per assenze di almeno un giorno oltre quello dell'evento.","v":{"p":null,"e":[["48","n",["48"]],["ore","k",["ore"]],["assenze","k",["assen"]],["giorno","k",["giorn","gg"]],["evento","k",["event"]]],"r":[]},"t":"d"},{"id":"INAIL-11~3","s":"INAIL-11","q":"Da quando è attivo il registro infortuni telematico?","a":"Dal marzo 2025.","v":{"p":null,"e":[["2025","n",["2025"]],["marzo","k",["marzo"]]],"r":[]},"t":"d"},{"id":"INAIL-12~0","s":"INAIL-12","q":"Qual è il cuore di «La denuncia di malattia professionale»? Rispondi in due o tre frasi.","a":"La malattia professionale va comunicata dal lavoratore al datore entro 15 giorni dalla manifestazione, e il datore la denuncia all'INAIL in via telematica nei 5 giorni successivi (artt. 52-53 T.U.).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INAIL-12~1","s":"INAIL-12","q":"Entro quanto il lavoratore comunica la malattia professionale al datore?","a":"Entro 15 giorni dalla manifestazione.","v":{"p":null,"e":[["15","n",["15"]],["giorni","k",["giorn","gg"]],["manifestazione","k",["manifest"]]],"r":[]}},{"id":"INAIL-12~2","s":"INAIL-12","q":"Entro quanto il datore denuncia la malattia professionale?","a":"Entro 5 giorni, in via telematica.","v":{"p":null,"e":[["5","n",["5"]],["giorni","k",["giorn","gg"]],["telematica","k",["telemat","online","on line","via web","digital"]]],"r":[]}},{"id":"INAIL-12~3","s":"INAIL-12","q":"Quale norma impone al medico la denuncia della malattia professionale?","a":"L'art. 139 T.U.","v":{"p":null,"e":[["art. 139","n",["139"]],["TU","k",["tu"]]],"r":[]},"t":"e"},{"id":"INAIL-13~0","s":"INAIL-13","q":"Qual è il cuore di «Malattie professionali tabellate e non tabellate»? Rispondi in due o tre frasi.","a":"Il sistema delle malattie professionali è misto: per quelle tabellate il nesso con il lavoro si presume, per quelle non tabellate il lavoratore deve provarlo (art. 3 T.U.; Corte cost. 179/1988; art. 10, c. 4, D.Lgs. 38/2000).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INAIL-13~1","s":"INAIL-13","q":"Quale sentenza ha aperto la tutela alle malattie non tabellate?","a":"Corte cost. 179/1988.","v":{"p":null,"e":[["179/1988","n",["179","1988"]],["Corte","k",["corte"]]],"r":[]},"t":"e"},{"id":"INAIL-13~2","s":"INAIL-13","q":"Per le malattie tabellate cosa deve provare il lavoratore?","a":"Solo l'adibizione alla lavorazione e la malattia: il nesso si presume.","v":{"p":null,"e":[["adibizione","k",["adibizi"]],["lavorazione","k",["lavorazi"]],["nesso","k",["nesso"]],["presume","k",["presu"]]],"r":[]}},{"id":"INAIL-13~3","s":"INAIL-13","q":"Su cosa rileva la distinzione tra tabellate e non tabellate?","a":"Solo sulla prova del nesso causale (Cass. S.U. 1919/1990).","v":{"p":null,"e":[["prova","k",["prova"]],["nesso","k",["nesso"]],["causale","k",["causa"]]],"r":[["1919/1990",["1919","1990"]]]}},{"id":"INAIL-19~0","s":"INAIL-19","q":"Qual è il cuore di «L'occasione di lavoro e la causa violenta»? Rispondi in due o tre frasi.","a":"Perché ci sia infortunio indennizzabile devono coesistere tre elementi: la lesione, la causa violenta e l'occasione di lavoro (art. 2 T.U.).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INAIL-19~1","s":"INAIL-19","q":"Quali sono i tre elementi dell'infortunio indennizzabile?","a":"Lesione, causa violenta, occasione di lavoro.","v":{"p":null,"e":[["Lesione","k",["lesio"]],["causa","k",["causa"]],["violenta","k",["viole"]],["occasione","k",["occasi"]],["lavoro","k",["lavor","dipendent","prestator"]]],"r":[]}},{"id":"INAIL-19~2","s":"INAIL-19","q":"Cosa distingue l'infortunio dalla malattia professionale?","a":"La causa violenta, rapida e concentrata (nella malattia è lenta).","v":{"p":null,"e":[["causa","k",["causa"]],["violenta","k",["viole"]],["rapida","k",["rapid"]],["concentrata","k",["concentr"]]],"r":[]}},{"id":"INAIL-19~3","s":"INAIL-19","q":"La semplice colpa del lavoratore esclude l'indennizzo?","a":"No.","v":{"p":"n","e":[],"r":[]}},{"id":"INAIL-20~0","s":"INAIL-20","q":"Qual è il cuore di «Dolo e colpa del lavoratore nell'infortunio»? Rispondi in due o tre frasi.","a":"La colpa del lavoratore non esclude l'indennizzo dell'infortunio: lo esclude il rischio elettivo. Se l'infortunio è dovuto a dolo del lavoratore accertato con sentenza penale, l'INAIL può agire in regresso contro di lui per recuperare quanto erogato (art. 11, ultimo comma, T.U.).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INAIL-20~1","s":"INAIL-20","q":"Cosa esclude l'indennizzo dell'infortunio?","a":"Il rischio elettivo; la colpa del lavoratore no.","v":{"p":null,"e":[["rischio","k",["risch"]],["elettivo","k",["elett"]],["colpa","k",["colpa"]],["lavoratore","k",["lavorat","dipendent","prestator"]]],"r":[]}},{"id":"INAIL-20~2","s":"INAIL-20","q":"Quando l'INAIL agisce in regresso contro l'infortunato?","a":"Per dolo dell'infortunato accertato con sentenza penale (art. 11, ultimo comma, T.U.).","v":{"p":null,"e":[["dolo","k",["dol"]],["accertato","k",["accert"]],["sentenza","k",["sente"]],["penale","k",["penal"]]],"r":[["art. 11",["11"]]]}},{"id":"INAIL-20~3","s":"INAIL-20","q":"La colpa del lavoratore esonera il datore dalla responsabilità?","a":"No, se l'evento era prevedibile e mancavano le misure di sicurezza (art. 2087 c.c.).","v":{"p":"n","e":[["evento","k",["event"]],["prevedibile","k",["prevedib"]],["mancavano","k",["mancav"]],["misure","k",["misur"]],["sicurezza","k",["sicure"]]],"r":[["art. 2087 c.c.",["2087"]]]}},{"id":"INAIL-22~0","s":"INAIL-22","q":"Qual è il cuore di «Infortunio e malattia professionale: le differenze»? Rispondi in due o tre frasi.","a":"Infortunio e malattia professionale hanno la stessa tutela e gli stessi presupposti assicurativi, ma si distinguono per la causa: violenta e concentrata nel primo, lenta e progressiva nella seconda.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INAIL-22~1","s":"INAIL-22","q":"Per quale evento esiste la tutela in itinere?","a":"Solo per l'infortunio.","v":{"p":null,"e":[["infortunio","k",["infortu","incident"]]],"r":[]}},{"id":"INAIL-22~2","s":"INAIL-22","q":"Differenza di causa tra infortunio e malattia professionale?","a":"Violenta e rapida nell'infortunio; lenta e progressiva nella malattia.","v":{"p":null,"e":[["Violenta","k",["viole"]],["rapida","k",["rapid"]],["lenta","k",["lenta"]],["progressiva","k",["progress"]]],"r":[]}},{"id":"INAIL-22~3","s":"INAIL-22","q":"Le prestazioni sono diverse tra infortunio e malattia professionale?","a":"No, sono le stesse.","v":{"p":"n","e":[["stesse","k",["stess"]]],"r":[]}},{"id":"INAIL-7~0","s":"INAIL-7","q":"Qual è il cuore di «Le prestazioni economiche, sanitarie e sociosanitarie»? Rispondi in due o tre frasi.","a":"L'INAIL eroga prestazioni economiche (indennità temporanea, indennizzo del danno biologico, rendite, prestazioni ai superstiti), sanitarie e socio-sanitarie per il recupero e il reinserimento.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INAIL-7~1","s":"INAIL-7","q":"Misura dell'indennità per inabilità temporanea assoluta?","a":"60% fino al 90° giorno, 75% dal 91° (art. 68 T.U.).","v":{"p":null,"e":[["60%","n",["60"]],["90","n",["90"]],["75%","n",["75"]],["91","n",["91"]],["giorno","k",["giorn","gg"]]],"r":[["art. 68",["68"]]]}},{"id":"INAIL-7~2","s":"INAIL-7","q":"Prestazioni in caso di morte?","a":"Rendita ai superstiti e assegno funerario (art. 85 T.U.).","v":{"p":null,"e":[["Rendita","k",["rendi"]],["superstiti","k",["superst"]],["assegno","k",["asseg"]],["funerario","k",["funera"]]],"r":[["art. 85",["85"]]]}},{"id":"INAIL-7~3","s":"INAIL-7","q":"Quali prestazioni accessorie eroga l'INAIL?","a":"Assegno per assistenza personale continuativa, assegno di incollocabilità.","v":{"p":null,"e":[["Assegno","k",["asseg"]],["assistenza","k",["assiste"]],["personale","k",["person"]],["continuativa","k",["continua"]],["incollocabilità","k",["incolloc"]]],"r":[]}},{"id":"INAIL-14~0","s":"INAIL-14","q":"Qual è il cuore di «I criteri per la costituzione della rendita»? Rispondi in due o tre frasi.","a":"Per gli eventi dal 25/7/2000 l'inabilità permanente si indennizza come danno biologico: in capitale dal 6% al 15%, in rendita dal 16% al 100% (art. 13 D.Lgs. 38/2000).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INAIL-14~1","s":"INAIL-14","q":"Danno biologico: quando c'è indennizzo in capitale e quando rendita?","a":"Capitale dal 6% al 15%; rendita dal 16% al 100% (art. 13 D.Lgs. 38/2000).","v":{"p":null,"e":[["6%","n",["6"]],["15%","n",["15"]],["16%","m",["16"]],["100%","m",["100"]]],"r":[["38/2000",["38","2000"]],["art. 13",["13"]]]}},{"id":"INAIL-14~2","s":"INAIL-14","q":"Sotto quale percentuale non c'è indennizzo?","a":"Sotto il 6% (franchigia).","v":{"p":null,"e":[["6%","n",["6"]]],"r":[]}},{"id":"INAIL-14~3","s":"INAIL-14","q":"Da quando vale il sistema del danno biologico?","a":"Per gli eventi dal 25/7/2000.","v":{"p":null,"e":[["25","n",["25"]],["2000","n",["2000"]],["eventi","k",["event"]],["luglio","k",["lugli"]]],"r":[]},"t":"d"},{"id":"INAIL-15~0","s":"INAIL-15","q":"Qual è il cuore di «La rendita ai superstiti»? Rispondi in due o tre frasi.","a":"Se l'infortunio o la malattia professionale causano la morte, l'INAIL paga una rendita ai superstiti e un assegno funerario (art. 85 T.U.).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INAIL-15~1","s":"INAIL-15","q":"Quota della rendita ai superstiti per il coniuge e per ogni figlio?","a":"50% al coniuge, 20% per ogni figlio (40% se orfano di entrambi).","v":{"p":null,"e":[["50%","n",["50"]],["20%","n",["20"]]],"r":[]}},{"id":"INAIL-15~2","s":"INAIL-15","q":"Fino a quale età i figli universitari hanno la rendita ai superstiti?","a":"Fino a 26 anni.","v":{"p":null,"e":[["26","n",["26"]],["anni","k",["ann"]]],"r":[]},"t":"d"},{"id":"INAIL-15~3","s":"INAIL-15","q":"Il totale delle rendite ai superstiti può superare la retribuzione?","a":"No, non oltre il 100%.","v":{"p":"n","e":[["100%","n",["100"]]],"r":[]},"t":"d"},{"id":"INAIL-17~0","s":"INAIL-17","q":"Qual è il cuore di «L'azione di rivalsa»? Rispondi in due o tre frasi.","a":"L'assicurazione INAIL esonera il datore dalla responsabilità civile, salvo che l'infortunio derivi da un reato perseguibile d'ufficio; in quel caso l'INAIL paga e poi agisce in regresso verso i responsabili (artt. 10-11 T.U.).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INAIL-17~1","s":"INAIL-17","q":"Quando il datore perde l'esonero dalla responsabilità civile?","a":"Se l'infortunio deriva da un reato perseguibile d'ufficio (Corte cost. 22/1967).","v":{"p":null,"e":[["infortunio","k",["infortu","incident"]],["deriva","k",["deriv"]],["reato","k",["reato"]],["perseguibile","k",["persegui"]],["ufficio","k",["uffic"]]],"r":[["22/1967",["22","1967"]]]}},{"id":"INAIL-17~2","s":"INAIL-17","q":"Cosa può chiedere il lavoratore al datore responsabile?","a":"Il danno differenziale (art. 10, c. 6-7, T.U.).","v":{"p":null,"e":[["danno","k",["danno"]],["differenziale","k",["differen"]]],"r":[["art. 10",["10"]]]}},{"id":"INAIL-17~3","s":"INAIL-17","q":"Verso il terzo estraneo responsabile l'INAIL quale azione esercita?","a":"La surroga (art. 1916 c.c.).","v":{"p":null,"e":[["surroga","k",["surro"]]],"r":[["art. 1916 c.c.",["1916"]]]}},{"id":"INAIL-18~0","s":"INAIL-18","q":"Qual è il cuore di «L'automaticità delle prestazioni INAIL»? Rispondi in due o tre frasi.","a":"Le prestazioni INAIL spettano al lavoratore anche se il datore non ha denunciato l'attività o non ha pagato il premio: è il principio di automaticità (art. 67 T.U.).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INAIL-18~1","s":"INAIL-18","q":"Quale articolo del T.U. prevede l'automaticità delle prestazioni INAIL?","a":"L'art. 67.","v":{"p":null,"e":[["art. 67","n",["67"]]],"r":[]},"t":"e"},{"id":"INAIL-18~2","s":"INAIL-18","q":"Per chi non vale l'automaticità INAIL?","a":"Per i lavoratori autonomi e per l'assicurazione degli infortuni domestici.","v":{"p":null,"e":[["lavoratori","k",["lavorat","dipendent","prestator"]],["autonomi","k",["auton"]],["assicurazione","k",["assicura"]],["infortuni","k",["infort","incident"]],["domestici","k",["domest"]]],"r":[]}},{"id":"INAIL-18~3","s":"INAIL-18","q":"Differenza con l'automaticità INPS?","a":"Quella INAIL è piena per i subordinati; quella INPS opera nei limiti della prescrizione.","v":{"p":null,"e":[["INAIL","k",["inail"]],["piena","k",["piena"]],["subordinati","k",["subordin"]],["opera","k",["opera"]],["limiti","k",["limit"]],["prescrizione","k",["prescriz"]]],"r":[]}},{"id":"INAIL-21~0","s":"INAIL-21","q":"Qual è il cuore di «L'indennità per inabilità temporanea assoluta»? Rispondi in due o tre frasi.","a":"L'indennità per inabilità temporanea assoluta sostituisce la retribuzione quando l'infortunio o la malattia professionale impediscono totalmente il lavoro: spetta dal quarto giorno fino alla guarigione clinica (art. 68 T.U.).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"INAIL-21~1","s":"INAIL-21","q":"Da quale giorno spetta l'indennità di inabilità temporanea?","a":"Dal quarto giorno successivo all'evento.","v":{"p":null,"e":[["quarto","k",["quart"]],["successivo","k",["success"]],["evento","k",["event"]]],"r":[]}},{"id":"INAIL-21~2","s":"INAIL-21","q":"Cosa paga il datore nel periodo di carenza?","a":"L'intera retribuzione del giorno dell'infortunio e il 60% dei tre giorni successivi (art. 73).","v":{"p":null,"e":[["60%","n",["60"]],["3","n",["3"]],["intera","k",["inter"]],["retribuzione","k",["retribuz","stipend","paga","salari"]],["giorno","k",["giorn","gg"]],["infortunio","k",["infortu","incident"]],["successivi","k",["success"]]],"r":[["art. 73",["73"]]]}},{"id":"INAIL-21~3","s":"INAIL-21","q":"Il datore anticipa l'indennità INAIL?","a":"Sì, se l'Istituto glielo chiede, con rimborso a fine mese (art. 70 T.U.).","v":{"p":"s","e":[["Istituto","k",["istit"]],["glielo","k",["gliel"]],["chiede","k",["chied"]],["rimborso","k",["rimbo"]],["fine","k",["fin"]],["mese","k",["mes"]]],"r":[["art. 70",["70"]]]}},{"id":"PPP-9~0","s":"PPP-9","q":"Qual è il cuore di «Capacità giuridica e capacità di agire»? Rispondi in due o tre frasi.","a":"La capacità giuridica è l'attitudine a essere titolari di diritti e doveri e si acquista con la nascita (art. 1 c.c.); la capacità di agire è l'idoneità a compiere da sé atti giuridici validi e si acquista con la maggiore età, a 18 anni (art. 2 c.c.).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"PPP-9~1","s":"PPP-9","q":"Differenza tra capacità giuridica e capacità di agire?","a":"La giuridica è l'attitudine a essere titolari di diritti e doveri, dalla nascita; quella di agire è l'idoneità a compiere da sé atti validi, a 18 anni.","v":{"p":null,"e":[["18","m",["18"]],["attitudine","k",["attitud"]],["titolari","k",["titol"]],["diritti","k",["dirit"]],["doveri","k",["dover"]],["nascita","k",["nasci"]],["idoneità","k",["idone"]],["compiere","k",["compi"]],["atti","k",["att"]],["validi","k",["valid"]],["anni","k",["ann"]]],"r":[]}},{"id":"PPP-9~2","s":"PPP-9","q":"Differenza tra interdizione e inabilitazione?","a":"Interdizione: incapacità totale, tutore, atti annullabili; inabilitazione: incapacità parziale, curatore, da sé solo l'ordinaria amministrazione.","v":{"p":null,"e":[["incapacità","k",["incapac"]],["totale","k",["total"]],["tutore","k",["tutor"]],["atti","k",["att"]],["annullabili","k",["annullab"]],["parziale","k",["parzi"]],["curatore","k",["curat"]],["ordinaria","k",["ordina"]],["amministrazione","k",["amminist"]]],"r":[]}},{"id":"PPP-9~3","s":"PPP-9","q":"Quando si annulla il contratto concluso da un incapace naturale?","a":"Se era incapace di intendere o di volere al momento dell'atto e l'altro contraente era in mala fede.","v":{"p":null,"e":[["intendere","k",["intend"]],["volere","k",["voler"]],["momento","k",["momen"]],["atto","k",["att"]],["mala","k",["mal"]],["fede","k",["fed"]]],"r":[]}},{"id":"PPP-9~4","s":"PPP-9","q":"Cos'è l'amministrazione di sostegno?","a":"Una misura flessibile decisa dal giudice tutelare: il beneficiario conserva la capacità per gli atti non riservati all'amministratore.","v":{"p":null,"e":[["misura","k",["misur"]],["flessibile","k",["flessib"]],["decisa","k",["decis"]],["giudice","k",["giudi","tribunal"]],["tutelare","k",["tutel"]],["beneficiario","k",["benefici"]],["conserva","k",["conse"]],["capacità","k",["capac"]],["atti","k",["att"]],["riservati","k",["riserv"]]],"r":[]}},{"id":"PPP-10~0","s":"PPP-10","q":"Qual è il cuore di «Il contratto e i suoi elementi essenziali»? Rispondi in due o tre frasi.","a":"Il contratto è l'accordo di due o più parti per costituire, regolare o estinguere tra loro un rapporto giuridico patrimoniale (art. 1321 c.c.); i suoi requisiti sono l'accordo, la causa, l'oggetto e la forma quando è prescritta a pena di nullità (art. 1325).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"PPP-10~1","s":"PPP-10","q":"Quali sono i requisiti del contratto?","a":"Accordo, causa, oggetto e forma quando è prescritta a pena di nullità.","v":{"p":null,"e":[["Accordo","k",["accor"]],["causa","k",["causa"]],["oggetto","k",["ogget"]],["forma","k",["forma"]],["prescritta","k",["prescri"]],["pena","k",["pen"]],["nullità","k",["nulli","invalid","inefficac","privo","priva","nessun effett","non ha effett","non produce effett"]]],"r":[]}},{"id":"PPP-10~2","s":"PPP-10","q":"Cos'è la causa e cosa accade se è illecita?","a":"La funzione economico-sociale del contratto; se manca o è illecita il contratto è nullo.","v":{"p":null,"e":[["funzione","k",["funzi"]],["economico","k",["econom"]],["sociale","k",["socia"]],["contratto","k",["contra","rapport"]],["manca","k",["manca"]],["nullo","k",["nullo","invalid","inefficac","privo","priva","nessun effett","non ha effett","non produce effett"]]],"r":[]}},{"id":"PPP-10~3","s":"PPP-10","q":"Differenza tra forma ad substantiam e ad probationem?","a":"La prima è richiesta a pena di nullità; la seconda serve solo a provare il contratto.","v":{"p":null,"e":[["richiesta","k",["richie"]],["pena","k",["pen"]],["nullità","k",["nulli","invalid","inefficac","privo","priva","nessun effett","non ha effett","non produce effett"]],["seconda","k",["secon"]],["serve","k",["serve"]],["provare","k",["prova"]],["contratto","k",["contra","rapport"]]],"r":[]}},{"id":"PPP-10~4","s":"PPP-10","q":"Che effetti ha il contratto tra le parti e verso i terzi?","a":"Forza di legge tra le parti; nessun effetto verso i terzi, salvo i casi di legge come il contratto a favore di terzo.","v":{"p":null,"e":[["Forza","k",["forza"]],["legge","k",["legge"]],["nessun","k",["nessu"]],["favore","k",["favor"]],["terzo","k",["terzo"]]],"r":[]}},{"id":"PPP-10~5","s":"PPP-10","q":"Da cosa nasce la responsabilità precontrattuale?","a":"Dalla violazione della buona fede nelle trattative.","v":{"p":null,"e":[["violazione","k",["violazi"]],["buona","k",["buona"]],["fede","k",["fed"]],["trattative","k",["trattat"]]],"r":[]}},{"id":"PPP-11~0","s":"PPP-11","q":"Qual è il cuore di «Proprietà e possesso»? Rispondi in due o tre frasi.","a":"La proprietà è il diritto di godere e disporre delle cose in modo pieno ed esclusivo, entro i limiti e con l'osservanza degli obblighi stabiliti dall'ordinamento (art. 832 c.c.); il possesso è invece una situazione di fatto: il potere sulla cosa che si manifesta come esercizio della proprietà o di un altro diritto reale, anche senza esserne titolari.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"PPP-11~1","s":"PPP-11","q":"Differenza tra proprietà e possesso?","a":"La proprietà è un diritto pieno ed esclusivo; il possesso è una situazione di fatto, il potere sulla cosa come se si fosse titolari, anche senza esserlo.","v":{"p":null,"e":[["diritto","k",["dirit"]],["pieno","k",["pieno"]],["esclusivo","k",["esclus"]],["situazione","k",["situazi"]],["fatto","k",["fatto"]],["potere","k",["poter"]],["cosa","k",["cos"]],["fosse","k",["fosse"]],["titolari","k",["titol"]],["esserlo","k",["esser"]]],"r":[]}},{"id":"PPP-11~2","s":"PPP-11","q":"Differenza tra possesso e detenzione?","a":"Nella detenzione si ha la cosa senza l'intenzione di comportarsi come titolari (per esempio conduttore o depositario).","v":{"p":null,"e":[["cosa","k",["cos"]],["intenzione","k",["intenzi"]],["comportarsi","k",["comporta"]],["titolari","k",["titol"]]],"r":[]}},{"id":"PPP-11~3","s":"PPP-11","q":"Quali azioni tutelano il possesso?","a":"Reintegrazione o spoglio contro chi sottrae il possesso; manutenzione contro molestie e turbative; azioni di nunciazione.","v":{"p":null,"e":[["Reintegrazione","k",["reintegr"]],["spoglio","k",["spogl"]],["contro","k",["contr","rapport","contribuz","contribut"]],["sottrae","k",["sottr"]],["manutenzione","k",["manutenz"]],["molestie","k",["moles"]],["turbative","k",["turbat"]],["nunciazione","k",["nunciazi"]]],"r":[]}},{"id":"PPP-11~4","s":"PPP-11","q":"Cos'è l'usucapione?","a":"Acquisto a titolo originario con il possesso continuo, ininterrotto, non violento né clandestino per il tempo di legge.","v":{"p":null,"e":[["Acquisto","k",["acqui"]],["titolo","k",["titol"]],["originario","k",["origina"]],["possesso","k",["posse"]],["continuo","k",["conti"]],["ininterrotto","k",["ininterr"]],["violento","k",["viole"]],["clandestino","k",["clandest"]],["tempo","k",["tempo"]],["legge","k",["legge"]]],"r":[]}},{"id":"PPP-12~0","s":"PPP-12","q":"Qual è il cuore di «Gli elementi accidentali del contratto»? Rispondi in due o tre frasi.","a":"Gli elementi accidentali sono clausole che le parti possono aggiungere al contratto per incidere sulla sua efficacia: la condizione, il termine e il modo (o onere).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"PPP-12~1","s":"PPP-12","q":"Quali sono gli elementi accidentali del contratto?","a":"Condizione, termine e modo (onere).","v":{"p":null,"e":[["Condizione","k",["condizi"]],["termine","k",["termi","scadenz"]]],"r":[]}},{"id":"PPP-12~2","s":"PPP-12","q":"Differenza tra condizione e termine?","a":"La condizione è un evento futuro e incerto; il termine è futuro e certo.","v":{"p":null,"e":[["evento","k",["event"]],["futuro","k",["futur"]],["incerto","k",["incer"]],["certo","k",["certo"]]],"r":[]}},{"id":"PPP-12~3","s":"PPP-12","q":"Che effetto ha una condizione sospensiva meramente potestativa?","a":"Rende nullo il contratto.","v":{"p":null,"e":[["Rende","k",["rende"]],["nullo","k",["nullo","invalid","inefficac","privo","priva","nessun effett","non ha effett","non produce effett"]],["contratto","k",["contra","rapport"]]],"r":[]}},{"id":"PPP-12~4","s":"PPP-12","q":"A quali atti si appone il modo?","a":"Solo agli atti a titolo gratuito, come donazione e testamento.","v":{"p":null,"e":[["titolo","k",["titol"]],["gratuito","k",["gratu"]],["donazione","k",["donazi"]],["testamento","k",["testame"]]],"r":[]}},{"id":"PPP-13~0","s":"PPP-13","q":"Qual è il cuore di «Nullità e annullabilità»? Rispondi in due o tre frasi.","a":"Nullità e annullabilità sono le due forme di invalidità del contratto: la nullità colpisce i vizi più gravi ed è insanabile; l'annullabilità protegge una parte e il contratto produce effetti finché non è annullato.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"PPP-13~1","s":"PPP-13","q":"Quali differenze di regime ci sono tra nullità e annullabilità?","a":"Nullità: nessun effetto, la fa valere chiunque, rilevabile d'ufficio, imprescrittibile, non convalidabile. Annullabilità: effetti fino all'annullamento, solo la parte protetta, prescrizione in cinque anni, convalidabile.","v":{"p":null,"e":[["5","n",["5"]],["nessun","k",["nessu"]],["effetto","k",["effet"]],["valere","k",["valer"]],["chiunque","k",["chiun"]],["rilevabile","k",["rilevab"]],["ufficio","k",["uffic"]],["imprescrittibile","k",["imprescr","non si prescrive","non si prescrivono"]],["convalidabile","k",["convalid"]],["annullamento","k",["annullam"]],["protetta","k",["prote"]],["prescrizione","k",["prescriz"]]],"r":[]}},{"id":"PPP-13~2","s":"PPP-13","q":"Quali sono i vizi del consenso?","a":"Errore essenziale e riconoscibile, violenza morale, dolo determinante.","v":{"p":null,"e":[["Errore","k",["error"]],["essenziale","k",["essenzi"]],["riconoscibile","k",["riconosc"]],["violenza","k",["viole"]],["morale","k",["moral"]],["dolo","k",["dol"]],["determinante","k",["determin"]]],"r":[]}},{"id":"PPP-13~3","s":"PPP-13","q":"Che natura hanno la sentenza di nullità e quella di annullamento?","a":"Dichiarativa la prima, costitutiva la seconda.","v":{"p":null,"e":[["Dichiarativa","k",["dichiara"]],["costitutiva","k",["costitut"]],["seconda","k",["secon"]]],"r":[]}},{"id":"PPP-14~0","s":"PPP-14","q":"Qual è il cuore di «L'obbligazione e l'adempimento»? Rispondi in due o tre frasi.","a":"L'obbligazione è il rapporto per cui il debitore deve al creditore una prestazione suscettibile di valutazione economica (art. 1174 c.c.); si estingue normalmente con l'adempimento, cioè con l'esatta esecuzione della prestazione.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"PPP-14~1","s":"PPP-14","q":"Quali sono le fonti delle obbligazioni?","a":"Contratto, fatto illecito e ogni altro atto o fatto idoneo secondo l'ordinamento.","v":{"p":null,"e":[["Contratto","k",["contra","rapport"]],["fatto","k",["fatto"]],["illecito","k",["illec"]],["atto","k",["att"]],["idoneo","k",["idone"]],["secondo","k",["secon"]],["ordinamento","k",["ordiname"]]],"r":[]}},{"id":"PPP-14~2","s":"PPP-14","q":"Con quale diligenza si adempie?","a":"Con la diligenza del buon padre di famiglia.","v":{"p":null,"e":[["buon","k",["buon"]],["padre","k",["padre"]],["famiglia","k",["famig"]]],"r":[]}},{"id":"PPP-14~3","s":"PPP-14","q":"Quando il debitore inadempiente non risponde del danno?","a":"Se prova che l'inadempimento dipende da causa a lui non imputabile.","v":{"p":null,"e":[["prova","k",["prova"]],["dipende","k",["dipen","lavorat"]],["causa","k",["causa"]],["imputabile","k",["imputab"]]],"r":[]}},{"id":"PPP-14~4","s":"PPP-14","q":"Cos'è la datio in solutum?","a":"Con il consenso del creditore il debitore si libera con una prestazione diversa.","v":{"p":null,"e":[["consenso","k",["conse"]],["creditore","k",["credit"]],["debitore","k",["debit"]],["libera","k",["liber"]],["prestazione","k",["prestazi"]],["diversa","k",["diver"]]],"r":[]}},{"id":"PPP-15~0","s":"PPP-15","q":"Qual è il cuore di «I diritti reali di godimento e di garanzia»? Rispondi in due o tre frasi.","a":"I diritti reali sono diritti assoluti su una cosa, opponibili a tutti e tipici (solo quelli previsti dalla legge). Accanto alla proprietà ci sono i diritti reali su cosa altrui: di godimento, che consentono di usare il bene altrui, e di garanzia, che vincolano un bene all'adempimento di un credito.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"PPP-15~1","s":"PPP-15","q":"Quali sono i caratteri dei diritti reali?","a":"Immediatezza, assolutezza, inerenza e tipicità.","v":{"p":null,"e":[["Immediatezza","k",["immediat"]],["assolutezza","k",["assolute"]],["inerenza","k",["inere"]],["tipicità","k",["tipic"]]],"r":[]}},{"id":"PPP-15~2","s":"PPP-15","q":"Quali sono i diritti reali di godimento?","a":"Superficie, enfiteusi, usufrutto, uso, abitazione, servitù prediali.","v":{"p":null,"e":[["Superficie","k",["superfi"]],["enfiteusi","k",["enfite"]],["usufrutto","k",["usufru"]],["abitazione","k",["abitazi"]],["servitù","k",["servi"]],["prediali","k",["predi"]]],"r":[]}},{"id":"PPP-15~3","s":"PPP-15","q":"Differenza tra pegno e ipoteca?","a":"Pegno su beni mobili con lo spossessamento del debitore; ipoteca su immobili o mobili registrati, con l'iscrizione nei registri.","v":{"p":null,"e":[["beni","k",["ben"]],["mobili","k",["mobil"]],["spossessamento","k",["spossess"]],["debitore","k",["debit"]],["immobili","k",["immob"]],["registrati","k",["registr"]],["iscrizione","k",["iscrizi"]],["registri","k",["regis"]]],"r":[]}},{"id":"PPP-16~0","s":"PPP-16","q":"Qual è il cuore di «Rescissione e risoluzione del contratto»? Rispondi in due o tre frasi.","a":"La rescissione tutela chi ha concluso un contratto a condizioni inique per stato di pericolo o di bisogno (artt. 1447-1448 c.c.); la risoluzione scioglie un contratto valido quando sopravvengono inadempimento, impossibilità o eccessiva onerosità.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"PPP-16~1","s":"PPP-16","q":"Quando si rescinde un contratto per lesione?","a":"Sproporzione oltre la metà, stato di bisogno e approfittamento; l'azione si prescrive in un anno.","v":{"p":null,"e":[["Sproporzione","k",["sproporz"]],["metà","k",["met"]],["bisogno","k",["bisog"]],["approfittamento","k",["approfit"]],["azione","k",["azion"]],["prescrive","k",["prescr"]],["anno","k",["ann"]]],"r":[]}},{"id":"PPP-16~2","s":"PPP-16","q":"Cosa può scegliere la parte fedele davanti all'inadempimento?","a":"Tra adempimento e risoluzione, con il risarcimento; l'inadempimento non deve essere di scarsa importanza.","v":{"p":null,"e":[["adempimento","k",["adempime"]],["risoluzione","k",["risoluzi"]],["risarcimento","k",["risarcim"]],["scarsa","k",["scars"]],["importanza","k",["importa"]]],"r":[]}},{"id":"PPP-16~3","s":"PPP-16","q":"Quando la risoluzione opera di diritto?","a":"Con la clausola risolutiva espressa, la diffida ad adempiere e il termine essenziale.","v":{"p":null,"e":[["clausola","k",["claus"]],["risolutiva","k",["risolut"]],["espressa","k",["espre"]],["diffida","k",["diffi"]],["adempiere","k",["adempi"]],["termine","k",["termi","scadenz"]],["essenziale","k",["essenzi"]]],"r":[]}},{"id":"PPP-16~4","s":"PPP-16","q":"Come si evita la risoluzione per eccessiva onerosità?","a":"La controparte offre di modificare equamente il contratto (reductio ad aequitatem).","v":{"p":null,"e":[["controparte","k",["contropa"]],["offre","k",["offre"]],["modificare","k",["modific"]],["equamente","k",["equame"]],["contratto","k",["contra","rapport"]]],"r":[]}},{"id":"PPP-17~0","s":"PPP-17","q":"Qual è il cuore di «La nozione di imprenditore»? Rispondi in due o tre frasi.","a":"È imprenditore chi esercita professionalmente un'attività economica organizzata al fine della produzione o dello scambio di beni o di servizi (art. 2082 c.c.).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"PPP-17~1","s":"PPP-17","q":"Chi è imprenditore?","a":"Chi esercita professionalmente un'attività economica organizzata per produrre o scambiare beni o servizi.","v":{"p":null,"e":[["esercita","k",["eserc"]],["professionalmente","k",["professi"]],["attività","k",["attiv"]],["economica","k",["econom"]],["organizzata","k",["organizz"]],["produrre","k",["produ"]],["scambiare","k",["scambi"]],["beni","k",["ben"]],["servizi","k",["servi"]]],"r":[]}},{"id":"PPP-17~2","s":"PPP-17","q":"Lo scopo di lucro è necessario per essere imprenditore?","a":"No: basta l'economicità, cioè ricavi che coprono i costi.","v":{"p":"n","e":[["basta","k",["basta"]],["economicità","k",["economic"]],["ricavi","k",["ricav"]],["coprono","k",["copro"]],["costi","k",["costi"]]],"r":[]}},{"id":"PPP-17~3","s":"PPP-17","q":"Chi è il piccolo imprenditore?","a":"Coltivatori diretti, artigiani, piccoli commercianti, con prevalenza del lavoro proprio e dei familiari.","v":{"p":null,"e":[["Coltivatori","k",["coltivat"]],["diretti","k",["diret"]],["artigiani","k",["artigi"]],["commercianti","k",["commerci"]],["prevalenza","k",["prevale"]],["lavoro","k",["lavor","dipendent","prestator"]],["familiari","k",["famili"]]],"r":[]}},{"id":"PPP-17~4","s":"PPP-17","q":"Quale obbligo ha l'imprenditore collettivo rispetto alla crisi?","a":"Istituire un assetto organizzativo, amministrativo e contabile adeguato, anche per rilevare tempestivamente la crisi.","v":{"p":null,"e":[["Istituire","k",["istitu"]],["assetto","k",["asset"]],["organizzativo","k",["organizz"]],["amministrativo","k",["amminist"]],["contabile","k",["contab"]],["adeguato","k",["adegu"]],["rilevare","k",["rilev"]],["tempestivamente","k",["tempesti"]]],"r":[]}},{"id":"PPP-18~0","s":"PPP-18","q":"Qual è il cuore di «Impresa e società»? Rispondi in due o tre frasi.","a":"L'impresa è l'attività dell'imprenditore e l'azienda è il complesso dei beni organizzati per esercitarla (art. 2555 c.c.); la società è il contratto con cui due o più persone conferiscono beni o servizi per l'esercizio in comune di un'attività economica allo scopo di dividerne gli utili (art. 2247 c.c.).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"PPP-18~1","s":"PPP-18","q":"Differenza tra impresa e azienda?","a":"L'impresa è l'attività; l'azienda è lo strumento, il complesso dei beni organizzati.","v":{"p":null,"e":[["attività","k",["attiv"]],["strumento","k",["strume"]],["complesso","k",["comple"]],["beni","k",["ben"]],["organizzati","k",["organizz"]]],"r":[]}},{"id":"PPP-18~2","s":"PPP-18","q":"Chi risponde dei debiti nelle società di persone e in quelle di capitali?","a":"Società di persone: i soci illimitatamente, salvo gli accomandanti; società di capitali: solo la società (autonomia patrimoniale perfetta).","v":{"p":null,"e":[["illimitatamente","k",["illimita"]],["accomandanti","k",["accomand"]]],"r":[]}},{"id":"PPP-18~3","s":"PPP-18","q":"Cosa accade ai dipendenti nel trasferimento d'azienda?","a":"Il rapporto continua con il cessionario.","v":{"p":null,"e":[["rapporto","k",["rappo","contratt"]],["continua","k",["conti"]],["cessionario","k",["cessiona"]]],"r":[]}},{"id":"S22-PPP-1~0","s":"S22-PPP-1","q":"Qual è il cuore di «Persona fisica e persona giuridica»? Rispondi in due o tre frasi.","a":"Sono soggetti di diritto la persona fisica, cioè ogni individuo dotato di capacità giuridica, e la persona giuridica, cioè un complesso organizzato di persone e beni con uno scopo lecito a cui l'ordinamento riconosce la personalità. La differenza chiave per la persona giuridica è l'autonomia patrimoniale perfetta.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-PPP-1~1","s":"S22-PPP-1","q":"Cosa distingue la persona giuridica?","a":"L'autonomia patrimoniale perfetta: i beni sono dell'ente e i creditori dell'ente non aggrediscono i beni dei membri.","v":{"p":null,"e":[["autonomia","k",["autono"]],["patrimoniale","k",["patrimon"]],["perfetta","k",["perfe"]],["beni","k",["ben"]],["ente","k",["ent"]],["creditori","k",["credit"]],["aggrediscono","k",["aggredis"]],["membri","k",["membr"]]],"r":[]}},{"id":"S22-PPP-1~2","s":"S22-PPP-1","q":"Differenza tra domicilio e residenza?","a":"Domicilio: sede principale di affari e interessi; residenza: dimora abituale.","v":{"p":null,"e":[["principale","k",["princip"]],["affari","k",["affar"]],["interessi","k",["intere"]],["dimora","k",["dimor"]],["abituale","k",["abitu"]]],"r":[]}},{"id":"S22-PPP-1~3","s":"S22-PPP-1","q":"Come acquistano la personalità giuridica società di capitali e associazioni?","a":"Le società con l'iscrizione nel registro delle imprese; associazioni e fondazioni con il riconoscimento, cioè l'iscrizione nel registro presso le prefetture.","v":{"p":null,"e":[["iscrizione","k",["iscrizi"]],["registro","k",["regis"]],["imprese","k",["impre","non si prescrive","non si prescrivono"]],["fondazioni","k",["fondazi"]],["riconoscimento","k",["riconosc"]],["presso","k",["press"]],["prefetture","k",["prefett"]]],"r":[]}},{"id":"S22-PPP-8~0","s":"S22-PPP-8","q":"Qual è il cuore di «Il contratto: nullità, annullabilità, risoluzione»? Rispondi in due o tre frasi.","a":"Nullità, annullabilità e risoluzione sono rimedi diversi: nullità e annullabilità colpiscono il contratto nato viziato (momento genetico); la risoluzione scioglie un contratto valido quando un evento successivo altera l'equilibrio tra le prestazioni (momento funzionale).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-PPP-8~1","s":"S22-PPP-8","q":"Differenza tra nullità e annullabilità da un lato e risoluzione dall'altro?","a":"Le prime colpiscono il contratto nato viziato (momento genetico); la risoluzione scioglie un contratto valido per eventi successivi (momento funzionale).","v":{"p":null,"e":[["prime","k",["prime"]],["colpiscono","k",["colpisc"]],["contratto","k",["contra","rapport"]],["nato","k",["nat"]],["viziato","k",["vizia"]],["scioglie","k",["sciog"]],["valido","k",["valid"]],["eventi","k",["event"]],["successivi","k",["success"]]],"r":[]}},{"id":"S22-PPP-8~2","s":"S22-PPP-8","q":"La risoluzione pregiudica i terzi?","a":"No: è retroattiva tra le parti ma non pregiudica i diritti acquistati dai terzi prima della domanda giudiziale.","v":{"p":"n","e":[["retroattiva","k",["retroatt"]],["parti","k",["parti"]],["diritti","k",["dirit"]],["acquistati","k",["acquist"]],["domanda","k",["doman","istanz","richiest"]],["giudiziale","k",["giudizi"]]],"r":[]}},{"id":"PPP-1~0","s":"PPP-1","q":"Qual è il cuore di «L'iter legislativo»? Rispondi in due o tre frasi.","a":"Il procedimento legislativo ordinario passa per iniziativa, esame e approvazione dello stesso testo da parte di entrambe le Camere, promulgazione del Presidente della Repubblica e pubblicazione (artt. 70-74 Cost.).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"PPP-1~1","s":"PPP-1","q":"Chi esercita la funzione legislativa e cosa comporta il bicameralismo paritario?","a":"Le due Camere collettivamente: lo stesso testo deve essere approvato da entrambe.","v":{"p":null,"e":[["2","n",["2"]],["Camere","k",["camer"]],["collettivamente","k",["colletti"]],["testo","k",["testo"]],["approvato","k",["approv"]],["entrambe","k",["entra"]]],"r":[]}},{"id":"PPP-1~2","s":"PPP-1","q":"Chi ha l'iniziativa legislativa?","a":"Governo, ciascun parlamentare, organi ed enti previsti da legge costituzionale (CNEL, Consigli regionali) e il popolo con almeno 50.000 elettori.","v":{"p":null,"e":[["50.000","n",["50000"]],["Governo","k",["gover"]],["parlamentare","k",["parlamen"]],["organi","k",["organ"]],["enti","k",["ent"]],["previsti","k",["previ"]],["legge","k",["legge"]],["costituzionale","k",["costituz"]],["popolo","k",["popol"]],["elettori","k",["elett"]]],"r":[]}},{"id":"PPP-1~3","s":"PPP-1","q":"Il Presidente della Repubblica può rifiutare la promulgazione?","a":"No: può chiedere con messaggio motivato una nuova deliberazione, ma se le Camere riapprovano deve promulgare.","v":{"p":"n","e":[["chiedere","k",["chied"]],["messaggio","k",["messag"]],["motivato","k",["motiv"]],["nuova","k",["nuova"]],["deliberazione","k",["delibera"]],["Camere","k",["camer"]],["riapprovano","k",["riapprov"]]],"r":[]}},{"id":"PPP-1~4","s":"PPP-1","q":"Quali leggi non si possono approvare in commissione?","a":"Quelle a riserva di Assemblea: costituzionali, elettorali, di delega, di ratifica e di bilancio.","v":{"p":null,"e":[["riserva","k",["riser"]],["Assemblea","k",["assemb"]],["costituzionali","k",["costituz"]],["elettorali","k",["elettor"]],["delega","k",["deleg"]],["ratifica","k",["ratif"]],["bilancio","k",["bilan"]]],"r":[]}},{"id":"PPP-1~5","s":"PPP-1","q":"Quando entra in vigore una legge?","a":"Il quindicesimo giorno successivo alla pubblicazione, salvo diverso termine.","v":{"p":null,"e":[["quindicesimo","k",["quindice"]],["giorno","k",["giorn","gg"]],["successivo","k",["success"]],["pubblicazione","k",["pubblica"]],["diverso","k",["diver"]],["termine","k",["termi","scadenz"]]],"r":[]}},{"id":"PPP-2~0","s":"PPP-2","q":"Qual è il cuore di «La formazione del Governo»? Rispondi in due o tre frasi.","a":"Il Governo è formato dal Presidente del Consiglio e dai ministri; nasce dalla nomina del Presidente della Repubblica e deve ottenere la fiducia di entrambe le Camere (artt. 92-94 Cost.).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"PPP-2~1","s":"PPP-2","q":"Chi nomina il Presidente del Consiglio e i ministri?","a":"Il Presidente della Repubblica: nomina il Presidente del Consiglio e, su sua proposta, i ministri.","v":{"p":null,"e":[["Repubblica","k",["repubbl"]],["proposta","k",["propo"]]],"r":[]}},{"id":"PPP-2~2","s":"PPP-2","q":"Entro quando e da chi il Governo deve ottenere la fiducia?","a":"Da entrambe le Camere, entro 10 giorni dalla formazione, con mozione motivata votata per appello nominale.","v":{"p":null,"e":[["10","n",["10"]],["entrambe","k",["entra"]],["Camere","k",["camer"]],["giorni","k",["giorn","gg"]],["formazione","k",["formazi"]],["mozione","k",["mozio"]],["motivata","k",["motiv"]],["votata","k",["votat"]],["appello","k",["appel"]],["nominale","k",["nomin"]]],"r":[]}},{"id":"PPP-2~3","s":"PPP-2","q":"Il voto contrario su una proposta del Governo lo obbliga a dimettersi?","a":"No: serve una mozione di sfiducia firmata da almeno un decimo dei componenti.","v":{"p":"n","e":[["serve","k",["serve"]],["mozione","k",["mozio"]],["sfiducia","k",["sfidu"]],["firmata","k",["firma"]],["decimo","k",["decim"]],["componenti","k",["compone"]]],"r":[]}},{"id":"PPP-3~0","s":"PPP-3","q":"Qual è il cuore di «Il decreto-legge»? Rispondi in due o tre frasi.","a":"Il decreto-legge è un atto provvisorio con forza di legge che il Governo adotta, sotto la propria responsabilità, in casi straordinari di necessità e urgenza; perde efficacia fin dall'inizio se non è convertito in legge entro 60 giorni (art. 77 Cost.).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"PPP-3~1","s":"PPP-3","q":"Quali sono i presupposti del decreto-legge?","a":"Casi straordinari di necessità e urgenza; lo delibera il Consiglio dei ministri e lo emana il Presidente della Repubblica.","v":{"p":null,"e":[["straordinari","k",["straordi"]],["necessità","k",["necess"]],["urgenza","k",["urgen"]],["delibera","k",["delib"]],["Consiglio","k",["consig"]],["ministri","k",["minis"]],["emana","k",["emana"]],["Presidente","k",["preside"]],["Repubblica","k",["repubbl"]]],"r":[]}},{"id":"PPP-3~2","s":"PPP-3","q":"Cosa accade se il decreto-legge non è convertito?","a":"Perde efficacia fin dall'inizio (ex tunc); le Camere possono regolare con legge i rapporti sorti.","v":{"p":null,"e":[["Perde","k",["perde"]],["efficacia","k",["effica"]],["inizio","k",["inizi"]],["Camere","k",["camer"]],["regolare","k",["regol"]],["rapporti","k",["rappo","contratt"]],["sorti","k",["sorti"]]],"r":[]}},{"id":"PPP-3~3","s":"PPP-3","q":"Quali limiti incontra il decreto-legge oltre all'art. 77 Cost.?","a":"Niente deleghe legislative, materie riservate all'Assemblea, reiterazione di decreti non convertiti o ripristino di norme dichiarate illegittime; contenuto specifico e omogeneo.","v":{"p":null,"e":[["Niente","k",["nient"]],["deleghe","k",["deleg"]],["legislative","k",["legislat"]],["materie","k",["mater"]],["riservate","k",["riserv"]],["Assemblea","k",["assemb"]],["reiterazione","k",["reiteraz"]],["convertiti","k",["convert"]],["ripristino","k",["riprist"]],["norme","k",["norme"]],["dichiarate","k",["dichiar"]],["illegittime","k",["illegitt"]],["contenuto","k",["conten"]],["specifico","k",["specif"]],["omogeneo","k",["omoge"]]],"r":[]}},{"id":"PPP-4~0","s":"PPP-4","q":"Qual è il cuore di «Il decreto legislativo delegato»? Rispondi in due o tre frasi.","a":"Il decreto legislativo è un atto con forza di legge adottato dal Governo su delega del Parlamento, che deve fissare principi e criteri direttivi, un tempo limitato e oggetti definiti (art. 76 Cost.).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"PPP-4~1","s":"PPP-4","q":"Cosa deve contenere la legge delega?","a":"Principi e criteri direttivi, tempo limitato e oggetti definiti.","v":{"p":null,"e":[["Principi","k",["princ"]],["criteri","k",["crite"]],["direttivi","k",["dirett"]],["tempo","k",["tempo"]],["limitato","k",["limit"]],["oggetti","k",["ogget"]],["definiti","k",["defin"]]],"r":[]}},{"id":"PPP-4~2","s":"PPP-4","q":"Qual è il vizio tipico del decreto legislativo e chi lo giudica?","a":"L'eccesso di delega, che lo rende illegittimo; giudica la Corte costituzionale.","v":{"p":null,"e":[["eccesso","k",["ecces"]],["delega","k",["deleg"]],["rende","k",["rende"]],["illegittimo","k",["illegitt"]],["Corte","k",["corte"]],["costituzionale","k",["costituz"]]],"r":[]}},{"id":"PPP-4~3","s":"PPP-4","q":"La legge delega si può approvare in commissione?","a":"No: è a riserva di Assemblea.","v":{"p":"n","e":[["riserva","k",["riser"]],["Assemblea","k",["assemb"]]],"r":[]}},{"id":"PPP-5~0","s":"PPP-5","q":"Qual è il cuore di «Il referendum abrogativo e il referendum costituzionale»? Rispondi in due o tre frasi.","a":"Il referendum abrogativo elimina in tutto o in parte una legge o un atto con valore di legge (art. 75 Cost.); il referendum costituzionale è eventuale e confermativo di una legge di revisione approvata senza i due terzi (art. 138 Cost.).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"PPP-5~1","s":"PPP-5","q":"Chi può chiedere il referendum abrogativo?","a":"500.000 elettori o 5 Consigli regionali.","v":{"p":null,"e":[["500.000","n",["500000"]],["5","n",["5"]],["elettori","k",["elett"]],["Consigli","k",["consi"]],["regionali","k",["region"]]],"r":[]}},{"id":"PPP-5~2","s":"PPP-5","q":"Su quali leggi non è ammesso il referendum abrogativo?","a":"Leggi tributarie e di bilancio, amnistia e indulto, autorizzazione a ratificare trattati internazionali.","v":{"p":null,"e":[["tributarie","k",["tributa"]],["bilancio","k",["bilan"]],["amnistia","k",["amnis"]],["indulto","k",["indul"]],["autorizzazione","k",["autorizz"]],["ratificare","k",["ratific"]],["trattati","k",["tratt"]],["internazionali","k",["internaz"]]],"r":[]}},{"id":"PPP-5~3","s":"PPP-5","q":"Quale quorum serve nel referendum abrogativo e in quello costituzionale?","a":"Abrogativo: deve votare la maggioranza degli aventi diritto; costituzionale: nessun quorum.","v":{"p":null,"e":[["votare","k",["votar"]],["maggioranza","k",["maggiora"]],["aventi","k",["avent"]],["diritto","k",["dirit"]],["nessun","k",["nessu"]]],"r":[]}},{"id":"PPP-5~4","s":"PPP-5","q":"Quando il referendum costituzionale non si può chiedere?","a":"Se la legge di revisione è approvata con i due terzi nella seconda votazione.","v":{"p":null,"e":[["2","n",["2"]],["legge","k",["legge"]],["revisione","k",["revisi"]],["approvata","k",["approv"]],["terzi","k",["terzi"]],["seconda","k",["secon"]],["votazione","k",["votazi"]]],"r":[]}},{"id":"PPP-6~0","s":"PPP-6","q":"Qual è il cuore di «La Corte costituzionale»? Rispondi in due o tre frasi.","a":"La Corte costituzionale è l'organo di garanzia che giudica la legittimità delle leggi e degli atti con forza di legge, i conflitti di attribuzione e le accuse al Presidente della Repubblica (art. 134 Cost.).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"PPP-6~1","s":"PPP-6","q":"Cosa giudica la Corte costituzionale?","a":"La legittimità di leggi e atti con forza di legge, i conflitti di attribuzione e le accuse al Presidente della Repubblica.","v":{"p":null,"e":[["legittimità","k",["legittim"]],["leggi","k",["leggi"]],["atti","k",["att"]],["forza","k",["forza"]],["legge","k",["legge"]],["conflitti","k",["confli"]],["attribuzione","k",["attribuz"]],["accuse","k",["accus"]],["Presidente","k",["preside"]],["Repubblica","k",["repubbl"]]],"r":[]}},{"id":"PPP-6~2","s":"PPP-6","q":"Come è composta la Corte costituzionale?","a":"15 giudici: un terzo dal Presidente della Repubblica, un terzo dal Parlamento in seduta comune, un terzo dalle supreme magistrature; mandato di 9 anni non rinnovabile.","v":{"p":null,"e":[["15","n",["15"]],["9","m",["9"]],["giudici","k",["giudi","tribunal"]],["terzo","k",["terzo"]],["Presidente","k",["preside"]],["Repubblica","k",["repubbl"]],["Parlamento","k",["parlame"]],["seduta","k",["sedut"]],["supreme","k",["supre"]],["magistrature","k",["magistra"]],["mandato","k",["manda"]],["anni","k",["ann"]],["rinnovabile","k",["rinnovab"]]],"r":[]}},{"id":"PPP-6~3","s":"PPP-6","q":"Da quando la norma dichiarata illegittima perde efficacia?","a":"Dal giorno successivo alla pubblicazione della decisione.","v":{"p":null,"e":[["giorno","k",["giorn","gg"]],["successivo","k",["success"]],["pubblicazione","k",["pubblica"]],["decisione","k",["decisi"]]],"r":[]}},{"id":"PPP-6~4","s":"PPP-6","q":"Come si arriva alla Corte costituzionale?","a":"In via incidentale, quando un giudice solleva la questione nel corso di un giudizio, o in via principale con il ricorso dello Stato o della Regione.","v":{"p":null,"e":[["incidentale","k",["incident"]],["giudice","k",["giudi","tribunal"]],["solleva","k",["solle"]],["questione","k",["questi"]],["corso","k",["corso"]],["principale","k",["princip"]],["ricorso","k",["ricor"]],["Regione","k",["regio"]]],"r":[]}},{"id":"PPP-7~0","s":"PPP-7","q":"Qual è il cuore di «La legge statale e la legge regionale nel sistema delle fonti»? Rispondi in due o tre frasi.","a":"Legge statale e legge regionale sono entrambe fonti primarie: il rapporto non è gerarchico ma di competenza, secondo il riparto per materie dell'art. 117 Cost.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"PPP-7~1","s":"PPP-7","q":"Che rapporto c'è tra legge statale e legge regionale?","a":"Non gerarchico ma di competenza, secondo il riparto per materie dell'art. 117 Cost.","v":{"p":null,"e":[["art. 117","n",["117"]],["gerarchico","k",["gerarch"]],["competenza","k",["compete"]],["secondo","k",["secon"]],["riparto","k",["ripar"]],["materie","k",["mater"]]],"r":[]}},{"id":"PPP-7~2","s":"PPP-7","q":"A chi spetta legiferare su rapporto di lavoro privato e previdenza sociale?","a":"Allo Stato in via esclusiva (ordinamento civile; previdenza sociale).","v":{"p":null,"e":[["esclusiva","k",["esclus"]]],"r":[]}},{"id":"PPP-7~3","s":"PPP-7","q":"Tutela e sicurezza del lavoro: che tipo di potestà legislativa?","a":"Concorrente: lo Stato fissa i principi fondamentali, le Regioni il resto.","v":{"p":null,"e":[["Concorrente","k",["concorre"]],["fissa","k",["fissa"]],["principi","k",["princ"]],["fondamentali","k",["fondamen"]],["Regioni","k",["regio"]],["resto","k",["resto"]]],"r":[]}},{"id":"PPP-7~4","s":"PPP-7","q":"Cos'è la potestà residuale delle Regioni?","a":"La competenza su ogni materia non riservata allo Stato.","v":{"p":null,"e":[["competenza","k",["compete"]],["materia","k",["mater"]],["riservata","k",["riserv"]]],"r":[]}},{"id":"PPP-8~0","s":"PPP-8","q":"Qual è il cuore di «Il Presidente della Repubblica»? Rispondi in due o tre frasi.","a":"Il Presidente della Repubblica è il capo dello Stato e rappresenta l'unità nazionale; è eletto dal Parlamento in seduta comune per sette anni ed è un organo di garanzia (artt. 83-90 Cost.).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"PPP-8~1","s":"PPP-8","q":"Come viene eletto il Presidente della Repubblica?","a":"Dal Parlamento in seduta comune integrato dai delegati regionali: due terzi nei primi tre scrutini, poi maggioranza assoluta.","v":{"p":null,"e":[["2","n",["2"]],["3","n",["3"]],["Parlamento","k",["parlame"]],["seduta","k",["sedut"]],["integrato","k",["integr"]],["delegati","k",["deleg"]],["regionali","k",["region"]],["terzi","k",["terzi"]],["primi","k",["primi"]],["scrutini","k",["scrut"]],["maggioranza","k",["maggiora"]],["assoluta","k",["assol"]]],"r":[]}},{"id":"PPP-8~2","s":"PPP-8","q":"Requisiti e durata del mandato del Presidente della Repubblica?","a":"Cittadino con almeno 50 anni; mandato di 7 anni.","v":{"p":null,"e":[["50","n",["50"]],["7","m",["7"]],["Cittadino","k",["cittad"]],["anni","k",["ann"]]],"r":[]}},{"id":"PPP-8~3","s":"PPP-8","q":"Cos'è la controfirma?","a":"Nessun atto del Presidente è valido senza la controfirma dei ministri proponenti, che ne assumono la responsabilità.","v":{"p":"n","e":[["Nessun","k",["nessu"]],["atto","k",["att"]],["Presidente","k",["preside"]],["valido","k",["valid"]],["ministri","k",["minis"]],["proponenti","k",["propone"]],["assumono","k",["assum"]],["responsabilità","k",["responsa"]]],"r":[]}},{"id":"PPP-8~4","s":"PPP-8","q":"Di cosa risponde il Presidente della Repubblica?","a":"Solo di alto tradimento e attentato alla Costituzione.","v":{"p":null,"e":[["alto","k",["alt"]],["tradimento","k",["tradime"]],["attentato","k",["attent"]]],"r":[]}},{"id":"PPP-X2~0","s":"PPP-X2","q":"Qual è il cuore di «Il procedimento amministrativo e il diritto di accesso (L. 241/1990)»? Rispondi in due o tre frasi.","a":"La L. 241/1990 regola come la pubblica amministrazione decide: l'attività amministrativa segue i criteri di economicità, efficacia, imparzialità, pubblicità e trasparenza (art. 1), ogni procedimento ha un responsabile e un termine certo di conclusione con provvedimento espresso e motivato, e gli interessati possono partecipare e accedere ai documenti.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"PPP-X2~1","s":"PPP-X2","q":"Entro quando si conclude il procedimento amministrativo se manca un termine?","a":"Entro 30 giorni, con provvedimento espresso e motivato.","v":{"p":null,"e":[["30","n",["30"]],["giorni","k",["giorn","gg"]],["provvedimento","k",["provvedi"]],["espresso","k",["espre"]],["motivato","k",["motiv"]]],"r":[]}},{"id":"PPP-X2~2","s":"PPP-X2","q":"Cos'è il preavviso di rigetto?","a":"Nei procedimenti a istanza di parte, prima del diniego, la comunicazione dei motivi ostativi con 10 giorni per le osservazioni.","v":{"p":null,"e":[["10","n",["10"]],["procedimenti","k",["procedim"]],["istanza","k",["istan"]],["diniego","k",["dinie"]],["comunicazione","k",["comunica"]],["motivi","k",["motiv"]],["ostativi","k",["ostat"]],["giorni","k",["giorn","gg"]],["osservazioni","k",["osservaz"]]],"r":[]}},{"id":"PPP-X2~3","s":"PPP-X2","q":"Chi ha diritto di accesso ai documenti amministrativi?","a":"Chi ha un interesse diretto, concreto e attuale collegato al documento; dopo 30 giorni senza risposta la richiesta si intende respinta.","v":{"p":null,"e":[["30","m",["30"]],["interesse","k",["intere"]],["diretto","k",["diret"]],["concreto","k",["concr"]],["attuale","k",["attua"]],["collegato","k",["colleg"]],["giorni","k",["giorn","gg"]],["risposta","k",["rispo"]],["richiesta","k",["richie"]],["intende","k",["inten"]],["respinta","k",["respi"]]],"r":[]}},{"id":"PPP-X2~4","s":"PPP-X2","q":"Il datore ispezionato può accedere alle dichiarazioni dei lavoratori?","a":"Non sempre: sono sottratte all'accesso se la divulgazione può esporre i lavoratori a discriminazioni o pressioni; il bilanciamento con il diritto di difesa lo fa il giudice amministrativo.","v":{"p":null,"e":[["sottratte","k",["sottra"]],["accesso","k",["acces"]],["divulgazione","k",["divulgaz"]],["esporre","k",["espor"]],["discriminazioni","k",["discrimi"]],["pressioni","k",["pressi"]],["bilanciamento","k",["bilancia"]],["diritto","k",["dirit"]],["difesa","k",["difes"]],["giudice","k",["giudi","tribunal"]],["amministrativo","k",["amminist"]]],"r":[]}},{"id":"PPP-X3~0","s":"PPP-X3","q":"Qual è il cuore di «Le fonti del diritto dell'Unione europea e il loro rapporto con il diritto interno»? Rispondi in due o tre frasi.","a":"Il diritto dell'Unione europea comprende i Trattati (TUE e TFUE) e la Carta dei diritti fondamentali come fonti primarie, e regolamenti, direttive e decisioni come fonti derivate (art. 288 TFUE); prevale sul diritto nazionale incompatibile grazie alle limitazioni di sovranità consentite dagli artt. 11 e 117, c. 1, Cost.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"PPP-X3~1","s":"PPP-X3","q":"Differenza tra regolamento e direttiva UE?","a":"Il regolamento è obbligatorio in tutti i suoi elementi e direttamente applicabile; la direttiva vincola lo Stato al risultato, lasciandogli forma e mezzi.","v":{"p":null,"e":[["obbligatorio","k",["obbligat","obblig"]],["elementi","k",["eleme"]],["applicabile","k",["applicab"]],["vincola","k",["vinco"]],["risultato","k",["risult"]],["lasciandogli","k",["lasciand"]],["forma","k",["forma"]],["mezzi","k",["mezzi"]]],"r":[]}},{"id":"PPP-X3~2","s":"PPP-X3","q":"Cosa fa il giudice davanti a una norma interna incompatibile con il diritto UE direttamente applicabile?","a":"Non la applica: primato del diritto dell'Unione.","v":{"p":null,"e":[["primato","k",["prima"]],["Unione","k",["union"]]],"r":[]}},{"id":"PPP-X3~3","s":"PPP-X3","q":"Cosa accade se lo Stato non attua una direttiva?","a":"Le disposizioni chiare, precise e incondizionate si possono invocare contro lo Stato; lo Stato inadempiente risarcisce i danni ai singoli.","v":{"p":null,"e":[["disposizioni","k",["disposiz"]],["chiare","k",["chiar"]],["precise","k",["preci"]],["incondizionate","k",["incondiz"]],["invocare","k",["invoc"]],["contro","k",["contr","rapport","contribuz","contribut"]],["inadempiente","k",["inadempi"]],["risarcisce","k",["risarci"]],["danni","k",["danni"]],["singoli","k",["singo"]]],"r":[]}},{"id":"PPP-X3~4","s":"PPP-X3","q":"Come si recepiscono le direttive in Italia?","a":"Con la legge di delegazione europea annuale, che delega il Governo ad attuarle con decreti legislativi.","v":{"p":null,"e":[["legge","k",["legge"]],["delegazione","k",["delegazi"]],["europea","k",["europ"]],["annuale","k",["annua"]],["delega","k",["deleg"]],["Governo","k",["gover"]],["attuarle","k",["attua"]],["decreti","k",["decre"]],["legislativi","k",["legislat"]]],"r":[]}},{"id":"S22-PPP-11~0","s":"S22-PPP-11","q":"Qual è il cuore di «I principi fondamentali della Costituzione»? Rispondi in due o tre frasi.","a":"I principi fondamentali (artt. 1-12 Cost.) disegnano l'identità della Repubblica: democrazia fondata sul lavoro, diritti inviolabili, uguaglianza, diritto al lavoro, autonomie, apertura internazionale e pace.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-PPP-11~1","s":"S22-PPP-11","q":"Su cosa è fondata la Repubblica?","a":"Sul lavoro: Repubblica democratica fondata sul lavoro, la sovranità appartiene al popolo.","v":{"p":null,"e":[["lavoro","k",["lavor","dipendent","prestator"]],["democratica","k",["democrat"]],["sovranità","k",["sovran"]],["appartiene","k",["apparti"]],["popolo","k",["popol"]]],"r":[]}},{"id":"S22-PPP-11~2","s":"S22-PPP-11","q":"Differenza tra uguaglianza formale e sostanziale?","a":"Formale: pari dignità sociale senza distinzioni; sostanziale: la Repubblica rimuove gli ostacoli economici e sociali.","v":{"p":null,"e":[["pari","k",["par"]],["dignità","k",["digni"]],["sociale","k",["socia"]],["distinzioni","k",["distinzi"]],["Repubblica","k",["repubbl"]],["rimuove","k",["rimuo"]],["ostacoli","k",["ostac"]],["economici","k",["econom"]]],"r":[]}},{"id":"S22-PPP-11~3","s":"S22-PPP-11","q":"Cosa prevede la Costituzione su guerra e sovranità?","a":"Ripudio della guerra; limitazioni di sovranità per la pace e la giustizia tra le Nazioni.","v":{"p":null,"e":[["Ripudio","k",["ripud"]],["limitazioni","k",["limitazi"]],["pace","k",["pac"]],["giustizia","k",["giusti"]],["Nazioni","k",["nazio"]]],"r":[]}},{"id":"S22-PPP-12~0","s":"S22-PPP-12","q":"Qual è il cuore di «Il Parlamento»? Rispondi in due o tre frasi.","a":"Il Parlamento è composto dalla Camera dei deputati e dal Senato della Repubblica (art. 55 Cost.), con bicameralismo perfetto: le due Camere hanno le stesse funzioni, legislativa e di indirizzo e controllo sul Governo.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-PPP-12~1","s":"S22-PPP-12","q":"Quanti sono oggi deputati e senatori?","a":"400 deputati e 200 senatori elettivi, più i senatori a vita.","v":{"p":null,"e":[["400","n",["400"]],["200","n",["200"]],["elettivi","k",["elett"]],["vita","k",["vit"]]],"r":[]}},{"id":"S22-PPP-12~2","s":"S22-PPP-12","q":"Cosa fa il Parlamento in seduta comune?","a":"Elegge il Presidente della Repubblica, un terzo dei membri del CSM e cinque giudici costituzionali; mette in stato d'accusa il Presidente.","v":{"p":null,"e":[["5","n",["5"]],["Elegge","k",["elegg"]],["Presidente","k",["preside"]],["Repubblica","k",["repubbl"]],["terzo","k",["terzo"]],["membri","k",["membr"]],["CSM","k",["csm"]],["giudici","k",["giudi","tribunal"]],["mette","k",["mette"]],["accusa","k",["accus"]]],"r":[]}},{"id":"S22-PPP-12~3","s":"S22-PPP-12","q":"Cosa significa divieto di mandato imperativo?","a":"Ogni parlamentare rappresenta la Nazione senza vincolo di mandato.","v":{"p":null,"e":[["parlamentare","k",["parlamen"]],["rappresenta","k",["rapprese"]],["Nazione","k",["nazio"]],["vincolo","k",["vinco"]]],"r":[]}},{"id":"S22-PPP-18~0","s":"S22-PPP-18","q":"Qual è il cuore di «Gli enti pubblici territoriali»? Rispondi in due o tre frasi.","a":"Gli enti pubblici territoriali sono i Comuni, le Province, le Città metropolitane e le Regioni, che con lo Stato costituiscono la Repubblica (art. 114 Cost., riformato dalla L. cost. 3/2001). Sono enti autonomi con propri statuti, poteri e funzioni.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-PPP-18~1","s":"S22-PPP-18","q":"Da quali enti è costituita la Repubblica?","a":"Comuni, Province, Città metropolitane, Regioni e Stato.","v":{"p":null,"e":[["Comuni","k",["comun"]],["Province","k",["provi"]],["Città","k",["citta"]],["metropolitane","k",["metropol"]],["Regioni","k",["regio"]]],"r":[]}},{"id":"S22-PPP-18~2","s":"S22-PPP-18","q":"A chi spettano di regola le funzioni amministrative?","a":"Ai Comuni, secondo sussidiarietà, differenziazione e adeguatezza.","v":{"p":null,"e":[["Comuni","k",["comun"]],["secondo","k",["secon"]],["sussidiarietà","k",["sussidia"]],["differenziazione","k",["differen"]],["adeguatezza","k",["adeguate"]]],"r":[]}},{"id":"S22-PPP-19~0","s":"S22-PPP-19","q":"Qual è il cuore di «I principi costituzionali della Pubblica Amministrazione»? Rispondi in due o tre frasi.","a":"La Costituzione fissa i principi della pubblica amministrazione soprattutto negli artt. 97 e 98: legalità, imparzialità e buon andamento, con equilibrio di bilancio, accesso per concorso e servizio esclusivo della Nazione.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-PPP-19~1","s":"S22-PPP-19","q":"Quali principi fissa la Costituzione per la pubblica amministrazione?","a":"Buon andamento e imparzialità, con riserva di legge sull'organizzazione; equilibrio di bilancio; accesso per concorso; servizio esclusivo della Nazione.","v":{"p":null,"e":[["Buon","k",["buon"]],["andamento","k",["andame"]],["imparzialità","k",["imparzia"]],["riserva","k",["riser"]],["legge","k",["legge"]],["organizzazione","k",["organizz"]],["equilibrio","k",["equilib"]],["bilancio","k",["bilan"]],["accesso","k",["acces"]],["concorso","k",["conco"]],["servizio","k",["servi"]],["esclusivo","k",["esclus"]],["Nazione","k",["nazio"]]],"r":[]}},{"id":"S22-PPP-19~2","s":"S22-PPP-19","q":"Come si accede agli impieghi pubblici?","a":"Mediante concorso, salvo i casi stabiliti dalla legge.","v":{"p":null,"e":[["Mediante","k",["media"]],["concorso","k",["conco"]],["stabiliti","k",["stabil"]],["legge","k",["legge"]]],"r":[]}},{"id":"S22-PPP-19~3","s":"S22-PPP-19","q":"Contro gli atti della PA la tutela giurisdizionale è sempre ammessa?","a":"Sì, davanti al giudice ordinario o amministrativo.","v":{"p":"s","e":[["davanti","k",["davan"]],["giudice","k",["giudi","tribunal"]],["ordinario","k",["ordina"]],["amministrativo","k",["amminist"]]],"r":[]}},{"id":"S22-PPP-20~0","s":"S22-PPP-20","q":"Qual è il cuore di «La magistratura ordinaria e amministrativa»? Rispondi in due o tre frasi.","a":"La magistratura costituisce un ordine autonomo e indipendente da ogni altro potere (art. 104 Cost.). La giurisdizione si divide tra giudice ordinario, civile e penale, e giudici speciali previsti dalla Costituzione: amministrativo (TAR e Consiglio di Stato), contabile (Corte dei conti), tributario e militare.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-PPP-20~1","s":"S22-PPP-20","q":"Quali garanzie di indipendenza ha la magistratura?","a":"Giudice naturale precostituito, soggezione soltanto alla legge, inamovibilità, obbligatorietà dell'azione penale.","v":{"p":null,"e":[["Giudice","k",["giudi","tribunal"]],["naturale","k",["natur"]],["precostituito","k",["precosti"]],["soggezione","k",["soggezi"]],["legge","k",["legge"]],["inamovibilità","k",["inamovib"]],["obbligatorietà","k",["obbligat","obblig"]],["azione","k",["azion"]],["penale","k",["penal"]]],"r":[]}},{"id":"S22-PPP-20~2","s":"S22-PPP-20","q":"Quali sono i principi del giusto processo?","a":"Contraddittorio in parità, giudice terzo e imparziale, ragionevole durata.","v":{"p":null,"e":[["Contraddittorio","k",["contradd"]],["parità","k",["parit"]],["giudice","k",["giudi","tribunal"]],["terzo","k",["terzo"]],["imparziale","k",["imparzi"]],["ragionevole","k",["ragionev"]],["durata","k",["durat"]]],"r":[]}},{"id":"S22-PPP-20~3","s":"S22-PPP-20","q":"Cosa tutela il giudice amministrativo e come è organizzato?","a":"Gli interessi legittimi e, in alcune materie, i diritti soggettivi; TAR in primo grado, Consiglio di Stato in appello.","v":{"p":null,"e":[["1","m",["1"]],["interessi","k",["intere"]],["legittimi","k",["legitt"]],["alcune","k",["alcun"]],["materie","k",["mater"]],["diritti","k",["dirit"]],["soggettivi","k",["soggett"]],["TAR","k",["tar"]],["grado","k",["grado"]],["Consiglio","k",["consig"]],["appello","k",["appel"]]],"r":[]}},{"id":"PPP-X1~0","s":"PPP-X1","q":"Qual è il cuore di «La parità di genere nel lavoro: art. 37 Cost. e Codice delle pari opportunità»? Rispondi in due o tre frasi.","a":"L'art. 37 Cost. riconosce alla donna lavoratrice gli stessi diritti e, a parità di lavoro, le stesse retribuzioni del lavoratore; il Codice delle pari opportunità (D.Lgs. 198/2006) attua il principio con divieti di discriminazione, tutela giudiziaria rafforzata e strumenti di promozione.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"PPP-X1~1","s":"PPP-X1","q":"Differenza tra discriminazione diretta e indiretta?","a":"Diretta: trattamento meno favorevole in ragione del sesso; indiretta: criteri o prassi apparentemente neutri che svantaggiano un sesso.","v":{"p":null,"e":[["trattamento","k",["trattame"]],["favorevole","k",["favorev"]],["ragione","k",["ragio"]],["sesso","k",["sesso"]],["criteri","k",["crite"]],["prassi","k",["prass"]],["apparentemente","k",["apparent"]],["neutri","k",["neutr"]],["svantaggiano","k",["svantagg"]]],"r":[]}},{"id":"PPP-X1~2","s":"PPP-X1","q":"Come funziona l'onere della prova nelle cause di discriminazione?","a":"È alleggerito: se il ricorrente porta elementi di fatto, anche statistici, tocca al datore provare l'assenza di discriminazione.","v":{"p":null,"e":[["alleggerito","k",["allegger"]],["ricorrente","k",["ricorre"]],["porta","k",["porta"]],["elementi","k",["eleme"]],["fatto","k",["fatto"]],["statistici","k",["statist"]],["tocca","k",["tocca"]],["datore","k",["dator","aziend","impres"]],["assenza","k",["assen"]]],"r":[]}},{"id":"PPP-X1~3","s":"PPP-X1","q":"Quando si presume il licenziamento per causa di matrimonio?","a":"Se intimato dalla richiesta delle pubblicazioni fino a un anno dalle nozze: è nullo.","v":{"p":null,"e":[["intimato","k",["intim"]],["richiesta","k",["richie"]],["pubblicazioni","k",["pubblica"]],["anno","k",["ann"]],["nozze","k",["nozze"]],["nullo","k",["nullo","invalid","inefficac","privo","priva","nessun effett","non ha effett","non produce effett"]]],"r":[]}},{"id":"PPP-X1~4","s":"PPP-X1","q":"Quali aziende redigono il rapporto biennale sul personale?","a":"Quelle con oltre 50 dipendenti.","v":{"p":null,"e":[["50","n",["50"]],["dipendenti","k",["dipende","lavorat"]]],"r":[]}},{"id":"PPP-19~0","s":"PPP-19","q":"Qual è il cuore di «Il principio di legalità»? Rispondi in due o tre frasi.","a":"Il principio di legalità penale vuole che nessuno sia punito se non in forza di una legge entrata in vigore prima del fatto commesso (art. 25, c. 2, Cost.) e per un fatto espressamente previsto come reato, con le pene da essa stabilite (art. 1 c.p.).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"PPP-19~1","s":"PPP-19","q":"Cosa dice il principio di legalità penale?","a":"Nessuno è punito se non per legge entrata in vigore prima del fatto e per un fatto espressamente previsto come reato.","v":{"p":"n","e":[["punito","k",["punit"]],["legge","k",["legge"]],["entrata","k",["entra"]],["vigore","k",["vigor"]],["fatto","k",["fatto"]],["espressamente","k",["espressa"]],["previsto","k",["previ"]],["reato","k",["reato"]]],"r":[]}},{"id":"PPP-19~2","s":"PPP-19","q":"Quali sono i corollari del principio di legalità?","a":"Riserva di legge, tassatività e determinatezza, divieto di analogia, irretroattività della norma sfavorevole.","v":{"p":null,"e":[["Riserva","k",["riser"]],["legge","k",["legge"]],["tassatività","k",["tassativ"]],["determinatezza","k",["determin"]],["divieto","k",["divie","vietat","vieta"]],["analogia","k",["analo"]],["irretroattività","k",["irretroa"]],["norma","k",["norma"]],["sfavorevole","k",["sfavorev"]]],"r":[]}},{"id":"PPP-19~3","s":"PPP-19","q":"Un regolamento può prevedere un reato?","a":"No: solo la legge o un atto con forza di legge (riserva di legge).","v":{"p":"n","e":[["legge","k",["legge"]],["atto","k",["att"]],["forza","k",["forza"]]],"r":[]}},{"id":"PPP-20~0","s":"PPP-20","q":"Qual è il cuore di «La personalità della responsabilità penale»? Rispondi in due o tre frasi.","a":"La responsabilità penale è personale (art. 27, c. 1, Cost.): si risponde solo di un fatto proprio e colpevole, mai per fatto altrui.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"PPP-20~1","s":"PPP-20","q":"Cosa significa che la responsabilità penale è personale?","a":"Si risponde solo di un fatto proprio e colpevole, mai per fatto altrui.","v":{"p":"s","e":[["risponde","k",["rispo"]],["fatto","k",["fatto"]],["colpevole","k",["colpev"]],["altrui","k",["altru"]]],"r":[]}},{"id":"PPP-20~2","s":"PPP-20","q":"Come ha letto la Corte costituzionale il principio di colpevolezza?","a":"Esclude la responsabilità oggettiva pura: la colpevolezza è fondamento e misura della pena.","v":{"p":null,"e":[["Esclude","k",["esclu"]],["responsabilità","k",["responsa"]],["oggettiva","k",["oggett"]],["pura","k",["pur"]],["fondamento","k",["fondame"]],["misura","k",["misur"]],["pena","k",["pen"]]],"r":[]}},{"id":"PPP-20~3","s":"PPP-20","q":"Cosa garantisce l'art. 27 Cost. all'imputato e sulla pena?","a":"Presunzione di non colpevolezza fino alla condanna definitiva; pene umane e rieducative; divieto della pena di morte.","v":{"p":null,"e":[["Presunzione","k",["presunzi"]],["colpevolezza","k",["colpevol"]],["condanna","k",["conda"]],["definitiva","k",["definit"]],["umane","k",["umane"]],["rieducative","k",["rieducat"]],["divieto","k",["divie","vietat","vieta"]],["morte","k",["morte"]]],"r":[]}},{"id":"PPP-21~0","s":"PPP-21","q":"Qual è il cuore di «L'irretroattività della legge penale»? Rispondi in due o tre frasi.","a":"La legge penale non è retroattiva: nessuno può essere punito per un fatto che, quando è stato commesso, non era reato (art. 25 Cost.; art. 2, c. 1, c.p.); retroagisce invece la legge più favorevole.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"PPP-21~1","s":"PPP-21","q":"Cos'è l'abolitio criminis?","a":"Se il fatto non è più reato cessano l'esecuzione e gli effetti penali della condanna, anche definitiva.","v":{"p":null,"e":[["fatto","k",["fatto"]],["reato","k",["reato"]],["cessano","k",["cessa"]],["esecuzione","k",["esecuzi"]],["effetti","k",["effet"]],["penali","k",["penal"]],["condanna","k",["conda"]],["definitiva","k",["definit"]]],"r":[]}},{"id":"PPP-21~2","s":"PPP-21","q":"Se la legge penale cambia dopo il fatto, quale si applica?","a":"Quella più favorevole al reo, salvo sentenza irrevocabile.","v":{"p":null,"e":[["favorevole","k",["favorev"]],["sentenza","k",["sente"]],["irrevocabile","k",["irrevoca"]]],"r":[]}},{"id":"PPP-21~3","s":"PPP-21","q":"Che differenza c'è tra l'irretroattività penale e quella delle altre leggi?","a":"La penale ha rango costituzionale; per le altre leggi è un principio generale derogabile.","v":{"p":null,"e":[["rango","k",["rango"]],["costituzionale","k",["costituz"]],["principio","k",["princi"]],["generale","k",["gener"]],["derogabile","k",["derogab"]]],"r":[]}},{"id":"PPP-22~0","s":"PPP-22","q":"Qual è il cuore di «Dolo e colpa»? Rispondi in due o tre frasi.","a":"Dolo e colpa sono le forme dell'elemento psicologico del reato (art. 43 c.p.): nel dolo l'evento è previsto e voluto, nella colpa non è voluto e si verifica per negligenza, imprudenza, imperizia o inosservanza di norme.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"PPP-22~1","s":"PPP-22","q":"Differenza tra dolo e colpa?","a":"Nel dolo l'evento è previsto e voluto; nella colpa non è voluto e deriva da negligenza, imprudenza, imperizia o inosservanza di norme.","v":{"p":null,"e":[["evento","k",["event"]],["previsto","k",["previ"]],["voluto","k",["volut"]],["deriva","k",["deriv"]],["negligenza","k",["neglige"]],["imprudenza","k",["imprude"]],["imperizia","k",["imperi"]],["inosservanza","k",["inosserv"]],["norme","k",["norme"]]],"r":[]}},{"id":"PPP-22~2","s":"PPP-22","q":"Differenza tra colpa generica e specifica?","a":"Generica: negligenza, imprudenza, imperizia; specifica: inosservanza di leggi, regolamenti, ordini o discipline.","v":{"p":null,"e":[["negligenza","k",["neglige"]],["imprudenza","k",["imprude"]],["imperizia","k",["imperi"]],["inosservanza","k",["inosserv"]],["leggi","k",["leggi"]],["regolamenti","k",["regolame"]],["ordini","k",["ordin"]],["discipline","k",["discipl"]]],"r":[]}},{"id":"PPP-22~3","s":"PPP-22","q":"Cos'è la preterintenzione?","a":"Dall'azione deriva un evento più grave di quello voluto.","v":{"p":null,"e":[["azione","k",["azion"]],["deriva","k",["deriv"]],["evento","k",["event"]],["grave","k",["grave"]],["voluto","k",["volut"]]],"r":[]}},{"id":"PPP-22~4","s":"PPP-22","q":"Delitti e contravvenzioni sono punibili per colpa?","a":"I delitti solo nei casi espressamente previsti; le contravvenzioni per dolo o colpa.","v":{"p":null,"e":[["espressamente","k",["espressa"]],["previsti","k",["previ"]],["dolo","k",["dol"]]],"r":[]}},{"id":"PPP-23~0","s":"PPP-23","q":"Qual è il cuore di «Delitti e contravvenzioni»? Rispondi in due o tre frasi.","a":"I reati si distinguono in delitti e contravvenzioni secondo la specie della pena prevista (art. 39 c.p.), non secondo la gravità astratta.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"PPP-23~1","s":"PPP-23","q":"Come si distinguono delitti e contravvenzioni?","a":"Per la specie di pena: delitti con ergastolo, reclusione, multa; contravvenzioni con arresto e ammenda.","v":{"p":null,"e":[["specie","k",["speci"]],["pena","k",["pen"]],["ergastolo","k",["ergast"]],["reclusione","k",["reclusi"]],["multa","k",["multa"]],["arresto","k",["arres"]],["ammenda","k",["ammen"]]],"r":[]}},{"id":"PPP-23~2","s":"PPP-23","q":"Come si estinguono le contravvenzioni in materia di lavoro e sicurezza?","a":"Con la prescrizione obbligatoria: adempimento e pagamento di un quarto del massimo dell'ammenda.","v":{"p":null,"e":[["prescrizione","k",["prescriz"]],["obbligatoria","k",["obbligat","obblig"]],["adempimento","k",["adempime"]],["pagamento","k",["pagame"]],["quarto","k",["quart"]],["ammenda","k",["ammen"]]],"r":[]}},{"id":"S22-PPP-26~0","s":"S22-PPP-26","q":"Qual è il cuore di «Denuncia, esposto e querela»? Rispondi in due o tre frasi.","a":"Denuncia, querela ed esposto sono i modi con cui un fatto viene portato all'autorità. La denuncia riguarda i reati perseguibili d'ufficio; la querela è la condizione di procedibilità per i reati che la legge rimette alla volontà della persona offesa; l'esposto è una segnalazione con cui si chiede l'intervento dell'autorità, senza una forma tipica.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-PPP-26~1","s":"S22-PPP-26","q":"Differenza tra denuncia e querela?","a":"La denuncia riguarda i reati perseguibili d'ufficio e la presenta chiunque; la querela è condizione di procedibilità e la presenta solo la persona offesa.","v":{"p":null,"e":[["riguarda","k",["rigua"]],["reati","k",["reati"]],["perseguibili","k",["persegui"]],["ufficio","k",["uffic"]],["presenta","k",["prese"]],["chiunque","k",["chiun"]],["condizione","k",["condizi"]],["procedibilità","k",["procedib"]],["persona","k",["perso"]],["offesa","k",["offes"]]],"r":[]}},{"id":"S22-PPP-26~2","s":"S22-PPP-26","q":"Entro quando si propone la querela?","a":"Entro tre mesi dalla notizia del fatto.","v":{"p":null,"e":[["3","n",["3"]],["mesi","k",["mes"]],["notizia","k",["notiz"]],["fatto","k",["fatto"]]],"r":[]}},{"id":"S22-PPP-26~3","s":"S22-PPP-26","q":"Le lesioni colpose gravi da violazione delle norme antinfortunistiche sono a querela?","a":"No: si procede d'ufficio.","v":{"p":"n","e":[["procede","k",["proce"]],["ufficio","k",["uffic"]]],"r":[]}},{"id":"S22-PPP-26~4","s":"S22-PPP-26","q":"Cosa fa l'ispettore che accerta una contravvenzione?","a":"Come ufficiale di polizia giudiziaria trasmette la notizia di reato al PM, prima di impartire la prescrizione.","v":{"p":null,"e":[["ufficiale","k",["uffici"]],["polizia","k",["poliz"]],["giudiziaria","k",["giudizia"]],["trasmette","k",["trasme"]],["notizia","k",["notiz"]],["reato","k",["reato"]],["PM","k",["pm"]],["impartire","k",["impart"]],["prescrizione","k",["prescriz"]]],"r":[]}},{"id":"S22-PPP-27~0","s":"S22-PPP-27","q":"Qual è il cuore di «Omicidio colposo e lesioni colpose per violazione delle norme di sicurezza sul lavoro»? Rispondi in due o tre frasi.","a":"L'omicidio colposo (art. 589 c.p.) e le lesioni personali colpose (art. 590 c.p.) sono i delitti tipici dell'infortunio sul lavoro: la violazione delle norme per la prevenzione degli infortuni è una circostanza aggravante, e la colpa del datore è di regola colpa specifica.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-PPP-27~1","s":"S22-PPP-27","q":"Che effetto ha la violazione delle norme antinfortunistiche sull'omicidio colposo?","a":"È un'aggravante: la reclusione va da due a sette anni invece che da sei mesi a cinque anni; e la colpa è di regola specifica.","v":{"p":null,"e":[["2","n",["2"]],["7","n",["7"]],["6","n",["6"]],["5","n",["5"]],["aggravante","k",["aggrava"]],["reclusione","k",["reclusi"]],["anni","k",["ann"]],["mesi","k",["mes"]],["colpa","k",["colpa"]],["regola","k",["regol"]],["specifica","k",["specif"]]],"r":[]}},{"id":"S22-PPP-27~2","s":"S22-PPP-27","q":"Perché il datore risponde anche per omissione?","a":"Perché ha l'obbligo giuridico di impedire l'evento.","v":{"p":null,"e":[["obbligo","k",["obbli","obblig"]],["giuridico","k",["giurid"]],["impedire","k",["imped"]],["evento","k",["event"]]],"r":[]}},{"id":"S22-PPP-27~3","s":"S22-PPP-27","q":"Che rapporto c'è tra infortunio e responsabilità della società?","a":"Omicidio e lesioni gravi da violazione delle norme di sicurezza sono reati presupposto della responsabilità dell'ente, salvo modello organizzativo efficace.","v":{"p":null,"e":[["Omicidio","k",["omici"]],["lesioni","k",["lesio"]],["gravi","k",["gravi"]],["violazione","k",["violazi"]],["norme","k",["norme"]],["sicurezza","k",["sicure"]],["reati","k",["reati"]],["presupposto","k",["presuppo"]],["ente","k",["ent"]],["modello","k",["model"]],["organizzativo","k",["organizz"]],["efficace","k",["effic"]]],"r":[]}},{"id":"S22-PPP-28~0","s":"S22-PPP-28","q":"Qual è il cuore di «La responsabilità penale del datore per l'omesso versamento delle ritenute previdenziali e assistenziali»? Rispondi in due o tre frasi.","a":"Il datore che trattiene le ritenute previdenziali e assistenziali dalla retribuzione del lavoratore e non le versa all'INPS commette il reato dell'art. 2, c. 1-bis, D.L. 463/1983, ma solo se l'importo omesso supera 10.000 euro l'anno; sotto questa soglia è un illecito amministrativo (D.Lgs. 8/2016).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-PPP-28~1","s":"S22-PPP-28","q":"Quando l'omesso versamento delle ritenute previdenziali è reato?","a":"Solo sopra 10.000 euro l'anno; sotto è illecito amministrativo.","v":{"p":null,"e":[["10.000","n",["10000"]],["sopra","k",["sopra"]],["euro","k",["eur"]],["anno","k",["ann"]],["sotto","k",["sotto"]],["illecito","k",["illec"]],["amministrativo","k",["amminist"]]],"r":[]}},{"id":"S22-PPP-28~2","s":"S22-PPP-28","q":"Come evita pena e sanzione il datore?","a":"Versando le ritenute entro tre mesi dalla contestazione o dalla notifica dell'accertamento.","v":{"p":null,"e":[["3","n",["3"]],["Versando","k",["versa"]],["ritenute","k",["riten"]],["mesi","k",["mes"]],["contestazione","k",["contesta"]],["notifica","k",["notif"]],["accertamento","k",["accertam"]]],"r":[]}},{"id":"S22-PPP-28~3","s":"S22-PPP-28","q":"L'omesso versamento della quota contributiva a carico del datore è reato?","a":"No: comporta sanzioni civili e recupero contributivo.","v":{"p":"n","e":[["comporta","k",["compo"]],["sanzioni","k",["sanzi","multa","ammend"]],["civili","k",["civil"]],["recupero","k",["recup"]]],"r":[]}},{"id":"S22-PPP-29~0","s":"S22-PPP-29","q":"Qual è il cuore di «L'oblazione nelle contravvenzioni»? Rispondi in due o tre frasi.","a":"L'oblazione è una causa di estinzione delle contravvenzioni: pagando una somma prima del dibattimento o del decreto di condanna, il contravventore fa estinguere il reato. Nel diritto penale del lavoro si affianca alla prescrizione obbligatoria del D.Lgs. 758/1994.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-PPP-29~1","s":"S22-PPP-29","q":"Differenza tra oblazione ordinaria e speciale?","a":"Ordinaria: contravvenzioni con sola ammenda, un terzo del massimo, è un diritto; speciale: arresto o ammenda alternativi, metà del massimo, il giudice può negarla.","v":{"p":null,"e":[["contravvenzioni","k",["contravv"]],["sola","k",["sol"]],["ammenda","k",["ammen"]],["terzo","k",["terzo"]],["diritto","k",["dirit"]],["arresto","k",["arres"]],["alternativi","k",["alternat"]],["metà","k",["met"]],["giudice","k",["giudi","tribunal"]],["negarla","k",["negar"]]],"r":[]}},{"id":"S22-PPP-29~2","s":"S22-PPP-29","q":"Come funziona la prescrizione obbligatoria?","a":"L'organo di vigilanza impone la regolarizzazione entro un termine; verificato l'adempimento, si paga un quarto del massimo dell'ammenda e il reato si estingue.","v":{"p":null,"e":[["organo","k",["organ"]],["vigilanza","k",["vigila"]],["impone","k",["impon"]],["regolarizzazione","k",["regolari"]],["termine","k",["termi","scadenz"]],["verificato","k",["verific"]],["adempimento","k",["adempime"]],["paga","k",["pag"]],["quarto","k",["quart"]],["ammenda","k",["ammen"]],["reato","k",["reato"]],["estingue","k",["estin"]]],"r":[]}},{"id":"S22-PPP-29~3","s":"S22-PPP-29","q":"A quali contravvenzioni non si applica la prescrizione obbligatoria?","a":"A quelle punite con il solo arresto o con arresto e ammenda congiunti.","v":{"p":null,"e":[["punite","k",["punit"]],["arresto","k",["arres"]],["ammenda","k",["ammen"]],["congiunti","k",["congiu"]]],"r":[]}},{"id":"S22-PPP-30~0","s":"S22-PPP-30","q":"Qual è il cuore di «Le conseguenze civili del reato»? Rispondi in due o tre frasi.","a":"Un reato può essere anche illecito civile: l'art. 185 c.p. obbliga il colpevole alle restituzioni e al risarcimento del danno patrimoniale e non patrimoniale, insieme alle persone che per legge devono rispondere per lui.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-PPP-30~1","s":"S22-PPP-30","q":"Quali obblighi civili nascono dal reato?","a":"Restituzioni e risarcimento del danno patrimoniale e non patrimoniale.","v":{"p":null,"e":[["Restituzioni","k",["restituz"]],["risarcimento","k",["risarcim"]],["danno","k",["danno"]],["patrimoniale","k",["patrimon"]]],"r":[]}},{"id":"S22-PPP-30~2","s":"S22-PPP-30","q":"Chi è il responsabile civile?","a":"Chi deve rispondere del fatto altrui, come il datore per il fatto del dipendente; la persona offesa può costituirsi parte civile.","v":{"p":null,"e":[["rispondere","k",["rispond"]],["fatto","k",["fatto"]],["altrui","k",["altru"]],["datore","k",["dator","aziend","impres"]],["dipendente","k",["dipende","lavorat"]],["persona","k",["perso"]],["offesa","k",["offes"]],["costituirsi","k",["costitui"]]],"r":[]}},{"id":"TRIB-1~0","s":"TRIB-1","q":"Qual è il cuore di «Gli elementi costitutivi del reddito di lavoro dipendente»? Rispondi in due o tre frasi.","a":"Il reddito di lavoro dipendente nasce da un rapporto di lavoro alle dipendenze e sotto la direzione di altri (art. 49 TUIR) ed è formato da tutto ciò che il lavoratore percepisce nell'anno in relazione al rapporto (art. 51, c. 1).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"TRIB-1~1","s":"TRIB-1","q":"Da cosa è formato il reddito di lavoro dipendente?","a":"Da tutte le somme e i valori percepiti a qualunque titolo nell'anno in relazione al rapporto, anche come erogazioni liberali (onnicomprensività).","v":{"p":null,"e":[["somme","k",["somme"]],["valori","k",["valor"]],["percepiti","k",["percep"]],["qualunque","k",["qualun"]],["titolo","k",["titol"]],["anno","k",["ann"]],["relazione","k",["relazi"]],["rapporto","k",["rappo","contratt"]],["erogazioni","k",["erogazi"]],["liberali","k",["liber"]]],"r":[]}},{"id":"TRIB-1~2","s":"TRIB-1","q":"Cos'è il criterio di cassa allargata?","a":"Le somme pagate entro il 12 gennaio si considerano percepite nell'anno precedente.","v":{"p":null,"e":[["12","n",["12"]],["somme","k",["somme"]],["pagate","k",["pagat"]],["gennaio","k",["genna"]],["considerano","k",["consider"]],["percepite","k",["percep"]],["anno","k",["ann"]],["precedente","k",["precede"]]],"r":[]}},{"id":"TRIB-1~3","s":"TRIB-1","q":"Le indennità di malattia e la cassa integrazione che reddito sono?","a":"Redditi sostitutivi: della stessa categoria del reddito sostituito, cioè lavoro dipendente.","v":{"p":null,"e":[["sostitutivi","k",["sostitut"]],["categoria","k",["catego"]],["sostituito","k",["sostitu"]],["lavoro","k",["lavor","dipendent","prestator"]],["dipendente","k",["dipende","lavorat"]]],"r":[]}},{"id":"TRIB-2~0","s":"TRIB-2","q":"Qual è il cuore di «I soggetti che presentano il modello 730»? Rispondi in due o tre frasi.","a":"Il modello 730 è la dichiarazione semplificata dei lavoratori dipendenti, dei pensionati e di chi ha redditi assimilati: si presenta entro il 30 settembre al sostituto d'imposta, a un CAF o a un professionista abilitato, oppure direttamente in precompilata.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"TRIB-2~1","s":"TRIB-2","q":"Chi può presentare il modello 730?","a":"Dipendenti, pensionati e titolari di redditi assimilati (anche collaboratori), pure con alcuni altri redditi; non chi ha redditi d'impresa o di lavoro autonomo professionale.","v":{"p":null,"e":[["Dipendenti","k",["dipende","lavorat"]],["pensionati","k",["pension"]],["titolari","k",["titol"]],["redditi","k",["reddi"]],["assimilati","k",["assimil"]],["pure","k",["pur"]],["alcuni","k",["alcun"]],["impresa","k",["impre","non si prescrive","non si prescrivono"]],["lavoro","k",["lavor","dipendent","prestator"]],["autonomo","k",["auton"]],["professionale","k",["professi"]]],"r":[]}},{"id":"TRIB-2~2","s":"TRIB-2","q":"Entro quando e a chi si presenta il 730?","a":"Entro il 30 settembre, al sostituto d'imposta, a un CAF, a un professionista abilitato o direttamente in precompilata.","v":{"p":null,"e":[["30","n",["30"]],["settembre","k",["settem"]],["sostituto","k",["sostit"]],["imposta","k",["impos"]],["CAF","k",["caf"]],["professionista","k",["professi"]],["abilitato","k",["abilit"]],["direttamente","k",["direttam"]],["precompilata","k",["precompi"]]],"r":[]}},{"id":"TRIB-2~3","s":"TRIB-2","q":"Quando il sostituto esegue il conguaglio da 730?","a":"Dal mese successivo al ricevimento del 730-4.","v":{"p":null,"e":[["730","n",["730"]],["4","n",["4"]],["mese","k",["mes"]],["successivo","k",["success"]],["ricevimento","k",["ricevime"]]],"r":[]}},{"id":"TRIB-3~0","s":"TRIB-3","q":"Qual è il cuore di «Gli oneri detraibili e deducibili»? Rispondi in due o tre frasi.","a":"Gli oneri deducibili riducono il reddito complessivo prima del calcolo dell'IRPEF (art. 10 TUIR); gli oneri detraibili riducono l'imposta lorda, di regola del 19% della spesa (art. 15 TUIR).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"TRIB-3~1","s":"TRIB-3","q":"Differenza tra oneri deducibili e detraibili?","a":"I deducibili riducono il reddito prima dell'IRPEF; i detraibili riducono l'imposta lorda, di regola del 19% della spesa.","v":{"p":null,"e":[["19%","m",["19"]],["riducono","k",["riduc"]],["reddito","k",["reddi"]],["IRPEF","k",["irpef"]],["imposta","k",["impos"]],["lorda","k",["lorda"]],["regola","k",["regol"]],["spesa","k",["spesa"]]],"r":[]}},{"id":"TRIB-3~2","s":"TRIB-3","q":"Per chi vale di più una deduzione rispetto a una detrazione?","a":"Per chi ha l'aliquota marginale più alta; la detrazione vale la stessa percentuale per tutti.","v":{"p":null,"e":[["aliquota","k",["aliqu"]],["marginale","k",["margin"]],["alta","k",["alt"]],["percentuale","k",["percentu"]]],"r":[]}},{"id":"TRIB-3~3","s":"TRIB-3","q":"Quando spetta la detrazione del 19% per le spese?","a":"Solo con pagamenti tracciabili, salvo medicinali, dispositivi medici e prestazioni di strutture pubbliche o accreditate.","v":{"p":null,"e":[["pagamenti","k",["pagame"]],["tracciabili","k",["tracciab"]],["medicinali","k",["medicin"]],["dispositivi","k",["disposit"]],["medici","k",["medic"]],["prestazioni","k",["prestazi"]],["strutture","k",["strutt"]],["pubbliche","k",["pubbli"]],["accreditate","k",["accredit"]]],"r":[]}},{"id":"TRIB-4~0","s":"TRIB-4","q":"Qual è il cuore di «Le detrazioni per familiari a carico e il limite di reddito»? Rispondi in due o tre frasi.","a":"Le detrazioni per carichi di famiglia (art. 12 TUIR) spettano per il coniuge, per i figli dai 21 ai 29 anni (o disabili dai 30) e per gli ascendenti conviventi, se il familiare ha un reddito non superiore a 2.840,51 euro (4.000 per i figli fino a 24 anni).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"TRIB-4~1","s":"TRIB-4","q":"Per quali familiari spettano le detrazioni dell'art. 12 TUIR?","a":"Coniuge, figli dai 21 ai 29 anni (o disabili dai 30) e ascendenti conviventi; per i figli più piccoli c'è l'assegno unico.","v":{"p":null,"e":[["21","n",["21"]],["29","n",["29"]],["Coniuge","k",["coniu"]],["figli","k",["figli"]],["anni","k",["ann"]],["ascendenti","k",["ascende"]],["conviventi","k",["convive"]],["piccoli","k",["picco"]],["assegno","k",["asseg"]],["unico","k",["unico"]]],"r":[]}},{"id":"TRIB-4~2","s":"TRIB-4","q":"Quale reddito non deve superare il familiare per essere a carico?","a":"2.840,51 euro lordi; 4.000 euro per i figli fino a 24 anni.","v":{"p":null,"e":[["2.840,51","n",["2840.51"]],["4.000","m",["4000"]],["24","m",["24"]],["euro","k",["eur"]],["lordi","k",["lordi"]],["figli","k",["figli"]],["anni","k",["ann"]]],"r":[]}},{"id":"TRIB-4~3","s":"TRIB-4","q":"Come si ripartisce la detrazione per i figli tra i genitori?","a":"Al 50%, salvo accordo diverso.","v":{"p":null,"e":[["50%","n",["50"]],["accordo","k",["accor"]],["diverso","k",["diver"]]],"r":[]}},{"id":"TRIB-6~0","s":"TRIB-6","q":"Qual è il cuore di «La base imponibile del lavoratore dipendente»? Rispondi in due o tre frasi.","a":"La base imponibile del lavoratore dipendente è il reddito determinato con l'art. 51 TUIR, al netto dei contributi previdenziali a suo carico e degli oneri deducibili riconosciuti dal sostituto; su di essa si applica l'IRPEF a scaglioni.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"TRIB-6~1","s":"TRIB-6","q":"Come si arriva alla base imponibile IRPEF del dipendente?","a":"Retribuzione imponibile dell'art. 51, meno contributi previdenziali a suo carico, voci escluse o esenti e oneri deducibili riconosciuti dal sostituto.","v":{"p":null,"e":[["art. 51","n",["51"]],["Retribuzione","k",["retribuz","stipend","paga","salari"]],["contributi","k",["contrib","contribuz","contribut"]],["previdenziali","k",["previden"]],["carico","k",["caric"]],["voci","k",["voc"]],["escluse","k",["esclu"]],["esenti","k",["esent"]],["oneri","k",["oneri"]],["deducibili","k",["deducib"]],["riconosciuti","k",["riconosc"]],["sostituto","k",["sostit"]]],"r":[]}},{"id":"TRIB-6~2","s":"TRIB-6","q":"Quali sono gli scaglioni IRPEF 2026?","a":"23% fino a 28.000 euro, 33% fino a 50.000, 43% oltre.","v":{"p":null,"e":[["23%","n",["23"]],["28.000","n",["28000"]],["33%","n",["33"]],["50.000","n",["50000"]],["43%","n",["43"]],["euro","k",["eur"]]],"r":[]}},{"id":"TRIB-6~3","s":"TRIB-6","q":"Quali redditi del dipendente restano fuori dall'IRPEF ordinaria?","a":"Quelli a tassazione separata (TFR, arretrati) e quelli a imposta sostitutiva.","v":{"p":null,"e":[["tassazione","k",["tassazi"]],["separata","k",["separ"]],["imposta","k",["impos"]],["sostitutiva","k",["sostitut"]]],"r":[]}},{"id":"TRIB-7~0","s":"TRIB-7","q":"Qual è il cuore di «La trasferta e la sua tassazione»? Rispondi in due o tre frasi.","a":"La trasferta è lo spostamento temporaneo del dipendente fuori dalla sede di lavoro: le indennità e i rimborsi hanno un regime fiscale di favore fuori dal comune, mentre nel comune sono imponibili salvo i rimborsi di trasporto documentati (art. 51, c. 5, TUIR).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"TRIB-7~1","s":"TRIB-7","q":"Che regime fiscale ha la trasferta nel comune e fuori comune?","a":"Fuori comune regime di favore per indennità e rimborsi; nel comune tutto imponibile salvo i rimborsi di trasporto documentati.","v":{"p":null,"e":[["favore","k",["favor"]],["indennità","k",["indenn"]],["rimborsi","k",["rimbo"]],["imponibile","k",["imponib"]],["trasporto","k",["traspo"]],["documentati","k",["document"]]],"r":[]}},{"id":"TRIB-7~2","s":"TRIB-7","q":"Fino a quanto è esente l'indennità forfettaria di trasferta?","a":"46,48 euro al giorno in Italia, 77,47 all'estero; si riduce di un terzo se è rimborsato vitto o alloggio, di due terzi se entrambi.","v":{"p":null,"e":[["46,48","n",["46.48"]],["77,47","n",["77.47"]],["2","m",["2"]],["euro","k",["eur"]],["giorno","k",["giorn","gg"]],["Italia","k",["itali"]],["estero","k",["ester"]],["riduce","k",["riduc"]],["terzo","k",["terzo"]],["rimborsato","k",["rimbors"]],["vitto","k",["vitto"]],["alloggio","k",["allog"]],["terzi","k",["terzi"]],["entrambi","k",["entra"]]],"r":[]}},{"id":"TRIB-7~3","s":"TRIB-7","q":"Il rimborso a piè di lista è reddito?","a":"No, se documentato; dal 2025 vitto, alloggio, viaggio e taxi in Italia solo se pagati con mezzi tracciabili.","v":{"p":"n","e":[["2025","m",["2025"]],["documentato","k",["document"]],["vitto","k",["vitto"]],["alloggio","k",["allog"]],["viaggio","k",["viagg"]],["taxi","k",["tax"]],["Italia","k",["itali"]],["pagati","k",["pagat"]],["mezzi","k",["mezzi"]],["tracciabili","k",["tracciab"]]],"r":[]}},{"id":"TRIB-10~0","s":"TRIB-10","q":"Qual è il cuore di «Le detrazioni per lavoro dipendente»? Rispondi in due o tre frasi.","a":"La detrazione per lavoro dipendente (art. 13 TUIR) riduce l'imposta lorda in misura decrescente al crescere del reddito complessivo e si rapporta ai giorni di lavoro dell'anno; si affiancano l'ulteriore detrazione del cuneo e il trattamento integrativo.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"TRIB-10~1","s":"TRIB-10","q":"Come funziona la detrazione per lavoro dipendente?","a":"Riduce l'imposta lorda, decresce al crescere del reddito, si azzera oltre 50.000 euro e si rapporta ai giorni di lavoro.","v":{"p":null,"e":[["50.000","n",["50000"]],["Riduce","k",["riduc"]],["imposta","k",["impos"]],["lorda","k",["lorda"]],["decresce","k",["decre"]],["crescere","k",["cresc"]],["reddito","k",["reddi"]],["azzera","k",["azzer"]],["euro","k",["eur"]],["rapporta","k",["rappo","contratt"]],["giorni","k",["giorn","gg"]]],"r":[]}},{"id":"TRIB-10~2","s":"TRIB-10","q":"Quanto vale la detrazione per redditi fino a 15.000 euro?","a":"1.955 euro, con un minimo di 690 (1.380 per i contratti a termine).","v":{"p":null,"e":[["1.955","n",["1955"]],["690","n",["690"]]],"r":[]}},{"id":"TRIB-10~3","s":"TRIB-10","q":"Cos'è il trattamento integrativo?","a":"Una somma fino a 1.200 euro per redditi fino a 15.000 euro, se c'è capienza d'imposta.","v":{"p":null,"e":[["1.200","n",["1200"]],["15.000","n",["15000"]],["somma","k",["somma"]],["euro","k",["eur"]],["redditi","k",["reddi"]],["capienza","k",["capie"]],["imposta","k",["impos"]]],"r":[]}},{"id":"TRIB-11~0","s":"TRIB-11","q":"Qual è il cuore di «Il conguaglio fiscale»? Rispondi in due o tre frasi.","a":"Il conguaglio fiscale è il ricalcolo, da parte del sostituto, dell'imposta dovuta sull'intero reddito corrisposto nell'anno, confrontata con le ritenute già operate: si fa entro il 28 febbraio dell'anno successivo o alla cessazione del rapporto (art. 23, c. 3, D.P.R. 600/1973).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"TRIB-11~1","s":"TRIB-11","q":"Cos'è il conguaglio fiscale ed entro quando si fa?","a":"Il ricalcolo dell'imposta sull'intero reddito dell'anno, confrontata con le ritenute operate: entro il 28 febbraio o alla cessazione del rapporto.","v":{"p":null,"e":[["28","n",["28"]],["ricalcolo","k",["ricalc"]],["imposta","k",["impos"]],["intero","k",["inter"]],["reddito","k",["reddi"]],["anno","k",["ann"]],["confrontata","k",["confront"]],["ritenute","k",["riten"]],["operate","k",["opera"]],["febbraio","k",["febbr"]],["cessazione","k",["cessazi"]],["rapporto","k",["rappo","contratt"]]],"r":[]}},{"id":"TRIB-11~2","s":"TRIB-11","q":"Il sostituto può tenere conto di redditi di altri rapporti?","a":"Sì, se il lavoratore lo chiede consegnando la CU entro il 12 gennaio.","v":{"p":"s","e":[["12","n",["12"]],["lavoratore","k",["lavorat","dipendent","prestator"]],["chiede","k",["chied"]],["consegnando","k",["consegna"]],["CU","k",["cu"]],["gennaio","k",["genna"]]],"r":[]}},{"id":"TRIB-11~3","s":"TRIB-11","q":"Come si recuperano le addizionali dopo il conguaglio?","a":"Regionale e saldo comunale in massimo 11 rate dell'anno dopo; acconto comunale del 30% in massimo 9 rate da marzo.","v":{"p":null,"e":[["11","n",["11"]],["30%","m",["30"]],["9","m",["9"]],["Regionale","k",["region"]],["saldo","k",["saldo"]],["rate","k",["rat"]],["anno","k",["ann"]],["acconto","k",["accon"]],["marzo","k",["marzo"]]],"r":[]}},{"id":"TRIB-11~4","s":"TRIB-11","q":"Cosa accade se le retribuzioni non bastano per le trattenute (incapienza)?","a":"Il lavoratore versa la differenza o autorizza il prelievo sulle retribuzioni successive con interesse dello 0,50% mensile.","v":{"p":null,"e":[["0,50%","n",["0.50"]],["lavoratore","k",["lavorat","dipendent","prestator"]],["versa","k",["versa"]],["differenza","k",["differe"]],["autorizza","k",["autori"]],["prelievo","k",["preli"]],["successive","k",["success"]],["interesse","k",["intere"]],["mensile","k",["mensi"]]],"r":[]}},{"id":"TRIB-12~0","s":"TRIB-12","q":"Qual è il cuore di «I redditi assimilati a quelli di lavoro dipendente»? Rispondi in due o tre frasi.","a":"I redditi assimilati a quelli di lavoro dipendente (art. 50 TUIR) nascono da rapporti diversi dalla subordinazione ma sono tassati con le stesse regole: ritenuta del sostituto, detrazioni, conguaglio.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"TRIB-12~1","s":"TRIB-12","q":"Cosa sono i redditi assimilati a quelli di lavoro dipendente?","a":"Redditi da rapporti diversi dalla subordinazione tassati con le stesse regole: ritenuta del sostituto, detrazioni, conguaglio.","v":{"p":null,"e":[["rapporti","k",["rappo","contratt"]],["diversi","k",["diver"]],["subordinazione","k",["subordin"]],["tassati","k",["tassa"]],["stesse","k",["stess"]],["regole","k",["regol"]],["ritenuta","k",["riten"]],["sostituto","k",["sostit"]],["detrazioni","k",["detrazi"]],["conguaglio","k",["conguag"]]],"r":[]}},{"id":"TRIB-12~2","s":"TRIB-12","q":"Il compenso dell'amministratore di società che reddito è?","a":"Assimilato al lavoro dipendente, salvo che rientri nell'attività professionale del contribuente.","v":{"p":null,"e":[["Assimilato","k",["assimil"]],["lavoro","k",["lavor","dipendent","prestator"]],["dipendente","k",["dipende","lavorat"]],["rientri","k",["rient"]],["attività","k",["attiv"]],["professionale","k",["professi"]],["contribuente","k",["contribu","contribuz","contribut"]]],"r":[]}},{"id":"TRIB-12~3","s":"TRIB-12","q":"Quali altri redditi sono assimilati?","a":"Co.co.co., compensi dei soci di cooperative, borse di studio, cariche pubbliche elettive, prestazioni di previdenza complementare.","v":{"p":null,"e":[["Co.co","k",["coc"]],["compensi","k",["compe"]],["soci","k",["soc"]],["cooperative","k",["cooperat"]],["borse","k",["borse"]],["studio","k",["studi"]],["cariche","k",["caric"]],["pubbliche","k",["pubbli"]],["elettive","k",["elett"]],["prestazioni","k",["prestazi"]],["previdenza","k",["previde"]],["complementare","k",["compleme"]]],"r":[]}},{"id":"TRIB-15~0","s":"TRIB-15","q":"Qual è il cuore di «Il modello 770»? Rispondi in due o tre frasi.","a":"Il modello 770 è la dichiarazione annuale dei sostituti d'imposta: riepiloga ritenute operate, versamenti, compensazioni e dati non già trasmessi con la Certificazione Unica; si presenta per via telematica entro il 31 ottobre (art. 4 D.P.R. 322/1998).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"TRIB-15~1","s":"TRIB-15","q":"Cos'è il modello 770 ed entro quando si presenta?","a":"La dichiarazione annuale dei sostituti d'imposta su ritenute, versamenti e compensazioni: entro il 31 ottobre.","v":{"p":null,"e":[["31","n",["31"]],["dichiarazione","k",["dichiara"]],["annuale","k",["annua"]],["sostituti","k",["sostit"]],["imposta","k",["impos"]],["ritenute","k",["riten"]],["versamenti","k",["versame"]],["compensazioni","k",["compensa"]],["ottobre","k",["ottob"]]],"r":[]}},{"id":"TRIB-15~2","s":"TRIB-15","q":"A cosa serve il 770 per l'Amministrazione?","a":"Al controllo incrociato tra ritenute certificate, ritenute dichiarate e versamenti.","v":{"p":null,"e":[["controllo","k",["contro"]],["incrociato","k",["incroci"]],["ritenute","k",["riten"]],["certificate","k",["certific"]],["dichiarate","k",["dichiar"]],["versamenti","k",["versame"]]],"r":[]}},{"id":"TRIB-15~3","s":"TRIB-15","q":"Quando l'omesso versamento di ritenute certificate diventa reato?","a":"Oltre 150.000 euro per periodo d'imposta, se non versate entro il 31 dicembre dell'anno successivo.","v":{"p":null,"e":[["150.000","n",["150000"]],["31","n",["31"]],["euro","k",["eur"]],["periodo","k",["perio"]],["imposta","k",["impos"]],["dicembre","k",["dicem"]],["anno","k",["ann"]],["successivo","k",["success"]]],"r":[]}},{"id":"S22-TRIB-6~0","s":"S22-TRIB-6","q":"Qual è il cuore di «Le addizionali regionale e comunale all'IRPEF: base imponibile e versamento»? Rispondi in due o tre frasi.","a":"Le addizionali regionale e comunale all'IRPEF sono tributi propri derivati che si applicano sulla stessa base dell'IRPEF: regionale art. 50 D.Lgs. 446/1997 (aliquote art. 6 D.Lgs. 68/2011), comunale art. 1 D.Lgs. 360/1998. Sono dovute solo se per lo stesso anno è dovuta l'IRPEF, cioè se l'imposta netta è positiva.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-TRIB-6~1","s":"S22-TRIB-6","q":"Quando sono dovute le addizionali regionale e comunale?","a":"Solo se per lo stesso anno è dovuta l'IRPEF, cioè con imposta netta positiva.","v":{"p":null,"e":[["anno","k",["ann"]],["IRPEF","k",["irpef"]],["imposta","k",["impos"]],["netta","k",["netta"]],["positiva","k",["posit"]]],"r":[]}},{"id":"S22-TRIB-6~2","s":"S22-TRIB-6","q":"Quale Regione e quale Comune contano per le addizionali?","a":"Quelli del domicilio fiscale al 1° gennaio dell'anno di riferimento.","v":{"p":null,"e":[["1","n",["1"]],["domicilio","k",["domici"]],["fiscale","k",["fisca"]],["gennaio","k",["genna"]],["anno","k",["ann"]],["riferimento","k",["riferime"]]],"r":[]}},{"id":"S22-TRIB-13~0","s":"S22-TRIB-13","q":"Qual è il cuore di «La tassazione separata dei redditi di lavoro dipendente diversi dal TFR»? Rispondi in due o tre frasi.","a":"Alcuni redditi di lavoro dipendente maturati in più anni o legati alla cessazione del rapporto non si sommano al reddito dell'anno in cui sono pagati ma si tassano separatamente (art. 17 TUIR), con un'aliquota media che evita l'effetto della progressività. Oltre al TFR (TRIB-14), riguarda soprattutto gli arretrati e le altre indennità di fine rapporto.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-TRIB-13~1","s":"S22-TRIB-13","q":"Perché alcuni redditi sono a tassazione separata?","a":"Perché maturati in più anni: un'aliquota media evita l'effetto della progressività.","v":{"p":null,"e":[["maturati","k",["matur"]],["anni","k",["ann"]],["aliquota","k",["aliqu"]],["media","k",["media"]],["evita","k",["evita"]],["effetto","k",["effet"]],["progressività","k",["progress"]]],"r":[]}},{"id":"S22-TRIB-13~2","s":"S22-TRIB-13","q":"Quali redditi di lavoro dipendente vanno a tassazione separata oltre al TFR?","a":"Arretrati di anni precedenti e altre indennità di cessazione (preavviso, non concorrenza, incentivi all'esodo).","v":{"p":null,"e":[["Arretrati","k",["arretr"]],["anni","k",["ann"]],["precedenti","k",["precede"]],["indennità","k",["indenn"]],["cessazione","k",["cessazi"]]],"r":[]}},{"id":"S22-TRIB-13~3","s":"S22-TRIB-13","q":"Con quale aliquota si tassano gli arretrati?","a":"Quella corrispondente alla metà del reddito complessivo netto del biennio precedente.","v":{"p":null,"e":[["corrispondente","k",["corrispo"]],["metà","k",["met"]],["reddito","k",["reddi"]],["complessivo","k",["compless"]],["netto","k",["netto"]],["biennio","k",["bienn"]],["precedente","k",["precede"]]],"r":[]}},{"id":"S22-TRIB-14~0","s":"S22-TRIB-14","q":"Qual è il cuore di «Il trattamento di fine rapporto: natura, formazione e tassazione»? Rispondi in due o tre frasi.","a":"Il trattamento di fine rapporto è una retribuzione differita che il lavoratore subordinato riceve alla cessazione del rapporto (art. 2120 c.c.). Si forma anno per anno accantonando una quota della retribuzione, che si rivaluta; fiscalmente è a tassazione separata con aliquota media (artt. 17 e 19 TUIR).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-TRIB-14~1","s":"S22-TRIB-14","q":"Come si forma il TFR ogni anno?","a":"Retribuzione annua utile divisa per 13,5, meno lo 0,50%; rivalutazione dell'1,5% più il 75% dell'aumento ISTAT.","v":{"p":null,"e":[["13,5","n",["13.5"]],["0,50%","n",["0.50"]],["1,5%","m",["1.5"]],["75%","m",["75"]],["Retribuzione","k",["retribuz","stipend","paga","salari"]],["utile","k",["utile"]],["divisa","k",["divis"]],["rivalutazione","k",["rivaluta"]],["aumento","k",["aumen"]],["ISTAT","k",["istat"]]],"r":[]}},{"id":"S22-TRIB-14~2","s":"S22-TRIB-14","q":"Quando si può chiedere l'anticipazione del TFR?","a":"Dopo 8 anni di servizio, fino al 70% del maturato, per spese sanitarie straordinarie, prima casa, congedi.","v":{"p":null,"e":[["8","n",["8"]],["70%","n",["70"]],["anni","k",["ann"]],["servizio","k",["servi"]],["maturato","k",["matur"]],["spese","k",["spese"]],["sanitarie","k",["sanita"]],["straordinarie","k",["straordi"]],["casa","k",["cas"]],["congedi","k",["conge"]]],"r":[]}},{"id":"S22-TRIB-14~3","s":"S22-TRIB-14","q":"Come si tassa il TFR?","a":"Tassazione separata con l'aliquota del reddito di riferimento; poi l'Agenzia riliquida con l'aliquota media dei 5 anni precedenti; sostitutiva del 17% sulle rivalutazioni.","v":{"p":null,"e":[["5","m",["5"]],["17%","m",["17"]],["separata","k",["separ"]],["aliquota","k",["aliqu"]],["reddito","k",["reddi"]],["riferimento","k",["riferime"]],["Agenzia","k",["agenz"]],["riliquida","k",["riliqu"]],["media","k",["media"]],["anni","k",["ann"]],["precedenti","k",["precede"]],["sostitutiva","k",["sostitut"]],["rivalutazioni","k",["rivaluta"]]],"r":[]}},{"id":"S22-TRIB-17~0","s":"S22-TRIB-17","q":"Qual è il cuore di «I fringe benefit: valore convenzionale e tassazione»? Rispondi in due o tre frasi.","a":"I fringe benefit sono i compensi in natura: beni e servizi che il datore dà al dipendente o ai suoi familiari (art. 51, c. 3, TUIR). Concorrono al reddito al valore normale, salvo i valori convenzionali previsti per auto, prestiti e fabbricati (c. 4). Sono esenti sotto una soglia annua, che per il 2025-2027 è aumentata.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-TRIB-17~1","s":"S22-TRIB-17","q":"Cosa sono i fringe benefit e come si valutano?","a":"Compensi in natura: concorrono al valore normale, salvo i valori convenzionali per auto, prestiti e fabbricati.","v":{"p":null,"e":[["natura","k",["natur"]],["concorrono","k",["concorr"]],["valore","k",["valor"]],["normale","k",["norma"]],["convenzionali","k",["convenzi"]],["auto","k",["aut"]],["prestiti","k",["prest"]],["fabbricati","k",["fabbric"]]],"r":[]}},{"id":"S22-TRIB-17~2","s":"S22-TRIB-17","q":"Qual è la soglia di esenzione 2025-2027 e cosa accade se si supera?","a":"1.000 euro, 2.000 con figli a carico; se si supera è tassato tutto il valore, non solo l'eccedenza.","v":{"p":null,"e":[["1.000","n",["1000"]],["2.000","n",["2000"]],["euro","k",["eur"]],["figli","k",["figli"]],["carico","k",["caric"]],["tassato","k",["tassa"]],["valore","k",["valor"]],["eccedenza","k",["eccede"]]],"r":[]}},{"id":"S22-TRIB-17~3","s":"S22-TRIB-17","q":"Come si tassa l'auto aziendale a uso promiscuo?","a":"Sul 50% del costo chilometrico ACI per 15.000 km, ridotto per le auto elettriche e ibride plug-in, al netto di quanto trattenuto.","v":{"p":null,"e":[["50%","n",["50"]],["15.000","n",["15000"]],["costo","k",["costo"]],["chilometrico","k",["chilomet"]],["ACI","k",["aci"]],["ridotto","k",["ridot"]],["elettriche","k",["elettri"]],["ibride","k",["ibrid"]],["plug","k",["plug"]],["netto","k",["netto"]],["trattenuto","k",["tratten"]]],"r":[]},"t":"d"},{"id":"S22-TRIB-18~0","s":"S22-TRIB-18","q":"Qual è il cuore di «Il regime fiscale di vitto, mensa, prestazioni e indennità sostitutive»? Rispondi in due o tre frasi.","a":"Il vitto fornito dal datore è un caso particolare di compenso in natura: l'art. 51, c. 2, lett. c), TUIR lo esclude dal reddito di lavoro dipendente se è somministrato direttamente o in mensa, e fino a importi giornalieri fissi se è sostitutivo (buoni pasto e indennità). Fuori da queste ipotesi, l'indennità di mensa in denaro è reddito.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-TRIB-18~1","s":"S22-TRIB-18","q":"La mensa aziendale è reddito per il dipendente?","a":"No: vitto somministrato e pasti in mensa sono esclusi senza limiti.","v":{"p":"n","e":[["vitto","k",["vitto"]],["somministrato","k",["somminis"]],["pasti","k",["pasti"]],["esclusi","k",["esclu"]],["limiti","k",["limit"]]],"r":[]}},{"id":"S22-TRIB-18~2","s":"S22-TRIB-18","q":"Fino a quanto sono esenti i buoni pasto?","a":"4 euro al giorno se cartacei, 10 euro se elettronici dal 2026.","v":{"p":null,"e":[["4","n",["4"]],["10","n",["10"]],["2026","n",["2026"]],["euro","k",["eur"]],["giorno","k",["giorn","gg"]],["cartacei","k",["carta"]],["elettronici","k",["elettron"]]],"r":[]}},{"id":"S22-TRIB-18~3","s":"S22-TRIB-18","q":"L'indennità di mensa in denaro è imponibile?","a":"Sì, salvo 5,29 euro al giorno per cantieri, strutture temporanee o zone senza servizi di ristorazione.","v":{"p":"s","e":[["5,29","n",["5.29"]],["euro","k",["eur"]],["giorno","k",["giorn","gg"]],["cantieri","k",["canti"]],["strutture","k",["strutt"]],["temporanee","k",["tempora"]],["zone","k",["zon"]],["servizi","k",["servi"]],["ristorazione","k",["ristoraz"]]],"r":[]}},{"id":"TRIB-9~0","s":"TRIB-9","q":"Qual è il cuore di «Il principio di competenza e il principio di cassa»? Rispondi in due o tre frasi.","a":"Con il principio di cassa un componente conta nell'anno in cui è incassato o pagato; con quello di competenza nell'anno in cui matura, a prescindere dal pagamento. Il TUIR usa la cassa per i redditi di lavoro e la competenza per il reddito d'impresa.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"TRIB-9~1","s":"TRIB-9","q":"Differenza tra principio di cassa e di competenza?","a":"Cassa: conta l'anno di incasso o pagamento; competenza: l'anno in cui il componente matura, a prescindere dal pagamento.","v":{"p":null,"e":[["conta","k",["conta"]],["anno","k",["ann"]],["incasso","k",["incas"]],["pagamento","k",["pagame"]],["componente","k",["compone"]],["matura","k",["matur"]],["prescindere","k",["prescind"]]],"r":[]}},{"id":"TRIB-9~2","s":"TRIB-9","q":"Quale principio vale per lavoro dipendente, autonomo e impresa?","a":"Cassa (allargata per il dipendente) per i redditi di lavoro; competenza per il reddito d'impresa.","v":{"p":null,"e":[["Cassa","k",["cassa","cig"]],["redditi","k",["reddi"]],["competenza","k",["compete"]]],"r":[]}},{"id":"TRIB-13~0","s":"TRIB-13","q":"Qual è il cuore di «Il regime forfettario: i soggetti»? Rispondi in due o tre frasi.","a":"Il regime forfettario (L. 190/2014, c. 54-89) è riservato alle persone fisiche che esercitano impresa, arti o professioni con ricavi o compensi non superiori a 85.000 euro e senza cause di esclusione: il reddito si determina con un coefficiente e paga un'imposta sostitutiva del 15% (5% per le nuove attività).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"TRIB-13~1","s":"TRIB-13","q":"Chi può accedere al regime forfettario?","a":"Persone fisiche con impresa, arti o professioni con ricavi o compensi fino a 85.000 euro e senza cause di esclusione.","v":{"p":null,"e":[["85.000","n",["85000"]],["Persone","k",["perso"]],["fisiche","k",["fisic"]],["impresa","k",["impre","non si prescrive","non si prescrivono"]],["arti","k",["art"]],["professioni","k",["professi"]],["ricavi","k",["ricav"]],["compensi","k",["compe"]],["euro","k",["eur"]],["cause","k",["cause"]],["esclusione","k",["esclusi"]]],"r":[]}},{"id":"TRIB-13~2","s":"TRIB-13","q":"Come si determina e si tassa il reddito nel forfettario?","a":"Ricavi incassati per il coefficiente di redditività, meno i contributi; imposta sostitutiva del 15% (5% per i primi cinque anni di attività nuova).","v":{"p":null,"e":[["15%","m",["15"]],["Ricavi","k",["ricav"]],["incassati","k",["incass"]],["coefficiente","k",["coeffici"]],["contributi","k",["contrib","contribuz","contribut"]],["imposta","k",["impos"]],["sostitutiva","k",["sostitut"]]],"r":[]}},{"id":"TRIB-13~3","s":"TRIB-13","q":"Quando si esce dal forfettario?","a":"Dall'anno dopo se si superano 85.000 euro; nello stesso anno se si superano 100.000.","v":{"p":null,"e":[["85.000","n",["85000"]],["100.000","m",["100000"]],["anno","k",["ann"]],["superano","k",["super"]],["euro","k",["eur"]]],"r":[]}},{"id":"TRIB-13~4","s":"TRIB-13","q":"Il forfettario applica IVA e subisce ritenuta?","a":"No: niente IVA in fattura, niente ritenuta d'acconto, esonero dall'IRAP.","v":{"p":"n","e":[["niente","k",["nient"]],["IVA","k",["iva"]],["fattura","k",["fattu"]],["acconto","k",["accon"]],["esonero","k",["esone","sgrav","agevol","riduz"]],["IRAP","k",["irap"]]],"r":[]}},{"id":"TRIB-14~0","s":"TRIB-14","q":"Qual è il cuore di «La classificazione dei redditi»? Rispondi in due o tre frasi.","a":"Il TUIR classifica i redditi delle persone fisiche in sei categorie (art. 6): fondiari, di capitale, di lavoro dipendente, di lavoro autonomo, d'impresa e diversi; ogni categoria ha le proprie regole di determinazione e la somma forma il reddito complessivo.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"TRIB-14~1","s":"TRIB-14","q":"Quali sono le categorie di reddito del TUIR?","a":"Sei: fondiari, di capitale, di lavoro dipendente, di lavoro autonomo, d'impresa e diversi.","v":{"p":null,"e":[["6","n",["6"]],["fondiari","k",["fondi"]],["capitale","k",["capit"]],["lavoro","k",["lavor","dipendent","prestator"]],["dipendente","k",["dipende","lavorat"]],["autonomo","k",["auton"]],["impresa","k",["impre","non si prescrive","non si prescrivono"]],["diversi","k",["diver"]]],"r":[]}},{"id":"TRIB-14~2","s":"TRIB-14","q":"Che reddito producono s.n.c. e s.a.s.?","a":"Sempre reddito d'impresa.","v":{"p":null,"e":[["impresa","k",["impre","non si prescrive","non si prescrivono"]]],"r":[]}},{"id":"TRIB-14~3","s":"TRIB-14","q":"Cosa sono i redditi diversi?","a":"La categoria residuale: plusvalenze, attività commerciali o di lavoro autonomo occasionali e simili.","v":{"p":null,"e":[["categoria","k",["catego"]],["residuale","k",["residu"]],["plusvalenze","k",["plusvale"]],["attività","k",["attiv"]],["commerciali","k",["commerci"]],["lavoro","k",["lavor","dipendent","prestator"]],["autonomo","k",["auton"]],["occasionali","k",["occasion"]],["simili","k",["simil"]]],"r":[]}},{"id":"TRIB-16~0","s":"TRIB-16","q":"Qual è il cuore di «L'autotutela»? Rispondi in due o tre frasi.","a":"L'autotutela è il potere dell'Amministrazione finanziaria di annullare o rinunciare ai propri atti illegittimi o infondati; dal 2024 lo Statuto del contribuente distingue un'autotutela obbligatoria (art. 10-quater) e una facoltativa (art. 10-quinquies), introdotte dal D.Lgs. 219/2023.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"TRIB-16~1","s":"TRIB-16","q":"Cos'è l'autotutela tributaria e come è distinta dal 2024?","a":"Il potere di annullare o rinunciare agli atti illegittimi o infondati: obbligatoria per gli errori manifesti, facoltativa negli altri casi.","v":{"p":null,"e":[["potere","k",["poter"]],["annullare","k",["annull"]],["rinunciare","k",["rinunci"]],["atti","k",["att"]],["illegittimi","k",["illegitt"]],["infondati","k",["infond"]],["obbligatoria","k",["obbligat","obblig"]],["errori","k",["error"]],["manifesti","k",["manife"]],["facoltativa","k",["facoltat"]]],"r":[]}},{"id":"TRIB-16~2","s":"TRIB-16","q":"Quando non c'è obbligo di autotutela?","a":"Se c'è un giudicato favorevole all'Amministrazione o dopo un anno dalla definitività dell'atto non impugnato.","v":{"p":null,"e":[["giudicato","k",["giudic","tribunal"]],["favorevole","k",["favorev"]],["Amministrazione","k",["amminist"]],["anno","k",["ann"]],["definitività","k",["definiti"]],["atto","k",["att"]],["impugnato","k",["impugn"]]],"r":[]}},{"id":"TRIB-16~3","s":"TRIB-16","q":"Il rifiuto di autotutela è impugnabile?","a":"Sì: il rifiuto espresso o tacito sull'obbligatoria e il rifiuto espresso sulla facoltativa.","v":{"p":"s","e":[["espresso","k",["espre"]],["tacito","k",["tacit"]],["obbligatoria","k",["obbligat","obblig"]],["facoltativa","k",["facoltat"]]],"r":[]}},{"id":"TRIB-17~0","s":"TRIB-17","q":"Qual è il cuore di «L'interpello»? Rispondi in due o tre frasi.","a":"L'interpello è l'istanza con cui il contribuente chiede all'Amministrazione finanziaria una risposta preventiva su un caso concreto e personale (art. 11 Statuto del contribuente, L. 212/2000, riformulato dal D.Lgs. 219/2023).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"TRIB-17~1","s":"TRIB-17","q":"Cos'è l'interpello?","a":"L'istanza con cui il contribuente chiede all'Amministrazione una risposta preventiva su un caso concreto e personale.","v":{"p":null,"e":[["istanza","k",["istan"]],["contribuente","k",["contribu","contribuz","contribut"]],["chiede","k",["chied"]],["Amministrazione","k",["amminist"]],["risposta","k",["rispo"]],["preventiva","k",["prevent"]],["concreto","k",["concr"]],["personale","k",["person"]]],"r":[]}},{"id":"TRIB-17~2","s":"TRIB-17","q":"Entro quando risponde l'Amministrazione e se tace?","a":"Entro 90 giorni; se tace vale il silenzio-assenso sulla soluzione del contribuente.","v":{"p":null,"e":[["90","n",["90"]],["giorni","k",["giorn","gg"]],["vale","k",["val"]],["silenzio","k",["silen"]],["assenso","k",["assen"]],["soluzione","k",["soluzi"]],["contribuente","k",["contribu","contribuz","contribut"]]],"r":[]}},{"id":"TRIB-17~3","s":"TRIB-17","q":"La risposta all'interpello è impugnabile e chi vincola?","a":"Non è impugnabile; vincola l'Amministrazione solo per quella questione e quel richiedente.","v":{"p":null,"e":[["Amministrazione","k",["amminist"]],["questione","k",["questi"]],["quel","k",["quel"]],["richiedente","k",["richiede"]]],"r":[]}},{"id":"TRIB-18~0","s":"TRIB-18","q":"Qual è il cuore di «L'IRAP»? Rispondi in due o tre frasi.","a":"L'IRAP è l'imposta regionale sulle attività produttive (D.Lgs. 446/1997): colpisce il valore della produzione netta delle attività autonomamente organizzate di società, enti e amministrazioni pubbliche; dal 2022 non la pagano le persone fisiche.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"TRIB-18~1","s":"TRIB-18","q":"Cos'è l'IRAP e chi la paga?","a":"L'imposta regionale sul valore della produzione netta delle attività autonomamente organizzate di società, enti e PA; dal 2022 non la pagano le persone fisiche.","v":{"p":null,"e":[["2022","m",["2022"]],["imposta","k",["impos"]],["regionale","k",["region"]],["valore","k",["valor"]],["produzione","k",["produzi"]],["netta","k",["netta"]],["attività","k",["attiv"]],["autonomamente","k",["autonoma"]],["organizzate","k",["organizz"]],["società","k",["socie"]],["enti","k",["ent"]],["persone","k",["perso"]],["fisiche","k",["fisic"]]],"r":[]}},{"id":"TRIB-18~2","s":"TRIB-18","q":"Il costo del lavoro è deducibile ai fini IRAP?","a":"Sì, per intero quello dei dipendenti a tempo indeterminato; per i contratti a termine solo deduzioni specifiche.","v":{"p":"s","e":[["intero","k",["inter"]],["dipendenti","k",["dipende","lavorat"]],["tempo","k",["tempo"]],["indeterminato","k",["indeterm"]],["contratti","k",["contra","rapport"]],["termine","k",["termi","scadenz"]],["deduzioni","k",["deduzi"]],["specifiche","k",["specifi"]]],"r":[]}},{"id":"TRIB-18~3","s":"TRIB-18","q":"Qual è l'aliquota ordinaria IRAP?","a":"3,9%, variabile dalle Regioni.","v":{"p":null,"e":[["3,9%","n",["3.9"]],["variabile","k",["variab"]],["Regioni","k",["regio"]]],"r":[]}},{"id":"TRIB-19~0","s":"TRIB-19","q":"Qual è il cuore di «Tributi, imposte, tasse e contributi»? Rispondi in due o tre frasi.","a":"Il tributo è la prestazione patrimoniale imposta dallo Stato o da un ente pubblico per finanziare la spesa pubblica (artt. 23 e 53 Cost.); si distingue in imposte, tasse e contributi.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"TRIB-19~1","s":"TRIB-19","q":"Differenza tra imposta, tassa e contributo?","a":"Imposta: senza controprestazione; tassa: per un servizio pubblico speciale e divisibile richiesto; contributo: per un vantaggio particolare o una maggiore spesa provocata.","v":{"p":null,"e":[["controprestazione","k",["contropr"]],["servizio","k",["servi"]],["pubblico","k",["pubbl"]],["speciale","k",["speci"]],["divisibile","k",["divisib"]],["richiesto","k",["richie"]],["vantaggio","k",["vantag"]],["particolare","k",["particol"]],["maggiore","k",["maggi"]],["spesa","k",["spesa"]],["provocata","k",["provoc"]]],"r":[]}},{"id":"TRIB-19~2","s":"TRIB-19","q":"Quali principi costituzionali reggono il sistema tributario?","a":"Riserva di legge relativa (art. 23), capacità contributiva e progressività (art. 53), divieto di referendum sulle leggi tributarie.","v":{"p":null,"e":[["Riserva","k",["riser"]],["legge","k",["legge"]],["capacità","k",["capac"]],["contributiva","k",["contribu","contribuz","contribut"]],["progressività","k",["progress"]],["divieto","k",["divie","vietat","vieta"]],["referendum","k",["referen"]],["leggi","k",["leggi"]]],"r":[["art. 23",["23"]],["art. 53",["53"]]]}},{"id":"TRIB-22~0","s":"TRIB-22","q":"Qual è il cuore di «Il ravvedimento operoso»? Rispondi in due o tre frasi.","a":"Il ravvedimento operoso consente di regolarizzare spontaneamente una violazione tributaria pagando tributo, interessi e una sanzione ridotta (art. 13 D.Lgs. 472/1997).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"TRIB-22~1","s":"TRIB-22","q":"Cos'è il ravvedimento operoso?","a":"La regolarizzazione spontanea di una violazione pagando tributo, interessi e sanzione ridotta.","v":{"p":null,"e":[["regolarizzazione","k",["regolari"]],["spontanea","k",["sponta"]],["violazione","k",["violazi"]],["pagando","k",["pagan"]],["tributo","k",["tribu"]],["interessi","k",["intere"]],["sanzione","k",["sanzi","multa","ammend"]],["ridotta","k",["ridot"]]],"r":[]}},{"id":"TRIB-22~2","s":"TRIB-22","q":"Cosa preclude il ravvedimento?","a":"Per i tributi dell'Agenzia delle Entrate solo la notifica di atti di liquidazione o di accertamento.","v":{"p":null,"e":[["tributi","k",["tribu"]],["Agenzia","k",["agenz"]],["Entrate","k",["entra"]],["notifica","k",["notif"]],["atti","k",["att"]],["liquidazione","k",["liquidaz"]],["accertamento","k",["accertam"]]],"r":[]}},{"id":"TRIB-22~3","s":"TRIB-22","q":"Il ravvedimento impedisce i controlli?","a":"No: non impedisce l'inizio o la prosecuzione dei controlli.","v":{"p":"n","e":[["inizio","k",["inizi"]],["prosecuzione","k",["prosecuz"]]],"r":[]}},{"id":"TRIB-8~0","s":"TRIB-8","q":"Qual è il cuore di «La cedolare secca»? Rispondi in due o tre frasi.","a":"La cedolare secca è un regime facoltativo con cui il proprietario persona fisica tassa i canoni di locazione abitativa con un'imposta sostitutiva, al posto dell'IRPEF e delle addizionali (art. 3 D.Lgs. 23/2011).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"TRIB-8~1","s":"TRIB-8","q":"Cos'è la cedolare secca e quali aliquote ha?","a":"Un'imposta sostitutiva facoltativa sui canoni di locazione abitativa delle persone fisiche: 21%, 10% per il canone concordato.","v":{"p":null,"e":[["21%","n",["21"]],["10%","n",["10"]],["imposta","k",["impos"]],["sostitutiva","k",["sostitut"]],["facoltativa","k",["facoltat"]],["canoni","k",["canon"]],["locazione","k",["locazi"]],["abitativa","k",["abitat"]],["persone","k",["perso"]],["fisiche","k",["fisic"]],["concordato","k",["concord"]]],"r":[]}},{"id":"TRIB-8~2","s":"TRIB-8","q":"Cosa sostituisce la cedolare e a cosa rinuncia il locatore?","a":"Sostituisce IRPEF, addizionali, registro e bollo; il locatore rinuncia agli aggiornamenti del canone, anche ISTAT.","v":{"p":null,"e":[["IRPEF","k",["irpef"]],["addizionali","k",["addizion"]],["registro","k",["regis"]],["bollo","k",["bollo"]],["aggiornamenti","k",["aggiorna"]],["canone","k",["canon"]],["ISTAT","k",["istat"]]],"r":[]}},{"id":"TRIB-X2~0","s":"TRIB-X2","q":"Qual è il cuore di «L'imposta sul valore aggiunto: presupposti, detrazione e adempimenti»? Rispondi in due o tre frasi.","a":"L'IVA è un'imposta indiretta sui consumi, che colpisce il valore aggiunto in ogni fase della produzione e dello scambio: il soggetto passivo addebita l'imposta al cliente (rivalsa) e detrae quella pagata sugli acquisti, così che il peso grava sul consumatore finale (D.P.R. 633/1972).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"TRIB-X2~1","s":"TRIB-X2","q":"Come funziona il meccanismo dell'IVA?","a":"Il soggetto passivo addebita l'IVA al cliente (rivalsa) e detrae quella sugli acquisti: il peso grava sul consumatore finale.","v":{"p":null,"e":[["soggetto","k",["sogge"]],["passivo","k",["passi"]],["addebita","k",["addeb"]],["IVA","k",["iva"]],["cliente","k",["clien"]],["detrae","k",["detra"]],["acquisti","k",["acqui"]],["peso","k",["pes"]],["grava","k",["grava"]],["consumatore","k",["consumat"]],["finale","k",["final"]]],"r":[]}},{"id":"TRIB-X2~2","s":"TRIB-X2","q":"Quali sono i presupposti dell'IVA?","a":"Oggettivo (cessioni di beni e prestazioni di servizi), soggettivo (impresa, arti o professioni), territoriale (operazioni in Italia).","v":{"p":null,"e":[["Oggettivo","k",["oggett"]],["soggettivo","k",["soggett"]],["territoriale","k",["territor"]]],"r":[]}},{"id":"TRIB-X2~3","s":"TRIB-X2","q":"Differenza tra operazioni non imponibili ed esenti?","a":"Le non imponibili (esportazioni, cessioni intracomunitarie) danno diritto alla detrazione; le esenti di regola no.","v":{"p":null,"e":[["danno","k",["danno"]],["diritto","k",["dirit"]],["detrazione","k",["detrazi"]],["regola","k",["regol"]]],"r":[]}},{"id":"TRIB-X4~0","s":"TRIB-X4","q":"Qual è il cuore di «L'accertamento delle imposte sui redditi: metodi, termini, contraddittorio e adesione»? Rispondi in due o tre frasi.","a":"L'accertamento è l'atto con cui l'amministrazione finanziaria, dopo l'istruttoria, rettifica il reddito dichiarato o lo determina se la dichiarazione manca; l'avviso deve essere motivato, preceduto a pena di annullabilità da un contraddittorio informato ed effettivo (art. 6-bis L. 212/2000) e notificato entro i termini di decadenza dell'art. 43 D.P.R. 600/1973.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"TRIB-X4~1","s":"TRIB-X4","q":"Quali sono i metodi di accertamento per le persone fisiche?","a":"Analitico per categorie di reddito e sintetico in base alle spese, se il reddito accertabile supera di almeno un quinto il dichiarato.","v":{"p":null,"e":[["Analitico","k",["analit"]],["categorie","k",["catego"]],["reddito","k",["reddi"]],["sintetico","k",["sintet"]],["spese","k",["spese"]],["accertabile","k",["accertab"]],["supera","k",["super"]],["quinto","k",["quint"]],["dichiarato","k",["dichiar"]]],"r":[]}},{"id":"TRIB-X4~2","s":"TRIB-X4","q":"Cos'è il contraddittorio preventivo?","a":"L'ufficio comunica lo schema di atto e dà almeno 60 giorni per osservazioni; senza, l'atto è annullabile.","v":{"p":null,"e":[["60","n",["60"]],["ufficio","k",["uffic"]],["comunica","k",["comun"]],["schema","k",["schem"]],["atto","k",["att"]],["giorni","k",["giorn","gg"]],["osservazioni","k",["osservaz"]],["annullabile","k",["annullab"]]],"r":[]}},{"id":"TRIB-X4~3","s":"TRIB-X4","q":"Entro quando va notificato l'avviso di accertamento?","a":"Entro il 31 dicembre del quinto anno successivo alla dichiarazione, del settimo se è omessa o nulla.","v":{"p":null,"e":[["31","n",["31"]],["dicembre","k",["dicem"]],["quinto","k",["quint"]],["anno","k",["ann"]],["successivo","k",["success"]],["dichiarazione","k",["dichiara"]],["settimo","k",["setti"]],["omessa","k",["omess"]],["nulla","k",["nulla","invalid","inefficac","privo","priva","nessun effett","non ha effett","non produce effett"]]],"r":[]}},{"id":"TRIB-X4~4","s":"TRIB-X4","q":"Cosa offre l'accertamento con adesione?","a":"Un accordo in contraddittorio non impugnabile, con sanzioni ridotte a un terzo del minimo.","v":{"p":null,"e":[["accordo","k",["accor"]],["contraddittorio","k",["contradd"]],["impugnabile","k",["impugnab"]],["sanzioni","k",["sanzi","multa","ammend"]],["ridotte","k",["ridot"]],["terzo","k",["terzo"]]],"r":[]}},{"id":"TRIB-X5~0","s":"TRIB-X5","q":"Qual è il cuore di «La riscossione delle imposte: ruolo, cartella, rateazione ed esecuzione»? Rispondi in due o tre frasi.","a":"Le imposte non versate spontaneamente si riscuotono in via coattiva tramite l'Agenzia delle entrate-Riscossione: con il ruolo e la cartella di pagamento per le somme da liquidazione e controllo delle dichiarazioni, oppure direttamente con l'avviso di accertamento esecutivo, che diventa titolo dopo il termine per ricorrere.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"TRIB-X5~1","s":"TRIB-X5","q":"Come si riscuotono le imposte non versate?","a":"In via coattiva tramite l'Agenzia delle entrate-Riscossione: con ruolo e cartella oppure con l'avviso di accertamento esecutivo.","v":{"p":null,"e":[["coattiva","k",["coatt"]],["tramite","k",["trami"]],["Agenzia","k",["agenz"]],["entrate","k",["entra"]],["Riscossione","k",["riscossi"]],["ruolo","k",["ruolo"]],["cartella","k",["carte"]],["avviso","k",["avvis"]],["accertamento","k",["accertam"]],["esecutivo","k",["esecut"]]],"r":[]}},{"id":"TRIB-X5~2","s":"TRIB-X5","q":"Entro quando si paga la cartella?","a":"Entro 60 giorni dalla notifica.","v":{"p":null,"e":[["60","n",["60"]],["giorni","k",["giorn","gg"]],["notifica","k",["notif"]]],"r":[]}},{"id":"TRIB-X5~3","s":"TRIB-X5","q":"Quante rate mancate fanno decadere dalla rateazione?","a":"8 rate, anche non consecutive.","v":{"p":null,"e":[["8","n",["8"]],["consecutive","k",["consecut"]]],"r":[]}},{"id":"TRIB-X5~4","s":"TRIB-X5","q":"Quali misure cautelari ed esecutive può usare l'agente della riscossione?","a":"Ipoteca sugli immobili, fermo dei beni mobili registrati, pignoramento presso terzi anche di stipendi e conti.","v":{"p":null,"e":[["Ipoteca","k",["ipote"]],["immobili","k",["immob"]],["fermo","k",["fermo"]],["beni","k",["ben"]],["mobili","k",["mobil"]],["registrati","k",["registr"]],["pignoramento","k",["pignoram"]],["presso","k",["press"]],["terzi","k",["terzi"]],["stipendi","k",["stipe"]],["conti","k",["conti"]]],"r":[]}},{"id":"TRIB-X6~0","s":"TRIB-X6","q":"Qual è il cuore di «Il processo tributario: giudici, atti impugnabili, ricorso e difesa tecnica»? Rispondi in due o tre frasi.","a":"Le liti sui tributi si decidono davanti alle Corti di giustizia tributaria di primo grado (in ogni capoluogo di provincia) e di secondo grado (in ogni capoluogo di regione), con ricorso finale in Cassazione; il processo è regolato dal D.Lgs. 546/1992 e comincia con il ricorso contro uno degli atti impugnabili dell'art. 19, entro 60 giorni dalla notifica.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"TRIB-X6~1","s":"TRIB-X6","q":"Davanti a chi si discutono le liti tributarie?","a":"Corti di giustizia tributaria di primo grado (provincia) e di secondo grado (regione), poi Cassazione.","v":{"p":null,"e":[["1","n",["1"]],["Corti","k",["corti"]],["giustizia","k",["giusti"]],["grado","k",["grado"]],["secondo","k",["secon"]],["Cassazione","k",["cassazi"]]],"r":[]}},{"id":"TRIB-X6~2","s":"TRIB-X6","q":"Entro quando si propone il ricorso tributario?","a":"Entro 60 giorni dalla notifica dell'atto, a pena di inammissibilità.","v":{"p":null,"e":[["60","n",["60"]],["giorni","k",["giorn","gg"]],["notifica","k",["notif"]],["atto","k",["att"]],["pena","k",["pen"]],["inammissibilità","k",["inammiss"]]],"r":[]}},{"id":"TRIB-X6~3","s":"TRIB-X6","q":"Il consulente del lavoro può difendere nel processo tributario?","a":"Sì, per tutte le materie; la difesa tecnica è obbligatoria sopra 3.000 euro di valore.","v":{"p":"s","e":[["3.000","m",["3000"]],["materie","k",["mater"]],["difesa","k",["difes"]],["tecnica","k",["tecni"]],["obbligatoria","k",["obbligat","obblig"]],["sopra","k",["sopra"]],["euro","k",["eur"]],["valore","k",["valor"]]],"r":[]}},{"id":"S22-TRIB-3~0","s":"S22-TRIB-3","q":"Qual è il cuore di «L'IRPEF: nozione, soggetti passivi e base imponibile»? Rispondi in due o tre frasi.","a":"L'IRPEF è l'imposta personale e progressiva sul reddito delle persone fisiche (TUIR, D.P.R. 917/1986), espressione della capacità contributiva e della progressività dell'art. 53 Cost. Il presupposto è il possesso di redditi in denaro o in natura delle sei categorie dell'art. 6; la base imponibile è il reddito complessivo al netto degli oneri deducibili.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-TRIB-3~1","s":"S22-TRIB-3","q":"Cos'è l'IRPEF?","a":"L'imposta personale e progressiva sul reddito delle persone fisiche, espressione di capacità contributiva e progressività.","v":{"p":null,"e":[["imposta","k",["impos"]],["personale","k",["person"]],["progressiva","k",["progress"]],["reddito","k",["reddi"]],["persone","k",["perso"]],["fisiche","k",["fisic"]],["espressione","k",["espressi"]],["capacità","k",["capac"]],["contributiva","k",["contribu","contribuz","contribut"]]],"r":[]}},{"id":"S22-TRIB-3~2","s":"S22-TRIB-3","q":"Come si tassano residenti e non residenti?","a":"Il residente su tutti i redditi ovunque prodotti; il non residente solo su quelli prodotti in Italia.","v":{"p":null,"e":[["redditi","k",["reddi"]],["ovunque","k",["ovunq"]],["prodotti","k",["prodo"]],["Italia","k",["itali"]]],"r":[]}},{"id":"S22-TRIB-3~3","s":"S22-TRIB-3","q":"Qual è la base imponibile IRPEF?","a":"Il reddito complessivo al netto degli oneri deducibili, esclusi i redditi esenti, a ritenuta d'imposta, a sostitutiva o a tassazione separata.","v":{"p":null,"e":[["reddito","k",["reddi"]],["complessivo","k",["compless"]],["netto","k",["netto"]],["oneri","k",["oneri"]],["deducibili","k",["deducib"]],["esclusi","k",["esclu"]],["esenti","k",["esent"]],["ritenuta","k",["riten"]],["imposta","k",["impos"]],["sostitutiva","k",["sostitut"]],["tassazione","k",["tassazi"]],["separata","k",["separ"]]],"r":[]}},{"id":"S22-TRIB-8~0","s":"S22-TRIB-8","q":"Qual è il cuore di «Il reddito professionale: base imponibile e deducibilità delle spese»? Rispondi in due o tre frasi.","a":"Il reddito di lavoro autonomo professionale (art. 54 TUIR, riformato dal D.Lgs. 192/2024) è la differenza tra tutte le somme percepite nel periodo d'imposta in relazione all'attività e le spese sostenute nello stesso periodo: vale il principio di cassa e quello di onnicomprensività. Le regole sulla deducibilità delle spese sono negli artt. 54-bis-54-octies.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-TRIB-8~1","s":"S22-TRIB-8","q":"Come si determina il reddito professionale?","a":"Differenza tra le somme percepite e le spese sostenute nel periodo: cassa e onnicomprensività.","v":{"p":null,"e":[["Differenza","k",["differe"]],["somme","k",["somme"]],["percepite","k",["percep"]],["spese","k",["spese"]],["sostenute","k",["sosten"]],["periodo","k",["perio"]],["cassa","k",["cassa","cig"]],["onnicomprensività","k",["onnicomp"]]],"r":[]}},{"id":"S22-TRIB-8~2","s":"S22-TRIB-8","q":"Il contributo integrativo ENPACL del 4% è reddito del consulente?","a":"No: i contributi di legge a carico del committente non sono reddito.","v":{"p":"n","e":[["legge","k",["legge"]],["carico","k",["caric"]],["committente","k",["committe"]]],"r":[]}},{"id":"S22-TRIB-8~3","s":"S22-TRIB-8","q":"Che ritenuta subisce il professionista?","a":"Il 20% sull'onorario, se il committente è sostituto d'imposta.","v":{"p":null,"e":[["20%","n",["20"]],["onorario","k",["onora"]],["committente","k",["committe"]],["sostituto","k",["sostit"]],["imposta","k",["impos"]]],"r":[]}},{"id":"S22-TRIB-9~0","s":"S22-TRIB-9","q":"Qual è il cuore di «I redditi da lavoro autonomo occasionale: definizione, tassazione e obblighi»? Rispondi in due o tre frasi.","a":"Il compenso per un'attività di lavoro autonomo svolta in modo non abituale è un reddito diverso (art. 67, c. 1, lett. l, TUIR), non un reddito di lavoro autonomo. Si tassa sul netto tra compensi incassati e spese specificamente inerenti, concorre al reddito complessivo e, se il committente è sostituto d'imposta, subisce una ritenuta d'acconto del 20%.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-TRIB-9~1","s":"S22-TRIB-9","q":"Che reddito è il lavoro autonomo occasionale?","a":"Un reddito diverso, non di lavoro autonomo: manca l'abitualità.","v":{"p":null,"e":[["diverso","k",["diver"]],["manca","k",["manca"]],["abitualità","k",["abitual"]]],"r":[]}},{"id":"S22-TRIB-9~2","s":"S22-TRIB-9","q":"Come si tassa il lavoro autonomo occasionale?","a":"Sul netto tra compensi incassati e spese inerenti, nel reddito complessivo; ritenuta d'acconto del 20% se il committente è sostituto.","v":{"p":null,"e":[["20%","m",["20"]],["netto","k",["netto"]],["incassati","k",["incass"]],["spese","k",["spese"]],["inerenti","k",["inere"]],["reddito","k",["reddi"]],["ritenuta","k",["riten"]],["acconto","k",["accon"]],["sostituto","k",["sostit"]]],"r":[]}},{"id":"S22-TRIB-9~3","s":"S22-TRIB-9","q":"Quando scatta l'iscrizione alla gestione separata per l'occasionale?","a":"Solo per la parte di reddito annuo oltre 5.000 euro.","v":{"p":null,"e":[["5.000","n",["5000"]],["reddito","k",["reddi"]],["annuo","k",["annuo"]],["euro","k",["eur"]]],"r":[]}},{"id":"S22-TRIB-10~0","s":"S22-TRIB-10","q":"Qual è il cuore di «La dichiarazione dei redditi (ex Modello Unico): soggetti obbligati»? Rispondi in due o tre frasi.","a":"La dichiarazione dei redditi è l'atto con cui il contribuente comunica all'Amministrazione redditi, imponibile e imposta per un periodo d'imposta (D.P.R. 600/1973 e D.P.R. 322/1998). Il modello Redditi (ex Unico) è obbligatorio per tutte le persone fisiche che hanno conseguito redditi, salvo i casi di esonero; chi ha solo redditi di lavoro dipendente, assimilati o pensione può usare il 730.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-TRIB-10~1","s":"S22-TRIB-10","q":"Chi è obbligato alla dichiarazione dei redditi?","a":"Chi ha conseguito redditi, salvo esoneri; chi tiene le scritture contabili anche senza reddito.","v":{"p":null,"e":[["conseguito","k",["consegu"]],["esoneri","k",["esone","sgrav","agevol","riduz"]],["tiene","k",["tiene"]],["scritture","k",["scritt"]],["contabili","k",["contab"]]],"r":[]}},{"id":"S22-TRIB-10~2","s":"S22-TRIB-10","q":"Chi è esonerato dalla dichiarazione?","a":"Per esempio chi ha solo redditi di lavoro dipendente da un unico sostituto che ha fatto il conguaglio.","v":{"p":null,"e":[["esempio","k",["esemp"]],["redditi","k",["reddi"]],["lavoro","k",["lavor","dipendent","prestator"]],["dipendente","k",["dipende","lavorat"]],["unico","k",["unico"]],["sostituto","k",["sostit"]],["fatto","k",["fatto"]],["conguaglio","k",["conguag"]]],"r":[]}},{"id":"S22-TRIB-10~3","s":"S22-TRIB-10","q":"Entro quando si presenta il modello Redditi PF?","a":"Per via telematica dal 30 aprile al 31 ottobre dell'anno successivo.","v":{"p":null,"e":[["30","n",["30"]],["31","n",["31"]],["telematica","k",["telemat","online","on line","via web","digital"]],["aprile","k",["april"]],["ottobre","k",["ottob"]],["anno","k",["ann"]],["successivo","k",["success"]]],"r":[]}},{"id":"S22-TRIB-12~0","s":"S22-TRIB-12","q":"Qual è il cuore di «La compensazione in F24: verticale, orizzontale e limiti»? Rispondi in due o tre frasi.","a":"Con il modello F24 il contribuente può compensare crediti e debiti tributari e contributivi (art. 17 D.Lgs. 241/1997). La compensazione è verticale se il credito si usa per un debito della stessa imposta, orizzontale se si usa per tributi o contributi diversi. L'orizzontale ha limiti e controlli più stretti.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-TRIB-12~1","s":"S22-TRIB-12","q":"Differenza tra compensazione verticale e orizzontale?","a":"Verticale: credito e debito della stessa imposta; orizzontale: tributi o contributi diversi, con limiti e controlli più stretti.","v":{"p":null,"e":[["credito","k",["credi"]],["debito","k",["debit"]],["imposta","k",["impos"]],["tributi","k",["tribu"]],["contributi","k",["contrib","contribuz","contribut"]],["diversi","k",["diver"]],["limiti","k",["limit"]],["controlli","k",["contro"]],["stretti","k",["stret"]]],"r":[]}},{"id":"S22-TRIB-12~2","s":"S22-TRIB-12","q":"Quando si blocca la compensazione in F24?","a":"Con ruoli o carichi scaduti e non sospesi per imposte erariali oltre 50.000 euro.","v":{"p":null,"e":[["50.000","n",["50000"]],["ruoli","k",["ruoli"]],["carichi","k",["caric"]],["scaduti","k",["scadu"]],["sospesi","k",["sospe"]],["imposte","k",["impos"]],["erariali","k",["erari"]],["euro","k",["eur"]]],"r":[]}},{"id":"S22-TRIB-12~3","s":"S22-TRIB-12","q":"Come recupera il datore le indennità anticipate per conto dell'INPS?","a":"Se superano i contributi dovuti, compensando il credito in F24 con i tributi.","v":{"p":null,"e":[["24","n",["24"]],["superano","k",["super"]],["contributi","k",["contrib","contribuz","contribut"]],["dovuti","k",["dovut"]],["credito","k",["credi"]],["tributi","k",["tribu"]]],"r":[]}},{"id":"TRIB-5~0","s":"TRIB-5","q":"Qual è il cuore di «Le società di persone e di capitali ai fini fiscali»? Rispondi in due o tre frasi.","a":"Le società di persone commerciali producono reddito d'impresa che è tassato in capo ai soci per trasparenza (art. 5 TUIR); le società di capitali sono soggetti IRES e pagano l'imposta sul proprio reddito (artt. 73 e 77 TUIR).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"TRIB-5~1","s":"TRIB-5","q":"Come si tassano le società di persone e quelle di capitali?","a":"Persone: reddito d'impresa imputato ai soci per trasparenza, anche se non percepito; capitali: IRES al 24% sul proprio reddito, poi dividendi tassati ai soci.","v":{"p":null,"e":[["24%","m",["24"]],["reddito","k",["reddi"]],["impresa","k",["impre","non si prescrive","non si prescrivono"]],["imputato","k",["imput"]],["trasparenza","k",["traspare"]],["percepito","k",["percep"]],["IRES","k",["ires"]],["dividendi","k",["divide"]]],"r":[]}},{"id":"TRIB-5~2","s":"TRIB-5","q":"Le s.r.l. possono scegliere la trasparenza?","a":"Sì, quelle a ristretta base proprietaria.","v":{"p":"s","e":[["ristretta","k",["ristre"]],["proprietaria","k",["propriet"]]],"r":[]}},{"id":"TRIB-20~0","s":"TRIB-20","q":"Qual è il cuore di «L'impresa familiare»? Rispondi in due o tre frasi.","a":"L'impresa familiare è l'impresa individuale in cui collaborano in modo continuativo il coniuge, i parenti entro il terzo grado e gli affini entro il secondo (art. 230-bis c.c.); ai fini fiscali fino al 49% del reddito può essere imputato ai familiari collaboratori (art. 5, c. 4, TUIR).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"TRIB-20~1","s":"TRIB-20","q":"Cos'è l'impresa familiare?","a":"L'impresa individuale in cui collaborano in modo continuativo coniuge, parenti entro il terzo grado e affini entro il secondo; è un istituto residuale.","v":{"p":null,"e":[["individuale","k",["individu"]],["collaborano","k",["collabor"]],["continuativo","k",["continua"]],["coniuge","k",["coniu"]],["parenti","k",["paren"]],["terzo","k",["terzo"]],["grado","k",["grado"]],["affini","k",["affin"]],["secondo","k",["secon"]],["istituto","k",["istit"]],["residuale","k",["residu"]]],"r":[]}},{"id":"TRIB-20~2","s":"TRIB-20","q":"Quanta parte del reddito si può imputare ai familiari?","a":"Fino al 49%, in proporzione alle quote, con atto anteriore all'inizio del periodo d'imposta.","v":{"p":null,"e":[["49%","n",["49"]],["proporzione","k",["proporzi"]],["quote","k",["quote"]],["atto","k",["att"]],["anteriore","k",["anteri"]],["inizio","k",["inizi"]],["periodo","k",["perio"]],["imposta","k",["impos"]]],"r":[]}},{"id":"TRIB-20~3","s":"TRIB-20","q":"Il convivente di fatto partecipa all'impresa familiare?","a":"Sì: la Corte costituzionale nel 2024 ha dichiarato illegittimo l'art. 230-bis nella parte in cui lo escludeva.","v":{"p":"s","e":[["art. 230-bis","n",["230"]],["2024","n",["2024"]],["Corte","k",["corte"]],["costituzionale","k",["costituz"]],["dichiarato","k",["dichiar"]],["illegittimo","k",["illegitt"]],["escludeva","k",["esclud"]]],"r":[]}},{"id":"TRIB-21~0","s":"TRIB-21","q":"Qual è il cuore di «I tipi di società»? Rispondi in due o tre frasi.","a":"Il codice civile distingue le società di persone (società semplice, in nome collettivo, in accomandita semplice), le società di capitali (per azioni, a responsabilità limitata, in accomandita per azioni) e le società cooperative.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"TRIB-21~1","s":"TRIB-21","q":"Quali tipi di società prevede il codice civile?","a":"Di persone (semplice, s.n.c., s.a.s.), di capitali (s.p.a., s.r.l., s.a.p.a.) e cooperative.","v":{"p":null,"e":[["persone","k",["perso"]],["capitali","k",["capit"]],["cooperative","k",["cooperat"]]],"r":[]}},{"id":"TRIB-21~2","s":"TRIB-21","q":"Quale attività può svolgere la società semplice?","a":"Solo attività non commerciali, tipicamente agricole o di gestione immobiliare.","v":{"p":null,"e":[["commerciali","k",["commerci"]],["tipicamente","k",["tipicame"]],["agricole","k",["agric"]],["gestione","k",["gesti"]],["immobiliare","k",["immobili"]]],"r":[]}},{"id":"TRIB-21~3","s":"TRIB-21","q":"Cosa distingue le cooperative?","a":"Lo scopo mutualistico anziché lucrativo.","v":{"p":null,"e":[["scopo","k",["scopo"]],["mutualistico","k",["mutualis"]],["anziché","k",["anzic"]],["lucrativo","k",["lucrat"]]],"r":[]}},{"id":"TRIB-23~0","s":"TRIB-23","q":"Qual è il cuore di «Soci accomandatari e accomandanti nella s.a.s.»? Rispondi in due o tre frasi.","a":"Nella società in accomandita semplice convivono due categorie di soci: gli accomandatari, che amministrano e rispondono illimitatamente e solidalmente delle obbligazioni sociali, e gli accomandanti, che rispondono nei limiti della quota conferita (art. 2313 c.c.).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"TRIB-23~1","s":"TRIB-23","q":"Differenza tra accomandatari e accomandanti?","a":"Gli accomandatari amministrano e rispondono illimitatamente e solidalmente; gli accomandanti rispondono nei limiti della quota.","v":{"p":null,"e":[["amministrano","k",["amminist"]],["rispondono","k",["rispond"]],["illimitatamente","k",["illimita"]],["solidalmente","k",["solidalm"]],["limiti","k",["limit"]],["quota","k",["quota"]]],"r":[]}},{"id":"TRIB-23~2","s":"TRIB-23","q":"Cos'è il divieto di immistione?","a":"L'accomandante che amministra o tratta affari in nome della società senza procura speciale risponde illimitatamente verso i terzi e può essere escluso.","v":{"p":null,"e":[["accomandante","k",["accomand"]],["amministra","k",["amminis"]],["tratta","k",["tratt"]],["affari","k",["affar"]],["nome","k",["nom"]],["società","k",["socie"]],["procura","k",["procu"]],["speciale","k",["speci"]],["risponde","k",["rispo"]],["illimitatamente","k",["illimita"]],["terzi","k",["terzi"]],["escluso","k",["esclu"]]],"r":[]}},{"id":"TRIB-X3~0","s":"TRIB-X3","q":"Qual è il cuore di «L'imposta sul reddito delle società (IRES)»? Rispondi in due o tre frasi.","a":"L'IRES è l'imposta proporzionale sul reddito delle società di capitali, degli enti commerciali e non commerciali e dei non residenti (art. 73 TUIR); si applica con aliquota del 24% (art. 77) sul reddito complessivo netto, che per le società si determina partendo dall'utile o dalla perdita del conto economico (art. 83).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"TRIB-X3~1","s":"TRIB-X3","q":"Cos'è l'IRES e su che base si calcola?","a":"L'imposta proporzionale al 24% sul reddito delle società di capitali ed enti, calcolata partendo dall'utile del conto economico con le variazioni fiscali.","v":{"p":null,"e":[["24%","n",["24"]],["imposta","k",["impos"]],["proporzionale","k",["proporzi"]],["reddito","k",["reddi"]],["società","k",["socie"]],["capitali","k",["capit"]],["enti","k",["ent"]],["partendo","k",["parte"]],["utile","k",["utile"]],["conto","k",["conto"]],["economico","k",["econom"]],["variazioni","k",["variazi"]],["fiscali","k",["fisca"]]],"r":[]}},{"id":"TRIB-X3~2","s":"TRIB-X3","q":"Come si riportano le perdite ai fini IRES?","a":"Senza limiti di tempo ma nel limite dell'80% del reddito di ogni anno, salvo quelle dei primi tre periodi.","v":{"p":null,"e":[["80%","n",["80"]],["3","n",["3"]],["limiti","k",["limit"]],["tempo","k",["tempo"]],["reddito","k",["reddi"]],["anno","k",["ann"]],["primi","k",["primi"]],["periodi","k",["perio"]]],"r":[]}},{"id":"TRIB-X1~0","s":"TRIB-X1","q":"Qual è il cuore di «Il sostituto d'imposta: chi è, soggetti, obblighi»? Rispondi in due o tre frasi.","a":"Il sostituto d'imposta è chi, per legge, è obbligato al pagamento di imposte in luogo di altri, per fatti o situazioni a questi riferibili, anche a titolo d'acconto, e deve esercitare la rivalsa (art. 64 D.P.R. 600/1973); nel lavoro dipendente è il datore di lavoro.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"TRIB-X1~1","s":"TRIB-X1","q":"Chi è il sostituto d'imposta?","a":"Chi per legge paga imposte al posto di altri, anche a titolo d'acconto, esercitando la rivalsa; nel lavoro dipendente è il datore.","v":{"p":null,"e":[["legge","k",["legge"]],["paga","k",["pag"]],["posto","k",["posto"]],["titolo","k",["titol"]],["acconto","k",["accon"]],["esercitando","k",["esercita"]],["rivalsa","k",["rival"]],["lavoro","k",["lavor","dipendent","prestator"]],["dipendente","k",["dipende","lavorat"]],["datore","k",["dator","aziend","impres"]]],"r":[]}},{"id":"TRIB-X1~2","s":"TRIB-X1","q":"Quali adempimenti annuali ha il sostituto?","a":"Conguaglio entro il 28 febbraio, CU entro il 16 marzo, 770 entro il 31 ottobre, esecuzione dei 730-4.","v":{"p":null,"e":[["28","n",["28"]],["16","n",["16"]],["770","n",["770"]],["31","n",["31"]],["730","n",["730"]],["4","n",["4"]],["Conguaglio","k",["conguag"]],["febbraio","k",["febbr"]],["CU","k",["cu"]],["marzo","k",["marzo"]],["ottobre","k",["ottob"]],["esecuzione","k",["esecuzi"]]],"r":[]}},{"id":"TRIB-X1~3","s":"TRIB-X1","q":"Entro quando si versano le ritenute mensili?","a":"Con F24 entro il 16 del mese successivo.","v":{"p":null,"e":[["24","n",["24"]],["16","n",["16"]],["mese","k",["mes"]],["successivo","k",["success"]]],"r":[]}},{"id":"TRIB-X1~4","s":"TRIB-X1","q":"Il lavoratore risponde se il sostituto non versa le ritenute d'acconto?","a":"No: risponde in solido solo per le ritenute a titolo d'imposta non operate né versate.","v":{"p":"n","e":[["solido","k",["solid"]],["titolo","k",["titol"]],["imposta","k",["impos"]],["operate","k",["opera"]]],"r":[]}},{"id":"RAG-1~0","s":"RAG-1","q":"Qual è il cuore di «L'indennità di malattia in bilancio»? Rispondi in due o tre frasi.","a":"In bilancio l'indennità di malattia a carico dell'INPS, anticipata dal datore in busta paga, non è un costo dell'impresa ma un credito verso l'INPS da recuperare a conguaglio; è costo solo la parte a carico del datore.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"RAG-1~1","s":"RAG-1","q":"L'indennità di malattia anticipata dal datore è un costo?","a":"No: la quota INPS è un credito verso l'INPS recuperato a conguaglio; è costo solo la parte a carico del datore.","v":{"p":"n","e":[["quota","k",["quota"]],["INPS","k",["inps"]],["credito","k",["credi"]],["recuperato","k",["recuper"]],["conguaglio","k",["conguag"]],["carico","k",["caric"]]],"r":[]}},{"id":"RAG-1~2","s":"RAG-1","q":"Quale parte della malattia è costo del datore e dove va?","a":"Carenza dei primi 3 giorni e integrazione del CCNL: costo del personale in B9 a).","v":{"p":null,"e":[["3","n",["3"]],["9","n",["9"]],["Carenza","k",["caren"]],["primi","k",["primi"]],["giorni","k",["giorn","gg"]],["integrazione","k",["integraz"]],["CCNL","k",["ccnl","contratto collettivo","contratti collettivi"]],["personale","k",["person"]]],"r":[]}},{"id":"RAG-1~3","s":"RAG-1","q":"Sulla parte INPS della malattia si versano contributi?","a":"No: il periodo è coperto da contribuzione figurativa; sull'integrazione del datore sì.","v":{"p":"n","e":[["periodo","k",["perio"]],["coperto","k",["coper"]],["figurativa","k",["figurat"]],["integrazione","k",["integraz"]],["datore","k",["dator","aziend","impres"]]],"r":[]}},{"id":"RAG-2~0","s":"RAG-2","q":"Qual è il cuore di «L'indennità di maternità in bilancio»? Rispondi in due o tre frasi.","a":"L'indennità di maternità (80% della retribuzione a carico dell'INPS) è anticipata dal datore in busta e recuperata a conguaglio: in bilancio è un credito verso l'INPS, mentre l'eventuale integrazione fino al 100% prevista dal CCNL è costo del personale.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"RAG-2~1","s":"RAG-2","q":"Come si rileva l'indennità di maternità anticipata?","a":"La quota INPS (80%) in dare di un credito verso l'INPS, non tra i costi; l'integrazione al 100% del CCNL è costo B9 a).","v":{"p":null,"e":[["100%","m",["100"]],["9","m",["9"]],["quota","k",["quota"]],["INPS","k",["inps"]],["dare","k",["dar"]],["credito","k",["credi"]],["costi","k",["costi"]],["integrazione","k",["integraz"]],["CCNL","k",["ccnl","contratto collettivo","contratti collettivi"]],["costo","k",["costo"]]],"r":[]}},{"id":"RAG-2~2","s":"RAG-2","q":"Come si calcola il TFR nel periodo di maternità?","a":"Sulla retribuzione che sarebbe spettata.","v":{"p":null,"e":[["retribuzione","k",["retribuz","stipend","paga","salari"]],["sarebbe","k",["sareb"]],["spettata","k",["spett"]]],"r":[]}},{"id":"RAG-5~0","s":"RAG-5","q":"Qual è il cuore di «I contributi a carico del datore nello stato patrimoniale e nel conto economico»? Rispondi in due o tre frasi.","a":"I contributi a carico del datore sono un costo del personale, voce B9 b) oneri sociali del conto economico; quelli liquidati e non ancora pagati sono un debito, voce D 13) debiti verso istituti di previdenza e di sicurezza sociale dello stato patrimoniale.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"RAG-5~1","s":"RAG-5","q":"Dove vanno in bilancio i contributi a carico del datore?","a":"A conto economico in B9 b) oneri sociali; quelli da versare in stato patrimoniale tra i debiti D 13) verso istituti previdenziali.","v":{"p":null,"e":[["9","n",["9"]],["13","m",["13"]],["conto","k",["conto"]],["economico","k",["econom"]],["oneri","k",["oneri"]],["sociali","k",["socia"]],["versare","k",["versa"]],["patrimoniale","k",["patrimon"]],["debiti","k",["debit"]],["istituti","k",["istit"]],["previdenziali","k",["previden"]]],"r":[]}},{"id":"RAG-5~2","s":"RAG-5","q":"Come si articola la voce B9 del conto economico?","a":"a) salari e stipendi, b) oneri sociali, c) TFR, d) quiescenza, e) altri costi.","v":{"p":null,"e":[["salari","k",["salar"]],["stipendi","k",["stipe"]],["oneri","k",["oneri"]],["sociali","k",["socia"]],["TFR","k",["tfr","trattamento di fine rapporto","liquidazione"]],["quiescenza","k",["quiesce"]],["costi","k",["costi"]]],"r":[]}},{"id":"RAG-5~3","s":"RAG-5","q":"Come si rileva a fine anno il premio INAIL?","a":"Con l'assestamento: costo di competenza in B9 b) e debito o credito per il conguaglio.","v":{"p":null,"e":[["9","n",["9"]],["assestamento","k",["assestam"]],["costo","k",["costo"]],["debito","k",["debit"]],["credito","k",["credi"]],["conguaglio","k",["conguag"]]],"r":[]}},{"id":"RAG-6~0","s":"RAG-6","q":"Qual è il cuore di «Le voci del costo dei lavoratori»? Rispondi in due o tre frasi.","a":"Il costo del lavoro dipendente si compone di retribuzione diretta, oneri contrattuali e differiti (mensilità aggiuntive, ferie, TFR) e oneri sociali; in bilancio è la voce B9 del conto economico.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"RAG-6~1","s":"RAG-6","q":"Di cosa si compone il costo del lavoro dipendente?","a":"Retribuzione diretta, oneri contrattuali e differiti (mensilità aggiuntive, ferie, TFR) e oneri sociali.","v":{"p":null,"e":[["Retribuzione","k",["retribuz","stipend","paga","salari"]],["diretta","k",["diret"]],["oneri","k",["oneri"]],["contrattuali","k",["contratt","rapport"]],["differiti","k",["differ"]],["sociali","k",["socia"]]],"r":[]}},{"id":"RAG-6~2","s":"RAG-6","q":"I compensi agli amministratori vanno in B9?","a":"No: in B7 tra i costi per servizi.","v":{"p":"n","e":[["7","n",["7"]],["costi","k",["costi"]],["servizi","k",["servi"]]],"r":[]}},{"id":"RAG-6~3","s":"RAG-6","q":"Il costo del lavoro somministrato dove si iscrive?","a":"In B9, secondo l'OIC 12.","v":{"p":null,"e":[["9","n",["9"]],["12","n",["12"]],["secondo","k",["secon"]],["OIC","k",["oic"]]],"r":[]}},{"id":"RAG-7~0","s":"RAG-7","q":"Qual è il cuore di «Il TFR liquidato»? Rispondi in due o tre frasi.","a":"Alla cessazione il TFR accumulato viene pagato al lavoratore: in contabilità si chiude il fondo TFR per la quota maturata, si rileva la quota dell'anno in corso e si trattengono le imposte come sostituto d'imposta.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"RAG-7~1","s":"RAG-7","q":"Come si rileva la liquidazione del TFR?","a":"In dare Fondo TFR, in avere il debito verso il dipendente; la ritenuta va a Erario c/ritenute e si paga il netto.","v":{"p":null,"e":[["dare","k",["dar"]],["Fondo","k",["fondo"]],["TFR","k",["tfr","trattamento di fine rapporto","liquidazione"]],["debito","k",["debit"]],["dipendente","k",["dipende","lavorat"]],["ritenuta","k",["riten"]],["Erario","k",["erari"]],["paga","k",["pag"]],["netto","k",["netto"]]],"r":[]}},{"id":"RAG-7~2","s":"RAG-7","q":"Chi paga il TFR versato al Fondo di Tesoreria o a un fondo pensione?","a":"Per quelle quote paga il fondo o l'INPS, non l'impresa.","v":{"p":null,"e":[["quote","k",["quote"]],["INPS","k",["inps"]],["impresa","k",["impre","non si prescrive","non si prescrivono"]]],"r":[]}},{"id":"RAG-7~3","s":"RAG-7","q":"Come si trattano le anticipazioni già erogate?","a":"Si detraggono dal TFR finale.","v":{"p":"s","e":[["detraggono","k",["detragg"]],["TFR","k",["tfr","trattamento di fine rapporto","liquidazione"]],["finale","k",["final"]]],"r":[]}},{"id":"RAG-9~0","s":"RAG-9","q":"Qual è il cuore di «Il conto «Personale c/retribuzioni»»? Rispondi in due o tre frasi.","a":"Il conto «Personale c/retribuzioni» (o Dipendenti c/retribuzioni) è un conto finanziario di debito che accoglie in avere le retribuzioni lorde maturate e in dare le trattenute, gli acconti e il pagamento del netto.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"RAG-9~1","s":"RAG-9","q":"Che natura ha il conto Personale c/retribuzioni?","a":"Conto finanziario di debito verso i dipendenti: in avere il lordo maturato, in dare trattenute, acconti e pagamento del netto.","v":{"p":null,"e":[["finanziario","k",["finanzia"]],["debito","k",["debit"]],["dipendenti","k",["dipende","lavorat"]],["lordo","k",["lordo"]],["maturato","k",["matur"]],["dare","k",["dar"]],["trattenute","k",["tratten"]],["acconti","k",["accon"]],["pagamento","k",["pagame"]],["netto","k",["netto"]]],"r":[]}},{"id":"RAG-9~2","s":"RAG-9","q":"Come si chiude il conto Personale c/retribuzioni?","a":"Con le trattenute (contro Istituti previdenziali ed Erario c/ritenute), gli acconti e il pagamento del netto con banca: saldo zero.","v":{"p":null,"e":[["trattenute","k",["tratten"]],["acconti","k",["accon"]],["pagamento","k",["pagame"]],["netto","k",["netto"]],["banca","k",["banca"]],["saldo","k",["saldo"]],["zero","k",["zer"]]],"r":[]}},{"id":"RAG-9~3","s":"RAG-9","q":"Se gli stipendi di dicembre si pagano a gennaio, dove va il saldo?","a":"In stato patrimoniale tra i debiti, voce D 14) altri debiti.","v":{"p":null,"e":[["14","n",["14"]],["patrimoniale","k",["patrimon"]],["debiti","k",["debit"]],["voce","k",["voc"]]],"r":[]}},{"id":"RAG-17~0","s":"RAG-17","q":"Qual è il cuore di «I compensi ad amministratori e sindaci»? Rispondi in due o tre frasi.","a":"I compensi ad amministratori e sindaci non sono costi del personale dipendente ma costi per servizi (voce B7 del conto economico); per gli amministratori sono fiscalmente deducibili nell'esercizio in cui sono pagati (art. 95, c. 5, TUIR).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"RAG-17~1","s":"RAG-17","q":"Dove si classificano i compensi ad amministratori e sindaci?","a":"In B7, costi per servizi, non tra i costi del personale.","v":{"p":null,"e":[["7","n",["7"]],["costi","k",["costi"]],["servizi","k",["servi"]],["personale","k",["person"]]],"r":[]}},{"id":"RAG-17~2","s":"RAG-17","q":"Quando è deducibile il compenso dell'amministratore?","a":"Per cassa, nell'esercizio in cui è pagato.","v":{"p":null,"e":[["cassa","k",["cassa","cig"]],["esercizio","k",["eserci"]],["pagato","k",["pagat"]]],"r":[]}},{"id":"RAG-17~3","s":"RAG-17","q":"Come si ripartiscono i contributi in gestione separata dell'amministratore?","a":"2/3 a carico della società, 1/3 dell'amministratore.","v":{"p":null,"e":[["2","n",["2"]],["3","n",["3"]],["1","n",["1"]],["carico","k",["caric"]],["società","k",["socie"]]],"r":[]}},{"id":"RAG-21~0","s":"RAG-21","q":"Qual è il cuore di «Il conto «Salari e stipendi»»? Rispondi in due o tre frasi.","a":"«Salari e stipendi» è il conto economico di costo che accoglie le retribuzioni lorde di competenza dei dipendenti; confluisce nella voce B9 a) del conto economico.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"RAG-21~1","s":"RAG-21","q":"Cosa accoglie il conto Salari e stipendi?","a":"Le retribuzioni lorde di competenza: minimi, scatti, superminimi, straordinari, indennità, mensilità aggiuntive, ferie maturate.","v":{"p":null,"e":[["retribuzioni","k",["retribuz","stipend","paga","salari"]],["lorde","k",["lorde"]],["competenza","k",["compete"]],["minimi","k",["minim"]],["scatti","k",["scatt"]],["superminimi","k",["supermin"]],["straordinari","k",["straordi"]],["indennità","k",["indenn"]],["mensilità","k",["mensil"]],["aggiuntive","k",["aggiunt"]],["ferie","k",["ferie"]],["maturate","k",["matur"]]],"r":[]}},{"id":"RAG-21~2","s":"RAG-21","q":"Cosa resta fuori dal conto Salari e stipendi?","a":"Contributi a carico del datore (B9 b), quota TFR (B9 c), indennità pagate per conto dell'INPS.","v":{"p":null,"e":[["Contributi","k",["contrib","contribuz","contribut"]],["carico","k",["caric"]],["datore","k",["dator","aziend","impres"]],["quota","k",["quota"]],["TFR","k",["tfr","trattamento di fine rapporto","liquidazione"]],["indennità","k",["indenn"]],["pagate","k",["pagat"]],["INPS","k",["inps"]]],"r":[]}},{"id":"RAG-21~3","s":"RAG-21","q":"Come si integra Salari e stipendi a fine esercizio?","a":"Con gli stanziamenti delle quote maturate e non pagate (quattordicesima, ferie non godute; tredicesima solo se non già pagata).","v":{"p":null,"e":[["stanziamenti","k",["stanziam"]],["quote","k",["quote"]],["maturate","k",["matur"]],["pagate","k",["pagat"]]],"r":[]}},{"id":"RAG-22~0","s":"RAG-22","q":"Qual è il cuore di «Il fondo TFR e la sua movimentazione»? Rispondi in due o tre frasi.","a":"Il fondo TFR è la passività che accoglie il TFR maturato dai dipendenti e rimasto in azienda (voce C del passivo, art. 2424 c.c.): aumenta con le quote annue e le rivalutazioni, diminuisce con l'imposta sostitutiva, le anticipazioni e le liquidazioni.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"RAG-22~1","s":"RAG-22","q":"Cos'è il fondo TFR in bilancio?","a":"La passività (voce C del passivo) che accoglie il TFR maturato e rimasto in azienda.","v":{"p":null,"e":[["passività","k",["passiv"]],["accoglie","k",["accog"]],["TFR","k",["tfr","trattamento di fine rapporto","liquidazione"]],["maturato","k",["matur"]],["rimasto","k",["rimas"]],["azienda","k",["azien"]]],"r":[]}},{"id":"RAG-22~2","s":"RAG-22","q":"Cosa fa aumentare e diminuire il fondo TFR?","a":"Aumenta con quote annue e rivalutazioni; diminuisce con imposta sostitutiva, anticipazioni e liquidazioni.","v":{"p":null,"e":[["quote","k",["quote"]],["annue","k",["annue"]],["rivalutazioni","k",["rivaluta"]],["imposta","k",["impos"]],["sostitutiva","k",["sostitut"]],["anticipazioni","k",["anticipa"]],["liquidazioni","k",["liquidaz"]]],"r":[]}},{"id":"RAG-22~3","s":"RAG-22","q":"Le quote destinate al Fondo di Tesoreria incrementano il fondo TFR?","a":"No: sono costo B9 c) ma diventano un debito da versare.","v":{"p":"n","e":[["9","n",["9"]],["costo","k",["costo"]],["diventano","k",["divent"]],["debito","k",["debit"]],["versare","k",["versa"]]],"r":[]}},{"id":"RAG-23~0","s":"RAG-23","q":"Qual è il cuore di «La quota annua di TFR maturata»? Rispondi in due o tre frasi.","a":"La quota annua di TFR è pari alla retribuzione dell'anno divisa per 13,5, ridotta dello 0,50% della retribuzione imponibile versato all'INPS (art. 2120 c.c.; L. 297/1982).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"RAG-23~1","s":"RAG-23","q":"Come si calcola la quota annua di TFR?","a":"Retribuzione annua utile divisa per 13,5, meno lo 0,50% versato all'INPS.","v":{"p":null,"e":[["13,5","n",["13.5"]],["0,50%","n",["0.50"]],["Retribuzione","k",["retribuz","stipend","paga","salari"]],["utile","k",["utile"]],["divisa","k",["divis"]],["versato","k",["versa"]],["INPS","k",["inps"]]],"r":[]}},{"id":"RAG-23~2","s":"RAG-23","q":"Cosa comprende la retribuzione utile per il TFR?","a":"Tutte le somme non occasionali, comprese quelle in natura, esclusi i rimborsi spese, salvo diversa previsione dei CCNL.","v":{"p":null,"e":[["somme","k",["somme"]],["occasionali","k",["occasion"]],["natura","k",["natur"]],["esclusi","k",["esclu"]],["rimborsi","k",["rimbo"]],["spese","k",["spese"]],["diversa","k",["diver"]],["previsione","k",["previsi"]],["CCNL","k",["ccnl","contratto collettivo","contratti collettivi"]]],"r":[]}},{"id":"RAG-23~3","s":"RAG-23","q":"Come si rileva la quota annua di TFR?","a":"Accantonamento TFR (B9 c) a Fondo TFR, o a debito verso fondo pensione o INPS se destinata altrove.","v":{"p":null,"e":[["Accantonamento","k",["accanton"]],["TFR","k",["tfr","trattamento di fine rapporto","liquidazione"]],["Fondo","k",["fondo"]],["debito","k",["debit"]],["pensione","k",["pensi"]],["INPS","k",["inps"]],["destinata","k",["destin"]],["altrove","k",["altro"]]],"r":[]}},{"id":"S22-RAG-3~0","s":"S22-RAG-3","q":"Qual è il cuore di «La rilevazione contabile del costo del personale»? Rispondi in due o tre frasi.","a":"In contabilità generale il costo del personale si rileva in partita doppia in più momenti: la retribuzione lorda come costo (Salari e stipendi), i contributi a carico dell'azienda (Oneri sociali), le ritenute e i contributi trattenuti come debiti verso Erario e istituti, il pagamento del netto e poi il versamento con F24. A fine anno si aggiungono gli stanziamenti di competenza: TFR, ratei di mensilità aggiuntive e ferie.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-RAG-3~1","s":"S22-RAG-3","q":"Come si rileva la retribuzione lorda e i contributi a carico azienda?","a":"Salari e stipendi (B9 a) a Dipendenti c/retribuzioni; Oneri sociali (B9 b) a Istituti previdenziali.","v":{"p":null,"e":[["Salari","k",["salar"]],["stipendi","k",["stipe"]],["Dipendenti","k",["dipende","lavorat"]],["Oneri","k",["oneri"]],["sociali","k",["socia"]],["Istituti","k",["istit"]],["previdenziali","k",["previden"]]],"r":[]}},{"id":"S22-RAG-3~2","s":"S22-RAG-3","q":"Come si rileva il pagamento delle retribuzioni?","a":"Dipendenti c/retribuzioni a diversi: acconti, Istituti previdenziali (quota lavoratore), Erario c/ritenute, Banca (netto).","v":{"p":null,"e":[["Dipendenti","k",["dipende","lavorat"]],["diversi","k",["diver"]],["acconti","k",["accon"]],["Istituti","k",["istit"]],["previdenziali","k",["previden"]],["Erario","k",["erari"]],["ritenute","k",["riten"]],["Banca","k",["banca"]]],"r":[]}},{"id":"S22-RAG-3~3","s":"S22-RAG-3","q":"L'imposta sostitutiva sulla rivalutazione del TFR è un costo aziendale?","a":"No: è trattenuta al dipendente (Fondo TFR a Erario c/ritenute).","v":{"p":"n","e":[["trattenuta","k",["tratten"]],["dipendente","k",["dipende","lavorat"]]],"r":[]}},{"id":"S22-RAG-10~0","s":"S22-RAG-10","q":"Qual è il cuore di «La denuncia salari INAIL: le rilevazioni contabili»? Rispondi in due o tre frasi.","a":"Il premio INAIL è a carico esclusivo del datore e si paga in autoliquidazione: entro il 16 febbraio si versano la rata del premio anticipato per l'anno in corso, calcolato sulle retribuzioni dell'anno prima, e il conguaglio dell'anno precedente sulle retribuzioni effettive. In contabilità serve una scrittura di assestamento per imputare il costo all'esercizio di competenza.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-RAG-10~1","s":"S22-RAG-10","q":"Chi paga il premio INAIL e come si versa?","a":"Solo il datore, in autoliquidazione entro il 16 febbraio: acconto dell'anno in corso e conguaglio del precedente.","v":{"p":null,"e":[["16","n",["16"]],["datore","k",["dator","aziend","impres"]],["autoliquidazione","k",["autoliqu"]],["febbraio","k",["febbr"]],["acconto","k",["accon"]],["anno","k",["ann"]],["corso","k",["corso"]],["conguaglio","k",["conguag"]],["precedente","k",["precede"]]],"r":[]}},{"id":"S22-RAG-10~2","s":"S22-RAG-10","q":"Come si rileva a fine anno il premio INAIL?","a":"Oneri sociali INAIL (B9 b) per il premio di competenza, contro Acconti INAIL e, per la differenza, debito o credito verso l'Istituto.","v":{"p":null,"e":[["Oneri","k",["oneri"]],["sociali","k",["socia"]],["contro","k",["contr","rapport","contribuz","contribut"]],["Acconti","k",["accon"]],["differenza","k",["differe"]],["debito","k",["debit"]],["credito","k",["credi"]],["Istituto","k",["istit"]]],"r":[]}},{"id":"RAG-3~0","s":"RAG-3","q":"Qual è il cuore di «Il bene strumentale»? Rispondi in due o tre frasi.","a":"Il bene strumentale è il bene destinato a essere utilizzato durevolmente nell'attività dell'impresa: si iscrive tra le immobilizzazioni al costo e si ammortizza in base alla residua possibilità di utilizzazione (artt. 2424-bis e 2426 c.c.).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"RAG-3~1","s":"RAG-3","q":"Cosa rende un bene un'immobilizzazione?","a":"La destinazione a un uso durevole nell'impresa, non la natura del bene.","v":{"p":null,"e":[["destinazione","k",["destinaz"]],["durevole","k",["durev"]],["impresa","k",["impre","non si prescrive","non si prescrivono"]],["natura","k",["natur"]]],"r":[]}},{"id":"RAG-3~2","s":"RAG-3","q":"A che valore si iscrive un bene strumentale?","a":"Al costo di acquisto con gli oneri accessori, o al costo di produzione interno.","v":{"p":null,"e":[["costo","k",["costo"]],["acquisto","k",["acqui"]],["oneri","k",["oneri"]],["accessori","k",["access"]],["produzione","k",["produzi"]],["interno","k",["inter"]]],"r":[]}},{"id":"RAG-3~3","s":"RAG-3","q":"Cosa accade alla cessione del bene strumentale?","a":"Si elimina il valore netto contabile e la differenza con il prezzo è plusvalenza o minusvalenza.","v":{"p":"s","e":[["elimina","k",["elimi"]],["valore","k",["valor"]],["netto","k",["netto"]],["contabile","k",["contab"]],["differenza","k",["differe"]],["prezzo","k",["prezz"]],["plusvalenza","k",["plusvale"]],["minusvalenza","k",["minusval"]]],"r":[]}},{"id":"RAG-4~0","s":"RAG-4","q":"Qual è il cuore di «I costi pluriennali»? Rispondi in due o tre frasi.","a":"I costi pluriennali sono costi sostenuti in un esercizio ma con utilità per più esercizi: si iscrivono tra le immobilizzazioni immateriali e si ripartiscono con l'ammortamento (art. 2426, n. 5, c.c.).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"RAG-4~1","s":"RAG-4","q":"Cosa sono i costi pluriennali?","a":"Costi sostenuti in un esercizio con utilità per più esercizi: immobilizzazioni immateriali da ammortizzare.","v":{"p":null,"e":[["sostenuti","k",["sosten"]],["esercizio","k",["eserci"]],["utilità","k",["utili"]],["esercizi","k",["eserc"]],["immobilizzazioni","k",["immobili"]],["immateriali","k",["immateri"]],["ammortizzare","k",["ammortiz"]]],"r":[]}},{"id":"RAG-4~2","s":"RAG-4","q":"Entro quanto si ammortizzano i costi di impianto e ampliamento?","a":"Entro 5 anni.","v":{"p":null,"e":[["5","n",["5"]],["anni","k",["ann"]]],"r":[]}},{"id":"RAG-4~3","s":"RAG-4","q":"Pubblicità e ricerca si possono capitalizzare?","a":"No, dal 2016: la ricerca è costo di periodo; la pubblicità solo se ha i requisiti dei costi di impianto e ampliamento.","v":{"p":"n","e":[["2016","n",["2016"]],["costo","k",["costo"]],["periodo","k",["perio"]],["requisiti","k",["requis"]],["costi","k",["costi"]],["impianto","k",["impia"]],["ampliamento","k",["ampliame"]]],"r":[]}},{"id":"RAG-8~0","s":"RAG-8","q":"Qual è il cuore di «Immobilizzazioni materiali e immateriali»? Rispondi in due o tre frasi.","a":"Le immobilizzazioni sono beni destinati a un uso durevole e si dividono in materiali, immateriali e finanziarie (art. 2424 c.c., voce B dell'attivo); le prime due si ammortizzano.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"RAG-8~1","s":"RAG-8","q":"Differenza tra immobilizzazioni materiali e immateriali?","a":"Le materiali hanno consistenza fisica (terreni, impianti, attrezzature); le immateriali no (brevetti, marchi, avviamento).","v":{"p":null,"e":[["consistenza","k",["consiste"]],["fisica","k",["fisic"]]],"r":[]}},{"id":"RAG-8~2","s":"RAG-8","q":"Quando si iscrive l'avviamento e come si ammortizza?","a":"Solo se acquisito a titolo oneroso; secondo la vita utile o, se non stimabile, entro 10 anni.","v":{"p":null,"e":[["10","m",["10"]],["acquisito","k",["acquis"]],["titolo","k",["titol"]],["oneroso","k",["onero"]],["secondo","k",["secon"]],["vita","k",["vit"]],["utile","k",["utile"]],["stimabile","k",["stimab"]],["anni","k",["ann"]]],"r":[]}},{"id":"RAG-10~0","s":"RAG-10","q":"Qual è il cuore di «Il bilancio d'esercizio e la sua composizione»? Rispondi in due o tre frasi.","a":"Il bilancio d'esercizio è costituito da stato patrimoniale, conto economico, rendiconto finanziario e nota integrativa, e deve rappresentare in modo veritiero e corretto la situazione patrimoniale, finanziaria e il risultato dell'esercizio (art. 2423 c.c.).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"RAG-10~1","s":"RAG-10","q":"Da cosa è composto il bilancio d'esercizio?","a":"Stato patrimoniale, conto economico, rendiconto finanziario e nota integrativa.","v":{"p":null,"e":[["patrimoniale","k",["patrimon"]],["conto","k",["conto"]],["economico","k",["econom"]],["rendiconto","k",["rendico"]],["finanziario","k",["finanzia"]],["nota","k",["not"]],["integrativa","k",["integrat"]]],"r":[]}},{"id":"RAG-10~2","s":"RAG-10","q":"Qual è la clausola generale del bilancio?","a":"Chiarezza e rappresentazione veritiera e corretta.","v":{"p":null,"e":[["Chiarezza","k",["chiare"]],["rappresentazione","k",["rapprese"]],["veritiera","k",["veriti"]],["corretta","k",["corre"]]],"r":[]}},{"id":"RAG-10~3","s":"RAG-10","q":"Quali sono i principi di redazione?","a":"Prudenza, continuità aziendale, prevalenza della sostanza, competenza, valutazione separata, costanza dei criteri.","v":{"p":null,"e":[["Prudenza","k",["prude"]],["continuità","k",["continu"]],["aziendale","k",["aziend"]],["prevalenza","k",["prevale"]],["sostanza","k",["sosta"]],["competenza","k",["compete"]],["valutazione","k",["valutazi"]],["separata","k",["separ"]],["costanza","k",["costa"]],["criteri","k",["crite"]]],"r":[]}},{"id":"RAG-11~0","s":"RAG-11","q":"Qual è il cuore di «Il capitale netto»? Rispondi in due o tre frasi.","a":"Il capitale netto (patrimonio netto) è la differenza tra attività e passività: rappresenta i mezzi propri dell'impresa ed è esposto nella voce A del passivo dello stato patrimoniale (art. 2424 c.c.).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"RAG-11~1","s":"RAG-11","q":"Cos'è il patrimonio netto?","a":"La differenza tra attività e passività: i mezzi propri, voce A del passivo.","v":{"p":null,"e":[["differenza","k",["differe"]],["attività","k",["attiv"]],["passività","k",["passiv"]],["mezzi","k",["mezzi"]],["voce","k",["voc"]],["passivo","k",["passi"]]],"r":[]}},{"id":"RAG-11~2","s":"RAG-11","q":"Differenza tra riserve e fondi rischi?","a":"Le riserve sono parti del patrimonio netto; i fondi sono passività per oneri determinati.","v":{"p":null,"e":[["parti","k",["parti"]],["patrimonio","k",["patrimo"]],["netto","k",["netto"]],["passività","k",["passiv"]],["oneri","k",["oneri"]],["determinati","k",["determin"]]],"r":[]}},{"id":"RAG-11~3","s":"RAG-11","q":"Qual è il capitale minimo di S.p.A. e S.r.l.?","a":"50.000 euro per la S.p.A.; per la S.r.l. 10.000, ma anche da 1 euro con conferimenti in denaro versati per intero.","v":{"p":null,"e":[["50.000","n",["50000"]],["10.000","m",["10000"]],["1","m",["1"]],["euro","k",["eur"]],["conferimenti","k",["conferim"]],["denaro","k",["denar"]],["versati","k",["versa"]],["intero","k",["inter"]]],"r":[]},"t":"d"},{"id":"RAG-13~0","s":"RAG-13","q":"Qual è il cuore di «Lo stato patrimoniale»? Rispondi in due o tre frasi.","a":"Lo stato patrimoniale rappresenta a fine esercizio attività, passività e patrimonio netto secondo lo schema obbligatorio a sezioni contrapposte dell'art. 2424 c.c.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"RAG-13~1","s":"RAG-13","q":"Com'è strutturato il passivo dello stato patrimoniale?","a":"A patrimonio netto, B fondi rischi e oneri, C TFR, D debiti, E ratei e risconti.","v":{"p":null,"e":[["netto","k",["netto"]],["fondi","k",["fondi"]],["rischi","k",["risch"]],["oneri","k",["oneri"]],["TFR","k",["tfr","trattamento di fine rapporto","liquidazione"]],["debiti","k",["debit"]],["ratei","k",["ratei"]],["risconti","k",["risco"]]],"r":[]}},{"id":"RAG-13~2","s":"RAG-13","q":"Dove vanno ritenute IRPEF, contributi da versare e debiti verso dipendenti?","a":"D 12) debiti tributari, D 13) debiti verso istituti previdenziali, D 14) altri debiti.","v":{"p":null,"e":[["12","n",["12"]],["13","n",["13"]],["14","n",["14"]],["tributari","k",["tribut"]],["istituti","k",["istit"]],["previdenziali","k",["previden"]]],"r":[]}},{"id":"RAG-13~3","s":"RAG-13","q":"Come sono esposte le immobilizzazioni?","a":"Al netto dei fondi di ammortamento e svalutazione.","v":{"p":null,"e":[["netto","k",["netto"]],["fondi","k",["fondi"]],["ammortamento","k",["ammortam"]],["svalutazione","k",["svalutaz"]]],"r":[]}},{"id":"RAG-14~0","s":"RAG-14","q":"Qual è il cuore di «Il conto economico»? Rispondi in due o tre frasi.","a":"Il conto economico espone i costi e i ricavi di competenza dell'esercizio in forma scalare secondo l'art. 2425 c.c., fino al risultato d'esercizio.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"RAG-14~1","s":"RAG-14","q":"Che forma ha il conto economico e cosa misura A − B?","a":"Forma scalare; A − B è il risultato della gestione caratteristica.","v":{"p":null,"e":[["scalare","k",["scala"]],["risultato","k",["risult"]],["gestione","k",["gesti"]],["caratteristica","k",["caratter"]]],"r":[]}},{"id":"RAG-14~2","s":"RAG-14","q":"Esiste ancora l'area straordinaria?","a":"No, dal 2016: proventi e oneri straordinari sono distribuiti nelle altre voci.","v":{"p":"n","e":[["2016","n",["2016"]],["proventi","k",["prove"]],["oneri","k",["oneri"]],["distribuiti","k",["distribu"]],["voci","k",["voc"]]],"r":[]}},{"id":"RAG-16~0","s":"RAG-16","q":"Qual è il cuore di «Il piano dei conti»? Rispondi in due o tre frasi.","a":"Il piano dei conti è l'elenco ordinato e codificato dei conti che l'impresa usa per registrare i fatti di gestione, costruito in modo da produrre il bilancio e le informazioni per il controllo.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"RAG-16~1","s":"RAG-16","q":"Cos'è il piano dei conti?","a":"L'elenco ordinato e codificato dei conti usati per registrare i fatti di gestione, raccordato agli schemi di bilancio.","v":{"p":null,"e":[["elenco","k",["elenc"]],["ordinato","k",["ordin"]],["codificato","k",["codific"]],["usati","k",["usati"]],["registrare","k",["registr"]],["fatti","k",["fatti"]],["gestione","k",["gesti"]],["raccordato","k",["raccord"]],["schemi","k",["schem"]],["bilancio","k",["bilan"]]],"r":[]}},{"id":"RAG-16~2","s":"RAG-16","q":"Quali livelli ha un piano dei conti?","a":"Mastro, conto e sottoconto.","v":{"p":null,"e":[["Mastro","k",["mastr"]],["conto","k",["conto"]],["sottoconto","k",["sottoco"]]],"r":[]}},{"id":"RAG-19~0","s":"RAG-19","q":"Qual è il cuore di «Competenza e cassa»? Rispondi in due o tre frasi.","a":"Per il principio di competenza costi e ricavi si imputano all'esercizio a cui si riferiscono economicamente, indipendentemente da incasso e pagamento (art. 2423-bis, c. 1, n. 3, c.c.); il principio di cassa guarda invece al momento del movimento di denaro.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"RAG-19~1","s":"RAG-19","q":"Cosa dice il principio di competenza civilistica?","a":"Costi e ricavi si imputano all'esercizio a cui si riferiscono, indipendentemente da incasso e pagamento.","v":{"p":null,"e":[["ricavi","k",["ricav"]],["imputano","k",["imput"]],["esercizio","k",["eserci"]],["riferiscono","k",["riferisc"]],["indipendentemente","k",["indipend"]],["incasso","k",["incas"]],["pagamento","k",["pagame"]]],"r":[]}},{"id":"RAG-19~2","s":"RAG-19","q":"Quali strumenti attuano la competenza?","a":"Ratei e risconti, fatture da emettere e da ricevere, accantonamenti, ammortamenti, rimanenze.","v":{"p":null,"e":[["Ratei","k",["ratei"]],["risconti","k",["risco"]],["fatture","k",["fattu"]],["emettere","k",["emett"]],["ricevere","k",["ricev"]],["accantonamenti","k",["accanton"]],["ammortamenti","k",["ammortam"]],["rimanenze","k",["rimane"]]],"r":[]}},{"id":"RAG-19~3","s":"RAG-19","q":"Cosa significa correlazione?","a":"I costi si imputano all'esercizio dei ricavi che hanno contribuito a produrre.","v":{"p":null,"e":[["imputano","k",["imput"]],["esercizio","k",["eserci"]],["ricavi","k",["ricav"]],["contribuito","k",["contribu","contribuz","contribut"]],["produrre","k",["produ"]]],"r":[]}},{"id":"RAG-X1~0","s":"RAG-X1","q":"Qual è il cuore di «La nota integrativa e il rendiconto finanziario»? Rispondi in due o tre frasi.","a":"Il bilancio d'esercizio è composto da stato patrimoniale, conto economico, rendiconto finanziario e nota integrativa (art. 2423 c.c.): la nota integrativa spiega e integra i numeri dei prospetti con le informazioni dell'art. 2427, il rendiconto finanziario mostra da dove arriva e dove va la liquidità dell'esercizio (art. 2425-ter).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"RAG-X1~1","s":"RAG-X1","q":"A cosa serve la nota integrativa e cosa interessa al consulente del lavoro?","a":"Spiega e integra i numeri del bilancio; al consulente interessano numero medio dei dipendenti per categoria e compensi di amministratori e sindaci.","v":{"p":null,"e":[["Spiega","k",["spieg"]],["numeri","k",["numer"]],["bilancio","k",["bilan"]],["medio","k",["medio"]],["dipendenti","k",["dipende","lavorat"]],["categoria","k",["catego"]],["compensi","k",["compe"]],["amministratori","k",["amminist"]],["sindaci","k",["sinda"]]],"r":[]}},{"id":"RAG-X1~2","s":"RAG-X1","q":"Cosa mostra il rendiconto finanziario?","a":"Da dove arriva e dove va la liquidità: flussi dell'attività operativa, di investimento e di finanziamento.","v":{"p":null,"e":[["arriva","k",["arriv"]],["liquidità","k",["liquid"]],["flussi","k",["fluss"]],["attività","k",["attiv"]],["operativa","k",["operat"]],["investimento","k",["investim"]]],"r":[]}},{"id":"RAG-X1~3","s":"RAG-X1","q":"Nel metodo indiretto come si tratta l'accantonamento al TFR?","a":"Si aggiunge all'utile, perché è un costo che non genera uscite; il TFR pagato ai cessati è invece un'uscita.","v":{"p":"s","e":[["aggiunge","k",["aggiu"]],["utile","k",["utile"]],["costo","k",["costo"]],["genera","k",["gener"]],["uscite","k",["uscit"]],["TFR","k",["tfr","trattamento di fine rapporto","liquidazione"]],["pagato","k",["pagat"]],["cessati","k",["cessa"]]],"r":[]}},{"id":"RAG-X2~0","s":"RAG-X2","q":"Qual è il cuore di «Il bilancio in forma abbreviata e il bilancio delle micro-imprese»? Rispondi in due o tre frasi.","a":"Le società che non hanno titoli quotati possono redigere il bilancio in forma abbreviata se nel primo esercizio o per due esercizi consecutivi non superano due su tre dei limiti dell'art. 2435-bis c.c. (attivo 5.500.000 euro, ricavi 11.000.000 euro, 50 dipendenti medi); sotto soglie più basse sono micro-imprese (art. 2435-ter: 220.000 euro, 440.000 euro, 5 dipendenti).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"RAG-X2~1","s":"RAG-X2","q":"Quando si può redigere il bilancio in forma abbreviata?","a":"Se non si superano due su tre limiti (attivo 5.500.000, ricavi 11.000.000, 50 dipendenti medi) nel primo esercizio o per due consecutivi.","v":{"p":null,"e":[["2","n",["2"]],["3","n",["3"]],["1","n",["1"]],["superano","k",["super"]],["limiti","k",["limit"]],["esercizio","k",["eserci"]],["consecutivi","k",["consecut"]]],"r":[]}},{"id":"RAG-X2~2","s":"RAG-X2","q":"Quali semplificazioni ha il bilancio abbreviato?","a":"Schemi ridotti, niente rendiconto finanziario, nota integrativa ridotta, niente costo ammortizzato.","v":{"p":null,"e":[["Schemi","k",["schem"]],["ridotti","k",["ridot"]],["niente","k",["nient"]],["rendiconto","k",["rendico"]],["finanziario","k",["finanzia"]],["nota","k",["not"]],["integrativa","k",["integrat"]],["costo","k",["costo"]],["ammortizzato","k",["ammortiz"]]],"r":[]}},{"id":"RAG-X2~3","s":"RAG-X2","q":"Entro quando si approva e si deposita il bilancio?","a":"Approvazione entro 120 giorni dalla chiusura (180 se previsto); deposito entro 30 giorni dall'approvazione.","v":{"p":null,"e":[["120","n",["120"]],["30","m",["30"]],["giorni","k",["giorn","gg"]],["chiusura","k",["chius"]]],"r":[]}},{"id":"RAG-X3~0","s":"RAG-X3","q":"Qual è il cuore di «I criteri di valutazione delle voci di bilancio (art. 2426 c.c.)»? Rispondi in due o tre frasi.","a":"L'art. 2426 c.c. stabilisce come si valutano le voci del bilancio: la regola di base è il costo storico (di acquisto o di produzione), corretto con ammortamenti e svalutazioni, nel rispetto dei principi di prudenza, competenza e continuità dei criteri dell'art. 2423-bis.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"RAG-X3~1","s":"RAG-X3","q":"Qual è la regola base di valutazione dell'art. 2426 c.c.?","a":"Il costo storico, corretto con ammortamenti e svalutazioni.","v":{"p":null,"e":[["costo","k",["costo"]],["storico","k",["stori"]],["corretto","k",["corre"]],["ammortamenti","k",["ammortam"]],["svalutazioni","k",["svalutaz"]]],"r":[]}},{"id":"RAG-X3~2","s":"RAG-X3","q":"Come si valutano le rimanenze?","a":"Al minore tra costo e valore di realizzo; per i beni fungibili media ponderata, FIFO o LIFO.","v":{"p":null,"e":[["minore","k",["minor"]],["costo","k",["costo"]],["valore","k",["valor"]],["realizzo","k",["reali"]],["beni","k",["ben"]],["fungibili","k",["fungib"]],["media","k",["media"]],["ponderata","k",["ponder"]],["FIFO","k",["fifo"]],["LIFO","k",["lifo"]]],"r":[]}},{"id":"RAG-X3~3","s":"RAG-X3","q":"Si possono cambiare i criteri di valutazione?","a":"Solo in casi eccezionali, motivati in nota integrativa.","v":{"p":null,"e":[["eccezionali","k",["eccezion","salvo","tranne","esclus","eccett"]],["motivati","k",["motiv"]],["nota","k",["not"]],["integrativa","k",["integrat"]]],"r":[]}},{"id":"S22-RAG-5~0","s":"S22-RAG-5","q":"Qual è il cuore di «L'ammortamento»? Rispondi in due o tre frasi.","a":"L'ammortamento è il procedimento con cui si ripartisce sistematicamente il costo di un'immobilizzazione di utilizzo limitato nel tempo tra gli esercizi della sua vita utile, per imputare a ciascuno il costo di competenza, indipendentemente dai risultati economici (OIC 16).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-RAG-5~1","s":"S22-RAG-5","q":"Cos'è l'ammortamento?","a":"La ripartizione sistematica del costo di un'immobilizzazione tra gli esercizi della sua vita utile.","v":{"p":null,"e":[["ripartizione","k",["ripartiz"]],["sistematica","k",["sistemat"]],["costo","k",["costo"]],["immobilizzazione","k",["immobili"]],["esercizi","k",["eserc"]],["vita","k",["vit"]],["utile","k",["utile"]]],"r":[]}},{"id":"S22-RAG-5~2","s":"S22-RAG-5","q":"Quali metodi di ammortamento sono ammessi?","a":"Quote costanti, decrescenti o per unità di prodotto; non quote crescenti né legate ai ricavi.","v":{"p":null,"e":[["Quote","k",["quote"]],["costanti","k",["costa"]],["decrescenti","k",["decresce"]],["unità","k",["unita"]],["prodotto","k",["prodo"]],["crescenti","k",["cresce"]],["legate","k",["legat"]],["ricavi","k",["ricav"]]],"r":[]}},{"id":"S22-RAG-5~3","s":"S22-RAG-5","q":"Come si rileva l'ammortamento indiretto?","a":"In dare Ammortamento (B10), in avere Fondo ammortamento, che rettifica il costo storico.","v":{"p":null,"e":[["dare","k",["dar"]],["Fondo","k",["fondo"]],["rettifica","k",["rettif"]],["costo","k",["costo"]],["storico","k",["stori"]]],"r":[]}},{"id":"S22-RAG-7~0","s":"S22-RAG-7","q":"Qual è il cuore di «Le scritture di assestamento: ratei e risconti»? Rispondi in due o tre frasi.","a":"Ratei e risconti sono scritture di assestamento che applicano la competenza economica ai costi e ricavi di contratti di durata a cavallo di due esercizi: i ratei integrano costi o ricavi maturati ma non ancora pagati o incassati; i risconti stornano costi o ricavi già rilevati ma di competenza futura.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-RAG-7~1","s":"S22-RAG-7","q":"Differenza tra ratei e risconti?","a":"I ratei integrano costi o ricavi maturati ma non ancora pagati o incassati; i risconti stornano quelli già rilevati ma di competenza futura.","v":{"p":null,"e":[["integrano","k",["integr"]],["costi","k",["costi"]],["ricavi","k",["ricav"]],["maturati","k",["matur"]],["pagati","k",["pagat"]],["incassati","k",["incass"]],["stornano","k",["storn"]],["rilevati","k",["rilev"]],["competenza","k",["compete"]],["futura","k",["futur"]]],"r":[]}},{"id":"S22-RAG-7~2","s":"S22-RAG-7","q":"Fai un esempio di risconto attivo.","a":"Un premio assicurativo annuale pagato in corso d'anno: la quota dell'anno dopo si storna.","v":{"p":null,"e":[["premio","k",["premi"]],["assicurativo","k",["assicura"]],["annuale","k",["annua"]],["pagato","k",["pagat"]],["corso","k",["corso"]],["anno","k",["ann"]],["quota","k",["quota"]],["storna","k",["storn"]]],"r":[]}},{"id":"S22-RAG-7~3","s":"S22-RAG-7","q":"Dove vanno ratei e risconti in bilancio?","a":"Voce D dell'attivo e voce E del passivo dello stato patrimoniale.","v":{"p":null,"e":[["Voce","k",["voc"]],["attivo","k",["attiv"]],["passivo","k",["passi"]],["patrimoniale","k",["patrimon"]]],"r":[]}},{"id":"S22-RAG-8~0","s":"S22-RAG-8","q":"Qual è il cuore di «L'inventario e la rilevazione contabile dell'ammortamento»? Rispondi in due o tre frasi.","a":"L'inventario d'esercizio è il documento che, a fine anno, rileva, descrive e valuta tutti gli elementi attivi e passivi del patrimonio aziendale; è la base delle scritture di assestamento, compreso l'ammortamento, e del bilancio (art. 2217 c.c.).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-RAG-8~1","s":"S22-RAG-8","q":"Cos'è l'inventario d'esercizio?","a":"Il documento che rileva, descrive e valuta a fine anno attività e passività: base dell'assestamento e del bilancio.","v":{"p":null,"e":[["documento","k",["docume"]],["rileva","k",["rilev"]],["descrive","k",["descr"]],["valuta","k",["valut"]],["fine","k",["fin"]],["anno","k",["ann"]],["attività","k",["attiv"]],["passività","k",["passiv"]],["assestamento","k",["assestam"]],["bilancio","k",["bilan"]]],"r":[]}},{"id":"S22-RAG-8~2","s":"S22-RAG-8","q":"Quali libri sono obbligatori per l'imprenditore commerciale?","a":"Il libro giornale e il libro degli inventari.","v":{"p":null,"e":[["libro","k",["libro"]],["giornale","k",["giorn","gg"]],["inventari","k",["invent"]]],"r":[]}},{"id":"S22-RAG-9~0","s":"S22-RAG-9","q":"Qual è il cuore di «Plusvalenze e minusvalenze: definizione e rilevazione»? Rispondi in due o tre frasi.","a":"Plusvalenze e minusvalenze sono le differenze positive o negative tra il prezzo di cessione di un'immobilizzazione e il suo valore netto contabile, cioè il costo storico meno il fondo ammortamento.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-RAG-9~1","s":"S22-RAG-9","q":"Come si calcola una plusvalenza?","a":"Prezzo di cessione meno valore netto contabile (costo storico meno fondo ammortamento).","v":{"p":null,"e":[["Prezzo","k",["prezz"]],["cessione","k",["cessi"]],["valore","k",["valor"]],["netto","k",["netto"]],["contabile","k",["contab"]]],"r":[]}},{"id":"S22-RAG-9~2","s":"S22-RAG-9","q":"Un bene interamente ammortizzato venduto che plusvalenza genera?","a":"Pari a tutto il ricavo.","v":{"p":null,"e":[["Pari","k",["par"]],["ricavo","k",["ricav"]]],"r":[]}},{"id":"S22-RAG-9~3","s":"S22-RAG-9","q":"Dove vanno plusvalenze e minusvalenze dal 2016?","a":"Nella gestione caratteristica: A5 altri ricavi, B14 oneri diversi.","v":{"p":null,"e":[["5","n",["5"]],["14","n",["14"]],["gestione","k",["gesti"]],["caratteristica","k",["caratter"]],["ricavi","k",["ricav"]],["oneri","k",["oneri"]],["diversi","k",["diver"]]],"r":[]}},{"id":"RAG-12~0","s":"RAG-12","q":"Qual è il cuore di «Gli elementi essenziali della fattura»? Rispondi in due o tre frasi.","a":"La fattura deve contenere gli elementi dell'art. 21 D.P.R. 633/1972: data e numero progressivo, dati del cedente e del cessionario, natura e quantità dell'operazione, imponibile, aliquota e imposta.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"RAG-12~1","s":"RAG-12","q":"Quali elementi deve contenere la fattura?","a":"Data e numero progressivo, dati di cedente e cessionario, natura e quantità dell'operazione, imponibile, aliquota e imposta.","v":{"p":null,"e":[["Data","k",["dat"]],["numero","k",["numer"]],["progressivo","k",["progress"]],["cedente","k",["ceden"]],["cessionario","k",["cessiona"]],["natura","k",["natur"]],["quantità","k",["quant"]],["operazione","k",["operazi"]],["imponibile","k",["imponib"]],["aliquota","k",["aliqu"]],["imposta","k",["impos"]]],"r":[]}},{"id":"RAG-12~2","s":"RAG-12","q":"Cosa va indicato per un'operazione senza IVA?","a":"La norma di riferimento (forfettario, esenzione, non imponibilità).","v":{"p":null,"e":[["norma","k",["norma"]],["riferimento","k",["riferime"]]],"r":[]}},{"id":"RAG-12~3","s":"RAG-12","q":"Quando si emette la fattura per i servizi?","a":"Al pagamento del corrispettivo; l'immediata va trasmessa entro 12 giorni dall'operazione.","v":{"p":null,"e":[["12","m",["12"]],["pagamento","k",["pagame"]],["corrispettivo","k",["corrispe"]],["immediata","k",["immedi"]],["trasmessa","k",["trasme"]],["giorni","k",["giorn","gg"]],["operazione","k",["operazi"]]],"r":[]}},{"id":"RAG-15~0","s":"RAG-15","q":"Qual è il cuore di «Gli obblighi contabili di arti e professioni»? Rispondi in due o tre frasi.","a":"Chi esercita arti e professioni tiene scritture semplificate per cassa (art. 19 D.P.R. 600/1973), con facoltà di optare per la contabilità ordinaria; i forfettari sono esonerati dalla tenuta delle scritture contabili.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"RAG-15~1","s":"RAG-15","q":"Che contabilità tiene il professionista?","a":"Semplificata per cassa, con facoltà di optare per l'ordinaria; i forfettari sono esonerati.","v":{"p":null,"e":[["Semplificata","k",["semplifi"]],["cassa","k",["cassa","cig"]],["facoltà","k",["facol"]],["optare","k",["optar"]],["ordinaria","k",["ordina"]],["forfettari","k",["forfett"]],["esonerati","k",["esoner","sgrav","agevol","riduz"]]],"r":[]}},{"id":"RAG-15~2","s":"RAG-15","q":"Come devono transitare compensi e spese del professionista?","a":"Dai conti correnti dedicati, con mezzi tracciabili salvo importi sotto 100 euro.","v":{"p":null,"e":[["100","n",["100"]],["conti","k",["conti"]],["correnti","k",["corre"]],["dedicati","k",["dedic"]],["mezzi","k",["mezzi"]],["tracciabili","k",["tracciab"]],["importi","k",["impor"]],["sotto","k",["sotto"]],["euro","k",["eur"]]],"r":[]}},{"id":"RAG-18~0","s":"RAG-18","q":"Qual è il cuore di «Contabilità ordinaria e semplificata»? Rispondi in due o tre frasi.","a":"La contabilità ordinaria (art. 14 D.P.R. 600/1973) è obbligatoria per le società di capitali e per le imprese oltre i limiti di ricavi; sotto i limiti le imprese individuali e le società di persone possono tenere la contabilità semplificata (art. 18).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"RAG-18~1","s":"RAG-18","q":"Per chi è obbligatoria la contabilità ordinaria?","a":"Per società di capitali ed enti commerciali sempre; per le altre imprese oltre i limiti di ricavi.","v":{"p":null,"e":[["società","k",["socie"]],["capitali","k",["capit"]],["enti","k",["ent"]],["commerciali","k",["commerci"]],["imprese","k",["impre","non si prescrive","non si prescrivono"]],["limiti","k",["limit"]],["ricavi","k",["ricav"]]],"r":[]}},{"id":"RAG-18~2","s":"RAG-18","q":"Quali sono i limiti della contabilità semplificata?","a":"Ricavi fino a 500.000 euro per i servizi e 800.000 euro per le altre attività.","v":{"p":null,"e":[["500.000","n",["500000"]],["800.000","n",["800000"]],["Ricavi","k",["ricav"]],["euro","k",["eur"]],["servizi","k",["servi"]],["attività","k",["attiv"]]],"r":[]}},{"id":"RAG-18~3","s":"RAG-18","q":"Con quale criterio si determina il reddito in semplificata?","a":"Criterio misto di cassa e competenza.","v":{"p":null,"e":[["misto","k",["misto"]],["cassa","k",["cassa","cig"]],["competenza","k",["compete"]]],"r":[]}},{"id":"RAG-20~0","s":"RAG-20","q":"Qual è il cuore di «La fattura elettronica»? Rispondi in due o tre frasi.","a":"Dal 1° gennaio 2019 la fattura tra operatori residenti è di regola elettronica: è un file XML trasmesso attraverso il Sistema di Interscambio (SdI) dell'Agenzia delle Entrate; dal 2024 l'obbligo riguarda anche i forfettari.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"RAG-20~1","s":"RAG-20","q":"Cos'è la fattura elettronica?","a":"Un file XML trasmesso tramite il Sistema di Interscambio; si considera emessa solo se lo SdI la accetta.","v":{"p":null,"e":[["file","k",["fil"]],["XML","k",["xml"]],["trasmesso","k",["trasme"]],["tramite","k",["trami"]],["Sistema","k",["siste"]],["Interscambio","k",["intersca"]],["considera","k",["consid"]],["emessa","k",["emess"]],["SdI","k",["sdi"]],["accetta","k",["accet"]]],"r":[]}},{"id":"RAG-20~2","s":"RAG-20","q":"I forfettari devono emettere fattura elettronica?","a":"Sì, tutti dal 1° gennaio 2024.","v":{"p":"s","e":[["1","n",["1"]],["2024","n",["2024"]],["gennaio","k",["genna"]]],"r":[]}},{"id":"RAG-20~3","s":"RAG-20","q":"Quali operazioni restano fuori dall'obbligo?","a":"Quelle con l'estero (si comunicano i dati) e le prestazioni sanitarie inviate al Sistema tessera sanitaria.","v":{"p":null,"e":[["estero","k",["ester"]],["prestazioni","k",["prestazi"]],["sanitarie","k",["sanita"]],["inviate","k",["invia"]],["Sistema","k",["siste"]],["tessera","k",["tesse"]]],"r":[]}},{"id":"S22-RAG-1~0","s":"S22-RAG-1","q":"Qual è il cuore di «Azienda, ditta, insegna e marchio»? Rispondi in due o tre frasi.","a":"L'azienda è il complesso dei beni organizzati dall'imprenditore per l'esercizio dell'impresa (art. 2555 c.c.). L'impresa si fa riconoscere sul mercato con tre segni distintivi: la ditta (il nome dell'imprenditore), l'insegna (il segno del locale) e il marchio (il segno dei prodotti o dei servizi).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-RAG-1~1","s":"S22-RAG-1","q":"Quali sono i segni distintivi dell'impresa?","a":"Ditta (nome dell'imprenditore, unico obbligatorio), insegna (del locale) e marchio (dei prodotti o servizi).","v":{"p":null,"e":[["Ditta","k",["ditta"]],["insegna","k",["inseg"]],["marchio","k",["march"]]],"r":[]}},{"id":"S22-RAG-1~2","s":"S22-RAG-1","q":"La ditta si può trasferire da sola?","a":"No: non si trasferisce senza l'azienda.","v":{"p":"n","e":[["azienda","k",["azien"]]],"r":[]}},{"id":"DEO-1~0","s":"DEO-1","q":"Qual è il cuore di «L'oggetto della professione di consulente del lavoro»? Rispondi in due o tre frasi.","a":"Il consulente del lavoro svolge, per conto di qualsiasi datore di lavoro, tutti gli adempimenti previsti dalle norme vigenti per l'amministrazione del personale dipendente, oltre a funzioni affini, connesse e conseguenti (art. 2 L. 12/1979).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DEO-1~1","s":"DEO-1","q":"Qual è l'oggetto della professione di consulente del lavoro?","a":"Tutti gli adempimenti per l'amministrazione del personale dipendente, per conto di qualsiasi datore, più le funzioni affini, connesse e conseguenti.","v":{"p":null,"e":[["adempimenti","k",["adempime"]],["amministrazione","k",["amminist"]],["personale","k",["person"]],["dipendente","k",["dipende","lavorat"]],["conto","k",["conto"]],["datore","k",["dator","aziend","impres"]],["funzioni","k",["funzi"]],["affini","k",["affin"]],["connesse","k",["conne"]],["conseguenti","k",["consegue"]]],"r":[]}},{"id":"DEO-1~2","s":"DEO-1","q":"Il consulente può farsi aiutare da terzi per i compiti esecutivi?","a":"Solo da propri dipendenti: risponde personalmente (professionalità specifica).","v":{"p":null,"e":[["dipendenti","k",["dipende","lavorat"]],["risponde","k",["rispo"]],["personalmente","k",["personal"]]],"r":[]}},{"id":"DEO-1~3","s":"DEO-1","q":"Quali altri ambiti di attività ha il consulente?","a":"Certificazione dei contratti, assistenza in conciliazione, CTU, Asse.Co., assistenza fiscale con il 730, funzioni nelle procedure della crisi.","v":{"p":null,"e":[["730","n",["730"]],["Certificazione","k",["certific"]],["contratti","k",["contra","rapport"]],["assistenza","k",["assiste"]],["conciliazione","k",["concilia"]],["CTU","k",["ctu"]],["Asse","k",["ass"]],["fiscale","k",["fisca"]],["funzioni","k",["funzi"]],["procedure","k",["proced"]],["crisi","k",["crisi"]]],"r":[]}},{"id":"DEO-2~0","s":"DEO-2","q":"Qual è il cuore di «La riserva di legge sugli adempimenti di lavoro»? Rispondi in due o tre frasi.","a":"Gli adempimenti di lavoro, previdenza e assistenza dei dipendenti, se non li cura direttamente il datore di lavoro, possono essere affidati solo ai consulenti del lavoro iscritti all'albo e a pochi altri professionisti indicati dalla legge (art. 1, c. 1, L. 12/1979).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DEO-2~1","s":"DEO-2","q":"Chi può curare gli adempimenti di lavoro per conto del datore?","a":"Solo i consulenti del lavoro e, con comunicazione all'Ispettorato, avvocati, commercialisti, ragionieri e periti commerciali.","v":{"p":null,"e":[["consulenti","k",["consule"]],["comunicazione","k",["comunica"]],["Ispettorato","k",["ispettor"]],["avvocati","k",["avvoc"]],["commercialisti","k",["commerci"]],["ragionieri","k",["ragioni"]],["periti","k",["perit"]]],"r":[]}},{"id":"DEO-2~2","s":"DEO-2","q":"Cosa possono fare i CED?","a":"Solo calcolo e stampa e attività strumentali e accessorie, sempre assistiti da un iscritto agli albi.","v":{"p":null,"e":[["calcolo","k",["calco"]],["stampa","k",["stamp"]],["attività","k",["attiv"]],["strumentali","k",["strument"]],["accessorie","k",["accesso"]],["assistiti","k",["assist"]],["iscritto","k",["iscri"]],["albi","k",["alb"]]],"r":[]}},{"id":"DEO-2~3","s":"DEO-2","q":"Quali attività restano sempre riservate?","a":"Quelle valutative: inquadramento, scelta del CCNL, assunzioni e cessazioni, comunicazioni obbligatorie, tenuta del LUL.","v":{"p":null,"e":[["valutative","k",["valutat"]],["inquadramento","k",["inquadra"]],["scelta","k",["scelt"]],["CCNL","k",["ccnl","contratto collettivo","contratti collettivi"]],["assunzioni","k",["assunzi"]],["cessazioni","k",["cessazi"]],["comunicazioni","k",["comunica"]],["obbligatorie","k",["obbligat","obblig"]],["tenuta","k",["tenut"]],["LUL","k",["lul","libro unico"]]],"r":[]}},{"id":"DEO-2~4","s":"DEO-2","q":"Cosa rischia chi esercita senza titolo?","a":"Il delitto di esercizio abusivo della professione.","v":{"p":null,"e":[["delitto","k",["delit"]],["abusivo","k",["abusi"]],["professione","k",["professi"]]],"r":[]}},{"id":"DEO-3~0","s":"DEO-3","q":"Qual è il cuore di «Le incompatibilità»? Rispondi in due o tre frasi.","a":"L'iscrizione all'albo è incompatibile con alcuni rapporti di lavoro e professioni indicati dall'art. 4 L. 12/1979.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DEO-3~1","s":"DEO-3","q":"Con quali attività è incompatibile l'iscrizione all'albo?","a":"Dipendente di enti pubblici, di patronati o di sindacati dei lavoratori; esattore di tributi, notaio, giornalista professionista.","v":{"p":null,"e":[["Dipendente","k",["dipende","lavorat"]],["enti","k",["ent"]],["pubblici","k",["pubbl"]],["patronati","k",["patron"]],["sindacati","k",["sindac"]],["lavoratori","k",["lavorat","dipendent","prestator"]],["esattore","k",["esatt"]],["tributi","k",["tribu"]],["notaio","k",["notai"]],["giornalista","k",["giornali","gg"]],["professionista","k",["professi"]]],"r":[]}},{"id":"DEO-3~2","s":"DEO-3","q":"Il lavoro subordinato privato è incompatibile?","a":"No: il Codice regola il consulente che esercita in un rapporto subordinato.","v":{"p":"n","e":[["Codice","k",["codic"]],["regola","k",["regol"]],["consulente","k",["consule"]],["esercita","k",["eserc"]],["rapporto","k",["rappo","contratt"]]],"r":[]}},{"id":"DEO-4~0","s":"DEO-4","q":"Qual è il cuore di «L'albo e le condizioni per l'iscrizione»? Rispondi in due o tre frasi.","a":"L'albo dei consulenti del lavoro è tenuto in ogni provincia dal Consiglio provinciale; l'iscritto può esercitare in tutto il territorio nazionale (art. 8 L. 12/1979).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DEO-4~1","s":"DEO-4","q":"Dove può esercitare l'iscritto all'albo provinciale?","a":"In tutto il territorio nazionale; non ci si può iscrivere a più albi.","v":{"p":null,"e":[["territorio","k",["territo"]],["nazionale","k",["nazion"]]],"r":[]}},{"id":"DEO-4~2","s":"DEO-4","q":"Entro quando decide il Consiglio provinciale sull'iscrizione e come si impugna il rigetto?","a":"Entro 2 mesi; il rigetto, dopo aver sentito l'interessato, si impugna al Consiglio nazionale entro 30 giorni.","v":{"p":null,"e":[["2","n",["2"]],["30","m",["30"]],["mesi","k",["mes"]],["aver","k",["aver"]],["sentito","k",["senti"]],["interessato","k",["interess"]],["nazionale","k",["nazion"]],["giorni","k",["giorn","gg"]]],"r":[]}},{"id":"DEO-5~0","s":"DEO-5","q":"Qual è il cuore di «Il DUI (documento unico di iscrizione)»? Rispondi in due o tre frasi.","a":"Il DUI, documento unico di identificazione, è il tesserino professionale del consulente del lavoro, predisposto dal Consiglio nazionale e rilasciato dal Consiglio provinciale.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DEO-5~1","s":"DEO-5","q":"Cos'è il DUI e a cosa serve?","a":"Il tesserino professionale: documento di riconoscimento con firma digitale, associato alla PEC, per identificarsi nei servizi telematici degli enti.","v":{"p":null,"e":[["tesserino","k",["tesser"]],["professionale","k",["professi"]],["documento","k",["docume"]],["riconoscimento","k",["riconosc"]],["firma","k",["firma"]],["digitale","k",["digit"]],["associato","k",["associ"]],["PEC","k",["pec"]],["identificarsi","k",["identifi"]],["servizi","k",["servi"]],["telematici","k",["telemat","online","on line","via web","digital"]],["enti","k",["ent"]]],"r":[]}},{"id":"DEO-6~0","s":"DEO-6","q":"Qual è il cuore di «L'azione disciplinare e le pene disciplinari»? Rispondi in due o tre frasi.","a":"Il consulente che commette abusi o mancanze nell'esercizio della professione, o fatti non conformi alla dignità e al decoro, è sottoposto a procedimento disciplinare; le pene sono censura, sospensione fino a due anni e radiazione (artt. 26-27 L. 12/1979).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DEO-6~1","s":"DEO-6","q":"Quali sono le sanzioni disciplinari?","a":"Censura, sospensione fino a 2 anni e radiazione.","v":{"p":null,"e":[["2","n",["2"]],["Censura","k",["censu"]],["sospensione","k",["sospensi"]],["anni","k",["ann"]],["radiazione","k",["radiazi"]]],"r":[]}},{"id":"DEO-6~2","s":"DEO-6","q":"Chi decide oggi sui procedimenti disciplinari?","a":"Il Consiglio di disciplina territoriale.","v":{"p":null,"e":[["Consiglio","k",["consig"]],["territoriale","k",["territor"]]],"r":[]}},{"id":"DEO-6~3","s":"DEO-6","q":"Dopo la radiazione si può essere riammessi?","a":"Sì, dopo almeno 6 anni e, se derivava da condanna, con la riabilitazione.","v":{"p":"s","e":[["6","n",["6"]],["anni","k",["ann"]],["derivava","k",["deriv"]],["condanna","k",["conda"]],["riabilitazione","k",["riabilit"]]],"r":[]}},{"id":"DEO-6~4","s":"DEO-6","q":"Cosa significano proporzionalità e unicità della sanzione?","a":"Sanzione adeguata a gravità e reiterazione; una sola sanzione per più infrazioni contestate nello stesso procedimento.","v":{"p":null,"e":[["adeguata","k",["adegu"]],["gravità","k",["gravi"]],["reiterazione","k",["reiteraz"]],["sola","k",["sol"]],["infrazioni","k",["infrazi"]],["contestate","k",["contest"]],["procedimento","k",["procedim"]]],"r":[]}},{"id":"DEO-22~0","s":"DEO-22","q":"Qual è il cuore di «La potestà disciplinare del Consiglio provinciale»? Rispondi in due o tre frasi.","a":"La potestà disciplinare non è più esercitata dal Consiglio provinciale, che la aveva in origine (art. 14 L. 12/1979): dal D.P.R. 137/2012 la esercitano i Consigli di disciplina territoriali istituiti presso ogni Consiglio provinciale.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DEO-22~1","s":"DEO-22","q":"Il Consiglio provinciale esercita ancora la potestà disciplinare?","a":"No: dal D.P.R. 137/2012 la esercitano i Consigli di disciplina territoriali; il Consiglio provinciale segnala i fatti.","v":{"p":"n","e":[["137/2012","n",["137","2012"]],["territoriali","k",["territor"]],["segnala","k",["segna"]],["fatti","k",["fatti"]]],"r":[]}},{"id":"DEO-22~2","s":"DEO-22","q":"Chi nomina i componenti del Consiglio di disciplina?","a":"Il Presidente del Tribunale, su un elenco doppio proposto dal Consiglio provinciale.","v":{"p":null,"e":[["Presidente","k",["preside"]],["Tribunale","k",["tribun"]],["elenco","k",["elenc"]],["doppio","k",["doppi"]],["proposto","k",["propo"]],["provinciale","k",["provinci"]]],"r":[]}},{"id":"DEO-22~3","s":"DEO-22","q":"Come si impugna la decisione disciplinare?","a":"Ricorso al Consiglio di disciplina nazionale entro 30 giorni; poi Tribunale di Roma entro 60 giorni.","v":{"p":null,"e":[["30","n",["30"]],["60","m",["60"]],["Ricorso","k",["ricor"]],["Consiglio","k",["consig"]],["nazionale","k",["nazion"]],["giorni","k",["giorn","gg"]],["Tribunale","k",["tribun"]],["Roma","k",["rom"]]],"r":[]}},{"id":"DEO-23~0","s":"DEO-23","q":"Qual è il cuore di «La formazione continua obbligatoria»? Rispondi in due o tre frasi.","a":"La formazione continua è un obbligo giuridico e deontologico di tutti gli iscritti: ogni professionista deve curare l'aggiornamento della propria competenza e la violazione è illecito disciplinare (art. 7 D.P.R. 137/2012).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DEO-23~1","s":"DEO-23","q":"La formazione continua è obbligatoria e per chi?","a":"Sì, per tutti gli iscritti, anche se non esercitano o sono sospesi; violarla è illecito disciplinare.","v":{"p":"s","e":[["iscritti","k",["iscri"]],["esercitano","k",["esercit"]],["sospesi","k",["sospe"]],["violarla","k",["viola"]],["illecito","k",["illec"]],["disciplinare","k",["discipli"]]],"r":[]}},{"id":"DEO-23~2","s":"DEO-23","q":"Su che periodo si contano i crediti formativi?","a":"Su un periodo biennale, con un numero minimo di crediti.","v":{"p":null,"e":[["biennale","k",["bienn"]],["numero","k",["numer"]]],"r":[]}},{"id":"DEO-X3~0","s":"DEO-X3","q":"Qual è il cuore di «Gli obblighi antiriciclaggio del consulente del lavoro»? Rispondi in due o tre frasi.","a":"Il consulente del lavoro è espressamente tra i professionisti obbligati dalla normativa antiriciclaggio (art. 3, c. 4, lett. a, D.Lgs. 231/2007), in forma individuale, associata o societaria: deve verificare il cliente, conservare i dati, segnalare le operazioni sospette e rispettare i limiti all'uso del contante; vigila il Consiglio nazionale dell'Ordine come organismo di autoregolamentazione.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DEO-X3~1","s":"DEO-X3","q":"Il consulente del lavoro è soggetto alla normativa antiriciclaggio?","a":"Sì, espressamente; vigila il Consiglio nazionale come organismo di autoregolamentazione.","v":{"p":"s","e":[["espressamente","k",["espressa"]],["vigila","k",["vigil"]],["Consiglio","k",["consig"]],["nazionale","k",["nazion"]],["organismo","k",["organi"]],["autoregolamentazione","k",["autorego"]]],"r":[]}},{"id":"DEO-X3~2","s":"DEO-X3","q":"Quali sono gli obblighi antiriciclaggio principali?","a":"Adeguata verifica del cliente e del titolare effettivo, conservazione per 10 anni, segnalazione delle operazioni sospette all'UIF, limiti al contante.","v":{"p":null,"e":[["10","n",["10"]],["Adeguata","k",["adegu"]],["verifica","k",["verif"]],["cliente","k",["clien"]],["titolare","k",["titol"]],["effettivo","k",["effett"]],["conservazione","k",["conserva"]],["anni","k",["ann"]],["segnalazione","k",["segnalaz"]],["operazioni","k",["operazi"]],["sospette","k",["sospe"]],["UIF","k",["uif"]],["limiti","k",["limit"]],["contante","k",["conta"]]],"r":[]}},{"id":"DEO-X3~3","s":"DEO-X3","q":"Cosa fare se non si riesce a completare l'adeguata verifica?","a":"Astenersi dalla prestazione.","v":{"p":null,"e":[["Astenersi","k",["astene"]],["prestazione","k",["prestazi"]]],"r":[]}},{"id":"DEO-X3~4","s":"DEO-X3","q":"Si possono pagare le retribuzioni in contanti?","a":"No, in nessun caso.","v":{"p":"n","e":[["nessun","k",["nessu"]]],"r":[]}},{"id":"DEO-X4~0","s":"DEO-X4","q":"Qual è il cuore di «Il praticantato e l'esame di Stato per consulente del lavoro»? Rispondi in due o tre frasi.","a":"Per diventare consulente del lavoro occorre un titolo di studio idoneo, un tirocinio di 18 mesi presso un consulente iscritto da almeno 5 anni, il superamento dell'esame di Stato indetto ogni anno dal Ministero del lavoro e infine l'iscrizione all'albo provinciale (L. 12/1979; D.P.R. 137/2012; Regolamento sul tirocinio del 2015).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DEO-X4~1","s":"DEO-X4","q":"Quali sono le tappe per diventare consulente del lavoro?","a":"Titolo di studio, tirocinio di 18 mesi presso un iscritto da almeno 5 anni, esame di Stato, iscrizione all'albo.","v":{"p":null,"e":[["18","n",["18"]],["5","n",["5"]],["Titolo","k",["titol"]],["studio","k",["studi"]],["tirocinio","k",["tiroci"]],["mesi","k",["mes"]],["presso","k",["press"]],["iscritto","k",["iscri"]],["anni","k",["ann"]],["esame","k",["esame"]],["iscrizione","k",["iscrizi"]],["albo","k",["alb"]]],"r":[]}},{"id":"DEO-X4~2","s":"DEO-X4","q":"Quanto vale il certificato di compiuta pratica?","a":"Perde efficacia se entro 5 anni non si supera l'esame.","v":{"p":null,"e":[["5","n",["5"]],["Perde","k",["perde"]],["efficacia","k",["effica"]],["anni","k",["ann"]],["supera","k",["super"]],["esame","k",["esame"]]],"r":[]}},{"id":"DEO-X4~3","s":"DEO-X4","q":"Che punteggio serve per l'orale e per l'abilitazione?","a":"Almeno 6/10 in ciascuno scritto per l'orale; almeno 6/10 all'orale.","v":{"p":null,"e":[["6","n",["6"]],["10","n",["10"]],["ciascuno","k",["ciasc"]],["scritto","k",["scrit"]]],"r":[]}},{"id":"DEO-X5~0","s":"DEO-X5","q":"Qual è il cuore di «La previdenza del consulente del lavoro: l'ENPACL»? Rispondi in due o tre frasi.","a":"L'ENPACL (Ente nazionale di previdenza e assistenza per i consulenti del lavoro) è la cassa di previdenza obbligatoria dei consulenti iscritti all'albo, ente di diritto privato secondo il D.Lgs. 509/1994: si finanzia con il contributo soggettivo sul reddito professionale, il contributo integrativo del 4% sui compensi e il contributo di maternità, e paga pensioni calcolate con il sistema contributivo per le anzianità dal 2013.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DEO-X5~1","s":"DEO-X5","q":"Cos'è l'ENPACL e come si finanzia?","a":"La cassa di previdenza obbligatoria dei consulenti, di diritto privato: contributo soggettivo, integrativo del 4% e di maternità.","v":{"p":null,"e":[["4%","n",["4"]],["cassa","k",["cassa","cig"]],["previdenza","k",["previde"]],["obbligatoria","k",["obbligat","obblig"]],["consulenti","k",["consule"]],["diritto","k",["dirit"]],["privato","k",["priva","nessun","inefficac","null","non ha effett","non produce","non vale"]],["contributo","k",["contrib","contribuz","contribut"]],["soggettivo","k",["soggett"]],["integrativo","k",["integrat"]],["maternità","k",["matern"]]],"r":[]}},{"id":"DEO-X5~2","s":"DEO-X5","q":"Il contributo integrativo ENPACL subisce IVA e ritenuta?","a":"È soggetto a IVA ma escluso dalla ritenuta; è ripetibile verso il cliente.","v":{"p":null,"e":[["soggetto","k",["sogge"]],["IVA","k",["iva"]],["escluso","k",["esclu"]],["ripetibile","k",["ripetib"]],["cliente","k",["clien"]]],"r":[]}},{"id":"DEO-X5~3","s":"DEO-X5","q":"Come si calcolano le pensioni ENPACL?","a":"Con il sistema contributivo per le anzianità dal 2013.","v":{"p":null,"e":[["2013","n",["2013"]],["sistema","k",["siste"]],["contributivo","k",["contribu","contribuz","contribut"]],["anzianità","k",["anzian"]]],"r":[]}},{"id":"DEO-X6~0","s":"DEO-X6","q":"Qual è il cuore di «La società tra professionisti (STP) e il consulente del lavoro»? Rispondi in due o tre frasi.","a":"Il consulente del lavoro può esercitare anche in forma societaria tramite una società tra professionisti (art. 10, c. 3 ss., L. 183/2011; D.M. 8/2/2013 n. 34): una società di persone, di capitali o cooperativa con oggetto esclusivo l'attività professionale, in cui i soci professionisti devono avere la maggioranza dei due terzi e che è iscritta in una sezione speciale dell'albo.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DEO-X6~1","s":"DEO-X6","q":"Cos'è una STP?","a":"Una società di qualsiasi tipo con oggetto esclusivo l'attività professionale, in cui i soci professionisti hanno la maggioranza dei due terzi.","v":{"p":null,"e":[["2","n",["2"]],["società","k",["socie"]],["qualsiasi","k",["qualsi"]],["oggetto","k",["ogget"]],["esclusivo","k",["esclus"]],["attività","k",["attiv"]],["professionale","k",["professi"]],["soci","k",["soc"]],["maggioranza","k",["maggiora"]],["terzi","k",["terzi"]]],"r":[]}},{"id":"DEO-X6~2","s":"DEO-X6","q":"Cosa accade se nella STP viene meno la maggioranza dei due terzi?","a":"La società si scioglie e viene cancellata se non la ripristina entro 6 mesi.","v":{"p":null,"e":[["6","n",["6"]],["società","k",["socie"]],["scioglie","k",["sciog"]],["cancellata","k",["cancell"]],["ripristina","k",["riprist"]],["mesi","k",["mes"]]],"r":[]}},{"id":"DEO-X6~3","s":"DEO-X6","q":"Chi esegue l'incarico in una STP?","a":"Solo i soci abilitati; il cliente può scegliere il professionista.","v":{"p":null,"e":[["soci","k",["soc"]],["abilitati","k",["abilit"]],["cliente","k",["clien"]],["scegliere","k",["scegli"]],["professionista","k",["professi"]]],"r":[]}},{"id":"S22-DEO-12~0","s":"S22-DEO-12","q":"Qual è il cuore di «L'esercizio della professione (art. 1 L. 12/1979; art. 30 Codice)»? Rispondi in due o tre frasi.","a":"L'art. 1 L. 12/1979 stabilisce chi può curare gli adempimenti di lavoro, previdenza e assistenza per conto dei datori: oltre al datore stesso, solo i consulenti del lavoro iscritti all'albo e gli altri professionisti indicati dalla legge. L'art. 30 del Codice deontologico regola invece come l'incarico va eseguito: con diligenza, perizia e chiarezza verso il cliente.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-DEO-12~1","s":"S22-DEO-12","q":"Il datore resta responsabile se affida gli adempimenti al consulente?","a":"Sì, resta responsabile dei propri obblighi.","v":{"p":"s","e":[["obblighi","k",["obbli","obblig"]]],"r":[]}},{"id":"DEO-7~0","s":"DEO-7","q":"Qual è il cuore di «Le finalità del codice deontologico»? Rispondi in due o tre frasi.","a":"Il Codice deontologico (delibera del Consiglio nazionale n. 101 del 14/7/2021, modificata con delibera n. 49 del 21/3/2024) serve a tutelare la legalità e la dignità del lavoro e l'affidamento della collettività e dei clienti nella professione.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DEO-7~1","s":"DEO-7","q":"A cosa serve il Codice deontologico?","a":"A tutelare la legalità e la dignità del lavoro e l'affidamento della collettività e dei clienti nella professione.","v":{"p":null,"e":[["tutelare","k",["tutel"]],["legalità","k",["legal"]],["dignità","k",["digni"]],["lavoro","k",["lavor","dipendent","prestator"]],["affidamento","k",["affidame"]],["collettività","k",["colletti"]],["clienti","k",["clien"]],["professione","k",["professi"]]],"r":[]}},{"id":"DEO-7~2","s":"DEO-7","q":"Le regole specifiche del Codice limitano i principi generali?","a":"No: sono esemplificazioni.","v":{"p":"n","e":[["esemplificazioni","k",["esemplif"]]],"r":[]}},{"id":"DEO-8~0","s":"DEO-8","q":"Qual è il cuore di «I destinatari del codice deontologico»? Rispondi in due o tre frasi.","a":"Il Codice deontologico si applica ai consulenti del lavoro e alle società tra professionisti iscritte all'albo; i praticanti vi conformano la condotta per quanto compatibile (art. 2).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DEO-8~1","s":"DEO-8","q":"A chi si applica il Codice deontologico?","a":"Ai consulenti iscritti, anche in forma associata o societaria, alle STP e, per quanto compatibile, ai praticanti.","v":{"p":null,"e":[["consulenti","k",["consule"]],["iscritti","k",["iscri"]],["forma","k",["forma"]],["associata","k",["associ"]],["societaria","k",["societa"]],["STP","k",["stp"]],["compatibile","k",["compatib"]],["praticanti","k",["pratica"]]],"r":[]}},{"id":"DEO-8~2","s":"DEO-8","q":"Cosa deve fare il consulente dipendente a cui si chiede una condotta contraria al Codice?","a":"Comunicare per iscritto il proprio dissenso.","v":{"p":null,"e":[["Comunicare","k",["comunic"]],["iscritto","k",["iscri"]],["dissenso","k",["disse"]]],"r":[]}},{"id":"DEO-9~0","s":"DEO-9","q":"Qual è il cuore di «Dignità, decoro e professionalità specifica»? Rispondi in due o tre frasi.","a":"Il dovere di dignità e decoro impone di osservare probità, dignità e decoro in ogni contesto, non solo al lavoro, per salvaguardare la propria reputazione e l'immagine della professione (art. 4 Codice).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DEO-9~1","s":"DEO-9","q":"Cosa impone il dovere di dignità e decoro?","a":"Probità, dignità e decoro in ogni contesto, anche privato, per tutelare la propria reputazione e l'immagine della professione.","v":{"p":null,"e":[["Probità","k",["probi"]],["contesto","k",["conte"]],["privato","k",["priva","nessun","inefficac","null","non ha effett","non produce","non vale"]],["tutelare","k",["tutel"]],["reputazione","k",["reputazi"]],["immagine","k",["immag"]],["professione","k",["professi"]]],"r":[]}},{"id":"DEO-9~2","s":"DEO-9","q":"Come va resa l'attività professionale?","a":"Sotto la propria direzione e responsabilità personale, indicando il titolo.","v":{"p":null,"e":[["Sotto","k",["sotto"]],["direzione","k",["direzi"]],["personale","k",["person"]],["indicando","k",["indica"]],["titolo","k",["titol"]]],"r":[]}},{"id":"DEO-10~0","s":"DEO-10","q":"Qual è il cuore di «Lealtà, correttezza, fedeltà e indipendenza»? Rispondi in due o tre frasi.","a":"Lealtà, correttezza, fedeltà e indipendenza sono doveri generali del Codice deontologico (artt. 5-7): regolano i rapporti con cliente, terzi, colleghi e istituzioni e garantiscono l'autonomia di giudizio.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DEO-10~1","s":"DEO-10","q":"Cosa significa il dovere di fedeltà?","a":"Anteporre gli interessi del cliente ai propri, nel rispetto della legge e del Codice.","v":{"p":null,"e":[["Anteporre","k",["antepo"]],["interessi","k",["intere"]],["cliente","k",["clien"]],["legge","k",["legge"]],["Codice","k",["codic"]]],"r":[]}},{"id":"DEO-10~2","s":"DEO-10","q":"Cosa significa indipendenza?","a":"Autonomia di giudizio tecnico e intellettuale, difesa da condizionamenti esterni.","v":{"p":null,"e":[["Autonomia","k",["autono"]],["giudizio","k",["giudi","tribunal"]],["tecnico","k",["tecni"]],["intellettuale","k",["intellet"]],["difesa","k",["difes"]],["condizionamenti","k",["condizio"]],["esterni","k",["ester"]]],"r":[]}},{"id":"DEO-10~3","s":"DEO-10","q":"Qual è il limite della fedeltà al cliente?","a":"Non suggerire atti nulli, illeciti o fraudolenti e rifiutare l'incarico che concorre a un'operazione illecita.","v":{"p":null,"e":[["suggerire","k",["sugger"]],["atti","k",["att"]],["nulli","k",["nulli","invalid","inefficac","privo","priva","nessun effett","non ha effett","non produce effett"]],["illeciti","k",["illec"]],["fraudolenti","k",["fraudole"]],["rifiutare","k",["rifiut"]],["incarico","k",["incar"]],["concorre","k",["conco"]],["operazione","k",["operazi"]]],"r":[]}},{"id":"DEO-11~0","s":"DEO-11","q":"Qual è il cuore di «Segreto professionale e riservatezza»? Rispondi in due o tre frasi.","a":"Il consulente è tenuto al segreto professionale su tutti i dati e le informazioni del cliente, anche dopo la fine dell'incarico (art. 6 L. 12/1979; art. 25 Codice), e deve garantire la riservatezza anche dei suoi collaboratori (art. 8 Codice).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DEO-11~1","s":"DEO-11","q":"Il segreto professionale vale anche dopo l'incarico?","a":"Sì, permane anche a incarico concluso.","v":{"p":"s","e":[["permane","k",["perma"]],["concluso","k",["concl"]]],"r":[]}},{"id":"DEO-11~2","s":"DEO-11","q":"Chi deve mantenere la riservatezza nello studio?","a":"Anche dipendenti, soci, praticanti e chiunque vi operi: il consulente deve vigilare.","v":{"p":null,"e":[["dipendenti","k",["dipende","lavorat"]],["soci","k",["soc"]],["praticanti","k",["pratica"]],["chiunque","k",["chiun"]],["operi","k",["operi"]],["consulente","k",["consule"]],["vigilare","k",["vigil"]]],"r":[]}},{"id":"DEO-11~3","s":"DEO-11","q":"Che ruolo privacy ha il consulente per i dati dei dipendenti dei clienti?","a":"Responsabile del trattamento; è titolare per i propri dati e clienti persone fisiche.","v":{"p":null,"e":[["Responsabile","k",["responsa"]],["trattamento","k",["trattame"]],["titolare","k",["titol"]],["persone","k",["perso"]],["fisiche","k",["fisic"]]],"r":[]}},{"id":"DEO-12~0","s":"DEO-12","q":"Qual è il cuore di «Competenza e informativa al cliente»? Rispondi in due o tre frasi.","a":"Il dovere di competenza vieta di accettare incarichi che non si sanno svolgere e impone organizzazione e aggiornamento; il dovere di informativa impone di spiegare al cliente l'incarico, il compenso e la polizza (artt. 9, 10, 27, 30 Codice).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DEO-12~1","s":"DEO-12","q":"Il consulente può accettare un incarico che non sa svolgere?","a":"No: deve rifiutarlo; deve curare organizzazione e aggiornamento.","v":{"p":"n","e":[["rifiutarlo","k",["rifiuta"]],["curare","k",["curar"]],["organizzazione","k",["organizz"]],["aggiornamento","k",["aggiorna"]]],"r":[]}},{"id":"DEO-12~2","s":"DEO-12","q":"Cosa va comunicato per iscritto al cliente?","a":"Oggetto, natura, compensi e polizza; e il preventivo con le voci di costo.","v":{"p":null,"e":[["Oggetto","k",["ogget"]],["natura","k",["natur"]],["compensi","k",["compe"]],["polizza","k",["poliz"]],["preventivo","k",["prevent"]],["voci","k",["voc"]]],"r":[]}},{"id":"DEO-12~3","s":"DEO-12","q":"Cosa fa il consulente se la prestazione diventa troppo complessa?","a":"Informa il cliente e chiede di essere sostituito o affiancato.","v":{"p":null,"e":[["Informa","k",["infor","incident"]],["cliente","k",["clien"]],["chiede","k",["chied"]],["sostituito","k",["sostitu"]],["affiancato","k",["affianc"]]],"r":[]}},{"id":"DEO-13~0","s":"DEO-13","q":"Qual è il cuore di «Polizza assicurativa e pubblicità»? Rispondi in due o tre frasi.","a":"Il consulente deve avere una polizza per i danni causati al cliente e comunicarne gli estremi (art. 11 Codice; art. 5 D.P.R. 137/2012); la pubblicità è ammessa con ogni mezzo, purché informativa, veritiera e corretta (art. 35 Codice; art. 4 D.P.R. 137/2012).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DEO-13~1","s":"DEO-13","q":"La polizza professionale è obbligatoria?","a":"Sì: copre i danni al cliente, anche per la custodia di documenti e valori; gli estremi si comunicano al cliente; esercitare senza è illecito disciplinare.","v":{"p":"s","e":[["copre","k",["copre"]],["danni","k",["danni"]],["cliente","k",["clien"]],["custodia","k",["custo"]],["documenti","k",["docume"]],["valori","k",["valor"]],["estremi","k",["estre"]],["comunicano","k",["comunic"]],["esercitare","k",["esercit"]],["illecito","k",["illec"]],["disciplinare","k",["discipli"]]],"r":[]}},{"id":"DEO-13~2","s":"DEO-13","q":"Che pubblicità può fare il consulente?","a":"Informativa, con ogni mezzo anche social: funzionale all'oggetto, veritiera e corretta, mai equivoca, ingannevole o denigratoria.","v":{"p":null,"e":[["Informativa","k",["informat"]],["mezzo","k",["mezzo"]],["social","k",["socia"]],["funzionale","k",["funzion"]],["oggetto","k",["ogget"]],["veritiera","k",["veriti"]],["corretta","k",["corre"]],["equivoca","k",["equiv"]],["ingannevole","k",["ingannev"]],["denigratoria","k",["denigrat"]]],"r":[]}},{"id":"DEO-14~0","s":"DEO-14","q":"Qual è il cuore di «I rapporti con altri professionisti e con i colleghi»? Rispondi in due o tre frasi.","a":"Nei rapporti con colleghi e altri professionisti il Codice chiede correttezza, riservatezza e il passaggio dall'Ordine prima del conflitto; vieta di lavorare con soggetti non abilitati (artt. 12-13).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DEO-14~1","s":"DEO-14","q":"Il consulente può collaborare con soggetti non abilitati?","a":"No, per le prestazioni riservate: non può accettare incarichi con loro né favorirne l'attività.","v":{"p":"n","e":[["prestazioni","k",["prestazi"]],["riservate","k",["riserv"]],["accettare","k",["accett"]],["incarichi","k",["incari"]],["favorirne","k",["favori"]],["attività","k",["attiv"]]],"r":[]}},{"id":"DEO-14~2","s":"DEO-14","q":"Cosa fare prima di agire in giudizio contro un collega?","a":"Interessare il Consiglio provinciale.","v":{"p":null,"e":[["Interessare","k",["interess"]],["Consiglio","k",["consig"]],["provinciale","k",["provinci"]]],"r":[]}},{"id":"DEO-14~3","s":"DEO-14","q":"Cosa è vietato nei rapporti con i colleghi?","a":"Registrare telefonate, divulgare la corrispondenza riservata, usare espressioni sconvenienti od offensive.","v":{"p":null,"e":[["Registrare","k",["registr"]],["telefonate","k",["telefon"]],["divulgare","k",["divulg"]],["corrispondenza","k",["corrispo"]],["riservata","k",["riserv"]],["usare","k",["usare"]],["espressioni","k",["espressi"]],["sconvenienti","k",["sconveni"]],["offensive","k",["offens"]]],"r":[]}},{"id":"DEO-15~0","s":"DEO-15","q":"Qual è il cuore di «La concorrenza sleale»? Rispondi in due o tre frasi.","a":"La concorrenza tra professionisti deve svolgersi secondo i principi dell'ordinamento integrati dal Codice; l'art. 14 elenca i comportamenti che possono costituire concorrenza sleale.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DEO-15~1","s":"DEO-15","q":"Quali comportamenti sono concorrenza sleale?","a":"Screditare un collega, atti diretti solo a danneggiarlo, segni distintivi confondibili, sottrarre clienti al collega sostituito, vantare influenze.","v":{"p":null,"e":[["Screditare","k",["scredit"]],["collega","k",["colle"]],["atti","k",["att"]],["diretti","k",["diret"]],["danneggiarlo","k",["danneggi"]],["segni","k",["segni"]],["distintivi","k",["distint"]],["confondibili","k",["confondi"]],["sottrarre","k",["sottra"]],["clienti","k",["clien"]],["sostituito","k",["sostitu"]],["vantare","k",["vanta"]],["influenze","k",["influe"]]],"r":[]}},{"id":"DEO-16~0","s":"DEO-16","q":"Qual è il cuore di «I rapporti con i colleghi»? Rispondi in due o tre frasi.","a":"I rapporti con i colleghi si basano su lealtà e correttezza (art. 5) e su regole precise per il subentro, la sostituzione e l'incarico congiunto (artt. 13, 16, 17, 27, 28).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DEO-16~1","s":"DEO-16","q":"Cosa deve fare il consulente che subentra a un collega?","a":"Comunicare subito la nomina al collega sostituito e verificare che il cliente abbia receduto.","v":{"p":null,"e":[["Comunicare","k",["comunic"]],["subito","k",["subit"]],["nomina","k",["nomin"]],["sostituito","k",["sostitu"]],["verificare","k",["verific"]],["cliente","k",["clien"]],["abbia","k",["abbia"]],["receduto","k",["reced"]]],"r":[]}},{"id":"DEO-16~2","s":"DEO-16","q":"Il consulente sostituito che doveri ha?","a":"Collaborare con il subentrante perché il cliente non subisca pregiudizio.","v":{"p":null,"e":[["Collaborare","k",["collabor"]],["subentrante","k",["subentra"]],["cliente","k",["clien"]],["subisca","k",["subis"]],["pregiudizio","k",["pregiudi"]]],"r":[]}},{"id":"DEO-17~0","s":"DEO-17","q":"Qual è il cuore di «I rapporti con praticanti, collaboratori e dipendenti»? Rispondi in due o tre frasi.","a":"Verso praticanti, collaboratori e dipendenti il consulente ha doveri di formazione, trasparenza, correttezza ed equo compenso (art. 22 Codice).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DEO-17~1","s":"DEO-17","q":"Che doveri ha il consulente verso il praticante?","a":"Addestramento teorico e pratico, anche deontologico; rapporto trasparente; attestazione veritiera; rimborso spese forfettario dopo i primi sei mesi.","v":{"p":null,"e":[["6","m",["6"]],["Addestramento","k",["addestra"]],["teorico","k",["teori"]],["deontologico","k",["deontolo"]],["rapporto","k",["rappo","contratt"]],["trasparente","k",["traspare"]],["attestazione","k",["attestaz"]],["veritiera","k",["veriti"]],["rimborso","k",["rimbo"]],["spese","k",["spese"]],["forfettario","k",["forfetta"]],["primi","k",["primi"]],["mesi","k",["mes"]]],"r":[]}},{"id":"DEO-17~2","s":"DEO-17","q":"Quanto dura il tirocinio e chi può essere affidatario?","a":"18 mesi, presso un consulente iscritto da almeno 5 anni, di regola con non più di 3 praticanti.","v":{"p":null,"e":[["18","n",["18"]],["5","n",["5"]],["3","n",["3"]],["mesi","k",["mes"]],["presso","k",["press"]],["consulente","k",["consule"]],["iscritto","k",["iscri"]],["anni","k",["ann"]],["regola","k",["regol"]],["praticanti","k",["pratica"]]],"r":[]}},{"id":"DEO-18~0","s":"DEO-18","q":"Qual è il cuore di «L'accettazione dell'incarico»? Rispondi in due o tre frasi.","a":"L'incarico si conferisce con le modalità di legge, specificando per iscritto oggetto, natura, compensi ed estremi della polizza (art. 27 Codice).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DEO-18~1","s":"DEO-18","q":"Che forma deve avere l'incarico?","a":"Scritta, con oggetto, natura, compensi ed estremi della polizza; l'incarico verbale va confermato per iscritto.","v":{"p":null,"e":[["Scritta","k",["scrit"]],["oggetto","k",["ogget"]],["natura","k",["natur"]],["compensi","k",["compe"]],["estremi","k",["estre"]],["polizza","k",["poliz"]],["verbale","k",["verba"]],["confermato","k",["conferm"]],["iscritto","k",["iscri"]]],"r":[]}},{"id":"DEO-18~2","s":"DEO-18","q":"Cosa verifica il consulente prima di accettare l'incarico?","a":"L'identità di chi lo conferisce e del titolare effettivo; se il cliente era di un collega, il recesso dal precedente rapporto.","v":{"p":null,"e":[["identità","k",["ident"]],["conferisce","k",["conferi"]],["titolare","k",["titol"]],["effettivo","k",["effett"]],["cliente","k",["clien"]],["collega","k",["colle"]],["recesso","k",["reces","licenzi"]],["precedente","k",["precede"]],["rapporto","k",["rappo","contratt"]]],"r":[]}},{"id":"DEO-18~3","s":"DEO-18","q":"Come si determina il compenso?","a":"Liberamente, senza tariffe minime; equo nei rapporti soggetti alla L. 49/2023.","v":{"p":null,"e":[["49/2023","m",["49","2023"]],["Liberamente","k",["liberame"]],["tariffe","k",["tarif"]],["minime","k",["minim"]],["equo","k",["equ"]],["rapporti","k",["rappo","contratt"]],["soggetti","k",["sogge"]]],"r":[]}},{"id":"DEO-19~0","s":"DEO-19","q":"Qual è il cuore di «L'esecuzione dell'incarico»? Rispondi in due o tre frasi.","a":"Nell'esecuzione dell'incarico il consulente usa la diligenza e la perizia richieste dalle norme del rapporto professionale e informa con chiarezza il cliente (art. 30 Codice).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DEO-19~1","s":"DEO-19","q":"Come deve eseguire l'incarico il consulente?","a":"Con diligenza e perizia, informando il cliente con semplicità e chiarezza e rettificando gli errori, a proprio carico se imputabili.","v":{"p":null,"e":[["diligenza","k",["dilige"]],["perizia","k",["periz"]],["informando","k",["informa"]],["cliente","k",["clien"]],["semplicità","k",["semplic"]],["chiarezza","k",["chiare"]],["rettificando","k",["rettific"]],["errori","k",["error"]],["carico","k",["caric"]],["imputabili","k",["imputab"]]],"r":[]}},{"id":"DEO-19~2","s":"DEO-19","q":"La trascuratezza degli interessi del cliente è illecito disciplinare?","a":"Sì, se intenzionale.","v":{"p":"s","e":[["intenzionale","k",["intenzio"]]],"r":[]}},{"id":"DEO-20~0","s":"DEO-20","q":"Qual è il cuore di «La restituzione dei documenti del cliente dopo la cessazione dell'incarico»? Rispondi in due o tre frasi.","a":"Quando il cliente lo chiede, il consulente deve restituirgli senza indugio i documenti relativi all'incarico; può trattenerne solo una copia, e solo per il compenso o per tutelarsi (art. 33 Codice).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DEO-20~1","s":"DEO-20","q":"Il consulente può trattenere i documenti del cliente per il compenso?","a":"No: deve restituirli senza indugio; può trattenerne solo una copia per il compenso o per tutelarsi.","v":{"p":"n","e":[["restituirli","k",["restitui"]],["indugio","k",["indug"]],["copia","k",["copia"]],["tutelarsi","k",["tutela"]]],"r":[]}},{"id":"DEO-20~2","s":"DEO-20","q":"Cosa deve fare prima di agire in giudizio contro il cliente?","a":"Rinunciare all'incarico.","v":{"p":null,"e":[["Rinunciare","k",["rinunci"]],["incarico","k",["incar"]]],"r":[]}},{"id":"DEO-21~0","s":"DEO-21","q":"Qual è il cuore di «La pubblicità informativa»? Rispondi in due o tre frasi.","a":"Il consulente può farsi pubblicità con ogni mezzo, anche sui social, purché sia informativa: su attività, specializzazioni, titoli, struttura dello studio e compensi, funzionale all'oggetto, veritiera e corretta, rispettosa del segreto e mai equivoca, ingannevole o denigratoria (art. 4 D.P.R. 137/2012; art. 35 Codice deontologico).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DEO-21~1","s":"DEO-21","q":"Quali limiti ha la pubblicità del consulente?","a":"Funzionale all'oggetto, veritiera e corretta, rispettosa del segreto, non equivoca, ingannevole o denigratoria, con titolo e denominazione dello studio.","v":{"p":null,"e":[["Funzionale","k",["funzion"]],["oggetto","k",["ogget"]],["veritiera","k",["veriti"]],["corretta","k",["corre"]],["rispettosa","k",["rispett"]],["segreto","k",["segre"]],["equivoca","k",["equiv"]],["ingannevole","k",["ingannev"]],["denigratoria","k",["denigrat"]],["titolo","k",["titol"]],["denominazione","k",["denomina"]],["studio","k",["studi"]]],"r":[]}},{"id":"DEO-21~2","s":"DEO-21","q":"Che conseguenze ha una pubblicità scorretta?","a":"Illecito disciplinare e violazione del Codice del consumo e della disciplina della pubblicità ingannevole.","v":{"p":null,"e":[["Illecito","k",["illec"]],["disciplinare","k",["discipli"]],["violazione","k",["violazi"]],["Codice","k",["codic"]],["consumo","k",["consu"]],["disciplina","k",["discipl"]],["ingannevole","k",["ingannev"]]],"r":[]}},{"id":"S22-DEO-1~0","s":"S22-DEO-1","q":"Qual è il cuore di «Il dovere di fedeltà e la trascuratezza degli interessi del cliente (artt. 6 e 32 Codice)»? Rispondi in due o tre frasi.","a":"Il dovere di fedeltà (art. 6 del Codice deontologico) impone al consulente di svolgere l'incarico con fedeltà verso il cliente e di anteporre gli interessi del cliente ai propri, nel rispetto della legge e del Codice. La sua violazione più tipica è la trascuratezza intenzionale degli interessi del cliente, che l'art. 32 qualifica come inadempimento disciplinare.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-DEO-1~1","s":"S22-DEO-1","q":"Quando la trascuratezza degli interessi del cliente è disciplinarmente rilevante?","a":"Quando è intenzionale: serve una condotta volontaria.","v":{"p":null,"e":[["intenzionale","k",["intenzio"]],["serve","k",["serve"]],["condotta","k",["condo"]],["volontaria","k",["volonta"]]],"r":[]}},{"id":"S22-DEO-1~2","s":"S22-DEO-1","q":"La responsabilità disciplinare esclude quella civile?","a":"No: restano distinte la responsabilità civile verso il cliente, coperta dalla polizza, e quella penale.","v":{"p":"n","e":[["restano","k",["resta"]],["distinte","k",["disti"]],["cliente","k",["clien"]],["coperta","k",["coper"]],["polizza","k",["poliz"]],["penale","k",["penal"]]],"r":[]}},{"id":"S22-DEO-14~0","s":"S22-DEO-14","q":"Qual è il cuore di «La partecipazione a società e le collaborazioni con imprese di servizi (art. 20 Codice)»? Rispondi in due o tre frasi.","a":"L'art. 20 del Codice deontologico regola il consulente che partecipa a società commerciali o collabora con imprese che offrono servizi nel settore dell'amministrazione del personale, cioè i centri di elaborazione dati e i servizi delle associazioni di categoria dell'art. 1, c. 4 e 5, L. 12/1979. La regola di fondo: il consulente porta con sé il Codice anche dentro la società e ne risponde.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-DEO-14~1","s":"S22-DEO-14","q":"Il consulente che amministra una società di servizi paga è soggetto al Codice?","a":"Sì: risponde degli atti della società rilevanti per il Codice, salvo funzioni attribuite ad altri o fatti di terzi.","v":{"p":"s","e":[["risponde","k",["rispo"]],["atti","k",["att"]],["rilevanti","k",["rileva"]],["funzioni","k",["funzi"]],["attribuite","k",["attribu"]],["fatti","k",["fatti"]],["terzi","k",["terzi"]]],"r":[]}},{"id":"S22-DEO-14~2","s":"S22-DEO-14","q":"Cosa deve assicurare il consulente sull'incarico dell'impresa di servizi?","a":"Che l'impresa comunichi il conferimento al Consiglio provinciale e all'Ispettorato del lavoro.","v":{"p":null,"e":[["comunichi","k",["comuni"]],["conferimento","k",["conferim"]],["Consiglio","k",["consig"]],["provinciale","k",["provinci"]],["Ispettorato","k",["ispettor"]],["lavoro","k",["lavor","dipendent","prestator"]]],"r":[]}},{"id":"S22-DEO-15~0","s":"S22-DEO-15","q":"Qual è il cuore di «Il consulente del lavoro nel rapporto di lavoro subordinato (art. 36 Codice)»? Rispondi in due o tre frasi.","a":"L'art. 36 del Codice deontologico riguarda il consulente iscritto all'Albo che lavora come dipendente, per esempio in un'azienda, in un'associazione di categoria o in uno studio. Il rapporto di subordinazione non lo esonera dal Codice: se gli si chiede una condotta contraria, deve dissentire per iscritto e prima.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"S22-DEO-15~1","s":"S22-DEO-15","q":"Il consulente dipendente come si comporta se gli si chiede una condotta contraria al Codice?","a":"Comunica prima e per iscritto il dissenso al superiore gerarchico.","v":{"p":null,"e":[["iscritto","k",["iscri"]],["dissenso","k",["disse"]],["superiore","k",["superi"]],["gerarchico","k",["gerarch"]]],"r":[]}},{"id":"S22-DEO-15~2","s":"S22-DEO-15","q":"Cosa aggrava la responsabilità del consulente dipendente?","a":"Aver preteso dai colleghi subordinati comportamenti contrari al Codice.","v":{"p":null,"e":[["Aver","k",["aver"]],["preteso","k",["prete"]],["colleghi","k",["colle"]],["subordinati","k",["subordin"]],["comportamenti","k",["comporta"]],["contrari","k",["contr","rapport","contribuz","contribut"]],["Codice","k",["codic"]]],"r":[]}},{"id":"DEO-X1~0","s":"DEO-X1","q":"Qual è il cuore di «L'esercizio abusivo della professione e i limiti dei CED»? Rispondi in due o tre frasi.","a":"Esercita abusivamente chi svolge senza titolo gli adempimenti riservati dall'art. 1 L. 12/1979; i CED possono solo calcolare, stampare e svolgere attività accessorie, sempre assistiti da un professionista abilitato.","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DEO-X1~1","s":"DEO-X1","q":"Cosa possono e non possono fare i CED?","a":"Possono calcolare, stampare e svolgere attività accessorie assistiti da un abilitato; non le attività valutative, come inquadramento, CCNL, assunzioni, LUL, assistenza nelle ispezioni.","v":{"p":null,"e":[["calcolare","k",["calcol"]],["stampare","k",["stamp"]],["svolgere","k",["svolg"]],["attività","k",["attiv"]],["accessorie","k",["accesso"]],["assistiti","k",["assist"]],["abilitato","k",["abilit"]],["valutative","k",["valutat"]],["inquadramento","k",["inquadra"]],["CCNL","k",["ccnl","contratto collettivo","contratti collettivi"]],["assunzioni","k",["assunzi"]],["LUL","k",["lul","libro unico"]],["assistenza","k",["assiste"]],["ispezioni","k",["ispezi"]]],"r":[]}},{"id":"DEO-X1~2","s":"DEO-X1","q":"Come reagisce l'ordinamento all'abusivismo?","a":"Delitto di esercizio abusivo; l'ispettore può usare la disposizione; il consulente collabora con l'Ordine contro l'abusivismo.","v":{"p":null,"e":[["Delitto","k",["delit"]],["esercizio","k",["eserci"]],["ispettore","k",["ispett"]],["usare","k",["usare"]],["disposizione","k",["disposiz"]],["consulente","k",["consule"]],["collabora","k",["collab"]],["contro","k",["contr","rapport","contribuz","contribut"]]],"r":[]}},{"id":"DEO-X2~0","s":"DEO-X2","q":"Qual è il cuore di «L'asseverazione Asse.Co.»? Rispondi in due o tre frasi.","a":"L'Asse.Co. è l'asseverazione di conformità dei rapporti di lavoro: un sistema terzo, indipendente e qualificato con cui un consulente accreditato verifica la regolarità retributiva e contributiva di un datore di lavoro (Protocollo Ministero del lavoro-Consiglio nazionale del 15/1/2014, rinnovato il 4/3/2016).","v":{"p":null,"e":[],"r":[]},"t":"c"},{"id":"DEO-X2~1","s":"DEO-X2","q":"Cos'è l'Asse.Co.?","a":"L'asseverazione di conformità dei rapporti di lavoro: un consulente accreditato verifica la regolarità retributiva e contributiva del datore.","v":{"p":null,"e":[["conformità","k",["conform"]],["rapporti","k",["rappo","contratt"]],["lavoro","k",["lavor","dipendent","prestator"]],["consulente","k",["consule"]],["accreditato","k",["accredit"]],["verifica","k",["verif"]],["regolarità","k",["regolar"]],["retributiva","k",["retribut"]],["contributiva","k",["contribu","contribuz","contribut"]],["datore","k",["dator","aziend","impres"]]],"r":[]}},{"id":"DEO-X2~2","s":"DEO-X2","q":"Quanto vale il certificato Asse.Co. e su che periodo si verifica?","a":"Si verificano i 12 mesi precedenti; vale 12 mesi se i requisiti permangono.","v":{"p":"s","e":[["12","n",["12"]],["mesi","k",["mes"]],["precedenti","k",["precede"]],["requisiti","k",["requis"]],["permangono","k",["permang"]]],"r":[]}},{"id":"DEO-X2~3","s":"DEO-X2","q":"Che responsabilità ha l'asseveratore?","a":"Rilascia una dichiarazione di responsabilità; la mendacità è illecito disciplinare.","v":{"p":null,"e":[["Rilascia","k",["rilas"]],["dichiarazione","k",["dichiara"]],["mendacità","k",["mendac"]],["illecito","k",["illec"]],["disciplinare","k",["discipli"]]],"r":[]}}]};
